FUNCTION Calculation_1_TwoPoint_Angle : REAL
VAR_INPUT
	in_X1_Start									:REAL;
	in_Y1_Start									:REAL;
	in_X2_End									:REAL;
	in_Y2_End									:REAL;
END_VAR

VAR
	Theta_Buffer								:REAL;
END_VAR



(* 1_TwoPoint_Angle_Calculation *)
IF  in_X1_Start = 0 AND in_Y1_Start = 0 AND in_X2_End = 0 AND in_Y2_End = 0 THEN
	Calculation_1_TwoPoint_Angle := 0;
	RETURN;
END_IF;
        //END X좌표 - Start X좌표 <> 0 인 경우(atan 사용가능)
    IF ( in_X2_End -  in_X1_Start) <> 0 THEN
         Theta_Buffer := 57.2958 * ATAN(( in_Y2_End -  in_Y1_Start) / ( in_X2_End -  in_X1_Start));
        IF ( in_X2_End -  in_X1_Start) < 0 THEN //X2-X1<0 인 경우 +180
             Theta_Buffer :=  Theta_Buffer + 180;
        END_IF;
        //End X좌표 - Start X좌표 = 0 인 경우(atan 사용불가)    
    ELSIF ( in_X2_End -  in_X1_Start) = 0 THEN
        IF  in_Y2_End >  in_Y1_Start THEN
             Theta_Buffer := 90;
        ELSIF  in_Y2_End <  in_Y1_Start THEN
             Theta_Buffer := 270;
        ELSE
             Theta_Buffer := 0;
        END_IF;
    END_IF;
        //Theta 0~360범위를 벗어날 시에, 보정
    IF  Theta_Buffer >= 360 THEN
         Theta_Buffer :=  Theta_Buffer - 360;
    ELSIF  Theta_Buffer < 0 THEN
         Theta_Buffer :=  Theta_Buffer + 360;
    END_IF;

     Calculation_1_TwoPoint_Angle :=  Theta_Buffer;

FUNCTION Calculation_2_TwoPoint_Distance : REAL
VAR_INPUT
	in_X1_Start									:REAL;
	in_Y1_Start									:REAL;
	in_X2_End									:REAL;
	in_Y2_End									:REAL;
END_VAR
VAR
END_VAR



(* in_2_TwoPoint_Distance_Calculation *)

     Calculation_2_TwoPoint_Distance := SQRT((( in_X2_End -  in_X1_Start) * ( in_X2_End -  in_X1_Start))
                                           + (( in_Y2_End -  in_Y1_Start) * ( in_Y2_End -  in_Y1_Start)));

FUNCTION Calculation_3_Angle_SUB_s180 : REAL
VAR_INPUT
	in_SUB_1 : REAL;
	in_SUB_2 : REAL;
END_VAR
VAR
	SUB1_Buffer_s180 : REAL;
END_VAR


 (* 3_Angle_SUB_Calculation *)
     SUB1_Buffer_s180 :=  in_SUB_1 -  in_SUB_2;
    IF  SUB1_Buffer_s180 > 180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 - 360;
    ELSIF  SUB1_Buffer_s180 <= -180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 + 360;
    END_IF;     

     Calculation_3_Angle_SUB_s180 :=  SUB1_Buffer_s180;

FUNCTION Calculation_4_Angle_SUB_us180 : REAL
VAR_INPUT	
	in_SUB_1 : REAL;
	in_SUB_2 : REAL;
END_VAR
VAR
	SUB1_Buffer_s180 : REAL;
END_VAR


(* 4_Angle_SUB_Calculation *)
     SUB1_Buffer_s180 :=  in_SUB_1 -  in_SUB_2;
    IF  SUB1_Buffer_s180 > 180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 - 360;
    ELSIF  SUB1_Buffer_s180 <= -180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 + 360;
    END_IF;     

     Calculation_4_Angle_SUB_us180 := ABS( SUB1_Buffer_s180);

FUNCTION Calculation_5_Angle_Range_Set : REAL
VAR_INPUT
	in_Angle									:REAL;
END_VAR

VAR
	Angle_Range_Set_Buffer						:REAL;
END_VAR


(* 5_Angle Range Set(0~360) *)

     Angle_Range_Set_Buffer :=  in_Angle;
    IF  Angle_Range_Set_Buffer >= 360 THEN
         Angle_Range_Set_Buffer :=  Angle_Range_Set_Buffer - 360;
    ELSIF  Angle_Range_Set_Buffer < 0 THEN
         Angle_Range_Set_Buffer :=  Angle_Range_Set_Buffer + 360;
    END_IF;
     Calculation_5_Angle_Range_Set :=  Angle_Range_Set_Buffer;

FUNCTION F_Scale : LREAL
VAR_INPUT
    nValue    : INT;
    nInMin    : INT;
    nInMax    : INT;
    fOutMin    : LREAL;
    fOutMax    : LREAL;
END_VAR
VAR
    _nValue        : INT;
    _nInValue    : INT;
    _fOutValue    : LREAL;
    _fScale        : LREAL;
END_VAR


IF nInMin >= nInMax    OR fOutMin >= fOutMax THEN
    F_Scale    := 0;
    RETURN;
END_IF



_nValue        := LIMIT(nInMin, nValue, nInMax);
_nInValue    := nInMax - nInMin;
_nValue        := _nValue - nInMin;
_fOutValue    := fOutMax - fOutMin;



_fScale        := _nValue / DINT_TO_LREAL(_nInValue);
F_Scale        := _fOutValue * _fScale + fOutMin;

