FUNCTION_BLOCK ACS_Parsing
VAR_INPUT
	in_Receive_Enable : BOOL;
	in_Send_Enable : BOOL;
	in_Data : ARRAY[0..100] OF BYTE;
	in_Vehicle_ID : BYTE;
	in_Node : INT;
	in_Link : DINT;
	in_Batt_Volt : INT;
	in_Batt_SOC : BYTE;
	in_Status : ARRAY[0..3] OF BYTE;
	in_Event : INT;
	in_Error : ARRAY[0..2] OF INT;
	in_Dest_Node : INT;
	in_Carrier_ID : ARRAY[0..9] OF BYTE;
	in_Map_Version : UDINT; 
END_VAR
VAR_OUTPUT
	out_Send_Type : INT;
	out_Data : ARRAY[0..100] OF BYTE;
	out_Data_Length : UDINT;	
	//1. Time_Data_Set
	out_1_TimeSTR : TIMESTRUCT;
	//2. Command_Send
	out_2_Vehicle_ID : BYTE;
	out_2_Command_Code : ARRAY[0..3] OF BYTE;
	out_2_Carrier_ID : ARRAY[0..9] OF BYTE;
	out_2_Via_Node : ARRAY[0..14] OF INT;
	//3. Data_Send
	out_3_Vehicle_ID : BYTE;
	out_3_Data : DINT;
	//4. Status_Data_Report

END_VAR
VAR
	//Default
	TON	:ARRAY[0..0] OF TON;
	TON_Q	:ARRAY[0..0] OF BOOL;
	TOF	:ARRAY[0..0] OF TOF;
	PN_Pulse :ARRAY[0..0] OF PN_Pulse;
	LoopIndex : ARRAY[0..2] OF INT;

	//Data_arrange
	Data_Empty_Number : INT;
	Data_Header_Number : INT;
	Data_Tail_Number : INT;
	Data_Full_Bit : BOOL;
	Data : ARRAY[0..9,0..100] OF BYTE;

	//String_Buffer
	String_Buffer : ARRAY[0..5] OF STRING;

	//Status_Buffer
	Status_Change_Bit : BOOL;
	Status_Buffer_Node : INT;
	Status_Buffer_Link : DINT;
	Status_Buffer_Status : ARRAY[0..3] OF BYTE;
	Status_Buffer_Event : INT;
	Status_Buffer_Error : ARRAY[0..2] OF INT;
END_VAR


Status_Change_Bit := FALSE;
Data_Full_Bit := FALSE;
out_Send_Type := 0;
FOR LoopIndex[1] := 0 TO 100 DO
	out_Data[LoopIndex[1]] := 0;
END_FOR;
out_Data_Length := 0;


IF in_Receive_Enable THEN
	IF in_Data[0] <> 0 THEN
		FOR LoopIndex[1] := 0 TO 9 DO		
			IF Data[LoopIndex[1],0] = 0 THEN
				Data_Empty_Number := LoopIndex[1];
				EXIT;
			END_IF;
			IF LoopIndex[1] = 9 AND Data_Empty_Number <> 9 THEN 
				Data_Full_Bit := TRUE;
			END_IF;
		END_FOR;		
		IF Data_Full_Bit = FALSE THEN
			Data_Header_Number := 0;
			Data_Tail_Number := 0;		
			FOR LoopIndex[1] := 0 TO 100 DO	
				IF Data_Tail_Number = 0 THEN
					IF In_Data[LoopIndex[1]] = 16#54 THEN 				
						Data_Header_Number := LoopIndex[1];
						Data_Tail_Number := LoopIndex[1]+16-1;
					ELSIF In_Data[LoopIndex[1]] = 16#43 THEN // 'C'
						Data_Header_Number := LoopIndex[1];
						Data_Tail_Number := LoopIndex[1]+77-1;
					ELSIF In_Data[LoopIndex[1]] = 16#44 THEN // 'D'
						Data_Header_Number := LoopIndex[1];
						Data_Tail_Number := LoopIndex[1]+7-1;
					ELSIF In_Data[LoopIndex[1]] = 16#53 THEN // 'S'
						Data_Header_Number := LoopIndex[1];
						Data_Tail_Number := LoopIndex[1]+3-1;
					ELSE
						IF 	LoopIndex[1] = 0 THEN //Data Error
							EXIT;
						END_IF				
					END_IF;	
				END_IF;	
				IF Data_Tail_Number <> 0 AND Data_Tail_Number = LoopIndex[1] AND In_Data[LoopIndex[1]] = 16#45 AND Data_Empty_Number < 10 THEN	
					FOR LoopIndex[2] := Data_Header_Number TO Data_Tail_Number DO
						Data[Data_Empty_Number,LoopIndex[2]-Data_Header_Number] := in_Data[LoopIndex[2]];
					END_FOR;
					Data_Empty_Number := Data_Empty_Number + 1;
					Data_Header_Number := 0;
					Data_Tail_Number := 0;
				END_IF;						
			END_FOR;
		END_IF;




	END_IF;	
END_IF;

IF in_Send_Enable THEN	
	IF 		Data[0,0] = 16#00 
		AND (	Status_Buffer_Node<>in_Node 
			OR Status_Buffer_Link<>in_Link 
			OR Status_Buffer_Status[0] <> in_Status[0] 
			OR Status_Buffer_Status[1] <> in_Status[1] 
			OR Status_Buffer_Status[2] <> in_Status[2]	
			OR Status_Buffer_Status[3] <> in_Status[3]	
			OR Status_Buffer_Event <> in_Event	
			OR Status_Buffer_Error[0] <> in_Error[0] 
			OR Status_Buffer_Error[1] <> in_Error[1] 
			OR Status_Buffer_Error[2] <> in_Error[2] ) THEN		
		Status_Change_Bit := TRUE;		
	END_IF;
	//Data_Send		
	IF TRUE THEN
		// 1. Time Data Set 
		IF Data[0,0] = 16#54 THEN 
			out_Send_Type := 1;
			MEMCPY(destAddr:=ADR(String_Buffer[0]) ,srcAddr:=ADR(Data[0,1]) , n:=10#4);			
			MEMCPY(destAddr:=ADR(String_Buffer[1]) ,srcAddr:=ADR(Data[0,5]) , n:=10#2);
			MEMCPY(destAddr:=ADR(String_Buffer[2]) ,srcAddr:=ADR(Data[0,7]) , n:=10#2);
			MEMCPY(destAddr:=ADR(String_Buffer[3]) ,srcAddr:=ADR(Data[0,9]) , n:=10#2);
			MEMCPY(destAddr:=ADR(String_Buffer[4]) ,srcAddr:=ADR(Data[0,11]) , n:=10#2);
			MEMCPY(destAddr:=ADR(String_Buffer[5]) ,srcAddr:=ADR(Data[0,13]) , n:=10#2);
			out_1_TimeSTR.wYear := STRING_TO_WORD(String_Buffer[0]);
			out_1_TimeSTR.wMonth := STRING_TO_WORD(String_Buffer[1]);
			out_1_TimeSTR.wDay := STRING_TO_WORD(String_Buffer[2]);
			out_1_TimeSTR.wHour := STRING_TO_WORD(String_Buffer[3]);
			out_1_TimeSTR.wMinute := STRING_TO_WORD(String_Buffer[4]);
			out_1_TimeSTR.wSecond := STRING_TO_WORD(String_Buffer[5]);
			out_Data[0] :=16#54;
			out_Data[1] :=16#45;
			out_Data_Length := 10#2;
		// 2. Command_Send
		ELSIF Data[0,0] = 16#43 AND Data[0,1] = in_Vehicle_ID THEN 
			out_Send_Type := 2;
			out_2_Vehicle_ID := Data[0,1];
			FOR LoopIndex[1] := 0 TO 3 DO
				out_2_Command_Code[LoopIndex[1]] := Data[0,2+LoopIndex[1]];
			END_FOR;
			FOR LoopIndex[1] := 0 TO 9 DO
				out_2_Carrier_ID[LoopIndex[1]] := Data[0,6+LoopIndex[1]];
			END_FOR;
			FOR LoopIndex[1] := 0 TO 14 DO
				MEMCPY(destAddr:=ADR(out_2_Via_Node[LoopIndex[1]]) , srcAddr:=ADR(Data[0,16+(LoopIndex[1]*4)]) , n:=4 );			
			END_FOR;						
			out_Data[0] :=16#43;
			out_Data[1] :=in_Vehicle_ID;
			out_Data[2] :=16#45;
			out_Data_Length := 10#3;
		// 3. Data_Send	
		ELSIF Data[0,0] = 16#44 AND Data[0,1] = in_Vehicle_ID THEN 
			out_Send_Type := 3;
			out_3_Vehicle_ID := Data[0,1];			
			out_3_Data := BYTE_TO_DINT(Data[0,2]) + SHL(BYTE_TO_DINT(Data[0,3]),8) 
						+ SHL(BYTE_TO_DINT(Data[0,4]),16) + SHL(BYTE_TO_DINT(Data[0,5]),24) ;
			out_Data[0] :=16#44;
			out_Data[1] :=in_Vehicle_ID;
			out_Data[2] :=16#45;
			out_Data_Length := 10#3;
		// 4. Status_Data_Report	
		ELSIF (Data[0,0] = 16#53 AND Data[0,1] = in_Vehicle_ID) OR Status_Change_Bit THEN 
			out_Send_Type := 4;
			out_Data[0] :=16#53;
			//Vehicle ID
			out_Data[1] :=out_2_Vehicle_ID;
			//Node
			out_Data[2] := INT_TO_BYTE(in_Node AND 16#00FF);
			out_Data[3] := INT_TO_BYTE(SHR(in_Node,8));
			out_Data[4] := 0;
			out_Data[5] := 0;
			//Link
			out_Data[6] := DINT_TO_BYTE( in_Link AND 16#000000FF );
			out_Data[7] := DINT_TO_BYTE( SHR(in_Link,8) AND 16#000000FF );
			out_Data[8] := DINT_TO_BYTE( SHR(in_Link,16) AND 16#000000FF );
			out_Data[9] := DINT_TO_BYTE( SHR(in_Link,24) );
			//Batt.Volt
			out_Data[10] := INT_TO_BYTE(in_Batt_Volt AND 16#00FF);
			out_Data[11] := INT_TO_BYTE(SHR(in_Batt_Volt,8));
			out_Data[12] := in_Batt_SOC;
			out_Data[13] := in_Status[0];
			out_Data[14] := in_Status[1];
			out_Data[15] := in_Status[2];
			out_Data[16] := in_Status[3];
			out_Data[17] := INT_TO_BYTE(in_Event AND 16#00FF);
			out_Data[18] := INT_TO_BYTE(SHR(in_Event,8));
			out_Data[19] := INT_TO_BYTE(in_Error[0] AND 16#00FF);
			out_Data[20] := INT_TO_BYTE(SHR(in_Error[0],8));
			out_Data[21] := INT_TO_BYTE(in_Error[1] AND 16#00FF);
			out_Data[22] := INT_TO_BYTE(SHR(in_Error[1],8));
			out_Data[23] := INT_TO_BYTE(in_Error[2] AND 16#00FF);
			out_Data[24] := INT_TO_BYTE(SHR(in_Error[2],8));
			out_Data[25] := INT_TO_BYTE(in_Dest_Node AND 16#00FF);
			out_Data[26] := INT_TO_BYTE(SHR(in_Dest_Node,8));
			out_Data[27] := 0;
			out_Data[28] := 0;
			out_Data[29] := in_Carrier_ID[0];
			out_Data[30] := in_Carrier_ID[1];
			out_Data[31] := in_Carrier_ID[2];
			out_Data[32] := in_Carrier_ID[3];
			out_Data[33] := in_Carrier_ID[4];
			out_Data[34] := in_Carrier_ID[5];
			out_Data[35] := in_Carrier_ID[6];
			out_Data[36] := in_Carrier_ID[7];
			out_Data[37] := in_Carrier_ID[8];
			out_Data[38] := in_Carrier_ID[9];
			out_Data[39] := DINT_TO_BYTE( in_Map_Version AND 16#000000FF );
			out_Data[40] := DINT_TO_BYTE( SHR(in_Map_Version,8) AND 16#000000FF );
			out_Data[41] := DINT_TO_BYTE( SHR(in_Map_Version,16) AND 16#000000FF );
			out_Data[42] := DINT_TO_BYTE( SHR(in_Map_Version,24) );
			out_Data[43] := 0;
			out_Data[44] := 0;
			out_Data[45] := 0;
			out_Data[46] := 0;
			out_Data[47] := 0;
			out_Data[48] := 0;
			out_Data[49] := 0;
			out_Data[50] := 0;
			out_Data[51] := 0;
			out_Data[52] := 0;
			out_Data[53] := 0;
			out_Data[54] := 0;
			out_Data[55] := 0;
			out_Data[56] := 0;
			out_Data[57] := 0;
			out_Data[58] := 0;
			out_Data[59] := 0;
			out_Data[60] := 0;
			out_Data[61] := 0;
			out_Data[62] := 0;
			out_Data[63] := 16#45;
			out_Data_Length := 10#64;
			Status_Buffer_Node := in_Node ;
			Status_Buffer_Link := in_Link ;
			Status_Buffer_Status[0] := in_Status[0]; 
			Status_Buffer_Status[1] := in_Status[1];
			Status_Buffer_Status[2] := in_Status[2];	
			Status_Buffer_Status[3] := in_Status[3];
			Status_Buffer_Event := in_Event;
			Status_Buffer_Error[0] := in_Error[0]; 
			Status_Buffer_Error[1] := in_Error[1];
			Status_Buffer_Error[2] := in_Error[2];		
		END_IF;



		FOR LoopIndex[1] := 0 TO 9 DO
			IF Data[LoopIndex[1],0] = 0 THEN
				EXIT;
			END_IF;
			IF LoopIndex[1] = 9 THEN 
				FOR LoopIndex[2] := 0 TO 100 DO
				Data[LoopIndex[1],LoopIndex[2]] := 0;
				END_FOR;
				EXIT;
			END_IF;
			FOR LoopIndex[2] := 0 TO 100 DO
				Data[LoopIndex[1],LoopIndex[2]] := Data[LoopIndex[1]+1,LoopIndex[2]];
			END_FOR;
		END_FOR;
	END_IF;



END_IF;

FUNCTION_BLOCK Angle_Calcuration

VAR_INPUT
in_1_TwoPoint_Angle_Calculation_Bit			:BOOL;
in_2_TwoPoint_Distance_Calculation_Bit		:BOOL;
in_X1_Start									:REAL;
in_Y1_Start									:REAL;
in_X2_End									:REAL;
in_Y2_End									:REAL;
in_3_Angle_SUB_bit							:BOOL;
in_SUB_1_1									:REAL;
in_SUB_1_2									:REAL;
in_SUB_2_1									:REAL;
in_SUB_2_2									:REAL;
in_SUB_3_1									:REAL;
in_SUB_3_2									:REAL;
in_SUB_4_1									:REAL;
in_SUB_4_2									:REAL;
in_4_AngleRangeSet_us360_Bit				:BOOL;
in_Angle									:REAL;
END_VAR


VAR_OUTPUT
out_1_Theta_us360							:REAL;
out_2_TwoPoint_Distance_mm					:REAL;
out_3_SUB1_s180								:REAL;
out_3_SUB1_us180							:REAL;
out_3_SUB2_s180								:REAL;
out_3_SUB2_us180							:REAL;
out_3_SUB3_s180								:REAL;
out_3_SUB3_us180							:REAL;
out_3_SUB4_s180								:REAL;
out_3_SUB4_us180							:REAL;
out_4_Angle_us360							:REAL;
END_VAR

VAR
Theta_Buffer								:REAL;
SUB1_Buffer_s180							:REAL;
SUB1_Buffer_us180							:REAL;
SUB2_Buffer_s180							:REAL;
SUB2_Buffer_us180							:REAL;
SUB3_Buffer_s180							:REAL;
SUB3_Buffer_us180							:REAL;
SUB4_Buffer_s180							:REAL;
SUB4_Buffer_us180							:REAL;
Angle_Range_Set_Buffer						:REAL;
END_VAR


//Initialize
out_1_Theta_us360 := 0;
out_2_TwoPoint_Distance_mm := 0;
out_3_SUB1_s180 := 0;
out_3_SUB1_us180 := 0;
out_3_SUB2_s180 := 0;
out_3_SUB2_us180 := 0;
out_3_SUB3_s180 := 0;
out_3_SUB3_us180 := 0;
out_3_SUB4_s180 := 0;
out_3_SUB4_us180 := 0;
out_4_Angle_us360 := 0;

 Theta_Buffer := 0;
 SUB1_Buffer_s180 := 0;
 SUB1_Buffer_us180 := 0;



(* 1_TwoPoint_Angle_Calculation *)
IF  in_1_TwoPoint_Angle_Calculation_Bit THEN
        //END X좌표 - Start X좌표 <> 0 인 경우(atan 사용가능)
    IF ( in_X2_End -  in_X1_Start) <> 0 THEN
         Theta_Buffer := 57.2958 * ATAN(( in_Y2_End -  in_Y1_Start) / ( in_X2_End -  in_X1_Start));
        IF ( in_X2_End -  in_X1_Start) < 0 THEN //X2-X1<0 인 경우 +180
             Theta_Buffer :=  Theta_Buffer + 180;
        END_IF;
        //End X좌표 - Start X좌표 = 0 인 경우(atan 사용불가)    
    ELSIF ( in_X2_End -  in_X1_Start) = 0 THEN
        IF  in_Y2_End >  in_Y1_Start THEN
             Theta_Buffer := 90;
        ELSIF  in_Y2_End <  in_Y1_Start THEN
             Theta_Buffer := 270;
        ELSE
             Theta_Buffer := 0;
        END_IF;
    END_IF;
        //Theta 0~360범위를 벗어날 시에, 보정
    IF  Theta_Buffer >= 360 THEN
         Theta_Buffer :=  Theta_Buffer - 360;
    ELSIF  Theta_Buffer < 0 THEN
         Theta_Buffer :=  Theta_Buffer + 360;
    END_IF;

     out_1_Theta_us360 :=  Theta_Buffer;
END_IF;

(* in_2_TwoPoint_Distance_Calculation *)
IF  in_2_TwoPoint_Distance_Calculation_Bit THEN
     out_2_TwoPoint_Distance_mm := SQRT((( in_X2_End -  in_X1_Start) * ( in_X2_End -  in_X1_Start))
                                           + (( in_Y2_End -  in_Y1_Start) * ( in_Y2_End -  in_Y1_Start)));
END_IF;

(* 3_Angle_SUB_Calculation *)
IF  in_3_Angle_SUB_bit THEN
    //SUB1
     SUB1_Buffer_s180 :=  in_SUB_1_1 -  in_SUB_1_2;
    IF  SUB1_Buffer_s180 > 180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 - 360;
    ELSIF  SUB1_Buffer_s180 <= -180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 + 360;
    END_IF;
     SUB1_Buffer_us180 := ABS( SUB1_Buffer_s180);

     out_3_SUB1_s180 :=  SUB1_Buffer_s180;
     out_3_SUB1_us180 :=  SUB1_Buffer_us180;

    //SUB2
     SUB2_Buffer_s180 :=  in_SUB_2_1 -  in_SUB_2_2;
    IF  SUB2_Buffer_s180 > 180 THEN
         SUB2_Buffer_s180 :=  SUB2_Buffer_s180 - 360;
    ELSIF  SUB2_Buffer_s180 <= -180 THEN
         SUB2_Buffer_s180 :=  SUB2_Buffer_s180 + 360;
    END_IF;
     SUB2_Buffer_us180 := ABS( SUB2_Buffer_s180);

     out_3_SUB2_s180 :=  SUB2_Buffer_s180;
     out_3_SUB2_us180 :=  SUB2_Buffer_us180;

    //SUB3
     SUB3_Buffer_s180 :=  in_SUB_3_1 -  in_SUB_3_2;
    IF  SUB3_Buffer_s180 > 180 THEN
         SUB3_Buffer_s180 :=  SUB3_Buffer_s180 - 360;
    ELSIF  SUB3_Buffer_s180 <= -180 THEN
         SUB3_Buffer_s180 :=  SUB3_Buffer_s180 + 360;
    END_IF;
     SUB3_Buffer_us180 := ABS( SUB3_Buffer_s180);

     out_3_SUB3_s180 :=  SUB3_Buffer_s180;
     out_3_SUB3_us180 :=  SUB3_Buffer_us180;

    //SUB4
     SUB4_Buffer_s180 :=  in_SUB_4_1 -  in_SUB_4_2;
    IF  SUB4_Buffer_s180 > 180 THEN
         SUB4_Buffer_s180 :=  SUB4_Buffer_s180 - 360;
    ELSIF  SUB4_Buffer_s180 <= -180 THEN
         SUB4_Buffer_s180 :=  SUB4_Buffer_s180 + 360;
    END_IF;
     SUB4_Buffer_us180 := ABS( SUB4_Buffer_s180);

     out_3_SUB4_s180 :=  SUB4_Buffer_s180;
     out_3_SUB4_us180 :=  SUB4_Buffer_us180;

END_IF;

(* 4_Angle Range Set(0~360) *)
IF  in_4_AngleRangeSet_us360_Bit THEN
     Angle_Range_Set_Buffer :=  in_Angle;
    IF  Angle_Range_Set_Buffer >= 360 THEN
         Angle_Range_Set_Buffer :=  Angle_Range_Set_Buffer - 360;
