VAR_INPUT
	Enable : BOOL;
	Renew : BOOL;
	in_Loadcell_Value_kg : REAL;	
	in_Min_Weight_Kg : REAL;
	in_Max_Weight_Kg : REAL;
	in_Turret_Weight_kg : REAL;
	in_Current_Speed_mps : REAL;		
	in_Motor_Current : BYTE;
	in_Actual_Lift_Pos : REAL;

END_VAR
VAR_OUTPUT
	out_Load_Complete : BOOL;
	out_Load_kg	:	REAL;
	out_Lift_Direction : INT;
	out_Lift_Speed_mpm : REAL;
	out_Load_Differential_First : REAL;
	out_Load_Differential_Second : REAL;
	out_Start_Pos : REAL;
END_VAR
VAR
	TON : ARRAY[0..1] OF TON;

	Step : INT;
	Load_Buffer : REAL;	
	Actual_Lift_Pos_Buffer_1 : REAL; // 터렛이 들린 Point
	Actual_Lift_Pos_Buffer_2 : REAL; // 터렛이 들리고 난 뒤, 위에 간섭된 Point

	Load_Differential_First : REAL;
	Load_Differential_Second : REAL;
	Pre_Loadcell_Value_kg : REAL;
	Pre_Load_Differential_First : REAL;
	Scan_Count	: REAL;
END_VAR

out_Load_Complete := 0;
out_Lift_Direction := 0;
out_Lift_Speed_mpm := 0;

IF Enable THEN
	IF Renew THEN
		Step := 1;
		Load_Buffer := 0;
		Pre_Loadcell_Value_kg := 0;
		Pre_Load_Differential_First := 0;
		out_Start_Pos := in_Actual_Lift_Pos;
	END_IF;

	IF Step = 1 THEN // Step_1 : Load Maintain Point Detect
		//100_Cycle_Check
		Scan_Count := Scan_Count + 1;
		IF Scan_Count = 50 THEN
			Scan_Count := 0;
			Load_Differential_First := in_Loadcell_Value_kg - Pre_Loadcell_Value_kg;
			Load_Differential_Second := Load_Differential_First - Pre_Load_Differential_First;	
			Pre_Loadcell_Value_kg := in_Loadcell_Value_kg;
			Pre_Load_Differential_First := Load_Differential_First;		
			//Load_Buffer Measurement
			IF 		in_Loadcell_Value_kg > 10.0
				AND in_Loadcell_Value_kg > in_Min_Weight_Kg
				AND in_Current_Speed_mps <> 0
				AND	ABS(Load_Differential_First) < 20.0   //5.0
				//AND	ABS(Load_Differential_First) < 3.0 
			THEN				
				Load_Buffer := Pre_Loadcell_Value_kg - in_Turret_Weight_kg;				
			END_IF;					
			out_Load_Differential_First := Load_Differential_First;
			out_Load_Differential_Second := Load_Differential_Second;
		END_IF;
		out_Lift_Direction := 1;
		out_Lift_Speed_mpm := 0.07; //0.15;
		//Complete
		IF Load_Buffer <> 0 THEN
			//Step := 2;
			Step := 3;
			out_Load_kg := Load_Buffer;
			Actual_Lift_Pos_Buffer_1 := in_Actual_Lift_Pos;
			TON[1](in:=FALSE);
		ELSIF in_Loadcell_Value_kg > in_Max_Weight_Kg THEN
			Step := 3;
			Load_Buffer := in_Max_Weight_Kg;
			out_Load_kg := in_Max_Weight_Kg;
			Actual_Lift_Pos_Buffer_1 := in_Actual_Lift_Pos;
			TON[1](in:=FALSE);
		END_IF;	
	END_IF;
	(*
	IF Step = 2 THEN // Step_2 : Load Up Point Detect
		out_Lift_Direction := 1;	
		out_Lift_Speed_mpm := 0.15;	
		//Complete
		IF (in_Loadcell_Value_kg - ( Load_Buffer (* + in_Turret_Weight_kg *))) > 5.0 THEN
			Step := 3;			
			Actual_Lift_Pos_Buffer_2 := in_Actual_Lift_Pos;
		END_IF;	
	END_IF;
	*)



	IF Step = 3 THEN // Step_3 : Load_Buffer_Move
		IF 	(Load_Buffer - in_Loadcell_Value_kg > 5.0 ) THEN
			out_Lift_Direction := 1;
		ELSIF (Load_Buffer - in_Loadcell_Value_kg < -5.0 ) THEN
			out_Lift_Direction := 2;
		END_IF
		IF ABS(Load_Buffer - in_Loadcell_Value_kg) > 50.0 THEN
			out_Lift_Speed_mpm := 0.07;
		ELSE
			out_Lift_Speed_mpm := 0.07;
		END_IF


		TON[1](in:= ABS(Load_Buffer - in_Loadcell_Value_kg) < 20.0 , PT := T#200MS );
		IF (TON[1].Q) THEN
			Step := 4;
		END_IF;
	END_IF;

	IF Step = 4 THEN // Step_4 : Complete
		out_Load_Complete := TRUE;
	END_IF;

	out_Load_kg	:=	Load_Buffer;
END_IF;
