END_VAR


IF  in_Enable = 1 THEN 
    IF  in_Work_Type = 1 OR  in_Work_Type = 2 OR  in_Work_Type = 3 THEN
        IF ( in_End_X -  in_Start_X) <> 0 THEN
             Progress_Target_us360 := 57.2958 * ATAN(( in_End_Y -  in_Start_Y) / ( in_End_X -  in_Start_X));
            IF ( in_End_X -  in_Start_X) < 0 THEN 
                 Progress_Target_us360 :=  Progress_Target_us360 + 180;
            END_IF;
        ELSIF ( in_End_X -  in_Start_X) = 0 THEN
            IF  in_End_Y >  in_Start_Y THEN
                 Progress_Target_us360 := 90;
            END_IF;

            IF  in_End_Y <  in_Start_Y THEN
                 Progress_Target_us360 := 270;
            END_IF;

        END_IF;
        IF  Progress_Target_us360 >= 360 THEN
             Progress_Target_us360 :=  Progress_Target_us360 - 360;
        ELSIF  Progress_Target_us360 < 0 THEN
             Progress_Target_us360 :=  Progress_Target_us360 + 360;
        END_IF;


         Progress_Current_us360 :=  in_Current_AGV_Angle - ((( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2) - 180);

