out_Turn_Error_Bit := 0;
IF  in_Enable = 1 THEN 
    IF  in_Work_Type = 1 OR  in_Work_Type = 3 THEN
        IF ( in_End_X -  in_Start_X) <> 0 THEN
             Progress_Target_us360 := 57.2958 * ATAN(( in_End_Y -  in_Start_Y) / ( in_End_X -  in_Start_X));
            IF ( in_End_X -  in_Start_X) < 0 THEN 
                 Progress_Target_us360 :=  Progress_Target_us360 + 180;
            END_IF;
        ELSIF ( in_End_X -  in_Start_X) = 0 THEN
            IF  in_End_Y >  in_Start_Y THEN
                 Progress_Target_us360 := 90;
            END_IF;

            IF  in_End_Y <  in_Start_Y THEN
                 Progress_Target_us360 := 270;
            END_IF;

        END_IF;
        IF  Progress_Target_us360 >= 360 THEN
             Progress_Target_us360 :=  Progress_Target_us360 - 360;
        ELSIF  Progress_Target_us360 < 0 THEN
             Progress_Target_us360 :=  Progress_Target_us360 + 360;
        END_IF;
         Progress_Current_us360 :=  in_Current_AGV_Angle - ((( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2) - 180);
        IF  Progress_Current_us360 >= 360 THEN
             Progress_Current_us360 :=  Progress_Current_us360 - 360;
        ELSIF  Progress_Current_us360 < 0 THEN
             Progress_Current_us360 :=  Progress_Current_us360 + 360;
        END_IF;
         SUB_TargetProgress_AGVAngle_s180 :=  Progress_Target_us360 -  in_Current_AGV_Angle;
        IF  SUB_TargetProgress_AGVAngle_s180 > 180 THEN
             SUB_TargetProgress_AGVAngle_s180 :=  SUB_TargetProgress_AGVAngle_s180 - 360;
        ELSIF  SUB_TargetProgress_AGVAngle_s180 <= -180 THEN
             SUB_TargetProgress_AGVAngle_s180 :=  SUB_TargetProgress_AGVAngle_s180 + 360;
        END_IF;
         SUB_TargetProgress_AGVAngle_us180 := ABS( SUB_TargetProgress_AGVAngle_s180);
         SUB_TargetProgress_CurrentProgress_s180 :=  Progress_Target_us360 -  Progress_Current_us360;
        IF  SUB_TargetProgress_CurrentProgress_s180 > 180 THEN
             SUB_TargetProgress_CurrentProgress_s180 :=  SUB_TargetProgress_CurrentProgress_s180 - 360;
        ELSIF  SUB_TargetProgress_CurrentProgress_s180 <= -180 THEN
             SUB_TargetProgress_CurrentProgress_s180 :=  SUB_TargetProgress_CurrentProgress_s180 + 360;
        END_IF;
         SUB_TargetProgress_CurrentProgress_us180 := ABS( SUB_TargetProgress_CurrentProgress_s180);
        IF  SUB_TargetProgress_AGVAngle_us180 > 95 THEN
             out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
             out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
             out_Travel_Direction_0F1B := 1; 
         ELSIF  SUB_TargetProgress_AGVAngle_us180 < 85 THEN
              out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
             out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
             out_Travel_Direction_0F1B := 0;
        ELSE
            IF  SUB_TargetProgress_CurrentProgress_us180 <= 90 THEN 
                 out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
                 out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
                 out_Travel_Direction_0F1B := 0; 
            END_IF;

            IF  SUB_TargetProgress_CurrentProgress_us180 > 90 THEN 
                 out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
                 out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
                 out_Travel_Direction_0F1B := 1; 
            END_IF;


        END_IF;


        IF  out_Target_FW_Wheel_Angle >= 360 THEN
             out_Target_FW_Wheel_Angle :=  out_Target_FW_Wheel_Angle - 360;
        ELSIF  out_Target_FW_Wheel_Angle < 0 THEN
             out_Target_FW_Wheel_Angle :=  out_Target_FW_Wheel_Angle + 360;
        END_IF;

        IF  out_Target_BW_Wheel_Angle >= 360 THEN
             out_Target_BW_Wheel_Angle :=  out_Target_BW_Wheel_Angle - 360;
        ELSIF  out_Target_BW_Wheel_Angle < 0 THEN
             out_Target_BW_Wheel_Angle :=  out_Target_BW_Wheel_Angle + 360;
        END_IF;

    ELSIF  in_Work_Type = 5  THEN
         out_Target_FW_Wheel_Angle := 180;
         out_Target_BW_Wheel_Angle := 180;
    ELSIF  in_Work_Type = 2 OR in_Work_Type = 6 THEN
        IF in_Turn = 5 THEN
             out_Target_FW_Wheel_Angle := 90;
             out_Target_BW_Wheel_Angle := 90;
        ELSIF in_Turn = 6 THEN
             out_Target_FW_Wheel_Angle := 180;
             out_Target_BW_Wheel_Angle := 180;
        ELSIF in_Turn = 7 THEN
             out_Target_FW_Wheel_Angle := 270;
             out_Target_BW_Wheel_Angle := 270;
        ELSE
             out_Turn_Error_Bit := 1;
        END_IF;
    END_IF;


END_IF;

FUNCTION_BLOCK BCG05_Receive
VAR_INPUT
	in_enable : BOOL;
	in_Data : ARRAY[0..40] OF BYTE;
	in_Position_Offset : REAL;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out1_Position_Value : REAL;
	out1_Position_Value_Offset_Ok : REAL;
	out1_STAT_A : UINT;
	out1_STAT_B : UINT;
	out2_Error_Register : BYTE;
	out2_Alarm_Status : UINT;
	out2_Warning_Status : UINT;
	out2_Time_Counter : UINT;
	out3_Speed_Value : INT;
	out3_Temperature_Value : UINT;
	out3_Position_Value_Raw : UDINT;
	out4_CAM_State_Register_Channel_1 : BYTE;
	out4_CAM_State_Register_Channel_2 : BYTE;
	out4_STAT_C : UINT;
	out4_Speed_Value_32bit : DINT;
END_VAR
VAR
	v_Buffer_Data : ARRAY[0..40] OF BYTE;
	v_Position_Value_Buffer : UDINT;
END_VAR


out_Complete := FALSE;
IF in_enable THEN
	MEMCPY(destAddr:=ADR(v_Buffer_Data[0]) , srcAddr:=ADR(in_Data[0]) , n:= SIZEOF(in_Data) );


	v_Position_Value_Buffer := SHL( BYTE_TO_UDINT(v_Buffer_Data[3]),24 ) + SHL( BYTE_TO_UDINT(v_Buffer_Data[2]),16 ) + SHL( BYTE_TO_UDINT(v_Buffer_Data[1]),8 ) + BYTE_TO_UDINT(v_Buffer_Data[0]);		
	out1_Position_Value := UDINT_TO_REAL(v_Position_Value_Buffer)/100;
	out1_Position_Value_Offset_Ok := UDINT_TO_REAL(v_Position_Value_Buffer)/100 - in_Position_Offset;
	out1_STAT_A := SHL( BYTE_TO_UINT(v_Buffer_Data[4]),8 ) + BYTE_TO_UINT(v_Buffer_Data[5]);	
	out1_STAT_B := SHL( BYTE_TO_UINT(v_Buffer_Data[6]),8 ) + BYTE_TO_UINT(v_Buffer_Data[7]);

	out2_Error_Register := v_Buffer_Data[10];
	out2_Alarm_Status := SHL( BYTE_TO_UINT(v_Buffer_Data[12]),8 ) + BYTE_TO_UINT(v_Buffer_Data[11]);
	out2_Warning_Status := SHL( BYTE_TO_UINT(v_Buffer_Data[14]),8 ) + BYTE_TO_UINT(v_Buffer_Data[13]);
	out2_Time_Counter := SHL( BYTE_TO_UINT(v_Buffer_Data[16]),8 ) + BYTE_TO_UINT(v_Buffer_Data[15]);

	out3_Speed_Value := SHL( BYTE_TO_INT(v_Buffer_Data[21]),8 ) + BYTE_TO_INT(v_Buffer_Data[20]);
	out3_Temperature_Value := SHL( BYTE_TO_UINT(v_Buffer_Data[23]),8 ) + BYTE_TO_UINT(v_Buffer_Data[22]);
	out3_Position_Value_Raw := SHL( BYTE_TO_UDINT(v_Buffer_Data[27]),24 ) + SHL( BYTE_TO_UDINT(v_Buffer_Data[26]),16 ) + SHL( BYTE_TO_UDINT(v_Buffer_Data[25]),8 ) + BYTE_TO_UDINT(v_Buffer_Data[24]);

	out4_CAM_State_Register_Channel_1 := v_Buffer_Data[30];
	out4_CAM_State_Register_Channel_2 := v_Buffer_Data[31];
	out4_STAT_C := SHL( BYTE_TO_UINT(v_Buffer_Data[33]),8 ) + BYTE_TO_UINT(v_Buffer_Data[32]);
	out4_Speed_Value_32bit := SHL( BYTE_TO_DINT(v_Buffer_Data[37]),24 ) + SHL( BYTE_TO_DINT(v_Buffer_Data[36]),16 ) + SHL( BYTE_TO_DINT(v_Buffer_Data[35]),8 ) + BYTE_TO_DINT(v_Buffer_Data[34]);

	out_Complete := TRUE;
END_IF

FUNCTION_BLOCK Data_Conversion
VAR_INPUT
in_Enable	:BOOL;
in_Start_Bit	:BOOL;
in_Add_Bit	:BOOL;
in_Command_Type	:INT;
in_Dest_Node	:INT;
in_SpinTurn_Target_Angle : REAL;
in_Data	:ARRAY[0..1000] OF INT;
in_Current_Node : INT;
END_VAR
VAR_OUTPUT
out_Complete	:BOOL;
out_Command_Type	:INT;
out_Dest_Node	:INT;
out_SpinTurn_Target_Angle : REAL;
out_Data	:ARRAY[0..1000] OF INT;
out_Error_In_Data_Fault	:INT;
out_Error_Dest_Node_Data_Fault	:INT;
out_Error_Node_Data_Fault	:INT;
out_Error_No_adjoin_Node	:INT;

END_VAR
VAR

Loop_Index_1	:INT;
Loop_Index_2	:INT;
va_Data	:ARRAY[0..1000] OF INT;
va_Pre_Data	:ARRAY[0..1000] OF INT;
va_Pre_Command_Type	:INT;
va_Pre_Dest_Node	:INT;
va_va_Data_End_Number	:INT;
va_in_Data_Add_Start_Number	:INT;

END_VAR


 va_in_Data_Add_Start_Number := 1;

 out_Complete := FALSE;
 out_Error_In_Data_Fault := 0;
 out_Error_Dest_Node_Data_Fault := 0;
 out_Error_No_adjoin_Node := 0;
 out_Error_Node_Data_Fault := 0;
FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
     va_Data[ Loop_Index_1] := 0;
END_FOR;



IF  in_Enable THEN

    IF  in_Start_Bit = 1 THEN 
        IF 	   (in_Command_Type = 1 )
				OR (in_Command_Type = 2  )
				OR  in_Command_Type = 3 THEN
            IF  GDB_Retain.Node[ in_Dest_Node]._Type = 0
                OR GDB_Retain.Node[ in_Dest_Node].X = 0
                OR GDB_Retain.Node[ in_Dest_Node].Y = 0 THEN
                 out_Error_Dest_Node_Data_Fault := 1;
            END_IF;
            IF  in_Data[1] = 0 AND in_Current_Node <> in_Dest_Node THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;
            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                    IF  in_Data[ Loop_Index_1] = 0 THEN
                        EXIT;
                    END_IF;
                    IF GDB_Retain.Node[ in_Data[ Loop_Index_1]].X = 0
                        OR GDB_Retain.Node[ in_Data[ Loop_Index_1]].Y = 0
                        OR GDB_Retain.Node[ in_Data[ Loop_Index_1]]._Type = 0
                    THEN
                         out_Error_Node_Data_Fault :=  Loop_Index_1;
                        EXIT;
                    END_IF;

                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[(( in_Data[ Loop_Index_1-1] * 10) +  Loop_Index_2)].End_Node =  in_Data[ Loop_Index_1] THEN
                             va_Data[ Loop_Index_1] := (( in_Data[ Loop_Index_1-1] * 10) +  Loop_Index_2);
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ Loop_Index_1] = 0 THEN
                             out_Error_No_adjoin_Node :=  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
            END_FOR;
            IF   out_Error_In_Data_Fault = 0
                    AND  out_Error_Dest_Node_Data_Fault = 0
                    AND  out_Error_Node_Data_Fault = 0
                    AND  out_Error_No_adjoin_Node = 0 THEN					
                     out_Command_Type := in_Command_Type;
                     out_Dest_Node :=  in_Dest_Node;
					 out_SpinTurn_Target_Angle := 0;
                    FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
                         out_Data[ Loop_Index_1] :=  va_Data[ Loop_Index_1];
                    END_FOR;
                     out_Complete := TRUE;
            END_IF;

        ELSIF  in_Command_Type = 4 THEN 
            IF  in_Dest_Node = 0
                OR GDB_Retain.Node[ in_Dest_Node]._Type <> 3
                OR GDB_Retain.Node[ in_Dest_Node].X = 0
                OR GDB_Retain.Node[ in_Dest_Node].Y = 0 THEN
                 out_Error_Dest_Node_Data_Fault := 1;
            END_IF;
            IF  out_Error_Dest_Node_Data_Fault = 0 THEN
                out_Command_Type := 4;
                out_Dest_Node :=  in_Dest_Node;         
                 out_Complete := TRUE;
            END_IF;

        ELSIF  in_Command_Type = 5 THEN 
            IF  in_SpinTurn_Target_Angle < 0 OR  in_SpinTurn_Target_Angle >= 360 THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;
            IF  out_Error_In_Data_Fault = 0 THEN
                 out_Command_Type := 5;
                 out_Dest_Node := 0;
				 out_SpinTurn_Target_Angle := in_SpinTurn_Target_Angle;                 				 
                 out_Complete := TRUE;
            END_IF;
        END_IF;


    END_IF;

    IF  in_Add_Bit AND  va_Pre_Command_Type = 3 THEN 

        IF TRUE THEN
            IF  in_Data[1] = 0 THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;

            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                 va_Data[ Loop_Index_1] :=  va_Pre_Data[ Loop_Index_1];
                IF  va_Data[ Loop_Index_1] = 0 THEN
                    EXIT;
                END_IF;
            END_FOR;


            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                IF  va_Data[ Loop_Index_1] = 0 THEN
                     va_va_Data_End_Number :=  Loop_Index_1 - 1 ;
                    EXIT;
                END_IF;
            END_FOR;
             Loop_Index_1 := 1;
            WHILE  in_Data[ Loop_Index_1] <> 0 DO
                IF  in_Data[ Loop_Index_1] = GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node THEN
                     va_in_Data_Add_Start_Number :=  Loop_Index_1 + 1;
                    EXIT;
                END_IF;
                IF  va_in_Data_Add_Start_Number <> 1 THEN
                    EXIT;
                END_IF;
                 Loop_Index_1 :=  Loop_Index_1 + 1;
            END_WHILE;
             Loop_Index_1 := 0;
            WHILE  in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1] <> 0 DO

                IF GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]].X = 0
                    OR GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]].Y = 0
                    OR GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]]._Type = 0
                THEN
                     out_Error_Node_Data_Fault :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                    EXIT;
                END_IF;
                IF  Loop_Index_1 = 0 THEN
                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[((GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node * 10) +  Loop_Index_2)].End_Node =  in_Data[ va_in_Data_Add_Start_Number] THEN
                             va_Data[ va_va_Data_End_Number + 1] := (((GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node * 10) +  Loop_Index_2));
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ va_va_Data_End_Number + 1] = 0 THEN
                             out_Error_No_adjoin_Node :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
                ELSE
                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[(( in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1 - 1] * 10) +  Loop_Index_2)].End_Node =  in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1] THEN
                             va_Data[ va_va_Data_End_Number +  Loop_Index_1 + 1] := (( in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1 - 1] * 10) +  Loop_Index_2);
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ va_va_Data_End_Number +  Loop_Index_1 + 1] = 0 THEN
                             out_Error_No_adjoin_Node :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
                END_IF;

                 Loop_Index_1 :=  Loop_Index_1 + 1;
            END_WHILE;
            IF  out_Error_In_Data_Fault = 0
                AND  out_Error_Dest_Node_Data_Fault = 0
                AND  out_Error_Node_Data_Fault = 0
                AND  out_Error_No_adjoin_Node = 0
                AND  va_Data[1] <> 0 THEN
                 out_Command_Type :=  in_Command_Type;
                 out_Dest_Node :=  in_Dest_Node;
                FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
                     out_Data[ Loop_Index_1] :=  va_Data[ Loop_Index_1];
                END_FOR;
                 out_Complete := TRUE;
            END_IF;



        END_IF;
    END_IF;

    IF  out_Complete THEN
         va_Pre_Command_Type :=  out_Command_Type;
         va_Pre_Dest_Node :=  out_Dest_Node;
        FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
             va_Pre_Data[ Loop_Index_1] :=  out_Data[ Loop_Index_1];
            IF  out_Data[ Loop_Index_1] = 0 THEN
                EXIT;
            END_IF;
        END_FOR;
    END_IF;


    END_IF;

FUNCTION_BLOCK F_Scale2
VAR_INPUT
    nValue    : INT;
    nInMin    : INT;
    nInMax    : INT;
    fOutMin    : LREAL;
    fOutMax    : LREAL;
END_VAR
VAR_OUTPUT
	out_Value : LREAL;
END_VAR
VAR
    _nValue        : INT;
    _nInValue    : INT;
    _fOutValue    : LREAL;
    _fScale        : LREAL;
END_VAR


IF nInMin >= nInMax    OR fOutMin >= fOutMax THEN
    out_Value    := 0;
    RETURN;
END_IF



_nValue        := LIMIT(nInMin, nValue, nInMax);
_nInValue    := nInMax - nInMin;
_nValue        := _nValue - nInMin;
_fOutValue    := fOutMax - fOutMin;



_fScale        := _nValue / DINT_TO_LREAL(_nInValue);
out_Value        := _fOutValue * _fScale + fOutMin;
LIMIT

FUNCTION_BLOCK FB_LogManager
VAR CONSTANT
	VAR_HEADER_BUFFER_SIZE : DINT := 3000;
	VAR_VALUE_BUFFER_SIZE : DINT := 100000;
END_VAR
VAR_IN_OUT
	IO_aHeader			: ARRAY[*] OF STRING;
	IO_aValue			: ARRAY[*] OF STRING;
END_VAR
VAR_INPUT
	IN_bExecute				: BOOL;
	IN_sLogType	 			: STRING := 'Period'; (* Period OR Manual *)
	IN_tLogingPeriod		: TIME := T#1S; (* Only Period Type *)
	IN_bManualLog			: BOOL; (* Only Manual Type *)
	IN_bForceSave			: BOOL;
	IN_sNetID				: STRING(80):='';
	IN_sFileDir				: STRING(80):='C:\'; (* 파일 저장경로 *)
	IN_sFileName	  	 	: STRING(80):='Test.csv'; (* 파일 이름 *)
	IN_bRenewHeader		 	: BOOL; (* 새로운 Cell Name 입력 시 *)
	IN_nBufferSize			: DINT := VAR_VALUE_BUFFER_SIZE; (* If bUseBuffer is true and Cant Bigger then VAR_VALUE_BUFFER_SIZE *)
	IN_bUseBuffer	 	 	: BOOL:=TRUE; (* Not used persistent data, 버퍼 쌓일시 바로 작성 *)
END_VAR
VAR_OUTPUT
	OUT_bError : BOOL;
	OUT_nErrorID :  UDINT;
	OUT_bLossStorage : BOOL;
END_VAR
VAR PERSISTENT
	aBufferWriteHeader			: ARRAY [1..VAR_HEADER_BUFFER_SIZE] OF BYTE;
	aBufferWriteValue			: ARRAY [1..VAR_VALUE_BUFFER_SIZE] OF BYTE;
	nBufferWriteHeaderSize : UDINT;	
	nBufferWriteValueSize : UDINT;
END_VAR
VAR	

	nErrorCnt : INT;	
	bLostStorage : BOOL;
	bError : BOOL; 
	nErrId : UDINT;  
	hFile : UINT; 	
	bSave : BOOL;
	nBeforeDay : WORD;
	bSaveComplete : BOOL;
	bHeaderChanged	: BOOL;
	bDayChanged : BOOL;
	bReWrite : BOOL;
	sHeaderCheck : STRING(4); 
	nHeaderMin : DINT;
	nHeaderMax : DINT;
	nValueMin : DINT;
	nValueMax : DINT;
	nBufferSize : DINT;

	fbLogingPeriod		: TON;
	fbManualLogTrig : R_TRIG;
	fbForceSaveTrig : R_TRIG;
	fbRenewHeaderTrig	: R_TRIG;

	nStep	: INT;
	nLastStep : INT;
	nIndex 	: DINT;

	fbFileOpen							: FB_FileOpen;
	fbFileClose							: FB_FileClose;
	fbFileWrite							: FB_FileWrite;
	fbFileWriteName						: FB_FileWrite;
	fbFileRead							: FB_FileRead;
	fbFileSeek							: FB_FileSeek;
	sFileName : STRING;

	fbNT_GetTime: NT_GetTime;
	sSystemTime							: STRING;
	stTempSTR							: TIMESTRUCT;
END_VAR
VAR CONSTANT
	sDate								: STRING(4):='Date';
	sComma								: STRING(1):=',';
	sSummary							: STRING(1):='$L';
END_VAR


//===================================================================================
// Initial
	SetCommon();

//===================================================================================
// Control	

	IF NOT (IN_bExecute AND IO_aHeader[nHeaderMin] <> '') THEN
		nStep := 0;
		nBufferWriteValueSize := 0;
		MEMSET(ADR(aBufferWriteValue),0,SIZEOF(aBufferWriteValue));
	ELSE
		(* Header Set *)
		fbRenewHeaderTrig(CLK:=IN_bRenewHeader);
		IF fbRenewHeaderTrig.Q OR nBufferWriteHeaderSize = 0 THEN
			SetHeader();
		END_IF

		(* Value Set *)
		fbLogingPeriod(IN:=fbLogingPeriod.Q = FALSE AND IN_sLogType = 'Period', PT:= IN_tLogingPeriod);
		fbManualLogTrig(CLK := IN_bManualLog AND IN_sLogType = 'Manual');
		IF fbLogingPeriod.Q OR fbManualLogTrig.Q THEN
			SetValue(); 						
		END_IF

		(* Save *)
		fbForceSaveTrig(CLK := IN_bForceSave);
		IF (fbForceSaveTrig.Q AND 0 < nBufferWriteValueSize)
		OR bDayChanged
		OR (ABS(nBufferSize - (nBufferSize/10)) < UDINT_TO_DINT(nBufferWriteValueSize) AND IN_bUseBuffer) THEN
			bSave := TRUE;
		END_IF

	END_IF

//===================================================================================
// Logging And Save

	CASE nStep OF 
		0 : (* Logging *)
			nErrId:=0; 
			bError:= FALSE; 
			bLostStorage := FALSE;
			bReWrite := FALSE;

			IF bSave THEN
				nStep := 1;
			END_IF 

		1 : (* Header Check*)	
			MEMSET(ADR(sHeaderCheck), 0, SIZEOF(sHeaderCheck));
			fbFileOpen( bExecute := FALSE );
			fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEREAD ); 
			nStep := 2;	

		2 : 
			fbFileOpen( bExecute := FALSE ); 
			IF NOT fbFileOpen.bBusy THEN 
				IF fbFileOpen.bError THEN
					bReWrite := TRUE;
					nStep := 10;
				ELSE		
					nStep := 3;
				END_IF
			END_IF 	

		3 : 
			fbFileRead(bExecute := FALSE);
			fbFileRead(bExecute := TRUE, pReadBuff := ADR(sHeaderCheck), cbReadLen := 4);	
			nStep := 4;

		4 :
			fbFileRead(bExecute := FALSE);
			IF NOT fbFileRead.bBusy THEN 
			    IF sHeaderCheck <> 'Date' THEN
					bReWrite := TRUE;
				END_IF
				nStep := 5;
			END_IF 

		5: (* File Close *)
			fbFileClose( bExecute := FALSE ); 
			fbFileClose( bExecute := TRUE); 
			nStep := 6;

		6: 
			fbFileClose( bExecute := FALSE ); 
			IF NOT fbFileClose.bBusy THEN 
			    IF fbFileClose.bError THEN 
				 	nErrId := fbFileClose.nErrId; 
				 	bError := TRUE; 
					nStep := 999;
				ELSE
					nStep := 10; 
			    END_IF   
			END_IF 


		10 : (* File Open *)
			fbFileOpen( bExecute := FALSE ); 
			IF bHeaderChanged OR bReWrite THEN
				fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEWRITE );  
			ELSE
				fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEAPPEND ); 
			END_IF
			nStep := 20;		

		20: 
			fbFileOpen( bExecute := FALSE ); 
			IF NOT fbFileOpen.bBusy THEN 
			    IF fbFileOpen.bError THEN 
					nErrId := fbFileOpen.nErrId; 
					bError := TRUE; 
					nStep := 999; 
					bLostStorage := SEL(bHeaderChanged OR bReWrite, FALSE, nErrId = 1804);
					// 여기서 Write모드로 썻는데 에러라면 D드라이브 없어서 그런거라고 볼수밖에 없나.
			    ELSE 
					nStep := SEL(bHeaderChanged OR bReWrite, 50, 30);
				END_IF 
			END_IF 

		30 : (* Header Write *)
			fbFileWrite( bExecute := FALSE ); 
			fbFileWrite( bExecute := TRUE, pWriteBuff := ADR(aBufferWriteHeader), cbWriteLen := nBufferWriteHeaderSize); 
			nStep := 40;

		40 : 
			fbFileWrite( bExecute := FALSE ); 
			IF NOT fbFileWrite.bBusy THEN 
			   IF fbFileWrite.bError THEN 
					nErrId := fbFileWrite.nErrId; 
					bError := TRUE; 
					nStep := 999; 
			   ELSE 
					nStep := 50; 
			   END_IF 
			END_IF 

		50 : (* Value Write *)
 			fbFileWrite( bExecute := FALSE ); 
			fbFileWrite( bExecute := TRUE, pWriteBuff := ADR(aBufferWriteValue), cbWriteLen := nBufferWriteValueSize); 
			nStep := 60;	

		60 : 
			fbFileWrite( bExecute := FALSE ); 
			IF NOT fbFileWrite.bBusy THEN 
			   IF fbFileWrite.bError THEN 
					nErrId := fbFileWrite.nErrId; 
					bError := TRUE; 
					nStep := 999; 
			   ELSE 
					nStep := 70; 
			   END_IF 
			END_IF 	

		70: (* File Close *)
			fbFileClose( bExecute := FALSE ); 
			fbFileClose( bExecute:=TRUE); 
			nStep := 80;

		80: 
			fbFileClose( bExecute := FALSE ); 
			IF NOT fbFileClose.bBusy THEN 
			    IF fbFileClose.bError THEN 
				 	nErrId := fbFileClose.nErrId; 
				 	bError := TRUE; 
					nStep := 999;
				ELSE
					nStep := 90; 
			    END_IF   
			END_IF 

		90: (* Complete *)
			bSave := FALSE;
			bHeaderChanged := FALSE;
			nBufferWriteValueSize := 0;
			MEMSET(ADR(aBufferWriteValue), 0, SIZEOF(aBufferWriteValue));
			nStep := 0;

		999: (* Error *)
			bSave := FALSE; 
			nErrorCnt := nErrorCnt + 1;
			nStep := 0;	//24.02.23 수정 (주석되어 있어서 에러 발생시 스텝 초기 안됨)

	END_CASE

	IF nStep <> 0 AND nStep <> 999 THEN
		nLastStep := nStep;
	END_IF

	OUT_bLossStorage := bLostStorage;
	OUT_bError := bError;
	OUT_nErrorID := nErrId;

	IF nStep = 999 OR OUT_bError THEN
		GDB.Error.USB_Error_Bit := TRUE;
	ELSE 
		GDB.Error.USB_Error_Bit := FALSE;
	END_IF

FUNCTION_BLOCK FB_TCPIP_OpenClose
VAR_INPUT

		IN_bEnable		: BOOL;
		IN_bReset		: BOOL;
		IN_sRemoteHost	: STRING;
		IN_nRemotePort	: UINT;	

END_VAR
VAR_OUTPUT

		OUT_nConnectState	: INT;
		OUT_nErrorCode		: UDINT;
		OUT_T_hSocket		: Tc2_TcpIp.T_HSOCKET;		

END_VAR
VAR

		va_nStep			: INT;
		va_TON				: ARRAY[1..3] OF TON;
		va_Reset			: PN_Pulse;			

		FB_SocketConnect	: FB_SocketConnect;
		FB_SocketClose		: FB_SocketClose;



END_VAR



	//Initialize =================================================================================================
	(*
		OUT_nConnectState

		0 : No Connection
		1 : Connection OK
		2 : Busy
		3 : Error
	*)
	OUT_nConnectState	:= 10#0;
	OUT_nErrorCode		:= 10#0;

	//Reset(Data Clear) ===========================================================================================
	va_Reset( in_Type := 1, in_Signal := IN_bReset);

	IF va_Reset.out_Pulse THEN

		va_nStep := 0;
		va_TON[1]( IN := FALSE);
		va_TON[2]( IN := FALSE);
		va_TON[3]( IN := FALSE);

	END_IF

	//FB_TCPIP_OpenClose_Start ====================================================================================
	IF IN_bEnable THEN

		CASE va_nStep OF

			//1. Socket Close Start
			0	:
					va_TON[1]( IN := IN_bEnable, PT := T#100MS);

					IF va_TON[1].Q THEN

						//FB_SocketClose CALL
						FB_SocketClose( bExecute := FALSE);

						IF OUT_T_hSocket.handle <> 0 THEN

							FB_SocketClose ( 	
											sSrvNetId 	:= '',
											hSocket		:= OUT_T_hSocket,
											bExecute	:= TRUE,
											tTimeout	:= T#3S);

						END_IF

						FB_SocketClose( bExecute := FALSE);

						va_nStep	:= 1;

					END_IF

			//2. Socket Open Start		
			1	:
					va_TON[2]( IN := IN_bEnable, PT := T#100MS);

					IF va_TON[2].Q THEN

						//FB_SocketConnect CALL
						FB_SocketConnect( bExecute := FALSE);

						FB_SocketConnect( 
											sSrvNetId  	:= '',
											sRemoteHost	:= IN_sRemoteHost,
											nRemotePort	:= IN_nRemotePort,
											bExecute	:= TRUE,
											tTimeout	:= T#15S);

						va_nStep	:= 2;

					END_IF

			//3. Socket State Check		
			2	:	
					FB_SocketConnect( bExecute := FALSE);

					IF FB_SocketConnect.bBusy THEN

						//OUT_nConnectState = 2, Busy
						OUT_nConnectState	:= 2;

					ELSIF FB_SocketConnect.bError THEN

						va_nStep	:= 4;

					ELSIF (NOT FB_SocketConnect.bBusy) AND (NOT FB_SocketConnect.bError) THEN

						va_nStep	:= 3;

					END_IF

			//4. Socket Open Complete		
			3	:
					OUT_nConnectState	:= 1;		
					OUT_T_hSocket		:= FB_SocketConnect.hSocket;

			//5. Socket Open Error		
			4	:			
					OUT_nConnectState	:= 3;
					OUT_nErrorCode		:= FB_SocketConnect.nErrId;

		END_CASE	

	ELSE

			//5. Socket Not Use(Not Wait, Docking Node)	
			va_TON[3]( IN := (IN_bEnable = FALSE), PT := T#100MS);

			IF va_TON[3].Q THEN

				//FB_SocketClose CALL
				FB_SocketClose( bExecute := FALSE);

				IF OUT_T_hSocket.handle <> 0 THEN

					FB_SocketClose ( 	
									sSrvNetId 	:= '',
									hSocket		:= OUT_T_hSocket,
									bExecute	:= TRUE,
									tTimeout	:= T#3S);

				END_IF

				FB_SocketClose( bExecute := FALSE);

			END_IF

	END_IF

FUNCTION_BLOCK Home_And_Limit_Search
VAR_INPUT
	in_No_Limit_Sensor	: BOOL;
	in_Start_Bit : BOOL;
	in_Stop_Bit : BOOL;
	in_Current_Pos : REAL;
	in_Home_Offset : REAL;
	in_HomeSensor_Bit_NO : BOOL;
	in_FW_Limit_Bit_NC : BOOL;
	in_BW_Limit_Bit_NC : BOOL;		
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Step : INT;
	out_Fail : BOOL;	
	out_Home_Pos : REAL;
	out_FW_Limit_Pos : REAL;
	out_BW_Limit_Pos : REAL;
	out_FW_Run_High : BOOL;
	out_FW_Run_Low : BOOL;
	out_BW_Run_High : BOOL;
	out_BW_Run_Low : BOOL;	
END_VAR
VAR
	Step : INT;
	TON : ARRAY[0..4] OF TON;
	PN_Pulse : ARRAY[0..1] OF PN_Pulse;
END_VAR


//초기화
out_Complete := FALSE;
out_Fail := FALSE;
out_FW_Run_High := FALSE;
out_FW_Run_Low := FALSE;
out_BW_Run_High := FALSE;
out_BW_Run_Low := FALSE;

//Start
PN_Pulse[1](in_Type:= 1, 
			in_Signal:= 	Step = 0 
						AND in_Start_Bit
						AND in_FW_Limit_Bit_NC = TRUE
						AND in_BW_Limit_Bit_NC = TRUE);
IF PN_Pulse[1].out_Pulse THEN
	Step := 1;	
	out_Home_Pos := 0;
	out_FW_Limit_Pos := 0;
	out_BW_Limit_Pos := 0;
END_IF;

//Stop
IF in_Stop_Bit THEN
	Step := 0;
END_IF

out_Step := Step;



//Step_1 : BW_Limit_Search
IF Step = 1 THEN
		out_BW_Run_High := TRUE;
	IF in_No_Limit_Sensor = FALSE AND in_BW_Limit_Bit_NC = FALSE THEN //BW_Limit 감지 시,
		out_BW_Limit_Pos := in_Current_Pos;
		Step := 3;				
	ELSIF in_No_Limit_Sensor AND in_HomeSensor_Bit_NO THEN //Home 감지 시,
		Step := 2;				
	END_IF;		
END_IF;
//Step_2 : Home_Detect
IF Step = 2 THEN
	out_BW_Run_Low := TRUE;
	TON[1](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
	IF TON[1].Q THEN
		Step := 3;
	END_IF;		
END_IF
//Step_3 : 	Home_Search
IF Step = 3 THEN
	out_FW_Run_High := TRUE;
	IF in_HomeSensor_Bit_NO THEN
		Step := 4;
	END_IF;
END_IF
//Step_4 : Home_Detect(FW_Run_Low)
IF Step = 4 THEN	
	out_FW_Run_Low := TRUE;
	TON[2](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
	IF TON[2].Q THEN
		Step := 5;
	END_IF;
END_IF;	
//Step_5 : Home_Detect(BW_Run_Low)
IF Step = 5 THEN
	out_BW_Run_Low := TRUE;
	IF in_HomeSensor_Bit_NO THEN
		Step := 6;
	END_IF;
END_IF;	
//Step_6 : 	Home_Set
IF Step = 6 THEN
	IF in_No_Limit_Sensor = FALSE AND in_HomeSensor_Bit_NO THEN				
		out_Home_Pos := in_Current_Pos - in_Home_Offset;
		Step := 7;
	ELSIF in_No_Limit_Sensor = TRUE AND in_HomeSensor_Bit_NO THEN				
		out_Home_Pos := in_Current_Pos - in_Home_Offset;
		out_Complete := TRUE;
		Step := 0;				
	END_IF;
END_IF; 	
//Step_7 : FW_Limit_Search
IF Step = 7 THEN
	out_FW_Run_High := TRUE;
	IF in_FW_Limit_Bit_NC = FALSE THEN
		out_FW_Limit_Pos := in_Current_Pos;				
		Step := 8;				
	END_IF	
END_IF
//Step_8 : BW_Move
IF Step = 8 THEN
	out_BW_Run_Low := TRUE;
	TON[3](IN:= in_FW_Limit_Bit_NC , PT:= T#1S);
	IF TON[3].Q THEN
		out_Complete := TRUE;
		Step := 0;			
	END_IF	
END_IF

//Timeout
TON[4](IN:= Step <> 0, PT:= T#300S);
IF TON[4].Q THEN
	out_Fail := TRUE;
	Step := 0;
END_IF

(*
	CASE Step OF
        1: //1 : BW_Limit_Search
			out_BW_Run_High := TRUE;
			IF in_BW_Limit_Bit_NC = FALSE THEN //BW_Limit 감지 시,
				out_BW_Limit_Pos := in_Current_Pos;
				Step := 3;				
			ELSIF in_Only_Home AND in_HomeSensor_Bit_NO THEN //Home 감지 시,
				Step := 2;				
			END_IF;		

		2: //2 : Home_Detect
			out_BW_Run_Low := TRUE;
			TON[1](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
				IF TON[1].Q OR in_BW_Limit_Bit_NC THEN
					Step := 3;
				END_IF;				
		3: //3 : Home_Search
			out_FW_Run_High := TRUE;
			IF in_HomeSensor_Bit_NO THEN
				Step := 4;
			END_IF;
		4: //4 : Home_Detect(FW_Run_Low)
			out_FW_Run_Low := TRUE;
				TON[2](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
				IF TON[2].Q THEN
					Step := 5;
				END_IF;
		5: //5 : Home_Detect(BW_Run_Low)
			out_BW_Run_Low := TRUE;
			IF in_HomeSensor_Bit_NO THEN
				Step := 6;
			END_IF
		6: //6 : Home_Set		
			IF in_Only_Home = FALSE AND in_Not_Move_Bit AND in_HomeSensor_Bit_NO THEN				
				out_Home_Pos := in_Current_Pos - in_Home_Offset;
				Step := 7;
			ELSIF in_Only_Home = TRUE AND in_Not_Move_Bit AND in_HomeSensor_Bit_NO THEN				
				out_Home_Pos := in_Current_Pos - in_Home_Offset;
				out_Complete := TRUE;
				Step := 0;				
			ELSIF in_Not_Move_Bit AND in_HomeSensor_Bit_NO = FALSE THEN
				out_Fail := TRUE;
				Step := 0;
			END_IF;
		7: //7 : FW_Limit_Search
			out_FW_Run_High := TRUE;
			IF in_FW_Limit_Bit_NC THEN
				out_FW_Limit_Pos := in_Current_Pos;				
				Step := 8;				
			END_IF	
		8: //8 : BW_Move
			out_BW_Run_Low := TRUE;
			TON[3](IN:= in_FW_Limit_Bit_NC , PT:= T#1S);
			IF TON[3].Q THEN
				out_Complete := TRUE;
				Step := 0;			
			END_IF
	ELSE
        Step := 0;
    END_CASE;
*)


