FUNCTION_BLOCK IPS208i_Recieve
VAR_INPUT
	in_bStart					:BOOL;
	in_array_ByRcvData			:ARRAY[0..100] OF BYTE;
END_VAR
VAR_OUTPUT
	out_bComplete				:BOOL;
	out_iStatus					:INT;
	out_realXpos				:REAL;
	out_realYpos				:REAL;
	out_iQuality				:INT;
END_VAR
VAR
	va_Array_ByRcvData			:ARRAY[0..100] OF BYTE;
	//String_Data
	sStatus						:STRING;
	sXpos						:STRING;
	sYpos						:STRING;
	sQuality					:STRING;
	//Data_Buffer
	Buffer_iStatus				:INT;
	Buffer_realXpos				:REAL;
	Buffer_realYpos				:REAL;
	Buffer_iQuality				:INT;
END_VAR


IF  in_bStart = TRUE THEN

    //변수 초기화     
     out_bComplete := FALSE;
	//In 변수를 Var 변수로 이동
    MEMCPY(destAddr:=ADR(va_Array_ByRcvData[0]) , srcAddr:=ADR(in_array_ByRcvData[0]) , n:= SIZEOF(in_array_ByRcvData));


    IF  va_Array_ByRcvData[0] = 16#53	AND		//'S'
		va_Array_ByRcvData[1] = 16#74	AND		//'t'
		va_Array_ByRcvData[2] = 16#61	AND		//'a'
		va_Array_ByRcvData[3] = 16#74	AND		//'t'
		va_Array_ByRcvData[4] = 16#75	AND		//'u'
		va_Array_ByRcvData[5] = 16#73	THEN	//'s'

		//X,Y Pos 쉼표 > 점으로 변경
		va_Array_ByRcvData[20] := 16#2E;
		va_Array_ByRcvData[34] := 16#2E;

		//ByteArray_TO_StringData
		MEMCPY(destAddr:=ADR(sStatus) , srcAddr:=ADR(va_Array_ByRcvData[8]) , n:= 10#1); // Status Value(String)
		MEMCPY(destAddr:=ADR(sXpos) , srcAddr:=ADR(va_Array_ByRcvData[14]) , n:= 10#9); // Status Value(String), va_array_ByRcvData[13]이 부호(2B:+, 2D:-)
		MEMCPY(destAddr:=ADR(sYpos) , srcAddr:=ADR(va_Array_ByRcvData[28]) , n:= 10#9);  // Status Value(String), va_array_ByRcvData[27]이 부호(2B:+, 2D:-)
		MEMCPY(destAddr:=ADR(sQuality) , srcAddr:=ADR(va_Array_ByRcvData[47]) , n:= 10#3); // Status Value(String)

		//StringData_TO_BufferData
		Buffer_iStatus := STRING_TO_INT(sStatus);		
		Buffer_realXpos := STRING_TO_REAL(sXpos);
		Buffer_realYpos := STRING_TO_REAL(sYpos);
		Buffer_iQuality := STRING_TO_INT(sQuality);
		IF va_Array_ByRcvData[13] = 16#2D THEN //Xpos 부호처리
			Buffer_realXpos := -1 * Buffer_realXpos;
		END_IF
		IF va_Array_ByRcvData[27] = 16#2D THEN //Xpos 부호처리
			Buffer_realYpos := -1 * Buffer_realYpos;
		END_IF

		//BufferData_TO_Output
		out_iStatus := Buffer_iStatus;		
		out_realXpos := Buffer_realXpos;
		out_realYpos := Buffer_realYpos;
		out_iQuality := Buffer_iQuality;


		out_bComplete := TRUE;
	END_IF
END_IF

