FUNCTION_BLOCK PILZ_Recieve
VAR_INPUT
	in_bStart					:BOOL;
	in_array_ByRcvData			:ARRAY[0..42] OF BYTE;
END_VAR

VAR_OUTPUT
	out_bComplete				:BOOL;
	out_bFormatError			:BOOL;
	out_array_ByIOData			:ARRAY[0..15] OF BYTE;
	out_ByTableNum				:BYTE;
	out_BySegmentNum			:BYTE;
	out_array_ByPayload			:ARRAY[0..12] OF BYTE;	
END_VAR

VAR
	static_ByBCC_Sum			:BYTE;
	static_iForIndex			:INT;
END_VAR


IF  in_bStart = TRUE THEN

    //변수 초기화
     out_bFormatError := false;
     out_bComplete := false;
     static_ByBCC_Sum := 0;

    //BCC 계산
    FOR  static_iForIndex := 10#4 TO 10#39 BY 10#1 DO
         static_ByBCC_Sum :=  static_ByBCC_Sum +  in_array_ByRcvData[ static_iForIndex];
    END_FOR;
     static_ByBCC_Sum := UINT_TO_BYTE(16#100 -  static_ByBCC_Sum);

    //BCC OK
    IF  static_ByBCC_Sum =  in_array_ByRcvData[41] THEN

        MEMMOVE(destAddr:=ADR(out_array_ByIOData[0]) , srcAddr:=ADR(in_array_ByRcvData[8]) , n:=10#16 );

        out_ByTableNum :=  in_array_ByRcvData[25]; // Table Number.
        out_BySegmentNum :=  in_array_ByRcvData[26]; // Segment Number.

		MEMMOVE(destAddr:=ADR(out_array_ByPayload[0]) , srcAddr:=ADR(in_array_ByRcvData[27]) , n:=10#16 ); 

		out_bComplete := TRUE;
    END_IF;

    //BCC NG
    IF  static_ByBCC_Sum <>  in_array_ByRcvData[41] THEN
         out_bFormatError := TRUE;
    END_IF;

END_IF;

IF  in_bStart = FALSE THEN
     out_bComplete := FALSE;
     out_bFormatError := FALSE;
END_IF;

FUNCTION_BLOCK PILZ_Send
VAR_INPUT
	in_bStart				:BOOL;
	in_array_ByIOdata		:ARRAY[0..15] OF BYTE;
	in_ByTableNo			:BYTE;
	in_BySegmentNo			:BYTE;
END_VAR
VAR_OUTPUT
	out_bComplete			:BOOL;
	out_array_BySendData	:ARRAY[0..42] OF BYTE;
END_VAR
VAR
	static_iForIndex		:INT;
END_VAR


IF  in_bStart = TRUE THEN

     out_bComplete := false;

     out_array_BySendData[0] := 16#05; //Byte0
     out_array_BySendData[1] := 16#15; //Byte1
     out_array_BySendData[2] := 16#00; //Byte2
     out_array_BySendData[3] := 16#26; //Byte3
     out_array_BySendData[4] := 16#5C; //Byte4
     out_array_BySendData[5] := 16#63; //Byte5_Controlbyte
     out_array_BySendData[6] := 16#00; //Byte6
     out_array_BySendData[7] := 16#00; //Byte7

     MEMCPY(destAddr:=ADR(out_array_BySendData[8]) , srcAddr:=ADR(in_array_ByIOdata[0]) , n:=SIZEOF(in_array_ByIOdata) );

     out_array_BySendData[25] :=  in_ByTableNo;//Byte25 : Table Number
     out_array_BySendData[26] :=  in_BySegmentNo;//Byte26 : Segment Sumber
     out_array_BySendData[27] := 16#00;//Byte27
     out_array_BySendData[28] := 16#00;//Byte28
     out_array_BySendData[29] := 16#00;//Byte29
     out_array_BySendData[30] := 16#00;//Byte30
     out_array_BySendData[31] := 16#00;//Byte31
     out_array_BySendData[32] := 16#00;//Byte32
     out_array_BySendData[33] := 16#00;//Byte33
     out_array_BySendData[34] := 16#00;//Byte34
     out_array_BySendData[35] := 16#00;//Byte35
     out_array_BySendData[36] := 16#00;//Byte36
     out_array_BySendData[37] := 16#00;//Byte37
     out_array_BySendData[38] := 16#00;//Byte38
     out_array_BySendData[39] := 16#00;//Byte39
     out_array_BySendData[40] := 16#00;//Byte40

     out_array_BySendData[41] := 16#00;//Byte41 : BCC(Byte4~39 Cehcksum);
    FOR  static_iForIndex := 10#4 TO 10#39 BY 10#1 DO
         out_array_BySendData[41] :=  out_array_BySendData[41] +  out_array_BySendData[ static_iForIndex];
    END_FOR;
     out_array_BySendData[41] := UINT_TO_BYTE(16#100 -  out_array_BySendData[41]);

     out_array_BySendData[42] := 16#10;//Byte42

     out_bComplete := TRUE;

END_IF;

IF  in_bStart = FALSE THEN
     out_bComplete := FALSE;
END_IF;

