FUNCTION_BLOCK Position_Control

VAR_INPUT
in_bStart							:BOOL;
in_iTarget_position_mm				:REAL;
in_iActual_position_mm				:REAL;
in_iTarget_High_Speed_mpm			:REAL;
in_iTarget_Low_Speed_mpm			:REAL;
in_iActual_Speed_mps				:REAL;
in_iAccel_Speed_mps2				:REAL;
in_iDecel_Speed_mps2				:REAL;
in_Decel_Distance_Offset_mm			:REAL;
in_InPosition_mm					:REAL;
in_Speed_0_Direction_0_Bit			:BOOL;
END_VAR

VAR_OUTPUT
out_bTarget_reached					:BOOL;
out_iDirection						:INT;
out_Output_Value_mpm				:REAL;
END_VAR

VAR
static_Decel_Distance_mm			:REAL;
static_Decel_Distance_Offset_mm 	:REAL;
END_VAR


 out_bTarget_reached := 0;
 out_iDirection := 0;
 out_Output_Value_mpm := 0;
// Decel_Distance (감속 거리 계산)
// 감속 거리 = (-1/2) * ( 현재속도^2 / 감속도 )
// [단위 m/s]
IF in_bStart AND in_iDecel_Speed_mps2 <> 0 THEN
 static_Decel_Distance_mm := ((0.5) * ( in_iActual_Speed_mps *  in_iActual_Speed_mps) /  in_iDecel_Speed_mps2) * 1000 ;
 //static_Decel_Distance_Offset_mm := in_Decel_Distance_Offset_mm + in_iActual_Speed_mps*0.1; //Offset 값 + 100ms동안 움직인 거리(반응속도)
 static_Decel_Distance_Offset_mm := in_Decel_Distance_Offset_mm ; //Offset 값 + 100ms동안 움직인 거리(반응속도)
//목표위치가 현재위치보다 큰 경우
IF  in_iTarget_position_mm >  in_iActual_position_mm THEN
    IF ( in_iTarget_position_mm -  in_iActual_position_mm) > ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //고속으로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_High_Speed_mpm;
    END_IF;

    IF ( in_iTarget_position_mm -  in_iActual_position_mm) < ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //저속으로 2로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_Low_Speed_mpm;
    END_IF;

    IF ABS( in_iTarget_position_mm -  in_iActual_position_mm) <  in_InPosition_mm THEN //In Position 값 설정
         out_Output_Value_mpm := 0;
        IF  in_iActual_Speed_mps = 0 THEN
             out_bTarget_reached := 1;
        END_IF;
    END_IF;
     out_iDirection := 1;
END_IF;

//목표위치가 현재위치보다 작은 경우
IF  in_iTarget_position_mm <  in_iActual_position_mm THEN
    IF ( in_iActual_position_mm -  in_iTarget_position_mm) > ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //목표속도 1로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_High_Speed_mpm;
    END_IF;

    IF ( in_iActual_position_mm -  in_iTarget_position_mm) < ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //목표속도 2로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_Low_Speed_mpm;
    END_IF;

    IF ABS( in_iActual_position_mm -  in_iTarget_position_mm) <  in_InPosition_mm THEN //In Position 값 설정
         out_Output_Value_mpm := 0;
        IF  in_iActual_Speed_mps = 0 THEN
             out_bTarget_reached := 1;
        END_IF;
    END_IF;
     out_iDirection := 2;
END_IF;

IF  in_iTarget_position_mm =  in_iActual_position_mm AND  in_iActual_Speed_mps = 0 THEN
     out_bTarget_reached := 1;
END_IF;


// in_Speed_0_Direction_0_Bit : 속도가 0일 때에, 방향 비트를 0으로 할 것인지 아니면 그대로 출력할 것인지 선택_
IF  in_Speed_0_Direction_0_Bit = 1 AND  out_Output_Value_mpm = 0 THEN    
         out_iDirection := 0;    
END_IF;


END_IF;

