	 MEMSET(destAddr:=ADR(StringData[1]) , fillByte:=16#0 , n:=SIZEOF(StringData)); //String Data Clear
	 MEMSET(destAddr:=ADR(DataPositionNo[1]) , fillByte:=16#0 , n:=SIZEOF(DataPositionNo)); //DataPoisitionNo Clear
  	 MEMMOVE(destAddr:=ADR(Static_Array_ByRcvData[1]) , srcAddr:= ADR(in_Array_ByRcvData[1]) , n:= 200 ); 

	IF  Static_Array_ByRcvData[1] = 16#02 AND  Static_Array_ByRcvData[3] = 16#41 THEN
        // 공백을 카운팅 해서 데이타를 구분한다.

		//[Byte_Array >>> String] Data Conversion   
        WHILE  Static_Array_ByRcvData[Static_iIndex1] > 0  DO // 0값이 나올때 까지 또는 200바이트 이상 일때 

            IF  Static_Array_ByRcvData[Static_iIndex1] = 16#20 OR  Static_Array_ByRcvData[Static_iIndex1] = 16#03  THEN
                 Static_iSpaceCount :=  Static_iSpaceCount + 1; //공백을 카운팅 한다. 구분선 역할                												

						MEMMOVE(destAddr:=ADR(StringData[Static_iSpaceCount]) , srcAddr:= ADR(Static_Array_ByRcvData[Static_iPrePos]) , n:= INT_TO_UDINT(Static_iIndex1 -  Static_iPrePos) ); //Byte Array 에서 String으로 데이터 이동						                        
                        DataPositionNo[Static_iSpaceCount] :=  Static_iIndex1 -  Static_iPrePos;  //자릿수 구하기
						Static_iPrePos :=  Static_iIndex1 + 1 ; //이전 시작위치 저장						                
            END_IF;

             Static_iIndex1 :=  Static_iIndex1 + 1; //다음 바이트 

        END_WHILE; //공백 검출


		//[HexString >> DINT] Data Conversion
        IF  StringData[1] = 'sAN' AND  StringData[2] = 'mNPOSGetPose' AND  StringData[6] = '1' AND  StringData[4] = '0' THEN            
            //16진수로 변환
			FOR Static_iIndex1 := 3 TO 10#16 DO // 1,2는 Header라 제외
				Buffer := HEXSTR_TO_DATA(sHex:=StringData[Static_iIndex1] , pData:=ADR(Conversion_Buffer_Byte[1]) , cbData:=SIZEOF(Conversion_Buffer_Byte));
				DataBuffer[Static_iIndex1] := 0;
				FOR Static_iIndex2 := 1 TO 4 DO
						Conversion_Buffer_Dint[Static_iIndex2] := BYTE_TO_DINT(Conversion_Buffer_Byte[Static_iIndex2]);
						IF (DataPositionNo[Static_iIndex1] - (2*Static_iIndex2)) > 0 THEN
							Conversion_Buffer_Dint[Static_iIndex2] := SHL(Conversion_Buffer_Dint[Static_iIndex2],((DataPositionNo[Static_iIndex1] - (2*Static_iIndex2))*4));
						END_IF
						DataBuffer[Static_iIndex1] := (DataBuffer[Static_iIndex1] OR Conversion_Buffer_Dint[Static_iIndex2]);
				END_FOR
			END_FOR



            //Output(Data Type Conversion)
             out_Version :=  DINT_TO_INT(DataBuffer[3]);
             out_ErrorCode :=  DINT_TO_INT(DataBuffer[4]);
             out_Wait :=  DINT_TO_INT(DataBuffer[5]);
             out_PoseData :=  DINT_TO_INT(DataBuffer[6]);
             out_Xpos_mm := DINT_TO_REAL( DataBuffer[7]);
             out_Ypos_mm := DINT_TO_REAL( DataBuffer[8]);
             out_Angle_us360 := DINT_TO_REAL(DataBuffer[9])/1000;
             out_optPoseData :=  DINT_TO_INT(DataBuffer[10]);
             out_Output_Mode :=  DINT_TO_INT(DataBuffer[11]);
             out_TimeStamp_ms :=  DataBuffer[12];
             out_MeanDev_mm :=  DINT_TO_INT(DataBuffer[13]);
             out_NavMode :=  DINT_TO_INT(DataBuffer[14]);
             out_InfoState :=  DataBuffer[15];
             out_NumUsedReflectors :=  DINT_TO_INT(DataBuffer[16]);


             Complete := 1;
        END_IF;

    END_IF;




END_IF;

FUNCTION_BLOCK Tabos_Battery_Receive
VAR_INPUT
	in_Enable : BOOL;
	in_Address : INT;
	in_Data : ARRAY[1..19] OF BYTE;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Receive_Fail : BOOL;
	out_Voltage_V : REAL;
	out_Current_A : REAL;
	out_SOC_Percentage : INT;
	out_Error : UINT;
	out_Temperature : REAL;
END_VAR
VAR
	bu_Checksum : BYTE;
	Test0 : UINT;
END_VAR


out_Complete := FALSE;
out_Receive_Fail := FALSE;
(*
out_Voltage_V := 0;
out_Current_A := 0;
out_SOC_Percentage := 0;
out_Error := 0;
out_Temperature := 0;
*)





IF in_Enable THEN
	//CheckSum := Adrress(3) + Length(4) + Command(5) + Order(6) + Data1 + Data 2 ... Data 10
	bu_Checksum := UINT_TO_BYTE((in_Data[3]+in_Data[4]+in_Data[5]+in_Data[6]+in_Data[7]+in_Data[8]+in_Data[9]+in_Data[10]+in_Data[11]+in_Data[12]+in_Data[13]+
					in_Data[14]+in_Data[15]+in_Data[16]) MOD (16#100));


	IF in_Data[1] = 16#AF AND in_Data[2] = 16#FA AND in_Data[17] = bu_Checksum AND in_Data[18] = 16#AF AND in_Data[19] = 16#A0 THEN
		//out_Voltage_V 
		out_Voltage_V := UINT_TO_REAL(BYTE_TO_UINT(in_Data[8]) + SHL(BYTE_TO_UINT(in_Data[7]),8))/100;
		//out_Current_A 
		out_Current_A := INT_TO_REAL(BYTE_TO_INT(in_Data[10]) + SHL(BYTE_TO_INT(in_Data[9]),8))/100;
		//out_SOC_Percentage 
		out_SOC_Percentage := BYTE_TO_INT(in_Data[12]);
		//out_Error (Bit Data)
				//0 배터리 과전압 		8 배터리 과전압
				//1 배터리 저전압 		9 배터리 저전압
				//2 충전 전류 과다 		10 충전 전류 과다
				//3 방전 전류 과다 		11 방전 전류 과다
				//4 고온도 				12 고온도
				//5 저온도 				13 저온도
				//6 BMU 에러 			14 -
				//7 - 					15 -
		out_Error := BYTE_TO_UINT(in_Data[14]) + SHL(BYTE_TO_UINT(in_Data[13]),8);
		//out_Temperature 
		out_Temperature := UINT_TO_REAL(BYTE_TO_UINT(in_Data[16]) + SHL(BYTE_TO_UINT(in_Data[15]),8))/10;

		out_Complete := TRUE;

	ELSE
		out_Receive_Fail := TRUE;
	END_IF

END_IF

FUNCTION_BLOCK TCPIP_OpenClose
VAR_INPUT
	in_bEnable 			:BOOL;
	in_bReset			:BOOL;
	in_sRemoteHost		:STRING;
	in_nRemotePort		:UINT;

END_VAR
VAR_OUTPUT
	// 	0 : No Connection
	//	1 : Busy
	//	2 : Error
	//	3 : Connection OK
	out_ConnectState	:INT;
	out_ErrorCode		:UDINT;
	out_T_hSocket		:Tc2_TcpIp.T_HSOCKET;		
END_VAR
VAR
	Step : UINT;	
	TON_1 : TON;
	TON_2 : TON;
	TON_3 : TON;
	TON_4 : TON;
	TON_5 : TON;

	PN_Pulse : PN_Pulse;

	FB_SocketConnect : FB_SocketConnect;
	FB_SocketClose : FB_SocketClose;
	Open_Excute : BOOL;
	Close_Excute : BOOL;
	T_hSocket_Buffer : T_HSOCKET;
END_VAR


//Initualize
out_ConnectState := 10#0;
out_ErrorCode :=10#0;
//Reset(Data Clear)
PN_Pulse(in_Type:= 1, in_Signal:= in_bReset);
IF PN_Pulse.out_Pulse THEN
	Step := 0;
	TON_1(IN:=FALSE);
	TON_2(IN:=FALSE);
	Open_Excute := FALSE;
	Close_Excute := FALSE;
END_IF

IF in_bEnable THEN	
	CASE step OF
		0:	//Socket Close Start					
			TON_1(IN:=TRUE,PT:=T#100MS);
			IF TON_1.Q THEN
				//FB_SocketClose Call				
				FB_SocketClose(bExecute:=FALSE);
				IF out_T_hSocket.handle <> 0 THEN
					FB_SocketClose( sSrvNetId:='', 
					hSocket:=out_T_hSocket, 
					bExecute:=TRUE, 
					tTimeout:=T#3S);
				END_IF;	
				Step := 1;
				FB_SocketClose(bExecute:=FALSE);
			END_IF			
		1:	//Socket Open Start									
			TON_2(IN:=TRUE,PT:=T#100MS);
			IF TON_1.Q THEN
				//FB_SocketConnect Call				
				FB_SocketConnect( bExecute:=FALSE );		
				FB_SocketConnect(sSrvNetId:='',
				 sRemoteHost:=in_sRemoteHost, 
				 nRemotePort:=in_nRemotePort, 
				 bExecute:=TRUE, 
				 tTimeout:=T#15S,				 
				);		
				Step := 2;
			END_IF	
		2:		//Socket State Check
				FB_SocketConnect(bExecute:=FALSE);
				IF FB_SocketConnect.bBusy THEN
					out_ConnectState := 2;			
				ELSIF FB_SocketConnect.bError THEN
					Step := 4;				
				ELSIF (NOT FB_SocketConnect.bBusy) AND (NOT FB_SocketConnect.bError) THEN
					Step := 3;
				END_IF	

		3:	//Socket Open Complete
				out_ConnectState := 1;
				out_T_hSocket := FB_SocketConnect.hSocket;		
		4:	//Socket Open Error
			out_ConnectState := 3;
			out_ErrorCode := FB_SocketConnect.nErrId;		
	END_CASE


ELSE
	out_ConnectState := 0;	
	Step := 0;	
END_IF;

FUNCTION_BLOCK TCPIP_Server_OpenClose
VAR_INPUT
	in_Enable 			:BOOL;
	in_Server_Reset		:BOOL;
	in_Client_Reset		:BOOL;
	in_LocalHost		:STRING;
	in_LocalPort		:UINT;	
END_VAR
VAR_OUTPUT
	// 	0 : No Connection
	//	1 : Connection OK
	// 	2 : Connection IDLE
	//	5 : Listen Socket Open Busy
	//	6 : Listen Socket Open Error
	//	7 : Client Socket Open Busy
	//	8 : Client Socket Open Error

	out_ConnectState	:INT;
	out_ErrorCode		:UDINT;
	out_T_hSocket		:T_HSOCKET;		
END_VAR
VAR
	Step : UINT;	
	TON : ARRAY[0..4] OF TON;
	PN_Pulse : ARRAY[0..2] OF PN_Pulse;
	FB_SocketListen : FB_SocketListen;
	FB_SocketAccept : FB_SocketAccept;	
	FB_SocketClose_Listen : FB_SocketClose;
	FB_SocketClose_Client : FB_SocketClose;



END_VAR

//Initualize
out_ConnectState := 10#0;
out_ErrorCode :=10#0;
//Reset(Data Clear)
PN_Pulse[1](in_Type:= 1, in_Signal:=in_Server_Reset);
PN_Pulse[2](in_Type:= 1, in_Signal:=in_Client_Reset);
IF PN_Pulse[1].out_Pulse THEN
	Step := 0;
	TON[1](IN:=FALSE);
	TON[2](IN:=FALSE);
	TON[3](IN:=FALSE);
	TON[4](IN:=FALSE);
ELSIF PN_Pulse[2].out_Pulse THEN	
	Step := 100;
	TON[3](IN:=FALSE);
	TON[4](IN:=FALSE);
END_IF

IF in_Enable THEN	
	CASE step OF
		0:  Step := 1;
		1:	//Listen Socket Close Start					
			TON[1](IN:=TRUE,PT:=T#100MS);
			IF TON[1].Q THEN
				IF FB_SocketListen.hListener.handle <> 0 THEN
					//FB_SocketClose Call				
					FB_SocketClose_Listen(bExecute:=FALSE);
					FB_SocketClose_Listen( sSrvNetId:='', 
					hSocket:=FB_SocketListen.hListener, 
					bExecute:=TRUE, 
					tTimeout:=T#3S);
				END_IF;
				Step := 10;
			END_IF;
		10:	//Listen Socket Open Start
			FB_SocketClose_Listen(bExecute:=FALSE);
			TON[2](IN:=TRUE,PT:=T#1S);
			IF TON[1].Q THEN
				FB_SocketListen(bExecute:= FALSE);
				FB_SocketListen(sSrvNetId:= '', 
								sLocalHost:= in_LocalHost, 
								nLocalPort:= in_LocalPort, 
								bExecute:= TRUE);
				Step := 20;
			END_IF;
		20: //Listen Socket State Check
			FB_SocketListen(bExecute:= FALSE);
			IF FB_SocketListen.bBusy THEN
				out_ConnectState := 5;			
			ELSIF FB_SocketListen.bError THEN
				Step := 30;				
			ELSIF (NOT FB_SocketListen.bBusy) AND (NOT FB_SocketListen.bError) THEN
				Step := 100;
			END_IF	
		30: //Listen Socket State Error
			out_ConnectState := 6;
			out_ErrorCode := FB_SocketListen.nErrId;	




		100:	//Client Socket Close Start					
			TON[3](IN:=TRUE,PT:=T#100MS);
			IF TON[3].Q THEN
				IF FB_SocketAccept.hSocket.handle <> 0 THEN
					//FB_SocketClose Call				
					FB_SocketClose_Client(bExecute:=FALSE);
					FB_SocketClose_Client( sSrvNetId:='', 
					hSocket:=FB_SocketAccept.hSocket, 
					bExecute:=TRUE, 
					tTimeout:=T#3S);
				END_IF;
				Step := 110;
			END_IF




		110:	//Client Socket Open Start			
			FB_SocketClose_Client(bExecute:=FALSE);
			out_ConnectState := 2;						
			TON[4](IN:=TRUE,PT:=T#1S);
			IF TON[4].Q THEN
				//FB_SocketConnect Call				
				FB_SocketAccept( bExecute:=FALSE );		
				FB_SocketAccept(sSrvNetId:= '', 
								hListener:= FB_SocketListen.hListener, 
								bExecute:= TRUE, 
								tTimeout:= T#3S);						
				Step := 120;
			END_IF	
		120:	//Client Socket State IDLE
				FB_SocketAccept( bExecute:=FALSE );	
				out_ConnectState := 2;					
				IF FB_SocketAccept.bBusy THEN
					out_ConnectState := 7;			
				ELSIF FB_SocketAccept.bError THEN
					Step := 140;				
				ELSIF FB_SocketAccept.bAccepted AND (NOT FB_SocketAccept.bBusy) AND (NOT FB_SocketAccept.bError) THEN
					Step := 130;
				ELSIF out_ConnectState = 2 THEN
					TON[4](IN:=FALSE,PT:=T#1S);
					Step := 110;
				END_IF;

		130:	//Client Socket Open Complete
				out_ConnectState := 1;
				out_T_hSocket := FB_SocketAccept.hSocket;		
		140:	//Client Socket Open Error
			out_ConnectState := 8;
			out_ErrorCode := FB_SocketAccept.nErrId;		
	END_CASE
ELSE
	out_ConnectState := 0;	
	Step := 0;	
END_IF;

FUNCTION_BLOCK UDPIP_OpenClose
VAR_INPUT
	in_bEnable 			:BOOL;
	in_bReset			:BOOL;
	in_sLocalHost		:STRING;
	in_nLocalPort		:UINT;

END_VAR
VAR_OUTPUT
	// 	0 : No Connection
	//	1 : Busy
	//	2 : Error
	//	3 : Connection OK
	out_ConnectState	:INT;
	out_ErrorCode		:UDINT;
	out_T_hSocket		:Tc2_TcpIp.T_HSOCKET;		
END_VAR
VAR
	Step : UINT;	
	TON_1 : TON;
	TON_2 : TON;
	TON_3 : TON;
	TON_4 : TON;
	TON_5 : TON;

	FB_SocketUdpCreate : FB_SocketUdpCreate;
	FB_SocketClose : FB_SocketClose;
	Open_Excute : BOOL;
	Close_Excute : BOOL;
	T_hSocket_Buffer : T_HSOCKET;
END_VAR


//Initualize
out_ConnectState := 10#0;
out_ErrorCode :=10#0;
//Reset(Data Clear)
IF in_bReset THEN
	Step := 0;
	TON_1(IN:=FALSE);
	TON_2(IN:=FALSE);
	Open_Excute := FALSE;
	Close_Excute := FALSE;
END_IF

IF in_bEnable THEN	
	CASE step OF
		0:	//Socket Close Start					
			TON_1(IN:=TRUE,PT:=T#100MS);
			IF TON_1.Q THEN
				//FB_SocketClose Call				
				FB_SocketClose(bExecute:=FALSE);
				FB_SocketClose( sSrvNetId:='', 
				hSocket:=out_T_hSocket, 
				bExecute:=TRUE, 
				tTimeout:=T#3S);
				Step := 1;
				FB_SocketClose(bExecute:=FALSE);
			END_IF			
		1:	//Socket Open Start									
			TON_2(IN:=TRUE,PT:=T#100MS);
			IF TON_1.Q THEN
				//FB_SocketConnect Call				
				FB_SocketUdpCreate( bExecute:=FALSE );		
				FB_SocketUdpCreate(sSrvNetId:='',
				 sLocalHost:=in_sLocalHost, 
				 nLocalPort:=in_nLocalPort, 
				 bExecute:=TRUE, 
				 tTimeout:=T#15S,				 
				);		
				Step := 2;
			END_IF	
		2:		//Socket State Check
				FB_SocketUdpCreate(bExecute:=FALSE);
				IF FB_SocketUdpCreate.bBusy THEN
					out_ConnectState := 2;			
				ELSIF FB_SocketUdpCreate.bError THEN
					Step := 4;				
				ELSIF (NOT FB_SocketUdpCreate.bBusy) AND (NOT FB_SocketUdpCreate.bError) THEN
					Step := 3;
				END_IF	

		3:	//Socket Open Complete
				out_ConnectState := 1;
				out_T_hSocket := FB_SocketUdpCreate.hSocket;		
		4:	//Socket Open Error
			out_ConnectState := 3;
			out_ErrorCode := FB_SocketUdpCreate.nErrId;		
	END_CASE

ELSE
	out_ConnectState := 0;	
	Step := 0;	
END_IF;

FUNCTION_BLOCK Virtual_Coordinate
VAR_INPUT
	in_bStart							:BOOL;
	in_bRenew_bit						:BOOL;
	in_diLaser_Xpos						:REAL;
	in_diLaser_Ypos						:REAL;
