/////////////////////////////////// in변수를 static변수로 변환(모두 Real타입으로 변경)///////////////////////////////////////////////
 static_Laser_Xpos :=  in_diLaser_Xpos;
 static_Laser_Ypos :=  in_diLaser_Ypos;

 static_Laser_Angle := ( in_iLaser_Angle); ////Absolute_Angle = -(PGV각도 - +X의 각도) //// 추후에 나누기10 해줘야함_****
IF  static_Laser_Angle < 0 THEN
     static_Laser_Angle :=  static_Laser_Angle + 360;
ELSIF  static_Laser_Angle >= 360 THEN
     static_Laser_Angle :=  static_Laser_Angle - 360;
END_IF;



 static_r_FW_Count_Encoder := DINT_TO_REAL( in_di_FW_Count_Encoder);
 static_r_BW_Count_Encoder := DINT_TO_REAL( in_di_BW_Count_Encoder);
 static_rDriving_Motor_gear_ratio :=  in_iDriving_Motor_gear_ratio;
 static_rWheel_diameter :=  in_iWheel_diameter;

 static_rFW_Wheel_Angle := ( in_rFW_Wheel_Angle - 180) ; //앞바퀴 각도( Default : 0 )
 static_rBW_Wheel_Angle := ( in_rBW_Wheel_Angle - 180); //앞바퀴 각도( Default : 0 )
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////변환 완료





////////////////////////////////////QR TAG 감지 시, 앞바퀴/뒷바퀴의 좌표값 시작위치 지정///////////////////////////////////////////////////////
IF ( in_bRenew_bit = 1) THEN

     out_rCurrent_Coordinate_X :=  static_Laser_Xpos; // Laser X 좌표 반영
     out_rCurrent_Coordinate_Y :=  static_Laser_Ypos; // Laser Y 좌표 반영
         out_rCurrent_AGV_Angle :=  static_Laser_Angle;



       (*
        (*앞바퀴/뒷바퀴 [X, Y 좌표] 값 생성*)
         Buffer_"rFW_X_POS(Virtual)" :=  "out_rCurrent_Coordinate[X]_[mm]" + (543_920950 * COS(( static_"Laser_Angle(360)" - 29_156918) * 0_0174533));
         Buffer_"rFW_Y_POS(Virtual)" :=  "out_rCurrent_Coordinate[Y]_[mm]" + (543_920950 * SIN(( static_"Laser_Angle(360)" - 29_156918) * 0_0174533));

         Buffer_"rBW_X_POS(Virtual)" :=  "out_rCurrent_Coordinate[X]_[mm]" + (543_920950 * COS(( static_"Laser_Angle(360)" + 150_843082) * 0_0174533));
         Buffer_"rBW_Y_POS(Virtual)" :=  "out_rCurrent_Coordinate[Y]_[mm]" + (543_920950 * SIN(( static_"Laser_Angle(360)" + 150_843082) * 0_0174533));

         Buffer_"rAGV_ANGLE(Virtual)" :=  out_rCurrent_AGV_Angle;
        (*
         "out_rTAG_Xpos(Virtual)" :=  static_rTAG_Xpos; // QR코드 감지시에는 PGV에서 들어온 값을 바로 OUT값으로 내보냄
         "out_rTAG_Ypos(Virtual)" :=  static_rTAG_Ypos; // QR코드 감지시에는 PGV에서 들어온 값을 바로 OUT값으로 내보냄
         "out_rTAG_Angle(Virtual)" :=  static_"rTAG_Angle(3600)"; // QR코드 감지시에는 PGV에서 들어온 값을 바로 OUT값으로 내보냄
        *)
        *)

         Buffer_rPre_FW_Count_Encoder := 0; //이전 Incremental Encoder Count 클리어
         Buffer_rPre_BW_Count_Encoder := 0; //이전 Incremental Encoder Count 클리어
         static_r_FW_Count_Encoder := 0;
         static_r_BW_Count_Encoder := 0;
    END_IF;
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////완료



///////////////////////////////////////////QR TAG 미감지 시, 좌표값 계산///////////////////////////////////////////////////////////////////////////////////////////////////////////////////
    //1_삼각함수 안에는 RADIAN값이 들어가야 한다_(1도 = 0_0174533 rad // 1rad = 57_2958도)
    //2_Wheel이 1 SCAN 동안 이동한 거리 = (((현재 카운터값 - 이전 카운터값)/ppr)/gear_ratio) * 파이 * 휠의 직경
    //3_빗변 * COS(Absolute Angle) = X 좌표 // 빗변 * SIN(Absolute Angle) = Y 좌표
    //    X pos = 이전 X pos 값 + (1 SCAN 동안 이동한 주행거리 * COS(PGV의 틀어진 각도 + 전방 휠의 틀어진 각도)
    //    Y pos = 이전 Y pos 값 + (1 SCAN 동안 이동한 주행거리 * SIN(PGV의 틀어진 각도 + 전방 휠의 틀어진 각도)
    //4_두 점을 잇는 선의 각도 = 아크탄젠트(Y거리/X거리)
    IF ( in_bRenew_bit = 0) THEN

         Buffer_rFW_X_POS_Virtual :=  Buffer_rPre_rCurrent_Coordinate_X + ((in_Distance_FwWheel_BwWheel_mm/2) * COS(( Buffer_rPre_rCurrent_AGV_Angle ) * 0.0174533));
         Buffer_rFW_Y_POS_Virtual :=  Buffer_rPre_rCurrent_Coordinate_Y + ((in_Distance_FwWheel_BwWheel_mm/2) * SIN(( Buffer_rPre_rCurrent_AGV_Angle ) * 0.0174533));

         Buffer_rBW_X_POS_Virtual :=  Buffer_rPre_rCurrent_Coordinate_X + ((in_Distance_FwWheel_BwWheel_mm/2) * COS(( Buffer_rPre_rCurrent_AGV_Angle + 180) * 0.0174533));
         Buffer_rBW_Y_POS_Virtual :=  Buffer_rPre_rCurrent_Coordinate_Y + ((in_Distance_FwWheel_BwWheel_mm/2) * SIN(( Buffer_rPre_rCurrent_AGV_Angle + 180) * 0.0174533));







        //FW Wheel (X,Y)
         static_rFW_Distance := ((( static_r_FW_Count_Encoder -  Buffer_rPre_FW_Count_Encoder) / in_rEncoder_ppr) /  static_rDriving_Motor_gear_ratio) * 3.141593 *  static_rWheel_diameter; //FW Wheel이 1 SCAN 동안 이동한 거리
         Buffer_rFW_X_POS_Virtual :=  Buffer_rFW_X_POS_Virtual + ( static_rFW_Distance * COS(( Buffer_rPre_rCurrent_AGV_Angle -  Buffer_rPre_FW_Wheel_Angle) * 0.0174533)); // FW Wheel X
         Buffer_rFW_Y_POS_Virtual :=  Buffer_rFW_Y_POS_Virtual + ( static_rFW_Distance * SIN(( Buffer_rPre_rCurrent_AGV_Angle -  Buffer_rPre_FW_Wheel_Angle) * 0.0174533)); // FW Wheel Y

        //BW Wheel (X,Y)
         static_rBW_Distance := ((( static_r_BW_Count_Encoder -  Buffer_rPre_BW_Count_Encoder) / in_rEncoder_ppr) /  static_rDriving_Motor_gear_ratio) * 3.141593 *  static_rWheel_diameter; //BW Wheel이 1 SCAN 동안 이동한 거리
         Buffer_rBW_X_POS_Virtual :=  Buffer_rBW_X_POS_Virtual + ( static_rBW_Distance * COS(( Buffer_rPre_rCurrent_AGV_Angle -  Buffer_rPre_BW_Wheel_Angle) * 0.0174533)); // BW Wheel X
         Buffer_rBW_Y_POS_Virtual :=  Buffer_rBW_Y_POS_Virtual + ( static_rBW_Distance * SIN(( Buffer_rPre_rCurrent_AGV_Angle -  Buffer_rPre_BW_Wheel_Angle) * 0.0174533)); // BW Wheel Y

        // AGV ANGLE
         static_rWheel_Angle := (57.2958 * ATAN(( Buffer_rFW_Y_POS_Virtual -  Buffer_rBW_Y_POS_Virtual) / ( Buffer_rFW_X_POS_Virtual -  Buffer_rBW_X_POS_Virtual)));
        IF ( Buffer_rFW_X_POS_Virtual- Buffer_rBW_X_POS_Virtual) < 0 THEN
             static_rWheel_Angle :=  static_rWheel_Angle + 180 ;
        END_IF;
         Buffer_rAGV_Angle_Virtual :=  static_rWheel_Angle; // AGV Angle

        IF  Buffer_rAGV_Angle_Virtual < 0 THEN
             Buffer_rAGV_Angle_Virtual :=  Buffer_rAGV_Angle_Virtual + 360;
        ELSIF  Buffer_rAGV_Angle_Virtual >= 360 THEN
             Buffer_rAGV_Angle_Virtual :=  Buffer_rAGV_Angle_Virtual - 360;
        END_IF;
        //Output AGV (X,Y,Angle)
         out_rCurrent_Coordinate_X := ( Buffer_rFW_X_POS_Virtual +  Buffer_rBW_X_POS_Virtual) / 2;
         out_rCurrent_Coordinate_Y := ( Buffer_rFW_Y_POS_Virtual +  Buffer_rBW_Y_POS_Virtual) / 2;
         out_rCurrent_AGV_Angle :=  Buffer_rAGV_Angle_Virtual;



    END_IF;
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////완료    


        //Drive Incremental Encoder의 Count값을 Buffer에 저장
         Buffer_rPre_FW_Count_Encoder :=  static_r_FW_Count_Encoder;
         Buffer_rPre_BW_Count_Encoder :=  static_r_BW_Count_Encoder;

        //FW,BW의 Wheel의 Angle 값을 Buffer에 저장
         Buffer_rPre_FW_Wheel_Angle :=  static_rFW_Wheel_Angle; //필요
         Buffer_rPre_BW_Wheel_Angle :=  static_rBW_Wheel_Angle; //필요

    //추가해야하는 내용

    //2_처음 시작할 때 TAG감지하고 시작해야함_그 내용도 표시
    //3_Start 내용 추가

         Buffer_rPre_rCurrent_Coordinate_X :=  out_rCurrent_Coordinate_X;
         Buffer_rPre_rCurrent_Coordinate_Y :=  out_rCurrent_Coordinate_Y;
        IF ( in_bRenew_bit = 1) OR  static_rFW_Distance <> 0 OR  static_rBW_Distance <> 0 THEN
             Buffer_rPre_rCurrent_AGV_Angle :=  out_rCurrent_AGV_Angle;
        END_IF;

FUNCTION_BLOCK WheelOffset_AutoSet
VAR_INPUT
	in_Start : BOOL;
	in_Start_Time_Sec : TIME;
	in_Move_Time_Sec : TIME;
	in_Manual_Mode : BOOL;
	in_Distance_FwWheel_BwWheel_mm : REAL;
	in_FW_Wheel_Angle : REAL;
	in_BW_Wheel_Angle : REAL;
	in_X_Pos : REAL;
	in_Y_Pos : REAL;
	in_AGV_Angle : REAL;
	in_Travel_Speed_mpm : REAL;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Step : INT;
	out_Not_Manual_Mode : BOOL;
	out_WheelAngle_NotReady : BOOL;
	out_FW_Run : BOOL;
	out_BW_Run : BOOL;
	out_FW_Offset : REAL; //두 바퀴의 Angle Gap.
	out_BW_Offset : REAL; //바퀴가 정면에서 꺾여져 있는 정도.
END_VAR
VAR
	Renew_Bit : BOOL;
	Step : INT;
	Start_X_Buffer : REAL;
	Start_Y_Buffer : REAL;
	Start_Angle_Buffer : REAL;
	End_X_Buffer : REAL;
	End_Y_Buffer : REAL;
	End_Angle_Buffer : REAL;
	Distance_Start_End : REAL;
	Angle_Start_End_us360 : REAL;
	SUB_EndAngle_StartAngle_s180 : REAL;
	Run_Count : INT;
	Offset_1_Buffer : ARRAY[0..5] OF REAL;
	Offset_2_Buffer : ARRAY[0..5] OF REAL;
	TON_Start_1 : TON;
	TON_Start_1_Pulse : BOOL;
	TON_Start_2 : TON;
	TON_Start_2_Pulse : BOOL;
	TON_1 : TON;
	TON_2 : TON;
	TON_3 : TON;
	TON_4 : TON;
	TON_5 : TON;
	Angle_Calcuration_1 : Angle_Calcuration;
	Angle_Calcuration_2 : Angle_Calcuration;
	Angle_Calcuration_3 : Angle_Calcuration;
	Angle_Calcuration_4 : Angle_Calcuration;
	Angle_Calcuration_5 : Angle_Calcuration;
END_VAR


out_Complete := FALSE;
out_Not_Manual_Mode := FALSE;
out_WheelAngle_NotReady := FALSE;
out_FW_Run := FALSE;
out_BW_Run := FALSE;
out_Step := Step;
IF in_Start = FALSE OR in_Manual_Mode = FALSE THEN
    Renew_Bit := FALSE;
    Step := 0;
    Offset_1_Buffer[0] := 0;
    Offset_2_Buffer[0] := 0;
    Run_Count := 0;
    TON_3(IN := FALSE);
END_IF;


IF in_Start THEN
	IF Renew_Bit = FALSE THEN
		Renew_Bit := TRUE;		
		Step := 1;
	END_IF
	CASE Step OF
        1: 
            IF in_Manual_Mode THEN
                    IF (179.5 < in_FW_Wheel_Angle AND in_FW_Wheel_Angle < 180.5) AND (179.5 < in_BW_Wheel_Angle AND in_BW_Wheel_Angle < 180.5) THEN
                        Step := 2;  
                    ELSE
                        out_WheelAngle_NotReady := TRUE;
                    END_IF;
            ELSE
                out_Not_Manual_Mode := TRUE;
            END_IF;

        2: 
            Run_Count := Run_Count + 1;
            TON_Start_1(IN := FALSE,PT := in_Start_Time_Sec);
			TON_Start_1_Pulse := FALSE;
            TON_1(IN := FALSE,PT := in_Move_Time_Sec);
            TON_2(IN := FALSE,PT := in_Move_Time_Sec);
            Step := 3;
        3: 
            out_FW_Run := TRUE;
			TON_Start_1(IN := TRUE,
                   PT := in_Start_Time_Sec);				   			
            TON_1(IN := TRUE,
                   PT := in_Move_Time_Sec);
			IF TON_Start_1.Q AND TON_Start_1_Pulse = FALSE THEN
				TON_Start_1_Pulse := TRUE;
				  Start_X_Buffer := in_X_Pos;
         	  Start_Y_Buffer := in_Y_Pos;
         	  Start_Angle_Buffer := in_AGV_Angle;
			END_IF			
            IF TON_1.Q THEN
                out_FW_Run := FALSE;
                IF in_Travel_Speed_mpm = 0 THEN
                    Step := 4;
                    End_X_Buffer := in_X_Pos;
                    End_Y_Buffer := in_Y_Pos;
                    End_Angle_Buffer := in_AGV_Angle;
                END_IF;
            END_IF;
        4:  
            out_BW_Run := TRUE;
            TON_2(IN := TRUE,
                   PT := in_Move_Time_Sec);
            IF TON_2.Q THEN
                out_BW_Run := FALSE;
                IF in_Travel_Speed_mpm = 0 THEN
                    Step := 5;
                END_IF;
            END_IF;
        5:     
		Angle_Calcuration_1(	in_2_TwoPoint_Distance_Calculation_Bit:=TRUE , 
									in_X1_Start:= Start_X_Buffer, 
									in_Y1_Start:= Start_Y_Buffer, 
									in_X2_End:= End_X_Buffer, 
									in_Y2_End:= End_Y_Buffer, 
									in_3_Angle_SUB_bit:= TRUE, 
									in_SUB_1_1:= END_Angle_Buffer, 
									in_SUB_1_2:= Start_Angle_Buffer, 
									out_2_TwoPoint_Distance_mm=> Distance_Start_End, 
									out_3_SUB1_s180=> SUB_EndAngle_StartAngle_s180 
								);	            

            Offset_1_Buffer[Run_Count] := 2 * 57.2958 * ASIN((in_Distance_FwWheel_BwWheel_mm * 3.141593 / 360 * SUB_EndAngle_StartAngle_s180) / Distance_Start_End);

            IF Run_Count = 5 THEN
                Offset_1_Buffer[0] := (Offset_1_Buffer[1] + Offset_1_Buffer[2] + Offset_1_Buffer[3] + Offset_1_Buffer[4] + Offset_1_Buffer[5]) / 5;
                TON_3(IN := TRUE,
                       PT := T#2S);
                IF TON_3.Q THEN
                    Step := 6;
                    Run_Count := 0;
                END_IF;
            ELSE
                Step := 2;
            END_IF;
        6: 
            IF (179.5 < in_FW_Wheel_Angle AND in_FW_Wheel_Angle < 180.5) AND (179.5 < in_BW_Wheel_Angle AND in_BW_Wheel_Angle < 180.5) THEN
                Run_Count := Run_Count + 1;
				TON_Start_2(IN := FALSE,PT := in_Start_Time_Sec);
				TON_Start_2_Pulse := FALSE;                
                TON_4(IN := FALSE,
                       PT := in_Move_Time_Sec);
                TON_5(IN := FALSE,
                       PT := in_Move_Time_Sec);
                Step := 7;
            END_IF;

        7: 
            out_FW_Run := TRUE;
			TON_Start_2(IN := TRUE,
                   PT := in_Start_Time_Sec);	
            TON_4(IN := TRUE,
                   PT := in_Move_Time_Sec);
			IF TON_Start_2.Q AND TON_Start_2_Pulse = FALSE THEN
				TON_Start_2_Pulse := TRUE;

       	   	  Start_X_Buffer := in_X_Pos;
         	  Start_Y_Buffer := in_Y_Pos;
         	  Start_Angle_Buffer := in_AGV_Angle;
			END_IF	
            IF TON_4.Q THEN
                out_FW_Run := FALSE;
                IF in_Travel_Speed_mpm = 0 THEN
                    Step := 8;
                    End_X_Buffer := in_X_Pos;
                    End_Y_Buffer := in_Y_Pos;
                    End_Angle_Buffer := in_AGV_Angle;
                END_IF;
            END_IF;
        8:  
            out_BW_Run := TRUE;
            TON_5(IN := TRUE,
                   PT := in_Move_Time_Sec);
            IF TON_5.Q THEN
                out_BW_Run := FALSE;
                IF in_Travel_Speed_mpm = 0 THEN
                    Step := 9;
                END_IF;
            END_IF;


        9: 
		Angle_Calcuration_2(	in_1_TwoPoint_Angle_Calculation_Bit:= TRUE ,  
								in_X1_Start:= Start_X_Buffer, 
								in_Y1_Start:= Start_Y_Buffer, 
								in_X2_End:= End_X_Buffer, 
								in_Y2_End:= End_Y_Buffer, 
								out_1_Theta_us360=> Angle_Start_End_us360 );		
		Angle_Calcuration_3(	in_3_Angle_SUB_bit:= TRUE , 
								in_SUB_1_1:= Angle_Start_End_us360 , 
								in_SUB_1_2:= Start_Angle_Buffer , 
								out_3_SUB1_s180=> Offset_2_Buffer[Run_Count] );
            IF Run_Count = 5 THEN
                Offset_2_Buffer[0] := (Offset_2_Buffer[1] + Offset_2_Buffer[2] + Offset_2_Buffer[3] + Offset_2_Buffer[4] + Offset_2_Buffer[5]) / 5;
                out_Complete := TRUE;
            ELSE
                Step := 6;
            END_IF;


        ELSE
            Step := 0;
    END_CASE;

    out_FW_Offset := Offset_1_Buffer[0] + Offset_2_Buffer[0];
    out_BW_Offset := Offset_2_Buffer[0];

END_IF

