END_VAR
VAR
	Renew_Bit : BOOL;
	Step : INT;
	Start_X_Buffer : REAL;
	Start_Y_Buffer : REAL;
	Start_Angle_Buffer : REAL;
	End_X_Buffer : REAL;
	End_Y_Buffer : REAL;
	End_Angle_Buffer : REAL;
