VAR
	va_Buffer_Data : ARRAY[0..30] OF BYTE;
	va_CurrentSpeed_buffer  				:INT;
	va_CurrentSpeed_rpm						:REAL;
	va_CurrentSpeed_mpm						:REAL;
	va_CurrentSpeed_mps						:REAL;
	va_AccelSpeed_mps2						:REAL;
	va_DecelSpeed_mps2						:REAL;
