out_Complete := FALSE;
IF in_enable AND in_Wheel_Diameter_mm <> 0 AND in_Gear_Ratio <> 0 AND in_Max_rpm <> 0 AND in_Accel_Time_s <> 0 AND in_Decel_Time_s <> 0 AND in_Motor_Nominal_Current_A <> 0 THEN
	MEMCPY(destAddr:=ADR(va_Buffer_Data[0]) , srcAddr:=ADR(in_Data[0]) , n:= SIZEOF(in_Data) );

	//out1_00_CurrentSpeed_Hz_d10				
	va_CurrentSpeed_buffer := SHL( BYTE_TO_INT(va_Buffer_Data[1]),8 ) + BYTE_TO_INT(va_Buffer_Data[0]);		
	out1_00_CurrentSpeed_Hz_x10 := va_CurrentSpeed_buffer;
	//out1_20_Power_Contact_Status			
	out1_20_Power_Contact_Status := va_Buffer_Data[2].0;
	//out1_21_NEB_Status						
	out1_21_NEB_Status := va_Buffer_Data[2].1;
	//out1_22_D0								
	out1_22_D0 := va_Buffer_Data[2].2;
	//out1_23_D1								
	out1_23_D1 := va_Buffer_Data[2].3;
	//out1_24_D2								
	out1_24_D2 := va_Buffer_Data[2].4;
	//out1_25_D3								
	out1_25_D3 := va_Buffer_Data[2].5;
	//out1_26_D4								
	out1_26_D4 := va_Buffer_Data[2].6;
	//out1_27_D5								
	out1_27_D5 := va_Buffer_Data[2].7;
	//out1_30_D6								
	out1_30_D6 := va_Buffer_Data[3].0;
	//out1_31_D7								
	out1_31_D7 := va_Buffer_Data[3].1;
	//out1_32_D8								
	out1_32_D8 := va_Buffer_Data[3].2;
	//out1_33_D9							
	out1_33_D9 := va_Buffer_Data[3].3;
	//out1_34_D10								
	out1_34_D10 := va_Buffer_Data[3].4;
	//out1_35_D11							
	out1_35_D11 := va_Buffer_Data[3].5;
	//out1_36_D12							
	out1_36_D12 := va_Buffer_Data[3].6;
	//out1_37_Stuffing					
	out1_37_Stuffing := va_Buffer_Data[3].7;
	//out1_40_Status_Byte					
	out1_40_Status_Byte := va_Buffer_Data[4];
	(* Not Use
//	//out1_50_Analog_Intput1				
//	out1_50_Analog_Intput1 := va_Buffer_Data[5];
//	//out1_60_Analog_Intput2					
//	out1_60_Analog_Intput2 := va_Buffer_Data[6];
	*)
	//out1_70_Actual_Current					
	out1_70_Actual_Current := va_Buffer_Data[7]*5;


	//out2_00_Warning_Alarm 				
	out2_00_Warning_Alarm := SHL( BYTE_TO_UINT(va_Buffer_Data[11]),8 ) + BYTE_TO_UINT(va_Buffer_Data[10]);		
	//out2_20_Motor_Temperature			
	out2_20_Motor_Temperature := va_Buffer_Data[12] - 40;
	//out2_30_Temperature					
	out2_30_Temperature := BYTE_TO_SINT(va_Buffer_Data[13]);
	//out2_40_BDI_Percentage			
	out2_40_BDI_Percentage := va_Buffer_Data[14];
	//out2_50_Battery_Current			
	out2_50_Battery_Current := va_Buffer_Data[15];
	//out2_60_Batterty_Voltage			
	out2_60_Batterty_Voltage := SHL( BYTE_TO_UINT(va_Buffer_Data[17]),8 ) + BYTE_TO_UINT(va_Buffer_Data[16]);	

(*	Not Use
//	//out3_00_CANopen_Alarm_Code			
//	out3_00_CANopen_Alarm_Code := SHL( BYTE_TO_UINT(va_Buffer_Data[20]),8 ) + BYTE_TO_UINT(va_Buffer_Data[21]);	
