//	out3_40_Flag_Alarm := va_Buffer_Data[24];
//	//out3_50_Extra_info_alarm			
//	out3_50_Extra_info_alarm := va_Buffer_Data[25];
*)	

	//Speed Calcuration
	va_CurrentSpeed_rpm := (INT_TO_REAL(ABS(va_CurrentSpeed_buffer)) / 10) * 30;
	va_CurrentSpeed_mpm := LREAL_TO_REAL((va_CurrentSpeed_rpm/in_Gear_Ratio)*(PI*in_Wheel_Diameter_mm))/1000;
	va_CurrentSpeed_mps := va_CurrentSpeed_mpm/60;
	va_AccelSpeed_mps2 := LREAL_TO_REAL((((in_Max_rpm/in_Gear_Ratio)*(PI*in_Wheel_Diameter_mm))/1000)/60)/in_Accel_Time_s;
	va_DecelSpeed_mps2 := LREAL_TO_REAL((((in_Max_rpm/in_Gear_Ratio)*(PI*in_Wheel_Diameter_mm))/1000)/60)/in_Decel_Time_s;
	out_CurrentSpeed_rpm := va_CurrentSpeed_rpm;
	out_CurrentSpeed_mpm := va_CurrentSpeed_mpm;
	out_CurrentSpeed_mps := va_CurrentSpeed_mps;
	out_AccelSpeed_mps2 := va_AccelSpeed_mps2;
	out_DecelSpeed_mps2 := va_DecelSpeed_mps2;
	out_Motor_Load_Percentage := ((BYTE_TO_REAL(va_Buffer_Data[7])*5) / in_Motor_Nominal_Current_A)*100;

	out_Complete := TRUE;
END_IF

