//ACS_Comm_Check
TOF[1](IN:=(ACS_Parsing.out_Send_Type = 4), PT:=T#10S , Q=>GDB.ACS.ACS_Comm_OK);

//Initialize
GDB.ACS.Command_Start_Bit := FALSE;
GDB.ACS.Command_Add_Bit := FALSE;
GDB.ACS.Command_Stop_Bit := FALSE;
GDB.ACS.Command_Charge_Stop_Bit := FALSE;
IF GDB.Mode.Auto = FALSE THEN	
	GDB.ACS.Host_pause := FALSE;
END_IF;
IF GDB.Auto._4_Charge.Step <> 3 THEN
	GDB.ACS.Command_Charge_Stop_Bit := FALSE;	
END_IF;
IF GDB.Mode.Active = FALSE THEN
	GDB.ACS.Command_Stop_Bit := FALSE;
END_IF;	

//TCPIP_Server
TON[5](IN:= (TCPIP_Server_OpenClose.out_ConnectState = 1 AND GDB.ACS.ACS_Comm_OK = FALSE), PT:=T#3S);
IF TRUE THEN
	TCPIP_Server_OpenClose(
		in_Enable:= TRUE, 
		in_Server_Reset:= , 
		in_Client_Reset:= TON[5].Q, 
		in_LocalHost:= GDB_Parameter.IP_Beckhoff_PC_2, 
		in_LocalPort:= GDB_Parameter.Port_Beckhoff_PC_2);
END_IF;

//Status_Data_Set 		
IF TRUE THEN
	ACS_Parsing.in_Map_Version := GDB_Parameter.Map_Ver;
	ACS_Parsing.in_Vehicle_ID:= GDB_Parameter.Vehicle_ID;
	ACS_Parsing.in_Node:= GDB_Retain.Current_Node;
	IF TRUE THEN //Link_ID
		IF ACS_Parsing.in_Link = 0 AND GDB_Retain.Current_Node <> 0 THEN
			FOR LoopIndex[1] := 1 TO 1000 DO
				IF GDB_Retain.Link_ID[LoopIndex[1]].End_Node = GDB_Retain.Current_Node 
					(*AND GDB_Retain.Link_ID[LoopIndex[1]].FB = 1*) THEN
						ACS_Parsing.in_Link := (GDB_Retain.Link_ID[LoopIndex[1]].Start_Node * 1000)
											 + (GDB_Retain.Link_ID[LoopIndex[1]].End_Node);
				END_IF; 
			END_FOR;			
		END_IF;		
		IF 		GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node <> 0
			AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node <> 0 THEN	
			ACS_Parsing.in_Link:= 	(GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node * 1000)
								 + (GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node);
		END_IF;			
	END_IF;
	ACS_Parsing.in_Batt_Volt:=  REAL_TO_INT((gdb.Unit.Tabos_Battery.Battery_1_Voltage_V + gdb.Unit.Tabos_Battery.Battery_2_Voltage_V)/2 *100);
	ACS_Parsing.in_Batt_SOC:=  INT_TO_BYTE(gdb.Unit.Tabos_Battery.Battery_1_SOC_Percentage + gdb.Unit.Tabos_Battery.Battery_2_SOC_Percentage)/2;
	IF TRUE THEN //Status		
		//Clear		
		Status_Buffer[0] := 0;
		//Status_Buffer[1] := 0;
		Status_Buffer[2] := 0;
		Status_Buffer[3] := 0;
		//Set
		TON[3](IN:= GDB.Unit.Drive.TravelControl.Status_Running_Bit, PT:= T#500MS);
		Status_Buffer[0].0 := TON[3].Q; //0.0 : Moving		
		(*IF 		GDB.Auto._3_Move.Step = 7 
			AND GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos = GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total
			AND (GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total - GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos < 5000.0) THEN //0.1 : Arriving
			Status_Buffer[0].1 := TRUE;
		END_IF;*)
		IF 		gdb.Mode.Auto 
			AND GDB.Auto._3_Move.Step = 7 
			AND GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos = GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total			
			AND (	
					((GDB.Unit.Drive.TravelControl.High_Speed >= 25) AND ( GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 4000.0))					
					OR ( GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)
 				)
		THEN //0.1 : Arriving
			Status_Buffer[0].1 := TRUE;
		END_IF;

		Status_Buffer[0].2 := (GDB.Auto._1_Loading.Step > 0); //0.2 : Acquring
		Status_Buffer[0].3 := (GDB.Auto._2_Unloading.Step > 0); //0.3 : Depositing
		Status_Buffer[0].4 := (GDB.Auto._4_Charge.Step > 0); //0.4 : Charging
		Status_Buffer[0].5 := NOT(GDB.Mode.Auto); //0.5 : Manual_Mode
		Status_Buffer[0].6 := GDB.Error.Error_On_Bit; //0.6 : Down
		Status_Buffer[0].7 := GDB.Mode.Auto AND GDB.Auto.Main.Step = 1; //0.7 : Active

		Status_Buffer[1].0 := (GDB.Command.Command_Type <> 0); //1.0 : HaveCmd
		IF GDB.Auto.PIO.PIO_Timeout_Bit THEN //PIO 에러일 경우,,
			GDB.Command.Command_Clear_Bit := TRUE;
			IF GDB.Mode.Auto THEN
				Status_Buffer[1].1 := TRUE; //1.1 : Canceled
			END_IF;
		ELSIF GDB.Auto.Main.Step = 3 THEN
			Status_Buffer[1].1 := FALSE; //1.1 : Canceled
		END_IF;
		IF GDB.Mode.Auto AND GDB.Auto.Main.Step = 99 THEN
			Status_Buffer[1].2 := TRUE; //1.2 : Job_Finished
		ELSIF GDB.Auto.Main.Step = 3 THEN
			Status_Buffer[1].2 := FALSE; //1.2 : Job_Finished
		END_IF;
		Status_Buffer[1].3 := FALSE; //1.3 : -
		TON[4](IN:= GDB.Unit.IO.di_Product_Detect, PT:= T#500MS);
		Status_Buffer[1].4 := TON[4].Q; //1.4 : Product_Detect
		Status_Buffer[1].5 := FALSE; //1.5 : -
		Status_Buffer[1].6 := FALSE; //1.6 : -
		Status_Buffer[1].7 := FALSE; //1.7 : -

		Status_Buffer[2].0 := GDB.ACS.Host_pause; //2.0 : Host_Pause
		Status_Buffer[2].1 := GDB.Unit.Drive.TravelControl.Control_Stop_Bit; //2.1 : Vehicle_Pause
		//Status_Buffer[2].1 := NOT(GDB.ACS.Host_pause) AND GDB.Auto._3_Move.Pause; //2.1 : Vehicle_Pause
		IF 		GDB.Mode.Active 
			OR (GDB.Mode.Active = FALSE AND 	(ABS(GDB_Retain.Node[GDB_Retain.Current_Node].X - GDB.monitor.Current_X) < 100.0
											AND ABS(GDB_Retain.Node[GDB_Retain.Current_Node].Y - GDB.monitor.Current_Y) < 100.0) ) THEN											
			Status_Buffer[2].2 := TRUE; //2.2 : Enter_MAP
		ELSE
			Status_Buffer[2].3 := TRUE; //2.3 : EXIT_MAP
		END_IF;
		Status_Buffer[2].4 := FALSE; //2.4 : -
		Status_Buffer[2].5 := FALSE; //2.5 : -
		Status_Buffer[2].6 := FALSE; //2.6 : -
		Status_Buffer[2].7 := FALSE; //2.7 : -

		Status_Buffer[3].0 := FALSE; //3.0 : Direction(EAST)
		Status_Buffer[3].1 := FALSE; //3.1 : Direction(WEST)
		Status_Buffer[3].2 := FALSE; //3.2 : Direction(SOUTH)
		Status_Buffer[3].3 := FALSE; //3.3 : Direction(NORTH)
		IF (GDB.Monitor.Current_AGV_Angle >= 0 AND GDB.Monitor.Current_AGV_Angle < 45) OR (GDB.Monitor.Current_AGV_Angle >= 315 AND GDB.Monitor.Current_AGV_Angle < 360) THEN
			Status_Buffer[3].0 := TRUE; //3.0 : Direction(EAST)
		ELSIF 	(GDB.Monitor.Current_AGV_Angle >= 45 AND GDB.Monitor.Current_AGV_Angle < 135) THEN
			Status_Buffer[3].3 := TRUE; //3.3 : Direction(NORTH)
		ELSIF 	(GDB.Monitor.Current_AGV_Angle >= 135 AND GDB.Monitor.Current_AGV_Angle < 225) THEN
			Status_Buffer[3].1 := TRUE; //3.1 : Direction(WEST)
		ELSIF 	(GDB.Monitor.Current_AGV_Angle >= 225 AND GDB.Monitor.Current_AGV_Angle < 315) THEN
			Status_Buffer[3].2 := TRUE; //3.2 : Direction(SOUTH)		
		END_IF;
		Status_Buffer[3].4 := FALSE; //3.4 : -
		Status_Buffer[3].5 := FALSE; //3.5 : -
		Status_Buffer[3].6 := FALSE; //3.6 : -
		Status_Buffer[3].7 := FALSE; //3.7 : -

		ACS_Parsing.in_Status:= Status_Buffer;	
	END_IF		
	ACS_Parsing.in_Event:= 0; //Not_Use
	IF TRUE THEN //Error
		Error_Buffer[0] := 0;
		Error_Buffer[1] := 0;
		Error_Buffer[2] := 0;
		Error_Count := 0;
		FOR LoopIndex[1] := 1 TO 1000 DO
			IF GDB.Error.Error_BIt[LoopIndex[1]] <> 0 THEN
				Error_Buffer[Error_Count] := LoopIndex[1];
				Error_Count := Error_Count + 1;
				IF Error_Count = 3 THEN
					EXIT;
				END_IF;
			END_IF;			
		END_FOR;
		ACS_Parsing.in_Error:= Error_Buffer;
	END_IF;	  
	ACS_Parsing.in_Dest_Node:=  GDB.Command.Dest_Node;
	IF GDB.Command.Dest_Node = 0 THEN
		ACS_Parsing.in_Dest_Node := GDB_Retain.Current_Node;
	END_IF	
	ACS_Parsing.in_Carrier_ID:=  GDB.ACS.Command_Carrier_ID;
	ACS_Parsing.in_Map_Version:= GDB_Parameter.Map_Ver; 
END_IF;


//ACS_Send,Receive
IF TRUE THEN		
	IF TCPIP_Server_OpenClose.out_ConnectState = 1 THEN


		//Pulse
		TON[1](IN := (TON_Q[1] = FALSE), PT := T#10MS(*T#10MS*), Q => TON_Q[1]);
		TON[2](IN := (TON_Q[2] = FALSE), PT := T#50MS(*T#50MS*), Q => TON_Q[2]);		
		FB_SocketReceive(sSrvNetId:='', 
						hSocket:= TCPIP_Server_OpenClose.out_T_hSocket, 
						cbLen:= SIZEOF(Receive_Data), 
						pDest:= ADR(Receive_Data), 
						bExecute:= TON[1].Q, 
						tTimeout:= T#5S);		
		ACS_Parsing(in_Receive_Enable:= TRUE, 
					in_Send_Enable:= TON_Q[2], 
					in_Data:= Receive_Data, 					
					out_Data=> Send_Data);
		FB_SocketSend(sSrvNetId:='', 
						hSocket:= TCPIP_Server_OpenClose.out_T_hSocket, 
						cbLen:= ACS_Parsing.out_Data_Length, 
						pSrc:= ADR(Send_Data), 
						bExecute:=ACS_Parsing.out_Send_Type <> 0);				
		IF Receive_Data[0] <> 16#53 AND Receive_Data[0] <> 16#0 AND Receive_Data[0] <> 16#54 THEN
			FOR LoopIndex[1] := 0 TO 100 DO
			Receive_Data_Test[LoopIndex[1]] := Receive_Data[LoopIndex[1]];
			END_FOR;
		END_IF;						
		FOR LoopIndex[1] := 0 TO 100 DO
			Receive_Data[LoopIndex[1]] := 0;		
		END_FOR;				

		// 1. Time_Data_Set				
		NT_SetLocalTime(NETID:= '', 
						TIMESTR:= ACS_Parsing.out_1_TimeSTR,
						START:= ACS_Parsing.out_Send_Type = 1);				
		//2. Command_Send
		IF GDB.Mode.Auto THEN
			 //Command_Start
			IF GDB.Auto.Main.Step = 1 AND ACS_Parsing.out_Send_Type = 2 THEN
				//Conversion_In_Data Clear
				FOR LoopIndex[1] := 0 TO 1000 DO 
					GDB.Data_Conversion.in_Data[LoopIndex[1]] := 0;
				END_FOR;			
				//1.Move
				IF ACS_Parsing.out_2_Command_Code[0].1 THEN
					GDB.ACS.Command_Start_Bit := TRUE;
					GDB.Data_Conversion.in_Command_Type := 3; //Command_Type
					GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; //SpinTurn_Target_Angle
					GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
					FOR LoopIndex[1] := 0 TO 14 DO
						IF ACS_Parsing.out_2_Via_Node[LoopIndex[1]] <> 0 THEN
							GDB.Data_Conversion.in_Dest_Node := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //Dest_Node
						END_IF;												
						GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //In_Data						
						IF LoopIndex[1] < 10 THEN
							GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
						END_IF;					
					END_FOR;
				//2.Loading	
				ELSIF ACS_Parsing.out_2_Command_Code[0].2 THEN
					GDB.ACS.Command_Start_Bit := TRUE;
					GDB.Data_Conversion.in_Command_Type := 1; //Command_Type
					GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; //SpinTurn_Target_Angle
					GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
					FOR LoopIndex[1] := 0 TO 14 DO
						IF ACS_Parsing.out_2_Via_Node[LoopIndex[1]] <> 0 THEN
							GDB.Data_Conversion.in_Dest_Node := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //Dest_Node
						END_IF;						
						GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //In_Data
						IF ACS_Parsing.out_2_Via_Node[0] = GDB_Retain.Current_Node THEN
							GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := 0;
						END_IF;
						IF LoopIndex[1] < 10 THEN
							GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
						END_IF;					
					END_FOR;	
				//3.Unloading	
				ELSIF ACS_Parsing.out_2_Command_Code[0].3 THEN
					GDB.ACS.Command_Start_Bit := TRUE;
					GDB.Data_Conversion.in_Command_Type := 2; //Command_Type
					GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; //SpinTurn_Target_Angle
					GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
					FOR LoopIndex[1] := 0 TO 14 DO
						IF ACS_Parsing.out_2_Via_Node[LoopIndex[1]] <> 0 THEN
							GDB.Data_Conversion.in_Dest_Node := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //Dest_Node
						END_IF;						
						GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //In_Data
						IF ACS_Parsing.out_2_Via_Node[0] = GDB_Retain.Current_Node THEN
							GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := 0;
						END_IF;
						IF LoopIndex[1] < 10 THEN
							GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
						END_IF;					
					END_FOR;						
				//4.Charge	
				ELSIF ACS_Parsing.out_2_Command_Code[0].4 THEN
					GDB.ACS.Command_Start_Bit := TRUE;
					GDB.Data_Conversion.in_Command_Type := 4; //Command_Type
					GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; //SpinTurn_Target_Angle
					GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
					FOR LoopIndex[1] := 0 TO 14 DO
						IF ACS_Parsing.out_2_Via_Node[LoopIndex[1]] <> 0 THEN
							GDB.Data_Conversion.in_Dest_Node := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //Dest_Node
						END_IF;						
						GDB.Data_Conversion.in_Data[LoopIndex[1]] := 0; //In_Data
						IF LoopIndex[1] < 10 THEN
							GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
						END_IF;					
					END_FOR;						
				//5.SpinTurn	
				ELSIF ACS_Parsing.out_2_Command_Code[0].5 THEN
					GDB.ACS.Command_Start_Bit := TRUE;
					GDB.Data_Conversion.in_Command_Type := 5; //Command_Type
					GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
					FOR LoopIndex[1] := 0 TO 14 DO										
						GDB.Data_Conversion.in_Data[LoopIndex[1]] := 0; //In_Data
						IF LoopIndex[1] < 10 THEN
							GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
						END_IF;					
					END_FOR;
					IF ACS_Parsing.out_2_Command_Code[3].0 AND ACS_Parsing.out_2_Command_Code[3].2 THEN //SpinTurn_Target_Angle				
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := (gdb.Monitor.Current_AGV_Angle + 90) ;
					ELSIF ACS_Parsing.out_2_Command_Code[3].0 AND ACS_Parsing.out_2_Command_Code[3].3 THEN 	
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := (GDB.Monitor.Current_AGV_Angle + 180) ;
					ELSIF ACS_Parsing.out_2_Command_Code[3].1 AND ACS_Parsing.out_2_Command_Code[3].2 THEN						
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := (GDB.Monitor.Current_AGV_Angle - 90) ;
					ELSIF ACS_Parsing.out_2_Command_Code[3].1 AND ACS_Parsing.out_2_Command_Code[3].3 THEN 	
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := (GDB.Monitor.Current_AGV_Angle - 180) ;						
					END_IF;					
					Angle_Calcuration[1](in_4_AngleRangeSet_us360_Bit := TRUE,
										in_Angle := (GDB.Data_Conversion.in_SpinTurn_Target_Angle));
					GDB.Data_Conversion.in_SpinTurn_Target_Angle := (Angle_Calcuration[1].out_4_Angle_us360);
					IF (GDB.Data_Conversion.in_SpinTurn_Target_Angle >= 0 AND GDB.Data_Conversion.in_SpinTurn_Target_Angle < 45) OR (GDB.Data_Conversion.in_SpinTurn_Target_Angle >= 315 AND GDB.Data_Conversion.in_SpinTurn_Target_Angle < 360) THEN
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; 
					ELSIF 	(GDB.Data_Conversion.in_SpinTurn_Target_Angle >= 45 AND GDB.Data_Conversion.in_SpinTurn_Target_Angle < 135) THEN
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := 90;
					ELSIF 	(GDB.Data_Conversion.in_SpinTurn_Target_Angle >= 135 AND GDB.Data_Conversion.in_SpinTurn_Target_Angle < 225) THEN
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := 180; 
					ELSIF 	(GDB.Data_Conversion.in_SpinTurn_Target_Angle >= 225 AND GDB.Data_Conversion.in_SpinTurn_Target_Angle < 315) THEN
						GDB.Data_Conversion.in_SpinTurn_Target_Angle := 270;		
					END_IF;
				END_IF;
			 //Command_Add
			ELSIF GDB.Auto._3_Move.Active AND ACS_Parsing.out_Send_Type = 2 AND ACS_Parsing.out_2_Command_Code[0].1 THEN
				GDB.ACS.Command_Add_Bit := TRUE;
				GDB.Data_Conversion.in_Command_Type := 3; //Command_Type
				GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0; //SpinTurn_Target_Angle
				GDB.Data_Conversion.in_Dest_Node := 0; //Dest_Node_Clear
				FOR LoopIndex[1] := 0 TO 14 DO
					IF ACS_Parsing.out_2_Via_Node[LoopIndex[1]] <> 0 THEN
						GDB.Data_Conversion.in_Dest_Node := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //Dest_Node
					END_IF;						
					GDB.Data_Conversion.in_Data[LoopIndex[1]+1] := ACS_Parsing.out_2_Via_Node[LoopIndex[1]]; //In_Data
					IF LoopIndex[1] < 10 THEN
						GDB.ACS.Command_Carrier_ID[LoopIndex[1]] := ACS_Parsing.out_2_Carrier_ID[LoopIndex[1]]; //Carrier_ID
					END_IF;					
				END_FOR;
			END_IF;
			//Pause, Resume, Stop, Charge_Stop
			IF ACS_Parsing.out_Send_Type = 2 THEN
				IF ACS_Parsing.out_2_Command_Code[1].2 THEN
					GDB.ACS.Host_pause := TRUE;
				ELSIF ACS_Parsing.out_2_Command_Code[1].3 THEN	
					GDB.ACS.Host_pause := FALSE;					
				ELSIF ACS_Parsing.out_2_Command_Code[1].4 THEN
					GDB.ACS.Command_Stop_Bit := TRUE;
				ELSIF ACS_Parsing.out_2_Command_Code[1].5 THEN
					GDB.ACS.Command_Charge_Stop_Bit := TRUE;	
				END_IF;
			END_IF;
		END_IF;
		//3. Data_Send		
		IF GDB.Mode.Auto AND ACS_Parsing.out_Send_Type = 3 THEN
			GDB.ACS.Transfered_Data := ACS_Parsing.out_3_Data;
			GDB.ACS.EPC_Data := DINT_TO_REAL(GDB.ACS.Transfered_Data)/10;			
		END_IF;

	END_IF;

END_IF;

PROGRAM Auto_1_Loading
VAR

TEST_ : ARRAY[1..30] OF BOOL;

PN_Pulse	:ARRAY[0..4] OF PN_Pulse;
TON	:ARRAY[0..6] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Loop_Index : INT;

Auto_Wheel_Ready_Run	:Auto_Wheel_Ready_Run;
Auto_Wheel_Move_1	:Auto_Wheel_Move;
Auto_Wheel_Move_2	:Auto_Wheel_Move;
Auto_Lift_Load		:Auto_Lift_Load_DemoTilt;

//Step3_Buffer
IPS_Y_Pos_Gap : REAL;
//Step5_Buffer
Lift_Pos_Buffer : REAL;
Y_Shift_Pos_Buffer : REAL;
Auto_Turret_Angle_Revision : Auto_Turret_Angle_Revision;
Turret_Angle_Gap : REAL;
Turret_Revision_Move_X_Pos : REAL;
Turret_Revision_Move_Y_Pos : REAL;
//Step9_Buffer
Load_Complete : BOOL;
Load_kg : REAL;
Load_Count : INT;
Load_Differential_First : REAL;
Load_Differential_Second : REAL;
bCheck	: BOOL;

END_VAR


//PIO_Ignore    2023.06.12 PIO Ignore 주석처리로 인해 추가된 파일 추후 삭제요망 
IF		(GDB.Mode.Auto = TRUE AND GDB.Touch.S25_PIO_Ignore)
	OR 	(GDB.Mode.Semi_Auto AND GDB.Touch.S25_PIO_Ignore) 
	OR 	GDB.Auto.PIO.PIO_Timeout_Bit THEN
	GDB.Auto.PIO.PIO_Ignore_Bit := TRUE;
END_IF;

/// 오토,세미 오토상태일때 pio 무시 , pio 타임아웃시 pio무시 

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._1_Loading.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._1_Loading.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._1_Loading.Active = FALSE THEN
        GDB.auto._1_Loading.Step := 0;
    END_IF;    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._1_Loading.Step = 1 THEN

		//Docking_Direction_Set		
			IF GDB.Monitor.Current_Y_Navi_Pos < -100 THEN
				GDB.Auto._1_Loading.Docking_Direction_1L_2R := 1;
			ELSIF GDB.Monitor.Current_Y_Navi_Pos > 100 THEN
				GDB.Auto._1_Loading.Docking_Direction_1L_2R := 2;
			ELSE
				GDB.Auto._1_Loading.Docking_Direction_1L_2R := 0;					
			END_IF			
		//Complete
		IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 33 THEN
			IF  GDB.Unit.IO.di_Product_Detect = FALSE
				AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2
				AND GDB.Auto._1_Loading.Docking_Direction_1L_2R <> 0
				AND GDB.Unit.IPS208i.Program_Change_OK_HP
				AND GDB.Unit.IPS208i.Program_Change_OK_OP 
				AND GDB.Unit.IPS208i.IPS208i_Comm_OK_HP = FALSE
				AND GDB.Unit.IPS208i.IPS208i_Comm_OK_OP = FALSE
				AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND (GDB.Unit.IO.di_DMS_in_2 OR GDB.Unit.IO.di_DMS_in_3) )
						OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE ))
			THEN       	   
						GDB.auto._1_Loading.Step := 3; //Step_3 : IPS_Check											
			END_IF;	
		ELSE // 33 공보빈 매거진
			IF GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2
				AND GDB.Auto._1_Loading.Docking_Direction_1L_2R <> 0
				AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_2 AND GDB.Unit.IO.di_DMS_in_3) 
						OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE ))
			THEN       	   
						GDB.auto._1_Loading.Step := 3; //Step_3 : IPS_Check	
			END_IF
		END_IF


	END_IF;		    
    //Step_3_IPS_Check & Docking_Direction_Set
	IF GDB.auto._1_Loading.Step = 3 THEN

		//Upper_Ready_Pos_Move
		IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 33 THEN
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
			GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
			GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
			IF  GDB.Auto._1_Loading.Docking_Direction_1L_2R = 1 THEN //Loading[Direction - Left]				
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos; 		
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
			ELSIF GDB.Auto._1_Loading.Docking_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
			END_IF;
			//Complete
			IF  	GDB.Unit.IPS208i.IPS208i_Comm_OK_HP
				AND GDB.Unit.IPS208i.IPS208i_Comm_OK_OP
				AND GDB.Unit.IPS208i.iState_HP = 0
				AND GDB.Unit.IPS208i.iState_OP = 0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				//AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 
			 THEN       	   
						GDB.auto._1_Loading.Step := 5; //Step_5 : Revision		
						IPS_Y_Pos_Gap := GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Zero_Angle_IPS_Y - ((GDB.Unit.IPS208i.rYpos_RealData_HP + GDB.Unit.IPS208i.rYpos_RealData_OP)/2);			
			END_IF;	

		ELSE // 33 공보빈 매거진
			GDB.Unit.Drive.Move_Data.Difference_mm_X := 0;
			GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
			GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
			IF  GDB.Auto._1_Loading.Docking_Direction_1L_2R = 1 THEN //Loading[Direction - Left]				
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Y_Navi_Pos; 		
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Y_Shift_Pos;
			ELSIF GDB.Auto._1_Loading.Docking_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
			END_IF;
			//Complete
			IF  ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 
			 THEN       	   
					GDB.auto._1_Loading.Step := 105; // 공보빈 매거진은 IPS보정 없이 로딩 Pos Step으로 점프	
					IPS_Y_Pos_Gap := GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Zero_Angle_IPS_Y - ((GDB.Unit.IPS208i.rYpos_RealData_HP + GDB.Unit.IPS208i.rYpos_RealData_OP)/2);	
					Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;
					Y_Shift_Pos_Buffer := GDB.Monitor.Current_Y_Shift_Pos;		
			END_IF;	
		END_IF		
	END_IF;	

	//Step_5_Revision
	IF GDB.auto._1_Loading.Step = 5 THEN
		IF TRUE THEN							

				Auto_Turret_Angle_Revision(		in_Enable:= GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 , 
												in_Chuck_X_Pos_Before:= GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Chuck_X_Pos_Before, 
												in_Chuck_Y_Pos_Before:= GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Chuck_Y_Pos_Before, 
												in_Reflector_X_Pos_Before:= GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Reflector_X_Pos_Before, 
												in_Reflector_Y_Pos_Before:= GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Reflector_Y_Pos_Before, 
												in_Y_Pos_Gap:= IPS_Y_Pos_Gap, 
												out_Turret_Angle_Gap=> Turret_Angle_Gap, 
												out_Move_X_Pos=> Turret_Revision_Move_X_Pos, 
												out_Move_Y_Pos=> Turret_Revision_Move_Y_Pos); 

				IF GDB.Auto._1_Loading.Docking_Direction_1L_2R = 1 THEN //Direction - Left										
					GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_HP_IPS_X + Turret_Revision_Move_X_Pos;
					GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_HP_IPS_Y;
					GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_OP_IPS_X + Turret_Revision_Move_X_Pos;
					GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_OP_IPS_Y;
				ELSIF GDB.Auto._1_Loading.Docking_Direction_1L_2R = 2 THEN //Direction - Right
					GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_HP_IPS_X - Turret_Revision_Move_X_Pos;
					GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_HP_IPS_Y;
					GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_OP_IPS_X - Turret_Revision_Move_X_Pos;
					GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_OP_IPS_Y;
				END_IF;														
				GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
				GDB.Unit.Drive.Move_Data.Difference_mm_Theta := (GDB.Unit.IPS208i.rXpos_HP - GDB.Unit.IPS208i.rXpos_OP);
				GDB.Unit.Drive.Move_Data.Difference_mm_Tilting := (GDB.Unit.IPS208i.rYpos_HP - GDB.Unit.IPS208i.rYpos_OP);													
				GDB.Unit.Drive.Move_Data.Difference_mm_Lift := (GDB.Unit.IPS208i.rYpos_HP + GDB.Unit.IPS208i.rYpos_OP)/2 ;													
				GDB.Unit.Drive.Move_Data.Difference_mm_Y := (GDB.Unit.IPS208i.rXpos_HP + GDB.Unit.IPS208i.rXpos_OP)/2 ;									
			END_IF;	
		//Complete
		IF TRUE THEN
			TON[2](IN:= 	ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Lift) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Y) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Theta) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Tilting) < 0.5						
				,PT:=T#300MS);

			IF TON[2].Q THEN //AND bCheck THEN (24.06.27)
				GDB.auto._1_Loading.Step := 105;
				Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;
				Y_Shift_Pos_Buffer := GDB.Monitor.Current_Y_Shift_Pos;
				RETURN;
			END_IF;
		END_IF;	
	END_IF;

	//Step_105_Data_Clear
	IF GDB.auto._1_Loading.Step = 105 AND GDB.Touch.S901_Loading_Step_Stop[5] = FALSE THEN
		GDB.auto._1_Loading.Step := 7;	
	END_IF;

	//Step_7_Loading_Point_Move
	GDB.Auto._1_Loading.Step_7_Lift_Decel_Bit := FALSE;
	IF GDB.auto._1_Loading.Step = 7 THEN
		IF TRUE THEN									
					GDB.Unit.Drive.Move_Data.Target_Pos_Lift := Lift_Pos_Buffer + GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_DT;
					IF 		(GDB.Monitor.Current_Lift_Pos - Lift_Pos_Buffer) > GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_Start_DT 
						AND (GDB.Monitor.Current_Lift_Pos - Lift_Pos_Buffer) < GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_End_DT
					THEN 
						GDB.Auto._1_Loading.Step_7_Lift_Decel_Bit := TRUE;
					END_IF;
		END_IF;	
		//Complete
		IF TRUE THEN
			TON[3](IN:= ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
					,PT:=T#100MS);			
			IF TON[3].Q THEN
				GDB.auto._1_Loading.Step := 107;
				RETURN;
			END_IF;
		END_IF;

		END_IF;

	//Step_107_Data_Clear
	IF GDB.auto._1_Loading.Step = 107 AND GDB.Touch.S901_Loading_Step_Stop[7] = FALSE THEN
		GDB.auto._1_Loading.Step := 9;	
		IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
			//GDB.Auto._1_Loading.Step_7_Loadcell_Offset := GDB.Monitor.Fork_Both_Loadcell_kg + GDB.Auto._1_Loading.Step_7_Loadcell_Offset;
		END_IF;	
	END_IF;			

	//Step_9_Turret_Loading
		PN_Pulse[3](in_Type:=1 , in_Signal:=GDB.auto._1_Loading.Step = 9);
		IF GDB.auto._1_Loading.Step = 9 THEN
			IF TRUE THEN								
				GDB.Monitor.Fork_Both_Loadcell_kg := GDB.Monitor.Fork_Both_Loadcell_kg;
				Auto_Lift_Load( Enable:= TRUE, 
								Renew:= PN_Pulse[3].out_Pulse, 
								in_Loadcell_Value_kg:= GDB.Monitor.Fork_Both_Loadcell_kg, 
								in_HP_Loadcell_Value_kg := GDB.Monitor.Fork_HP_Loadcell_kg,
								in_OP_Loadcell_Value_kg := GDB.Monitor.Fork_OP_Loadcell_kg,
								//in_Measured_Weight_kg:= GDB.Monitor.UltraSonic_Product_Weight_kg,
								in_Actual_Lift_Pos := GDB.Monitor.Current_Lift_Pos,
								out_Load_Complete=> Load_Complete, 
								out_Load_kg=> Load_kg, 
								out_Lift_Direction=> GDB.Auto._1_Loading.Step_9_Lift_Direction,
								out_Lift_Speed_mpm=> GDB.Auto._1_Loading.Step_9_Lift_Speed_mpm,
								out_Start_Pos=>GDB.Auto._1_Loading.Step_9_Start_Pos,
								out_Tilting_Direction=> GDB.Auto._1_Loading.Step_9_Tilting_Direction ,
								out_Tilting_Speed_mpm=> GDB.Auto._1_Loading.Step_9_Tilting_Speed_mpm );
			END_IF;	
			//Complete
			IF		(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND Load_Complete)
				OR	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2) 
				OR  (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 33)THEN
					GDB.auto._1_Loading.Step := 109;						
			END_IF;	
		END_IF;
	//Step_109_Data_Clear

	TON[6](IN:=(GDB.Auto._1_Loading.Step = 109), PT:=T#1S);   
	IF TON[6].Q AND GDB.Touch.S901_Loading_Step_Stop[9] = FALSE THEN
		GDB.auto._1_Loading.Step := 11;	
	END_IF;
	//Step_11_Turret_UnChucking_Check
		IF GDB.auto._1_Loading.Step = 11 THEN
			//Complete
			IF		(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND ( (GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE  AND GDB.Touch.S25_Turret_Complete)))
				OR	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2) 
				OR	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 33) AND ( (GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE  AND GDB.Touch.S25_Turret_Complete))
				THEN
					GDB.auto._1_Loading.Step := 111;							
					TON[4](IN:=FALSE,PT:=T#100MS);						
			END_IF;	
		END_IF;	
	//Step_111_Data_Clear
	IF GDB.auto._1_Loading.Step = 111 AND GDB.Touch.S901_Loading_Step_Stop[11] = FALSE THEN
		//GDB.auto._1_Loading.Step := 99;
		GDB.auto._1_Loading.Step := 13;	
	END_IF;

	//Step_13_Y_Shift_Home
	IF GDB.auto._1_Loading.Step = 13 THEN
		IF TRUE THEN								
			GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
			TON[6].IN := FALSE;   //230721 TON[6] 초기화추가
			IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 33 THEN
				GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
			END_IF

		END_IF;	
		//Complete
		IF GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Complete  THEN
			GDB.auto._1_Loading.Step := 113;						
		END_IF;	
	END_IF;	
	//Step_113_Data_Clear
	IF 		GDB.auto._1_Loading.Step = 113
		AND GDB.Touch.S901_Loading_Step_Stop[13] = FALSE 
		(*AND ((GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 AND ((GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  GDB.Auto.PIO.PIO_Ignore_Bit = TRUE))
			OR	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1)
			OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 33 AND ((GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  GDB.Auto.PIO.PIO_Ignore_Bit = TRUE)))*) THEN
		GDB.auto._1_Loading.Step := 99;	
	END_IF;

    //Step_99_Command_Complete           
	IF GDB.auto._1_Loading.Step = 99 THEN
        IF FALSE THEN
            GDB.auto._1_Loading.Step := 1;
        END_IF;
	END_IF;

PROGRAM Auto_1_Loading_1
VAR

TEST_ : ARRAY[1..30] OF BOOL;

PN_Pulse	:ARRAY[0..4] OF PN_Pulse;
TON	:ARRAY[0..5] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..2] OF Angle_Calcuration;
Loop_Index : INT;

Auto_Wheel_Ready_Run	:Auto_Wheel_Ready_Run;
Auto_Wheel_Move_1	:Auto_Wheel_Move;
Auto_Wheel_Move_2	:Auto_Wheel_Move;
Auto_Lift_Load		:Auto_Lift_Load;

//Step1_Buffer
Work_Type_Fault : BOOL;
//Step3_Buffer
END_X_Offset : REAL;
END_Y_Offset : REAL;
IPS_Y_Pos_Gap : REAL;
//Step5_Buffer
Lift_Pos_Buffer : REAL;
Y_Shift_Pos_Buffer : REAL;
Auto_Turret_Angle_Revision : Auto_Turret_Angle_Revision;
Turret_Angle_Gap : REAL;
Turret_Revision_Move_X_Pos : REAL;
Turret_Revision_Move_Y_Pos : REAL;
//Step9_Buffer
Load_Complete : BOOL;
Load_kg : REAL;
Load_Count : INT;
Load_Differential_First : REAL;
Load_Differential_Second : REAL;
//Step15_Buffer
START_X_Offset : REAL;
START_Y_Offset : REAL;
END_VAR



//Step_Set
IF TRUE THEN
    //Step_Active
    IF GDB.auto.Main.Step = 3 AND GDB.Command.Command_Type = 1 THEN   
        GDB.auto._1_Loading.Active := TRUE;
    ELSE
        GDB.auto._1_Loading.Active := FALSE;
    END_IF;
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._1_Loading.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._1_Loading.Step := 100;
    END_IF;
    //Step_Clear
    IF GDB.auto._1_Loading.Active = FALSE THEN
        GDB.auto._1_Loading.Step := 0;
    END_IF;    
END_IF;

//////////////////Command_Run이 완료된 시점 현제 현재위치가 목적지라면 로딩을 시작함 아닐경우 로딩 안함 

    //Step_1_Ready_Check
	IF GDB.auto._1_Loading.Step = 1 THEN
		//Link_Type_Check
		Work_Type_Fault := FALSE;
		Loop_Index := 1;
		WHILE GDB.Command.Data_List[Loop_Index] <> 0 DO
			IF GDB_Retain.Link_ID[GDB.Command.Data_List[Loop_Index]].Work_Type <> 2 OR Loop_Index = 999 THEN
				Work_Type_Fault := TRUE;
				EXIT;
			END_IF;
			Loop_Index := Loop_Index + 1;
		END_WHILE;		

//////////////////데이터 리스트의 루프가 0이 아니면 반복문 작동 링크가 작업지가 아니거나 루프가 999까지 증가시 정상작동 중이 아님 

		//Docking_Direction_Set
		Angle_Calcuration[1](in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
							in_X1_Start:= GDB_Retain.Node[GDB_Retain.Current_Node].X, 
							in_Y1_Start:= GDB_Retain.Node[GDB_Retain.Current_Node].Y, 
							in_X2_End:= GDB_Retain.Node[GDB.Command.Dest_Node].X, 
							in_Y2_End:= GDB_Retain.Node[GDB.Command.Dest_Node].Y);
		Angle_Calcuration[2](in_3_Angle_SUB_bit:= TRUE, 
							in_SUB_1_1:= Angle_Calcuration[1].out_1_Theta_us360, 
							in_SUB_1_2:= GDB.Monitor.Current_AGV_Angle);
		GDB.Auto._1_Loading.Docking_Direction_1L_2R := 0;
		IF Angle_Calcuration[2].out_3_SUB1_s180 > 80 AND Angle_Calcuration[2].out_3_SUB1_s180 < 100 THEN					
			GDB.Auto._1_Loading.Docking_Direction_1L_2R := 1;
		ELSIF Angle_Calcuration[2].out_3_SUB1_s180 > -100 AND Angle_Calcuration[2].out_3_SUB1_s180 < -80 THEN				
			GDB.Auto._1_Loading.Docking_Direction_1L_2R := 2;
		END_IF;

/////////////////각 축 기본 보정?을 한뒤 좌입 우입 결정		

		//Complete
       	IF  GDB.mode.Pause = FALSE
			AND Work_Type_Fault = FALSE
