				GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;
			END_IF;

			////////// 좌,우입 시작 위치 설정 우입시 도킹 옵셋값 적용 
			////////// 나머지 서보 축들은 0으로 설정 


            Auto_Wheel_Move_2(Enable:=TRUE,                                      //	Enable=TRUE => 항상 활성화 
                                      in_Renew_Bit:=PN_Pulse[4].out_Pulse,       //  진입 시점 펄스로 갱신 시작
                                      in_Pause:=FALSE,                           //  외부에서 정지 명령이 오면 일시 정지 
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Command_Current_Number := 100,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
									  in_Start_X_Offset := START_X_Offset,
									  in_Start_Y_Offset := START_Y_Offset,
                                      out_Command_Up_Bit=>GDB.Command.Command_Up_Bit,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4);
        END_IF;

		//////////////////in: 현재 상태&맵 정보&보정값 입력 부,   out:FB 내부 주행/ 조향/ 보정 연산 결과         
        ////////////////// 위에는 나머지 보정이나 이동값들 어디서 적용되는지, 주행 위치 목표 위치 



        //Complete
		IF TRUE THEN
	            TON[5](IN := ((GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#300MS);
	        IF TON[5].Q 
				AND GDB.Unit.Drive.LiftControl.Target_reached_Bit
				AND GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Complete
				AND	GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Theta_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Tilting_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Complete THEN
	            GDB.auto._1_Loading.Step := 99;
	        END_IF;
		END_IF;
	END_IF;	    

	///////////////// 목표위치와 실제위치가 조건에 만족하면 타이머 작동 타이머 종료 후 위조건 만족하면 step 99로


    //Step_99_Command_Complete           
	IF GDB.auto._1_Loading.Step = 99 THEN
        IF FALSE THEN
            GDB.auto._1_Loading.Step := 100;
        END_IF;
	END_IF;       

    /////////////////  99 false시 step 100

    //Step_100_Data Clear
	IF GDB.auto._1_Loading.Step = 100 THEN
        IF TRUE THEN
            GDB.auto._1_Loading.Step := 1;
        END_IF;
	END_IF;

	//// step 1로 돌아감 (초기화)

	//Step_90_SpinTurn
	IF GDB.auto._1_Loading.Step = 90 THEN
		IF GDB.Auto._5_Spinturn.Step = 99 THEN
			GDB.auto._3_move.Step := 1;
		END_IF
	END_IF;


	//스핀턴

PROGRAM Auto_2_Unloading
VAR
TEST_ : ARRAY[1..30] OF BOOL;

PN_Pulse	:ARRAY[0..4] OF PN_Pulse;
TON	:ARRAY[0..9] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;


Auto_Wheel_Ready_Run	:Auto_Wheel_Ready_Run;
Auto_Wheel_Move_1	:Auto_Wheel_Move;
Auto_Wheel_Move_2	:Auto_Wheel_Move;


//Step3_Buffer
IPS_Y_Pos_Gap : REAL;
//Step5_Buffer
Lift_Pos_Buffer : REAL;
Y_Shift_Pos_Buffer : REAL;
Auto_Turret_Angle_Revision : Auto_Turret_Angle_Revision;
Turret_Angle_Gap : REAL;
Turret_Revision_Move_X_Pos : REAL;
Turret_Revision_Move_Y_Pos : REAL;
END_VAR


//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._2_Unloading.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._2_Unloading.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._2_Unloading.Active = FALSE THEN
        GDB.auto._2_Unloading.Step := 0;
    END_IF;    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._2_Unloading.Step = 1 THEN
		//Docking_Direction_Set		
			IF GDB.Monitor.Current_Y_Navi_Pos < -100 THEN
				GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 1;
			ELSIF GDB.Monitor.Current_Y_Navi_Pos > 100 THEN
				GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 2;
			ELSE
				GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 0;					
			END_IF	
		//Complete
       	IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 33 THEN
			IF  GDB.Unit.IO.di_Product_Detect = TRUE
			AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2
			AND GDB.Auto._2_Unloading.Docking_Direction_1L_2R <> 0
			AND GDB.Unit.IPS208i.Program_Change_OK_HP
			AND GDB.Unit.IPS208i.Program_Change_OK_OP 
			AND GDB.Unit.IPS208i.IPS208i_Comm_OK_HP = FALSE
			AND GDB.Unit.IPS208i.IPS208i_Comm_OK_OP = FALSE		
			AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND (GDB.Unit.IO.di_DMS_in_1 OR GDB.Unit.IO.di_DMS_in_3)) 
					OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE ))	
				THEN       	   
	        	    GDB.auto._2_Unloading.Step := 3; //Step_3 : IPS_Check											
       		END_IF;	
		ELSE
			IF  GDB.Unit.IO.di_Product_Detect = TRUE
			AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2
			AND GDB.Auto._2_Unloading.Docking_Direction_1L_2R <> 0
			AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_1 AND GDB.Unit.IO.di_DMS_in_3) 
					OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE ))	
				THEN       	   
	        	    GDB.auto._2_Unloading.Step := 3; //Step_3 : IPS_Check											
       		END_IF;
		END_IF;			
	END_IF;		  

    //Step_3_IPS_Check & Docking_Direction_Set
	IF GDB.auto._2_Unloading.Step = 3 THEN	
			//Upper_Ready_Pos_Move
		IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 33 THEN	

			IF  GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm) + GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Left_X_Center_Offset;

			ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm) - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Right_X_Center_Offset;
			END_IF
			GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
			GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
			IF  GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Loading[Direction - Left]				
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
			ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos ; // 230724 포트 언로딩 X 보정을 위한 값 
			END_IF;

			//Complete
			IF  	GDB.Unit.IPS208i.IPS208i_Comm_OK_HP
				AND GDB.Unit.IPS208i.IPS208i_Comm_OK_OP
				AND GDB.Unit.IPS208i.iState_HP = 0
				AND GDB.Unit.IPS208i.iState_OP = 0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 
				AND GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1
			THEN       	   
 						GDB.auto._2_Unloading.Step := 5; //Step_5 : Revision		
						IPS_Y_Pos_Gap := GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Zero_Angle_IPS_Y - ((GDB.Unit.IPS208i.rYpos_RealData_HP + GDB.Unit.IPS208i.rYpos_RealData_OP)/2);
           	 ELSIF  GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 
				AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 10.0 THEN
			GDB.Auto._2_Unloading.Step := 21; // Line 91~93 230509 Demo port 티칭시 추가		
			END_IF;
		ELSE
			GDB.Unit.Drive.Move_Data.Difference_mm_X := 0;	
			GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
			GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
			IF  GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Loading[Direction - Left]				
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Y_Shift_Pos;
			ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
			END_IF;

			//Complete
			IF  	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				//AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 
			THEN       	   
						GDB.auto._2_Unloading.Step := 105; //Step_5 : Revision		
						IPS_Y_Pos_Gap := GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Zero_Angle_IPS_Y - ((GDB.Unit.IPS208i.rYpos_RealData_HP + GDB.Unit.IPS208i.rYpos_RealData_OP)/2);			
						Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;
						Y_Shift_Pos_Buffer := GDB.Monitor.Current_Y_Shift_Pos;
			END_IF;
		END_IF;

	END_IF;	

	//step_21
	IF GDB.Auto._2_Unloading.Step = 21  THEN

		IF  GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm) + GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Left_X_Center_Offset;

		ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm) - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Right_X_Center_Offset;

		END_IF;

		IF TRUE THEN  TON[6](IN:=  ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 1 ,pt := T#200MS );
		IF ton[6].Q  THEN
			GDB.Auto._2_Unloading.Step := 24;
		END_IF
		END_IF

		(*IF TRUE THEN  TON[5](IN:=  ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 1 + ABS(GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Left_X_Center_Offset) ,pt := T#200MS );
		IF ton[5].Q  THEN
			GDB.Auto._2_Unloading.Step := 24;
		END_IF
		END_IF*)
	END_IF

	IF GDB.Auto._2_Unloading.Step = 24  THEN
		ton[7](in:=FALSE);
		ton[6](in:= FALSE);
		ton[5](in:= FALSE);
		IF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN
		GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Left_Target_Y_Pos;
		ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN
			GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Right_Target_Y_Pos;
		END_IF
		IF TRUE THEN
		TON[9](IN:= ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0 ,pt := T#500MS);
		IF ton[9].Q THEN
			Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;

			GDB.Auto._2_Unloading.Step := 13;
			TON[9](IN:= FALSE);
		END_IF
	END_IF
	END_IF

	//Step_5_Revision
	IF GDB.auto._2_Unloading.Step = 5 THEN
		IF TRUE THEN				
			Auto_Turret_Angle_Revision( in_Enable:= GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 , 
										in_Chuck_X_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Chuck_X_Pos_Before, 
										in_Chuck_Y_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Chuck_Y_Pos_Before, 
										in_Reflector_X_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Reflector_X_Pos_Before, 
										in_Reflector_Y_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Reflector_Y_Pos_Before, 
										in_Y_Pos_Gap:= IPS_Y_Pos_Gap, 
										out_Turret_Angle_Gap=> Turret_Angle_Gap, 
										out_Move_X_Pos=> Turret_Revision_Move_X_Pos, 
										out_Move_Y_Pos=> Turret_Revision_Move_Y_Pos); 
			IF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Direction - Left									
				GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_HP_IPS_X + Turret_Revision_Move_X_Pos;
				GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_HP_IPS_Y;
				GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_OP_IPS_X + Turret_Revision_Move_X_Pos;
				GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_OP_IPS_Y;
			ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Direction - Right
				GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_HP_IPS_X - Turret_Revision_Move_X_Pos;
				GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_HP_IPS_Y;
				GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_OP_IPS_X - Turret_Revision_Move_X_Pos;
				GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_OP_IPS_Y;
			END_IF;									
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
			GDB.Unit.Drive.Move_Data.Difference_mm_Theta := (GDB.Unit.IPS208i.rXpos_HP - GDB.Unit.IPS208i.rXpos_OP);
			GDB.Unit.Drive.Move_Data.Difference_mm_Tilting := (GDB.Unit.IPS208i.rYpos_HP - GDB.Unit.IPS208i.rYpos_OP);				
			GDB.Unit.Drive.Move_Data.Difference_mm_Lift := (GDB.Unit.IPS208i.rYpos_HP + GDB.Unit.IPS208i.rYpos_OP)/2 ;													
			GDB.Unit.Drive.Move_Data.Difference_mm_Y := (GDB.Unit.IPS208i.rXpos_HP + GDB.Unit.IPS208i.rXpos_OP)/2 ;	
			END_IF;	
		//Complete
		IF TRUE THEN
			TON[2](IN:= 	ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Lift) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Y) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Theta) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Tilting) < 0.5						
				,PT:=T#300MS);

			IF TON[2].Q THEN
				GDB.auto._2_Unloading.Step := 105;
				Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;
				Y_Shift_Pos_Buffer := GDB.Monitor.Current_Y_Shift_Pos;
				RETURN;
			END_IF;
		END_IF;	
	END_IF;
	//Step_105_Data_Clear
	IF GDB.auto._2_Unloading.Step = 105 AND GDB.Touch.S901_Unloading_Step_Stop[5] = FALSE THEN
		GDB.auto._2_Unloading.Step := 11;	
	END_IF;

	//Step_11_Turret_Chucking_Check
		IF GDB.auto._2_Unloading.Step = 11 THEN
			//Complete
			IF		(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																					OR  (GDB.Auto.PIO.PIO_Ignore_Bit = TRUE AND GDB.Touch.S25_Turret_Complete))) 
				OR	(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 2)
				OR  (GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 33) THEN
					GDB.auto._2_Unloading.Step := 111;		
					TON[4](IN:=FALSE,PT:=T#100MS);						
			END_IF;	
		END_IF;	
	//Step_111_Data_Clear
	IF GDB.auto._2_Unloading.Step = 111 AND GDB.Touch.S901_Unloading_Step_Stop[11] = FALSE THEN
		GDB.auto._2_Unloading.Step := 13;	
	END_IF;



	//Step_13_Lift_Down
	GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit := FALSE;
	IF GDB.auto._2_Unloading.Step = 13 THEN
		IF TRUE THEN								
			GDB.Unit.Drive.Move_Data.Target_Pos_Lift := Lift_Pos_Buffer - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_DT;
						IF 		(Lift_Pos_Buffer - GDB.Monitor.Current_Lift_Pos) > GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_Decel_Start_DT 
							AND (Lift_Pos_Buffer - GDB.Monitor.Current_Lift_Pos) < GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_Decel_End_DT
						THEN 
							GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit := TRUE;
						END_IF;			
		END_IF;	
		//Complete
		IF 		ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0  THEN
				GDB.auto._2_Unloading.Step := 113;								
		END_IF;	
	END_IF;	
	//Step_113_Data_Clear
	IF 		GDB.auto._2_Unloading.Step = 113 
		AND GDB.Touch.S901_Unloading_Step_Stop[13] = FALSE
		(*AND (		(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  GDB.Auto.PIO.PIO_Ignore_Bit = TRUE))
				OR	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1)
                OR  (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 33 AND ( 	(GDB.Auto.PIO.PIO_Ignore_Bit = FALSE AND GDB.Unit.IO.di_DMS_in_6) 
																						OR  GDB.Auto.PIO.PIO_Ignore_Bit = TRUE)))*) THEN
		GDB.auto._2_Unloading.Step := 99;	
	END_IF;


    //Step_99_Command_Complete           
	IF GDB.auto._2_Unloading.Step = 99 THEN
        IF FALSE THEN
            GDB.auto._2_Unloading.Step := 1;
        END_IF;
	END_IF;

PROGRAM Auto_2_Unloading_1
VAR
TEST_ : ARRAY[1..30] OF BOOL;

PN_Pulse	:ARRAY[0..4] OF PN_Pulse;
TON	:ARRAY[0..5] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..2] OF Angle_Calcuration;


Auto_Wheel_Ready_Run	:Auto_Wheel_Ready_Run;
Auto_Wheel_Move_1	:Auto_Wheel_Move;
Auto_Wheel_Move_2	:Auto_Wheel_Move;


//Step3_Buffer
END_X_Buffer : REAL;
END_Y_Buffer : REAL;
IPS_Y_Pos_Gap : REAL;
//Step5_Buffer
Lift_Pos_Buffer : REAL;
Y_Shift_Pos_Buffer : REAL;
Auto_Turret_Angle_Revision : Auto_Turret_Angle_Revision;
Turret_Angle_Gap : REAL;
Turret_Revision_Move_X_Pos : REAL;
Turret_Revision_Move_Y_Pos : REAL;
//Step15_Buffer
START_X_Buffer : REAL;
START_Y_Buffer : REAL;
	Command_Up_Bit: INT;
END_VAR


//Step_Set
IF TRUE THEN
    //Step_Active
    IF GDB.auto.Main.Step = 3 AND GDB.Command.Command_Type = 2 THEN
        GDB.auto._2_Unloading.Active := TRUE;
    ELSE
        GDB.auto._2_Unloading.Active := FALSE;
    END_IF;
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._2_Unloading.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._2_Unloading.Step := 100;
    END_IF;
    //Step_Clear
    IF GDB.auto._2_Unloading.Active = FALSE THEN
        GDB.auto._2_Unloading.Step := 0;
    END_IF;    
END_IF;


//////////////////Command_Run이 완료된 시점 현제 현재위치가 목적지라면 언로딩을 시작함 아닐경우 언로딩 안함 


    //Step_1_Ready_Check
	IF GDB.auto._2_Unloading.Step = 1 THEN
		//Docking_Direction_Set
		Angle_Calcuration[1](in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
							in_X1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].X, 
							in_Y1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].Y, 
							in_X2_End:= GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X, 
							in_Y2_End:= GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y);
		Angle_Calcuration[2](in_3_Angle_SUB_bit:= TRUE, 
							in_SUB_1_1:= Angle_Calcuration[1].out_1_Theta_us360, 
							in_SUB_1_2:= GDB.Monitor.Current_AGV_Angle);
		GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 0;
		IF Angle_Calcuration[2].out_3_SUB1_s180 > 80 AND Angle_Calcuration[2].out_3_SUB1_s180 < 100 THEN					
			GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 1;
		ELSIF Angle_Calcuration[2].out_3_SUB1_s180 > -100 AND Angle_Calcuration[2].out_3_SUB1_s180 < -80 THEN				
			GDB.Auto._2_Unloading.Docking_Direction_1L_2R := 2;
		END_IF;

/////////////////각 축 기본 보정을 한뒤 좌입 우입 결정		


		//Docking_Direction_Angle_Set
		IF (GDB.Monitor.Current_AGV_Angle > 350 OR GDB.Monitor.Current_AGV_Angle < 10) THEN
			GDB.Auto._2_Unloading.Docking_Direction_Angle := 0;
		ELSIF (GDB.Monitor.Current_AGV_Angle > 80 AND GDB.Monitor.Current_AGV_Angle < 100) THEN
			GDB.Auto._2_Unloading.Docking_Direction_Angle := 90;
		ELSIF (GDB.Monitor.Current_AGV_Angle > 170 AND GDB.Monitor.Current_AGV_Angle < 190) THEN
			GDB.Auto._2_Unloading.Docking_Direction_Angle := 180;
		ELSIF (GDB.Monitor.Current_AGV_Angle > 260 AND GDB.Monitor.Current_AGV_Angle < 280) THEN
			GDB.Auto._2_Unloading.Docking_Direction_Angle := 270;
		ELSE
			GDB.Auto._2_Unloading.Docking_Direction_Angle := 999;
		END_IF;

//////////////// 언로딩 방향 설정	999는 정상작동 중이 아님


		//Complete
       	IF  GDB.mode.Pause = FALSE
			//AND TEST_[1]
			AND GDB.Unit.IO.di_Product_Detect = TRUE
			AND GDB.Auto._2_Unloading.Docking_Direction_1L_2R <> 0
			AND GDB.Auto._2_Unloading.Docking_Direction_Angle <> 999
       	    AND GDB_Retain.Current_Node = GDB.Command.Dest_Node
			AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2
       	    AND ABS(GDB_Retain.Node[GDB_Retain.Current_Node].X - GDB.monitor.Current_X) < 20.0
       	    AND ABS(GDB_Retain.Node[GDB_Retain.Current_Node].Y - GDB.monitor.Current_Y) < 20.0
			AND GDB.Unit.IPS208i.Program_Change_OK_HP
			AND GDB.Unit.IPS208i.Program_Change_OK_OP THEN
       	    GDB.auto._2_Unloading.Step := 2;
       	END_IF;
	END_IF;		      

////////////////// 정상 작동 중 위의 조건이 충족하면 스텝 2로 



    //Step_2_Wheel_Ready_Run
	IF GDB.auto._2_Unloading.Step = 2 THEN	
        Auto_Wheel_Ready_Run(in_Enable:=TRUE,
                                       in_Work_Type:=10#1,
                                       in_Start_X:=GDB.monitor.Current_X,
                                       in_Start_Y:=GDB.monitor.Current_Y,
                                       in_End_X:=GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X,
                                       in_End_Y:=GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y,
                                       in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                       in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                       in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                       out_Target_FW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                       out_Target_BW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle);
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
			//AND TEST_[2]
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0 THEN
            GDB.auto._2_Unloading.Step := 3;
        END_IF;
	END_IF;

///////////////////	목적 위치까지 휠준비 완료시 step 3로	


    //Step_3_Wheel_Move(Docking_Point)	
	PN_Pulse[2](in_Type:=1 , in_Signal:=GDB.auto._2_Unloading.Step = 3);
	IF GDB.auto._2_Unloading.Step = 3 THEN
        IF TRUE THEN
			//Data_Set( End_X,Y / LIFT / Y_Shift / Y_Navi )
			IF TRUE THEN
				GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
				GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
				IF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Direction - Left
					END_X_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X + 0;
					END_Y_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y + 0;
					GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Y_Navi_Pos; 				
					GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Lift_Pos;
					GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Y_Shift_Pos;
				ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Direction - Right
					END_X_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X - GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					END_Y_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y - GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
					GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Y_Navi_Pos; 
					GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Lift_Pos;
					GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_3_Y_Shift_Pos;
				END_IF;
			END_IF;

///////step 3 일때 펄스[2] 작동  
///////좌입은 x,y,나브축 초기상태에서 나브는 -*축, 리프트는 그대로 y축서보는 +*축 방향으로 이동 
///////우입은 x,y,나브축 초기상태에서 나브는 +*축, 리프트는 그대로 y축서보는 -*축 방향으로 이동하게 세팅


            Auto_Wheel_Move_1(Enable:=TRUE,
                                      in_Renew_Bit:=PN_Pulse[2].out_Pulse,                            //	Enable=TRUE => 항상 활성화
                                      in_Pause:=FALSE,                                                //  진입 시점 펄스로 갱신 시작
                                      in_Pause:=GDB.mode.Pause,                                       //  외부에서 정지 명령이 오면 일시 정지 
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Command_Current_Number := GDB.Command.Current_Number,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
                                      out_Command_Up_Bit=>GDB.Command.Command_Up_Bit,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4);
        END_IF;
//////////////////in: 현재 상태&맵 정보&보정값 입력 부,   out:FB 내부 주행/ 조향/ 보정 연산 결과         
////////////////// 위에는 나머지 보정이나 이동값들 어디서 적용되는지, 주행 위치 목표 위치 


        //Complete
		IF TRUE THEN
	            TON[1](IN := ((GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 5.0),
	                    PT := T#300MS);        //실제 위치가 목표위차의 차이가 5mm이내일때 작동
	        IF TON[1].Q 
				AND GDB.Unit.Drive.LiftControl.Target_reached_Bit
				AND GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Complete
				AND	GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Theta_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Tilting_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Complete THEN
	            GDB.auto._2_Unloading.Step := 103;

				RETURN;
	        END_IF;
		END_IF;
//////////////////  타이머 종료후 목표로 이동했나 나머지 축들 작동 완료했는지 확인되면 step 103번으로


	END_IF;	        
	//Step_103_Data_Clear
	IF GDB.auto._2_Unloading.Step = 103 (*AND TEST_[3]*) THEN
		GDB.auto._2_Unloading.Step := 5;	
		IPS_Y_Pos_Gap := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Zero_Angle_IPS_Y - ((GDB.Unit.IPS208i.rYpos_RealData_HP + GDB.Unit.IPS208i.rYpos_RealData_OP)/2);
	END_IF;
/////////////////	(터렛의 각도가 0일 때, IPS Y의 좌표 - (HP+OP)/2 ) 값을 ips y축 보정치 평균값

	//Step_5_Revision
	IF GDB.auto._2_Unloading.Step = 5 THEN
		IF TRUE THEN				
			Auto_Turret_Angle_Revision( in_Enable:= GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 , 
										in_Chuck_X_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Chuck_X_Pos_Before, 
										in_Chuck_Y_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Chuck_Y_Pos_Before, 
										in_Reflector_X_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Reflector_X_Pos_Before, 
										in_Reflector_Y_Pos_Before:= GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Turret_Reflector_Y_Pos_Before, 
										in_Y_Pos_Gap:= IPS_Y_Pos_Gap, 
										out_Turret_Angle_Gap=> Turret_Angle_Gap, 
										out_Move_X_Pos=> Turret_Revision_Move_X_Pos, 
										out_Move_Y_Pos=> Turret_Revision_Move_Y_Pos); 

                                               ///// 터렛 회전이 필요한지 파악 후 보정치 계산 
											   ///// 척과 리플랙터의 이전 위치의 차이로 보정 각도 위치 

			IF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Direction - Left									
				GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_HP_IPS_X;
				GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_HP_IPS_Y;
				GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_OP_IPS_X;
				GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Left_OP_IPS_Y;
			ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Direction - Right
				GDB.Unit.IPS208i.rXpos_HP := GDB.Unit.IPS208i.rXpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_HP_IPS_X;
				GDB.Unit.IPS208i.rYpos_HP := GDB.Unit.IPS208i.rYpos_RealData_HP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_HP_IPS_Y;
				GDB.Unit.IPS208i.rXpos_OP := GDB.Unit.IPS208i.rXpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_OP_IPS_X;
				GDB.Unit.IPS208i.rYpos_OP := GDB.Unit.IPS208i.rYpos_RealData_OP - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_5_Right_OP_IPS_Y;

				///////도킹 방향 좌,우 에 따라 IPS 센서의 HP/OP X,Y좌표를 보정함
            END_IF;									
			GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
			GDB.Unit.Drive.Move_Data.Difference_mm_Theta := (GDB.Unit.IPS208i.rXpos_HP - GDB.Unit.IPS208i.rXpos_OP);
			GDB.Unit.Drive.Move_Data.Difference_mm_Tilting := (GDB.Unit.IPS208i.rYpos_HP - GDB.Unit.IPS208i.rYpos_OP);				
			GDB.Unit.Drive.Move_Data.Difference_mm_Lift := (GDB.Unit.IPS208i.rYpos_HP + GDB.Unit.IPS208i.rYpos_OP)/2 ;													
			GDB.Unit.Drive.Move_Data.Difference_mm_Y := (GDB.Unit.IPS208i.rXpos_HP + GDB.Unit.IPS208i.rXpos_OP)/2 ;	
			END_IF;	
				/////각 서보축 보정치를 계산


		//Complete
		IF TRUE THEN
			TON[2](IN:= 	ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Lift) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Y) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Theta) < 0.5
						AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Tilting) < 0.5						
				,PT:=T#300MS);

				//위 보정치 내에 위치해 있을때 타이머 동작

			IF TON[2].Q THEN
				GDB.auto._2_Unloading.Step := 105;
				Lift_Pos_Buffer := GDB.Monitor.Current_Lift_Pos;
				Y_Shift_Pos_Buffer := GDB.Monitor.Current_Y_Shift_Pos;
				RETURN;
			END_IF;
			//위 조건 충족시 타이머 종료 후 step105번으로, 또 리프트와 y축 현재 좌표를 저장해 둠(buffer)

		END_IF;	
	END_IF;
	//Step_105_Data_Clear
	IF GDB.auto._2_Unloading.Step = 105 (*AND TEST_[5]*) THEN
		GDB.auto._2_Unloading.Step := 11;	
	END_IF;
/////step 11로

	//Step_11_Turret_UnChucking_Check
		IF GDB.auto._2_Unloading.Step = 11 THEN
			//Complete
			IF		(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 AND TEST.Chucking_OK)
				OR	(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 2) THEN
					GDB.auto._2_Unloading.Step := 13;		
					TON[4](IN:=FALSE,PT:=T#100MS);						
			END_IF;	
		END_IF;	

		//////////// 터렛 언처킹 되어있거나 포트면 step 13으로 


	//Step_13_Lift_Down
	GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit := FALSE;
	IF GDB.auto._2_Unloading.Step = 13 THEN
		IF TRUE THEN								
			GDB.Unit.Drive.Move_Data.Target_Pos_Lift := Lift_Pos_Buffer - GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_DT;
						IF 		(Lift_Pos_Buffer - GDB.Monitor.Current_Lift_Pos) > GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_Decel_Start_DT 
							AND (Lift_Pos_Buffer - GDB.Monitor.Current_Lift_Pos) < GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Step_13_Lift_Decel_End_DT
						THEN 
							GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit := TRUE;
						END_IF;			
		END_IF;	
		//////////// 언로딩 시 리프트값과 감속 시작, 감속 종료 설정 


		//Complete
		IF 		ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0  THEN
				GDB.auto._2_Unloading.Step := 113;
				RETURN;								
		END_IF;	
	END_IF;	

	/////////////// 목표 리프트값까지 리프팅 되었는지 확인 되면 step 113로


	//Step_113_Data_Clear
	IF GDB.auto._2_Unloading.Step = 113 (*AND TEST_[13]*) THEN
		GDB.auto._2_Unloading.Step := 15;	
	END_IF;

	//Step_15_Wheel_Move(Wait_Point)
	PN_Pulse[4](in_Type:=1 , in_Signal:=GDB.auto._2_Unloading.Step = 15);
	IF GDB.auto._2_Unloading.Step = 15 THEN
        IF TRUE THEN
			//Data_Set( START_X,Y / LIFT / Y_Shift / Y_Navi )
			IF TRUE THEN
				IF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 1 THEN //Direction - Left
					START_X_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X + 0;
					START_Y_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y + 0;					
				ELSIF GDB.Auto._2_Unloading.Docking_Direction_1L_2R = 2 THEN //Direction - Right
					START_X_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_X - GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					START_Y_Buffer := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Y - GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
				END_IF;
				GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
				GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;
			END_IF;
			////////// 로딩 할때 위치를 기준으로 두었음으로 우측 도킹 오프셋 을 줌 -??인 이유 
			////////// 나머지 서보 축들은 0으로 설정 



            Auto_Wheel_Move_2(Enable:=TRUE,
                                      in_Renew_Bit:=PN_Pulse[4].out_Pulse,               //	Enable=TRUE => 항상 활성화 
                                      in_Pause:=FALSE,                                   //  진입 시점 펄스로 갱신 시작
                                      in_Current_X_mm:=GDB.monitor.Current_X,            //  외부에서 정지 명령이 오면 일시 정지 
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Command_Current_Number := 100,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
                                      out_Command_Up_Bit=>GDB.Command.Command_Up_Bit,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4);
        END_IF;
        //////////////////in: 현재 상태&맵 정보&보정값 입력 부,   out:FB 내부 주행/ 조향/ 보정 연산 결과         
        ////////////////// 위에는 나머지 보정이나 이동값들 어디서 적용되는지, 주행 위치 목표 위치 



        //Complete
		IF TRUE THEN
	            TON[5](IN := ((GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#300MS);
	        IF TON[5].Q 
				//AND TEST_[15]
				AND GDB.Unit.Drive.LiftControl.Target_reached_Bit
				AND GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Complete
				AND	GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Theta_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Tilting_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Complete THEN
	            GDB.auto._2_Unloading.Step := 99;
	        END_IF;
		END_IF;
	END_IF;	    
	//////////////// 목표위치와 실제위치가 조건에 만족하면 타이머 작동 타이머 종료 후 위조건 만족하면 step 99로



    //Step_99_Command_Complete           
	IF GDB.auto._2_Unloading.Step = 99 THEN
        IF FALSE THEN
            GDB.auto._2_Unloading.Step := 100;
        END_IF;
	END_IF;    

/////////////////  99 false시 step 100


    //Step_100_Data Clear
	IF GDB.auto._2_Unloading.Step = 100 THEN
        IF TRUE THEN
            GDB.auto._2_Unloading.Step := 1;
        END_IF;
//// step 1로 돌아감 (초기화)		


	END_IF;

PROGRAM Auto_3_move
VAR
PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
TON	:ARRAY[0..1] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Auto_Wheel_Ready_Run_Instance	:Auto_Wheel_Ready_Run;
Auto_Wheel_move	:Auto_Wheel_move;

X_Offset	:REAL;
Y_Offset	:REAL;

END_VAR


//Initialize
GDB.Auto._3_Move.Pause := FALSE;
GDB.Auto._3_Move.Step_5_Y_Shift_Home := FALSE;
GDB.Auto._3_move.Step_7_EPC_Data := 0;
GDB.Auto._3_move.Step_7_Loading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := FALSE;
X_Offset := 0;
Y_Offset := 0;
//Pause
IF 	GDB.ACS.Host_pause 
	OR	GDB.Auto.PIO.PIO_Move_Pause_Bit
THEN
	GDB.Auto._3_Move.Pause := TRUE;
END_IF;

// X,Y_Offsetㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
	IF TRUE THEN								
		// Docking_Node_in Offset
		IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
				IF GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //[Direction - Left]
					X_Offset := 0;
					Y_Offset := 0;						
				ELSIF GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //[Direction - Right]
					X_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					Y_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
				END_IF;
				//EPC_Data_Set
				IF TRUE THEN
					IF GDB.Mode.Auto THEN
						GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;
					ELSIF GDB.Mode.Semi_Auto THEN
						GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;
					END_IF;	
					IF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 1 THEN
						X_Offset := X_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;
						Y_Offset := Y_Offset;					
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 2 THEN
						X_Offset := X_Offset;
						Y_Offset := Y_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 3 THEN
						X_Offset := X_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;
						Y_Offset := Y_Offset;									
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 4 THEN				
						X_Offset := X_Offset;
						Y_Offset := Y_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;									
					END_IF;
				END_IF;
		END_IF;
	END_IF;

//ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._3_move.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._3_move.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._3_move.Active = FALSE THEN
        GDB.auto._3_move.Step := 0;
    END_IF;	    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._3_move.Step = 1 THEN
        //Ready_Check_Complete
        IF  GDB.Auto._3_move.Pause = FALSE
            AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node = GDB_Retain.Current_Node
			AND NOT(GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2 AND GDB.Auto.Main.Distance_Curr_Dest < 1200 ) //Docking_Node 진입시, 최소거리 1200mm 확보필요.
        THEN			
	        IF GDB.Command.Direction_Angle_State = 1 THEN //Direction_Angle이 OK인 경우 Step_5
		            GDB.auto._3_move.Step := 5;
			ELSIF GDB.Command.Direction_Angle_State = 2 THEN //Direction_Angle이 NG인 경우 Step_3
					GDB.auto._3_move.Step := 3;
			END_IF;	
        END_IF;
		IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN //현재노드가 목적노드일 경우, Step_99(완료).
					GDB.auto._3_move.Step := 99;
		END_IF;	
	END_IF;	
	//Step_3_Spinturn
	IF GDB.auto._3_move.Step = 3 THEN    
		GDB.auto._5_Spinturn.Active := TRUE;
		GDB.Auto._5_Spinturn.Target_AGV_Angle := GDB.Command.Direction_Angle;
		IF GDB.Auto._5_Spinturn.Step = 99 THEN
			GDB.auto._3_move.Step := 5;
		END_IF				
	END_IF;	
    //Step_5_Wheel_Ready_Run
	IF GDB.auto._3_move.Step = 5 THEN
		//Y_Shift_Home
		IF GDB.Auto.Main.Docking_Node_in_3000mm = FALSE AND GDB.Unit.IO.di_Product_Detect THEN
		GDB.Auto._3_Move.Step_5_Y_Shift_Home := TRUE;
		GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
		END_IF;
		//Auto_Wheel_Ready_Run
        Auto_Wheel_Ready_Run_Instance(in_Enable:=TRUE,
                                       in_Work_Type:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type,
                                       in_Start_X:=GDB.monitor.Current_X,
                                       in_Start_Y:=GDB.monitor.Current_Y,
                                       in_End_X:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X - X_Offset,
                                       in_End_Y:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y - Y_Offset,
                                       in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                       in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                       in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                       out_Target_FW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                       out_Target_BW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle);
		IF 		gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle <= 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90;
		ELSIF	gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle > 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270;	
		END_IF;					   
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0
			AND ( (GDB.Auto._3_Move.Step_5_Y_Shift_Home AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0)
					OR (GDB.Auto._3_Move.Step_5_Y_Shift_Home = FALSE) ) THEN
            GDB.auto._3_move.Step := 7;
        END_IF;
    END_IF;

    //Step_7_Move	
	PN_Pulse[2](in_Type:= 1, in_Signal:= GDB.auto._3_move.Step = 7);	
	IF GDB.auto._3_move.Step = 7 THEN
        IF TRUE THEN		
			// Upper_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
			IF TRUE THEN				
				//Upper_Ready_Move(Docking)
				IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;

						IF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Loading[Direction - Left]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Unloading[Direction - Left]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Unloading[Direction - Right]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos - 5;	
						END_IF;

				//Upper_Home		
				ELSE 			
						IF GDB.Auto.Main.Distance_Curr_StartPoint > 500 THEN
							GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := TRUE;
							GDB.Auto._3_move.Step_7_Home_Bit := TRUE;
						END_IF;							
						GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;							
				END_IF;
			END_IF;
			// Travel_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
            		Auto_Wheel_move(  in_Enable:=TRUE,                                      
									  in_StartSet_Renew := PN_Pulse[2].out_Pulse,
                                      in_Extend_Permission_Bit:=GDB.Auto._3_move.Pause=FALSE,
									  in_Current_Wheel_Angle_Hold_Bit := gdb.Auto.Main.Docking_Node_out_500mm,
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Current_Node:= GDB_Retain.Current_Node, 									  
									  in_Command_Current_Number := GDB.Command.Current_Number,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
									  in_Start_X_Offset:= X_Offset, 
									  in_Start_Y_Offset:= Y_Offset, 
									  in_End_X_Offset:= X_Offset, 
									  in_End_Y_Offset:= Y_Offset,
									  out_Current_Node=> GDB_Retain.Current_Node,  
                                      out_Command_Current_Number=>GDB.Command.Current_Number,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4,
									  out_Error_Code=>GDB.Auto._3_Move.Step_7_Move_Error_Code);
        END_IF;        
        //Move_Complete
		IF TRUE THEN
	        IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 1
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 5.0),
	                    PT := T#500MS);
	        ELSIF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#200MS);
	        ELSE
	            TON[1](IN := FALSE,
	                    PT := T#200MS);
	        END_IF;
	        IF 		TON[1].Q 
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift - GDB.Monitor.Current_X_Shift_Pos) < 1.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 THEN			
					GDB.auto._3_move.Step := 9;	
				END_IF            
        END_IF;
	END_IF;	
	//Step_9_Step_Return or Command_Complete
	IF GDB.auto._3_move.Step = 9 THEN
		IF TRUE THEN
			GDB_Retain.Current_Node := GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node;
			GDB.Command.Current_Number := GDB.Command.Current_Number + 1;
			IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN
				GDB.auto._3_move.Step := 99;
			ELSE
				GDB.auto._3_move.Step := 1;	
			END_IF
        END_IF;
	END_IF;	
    // 99: Command_Complete        
    IF GDB.auto._3_move.Step = 99 THEN
		IF FALSE THEN
			GDB.auto._3_move.Step := 1;	
		END_IF;                
	END_IF;

PROGRAM Auto_3_Move_1
VAR
PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
TON	:ARRAY[0..1] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Auto_Wheel_Ready_Run_Instance	:Auto_Wheel_Ready_Run;
Auto_Wheel_move	:Auto_Wheel_move;

X_Offset	:REAL;
Y_Offset	:REAL;

END_VAR


//Initialize
GDB.Auto._3_Move.Pause := FALSE;
GDB.Auto._3_Move.Step_5_Y_Shift_Home := FALSE;
GDB.Auto._3_move.Step_7_EPC_Data := 0;
GDB.Auto._3_move.Step_7_Loading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := FALSE;
gdb.Auto._3_Move.Step_7_X_Offset := 0;
gdb.Auto._3_Move.Step_7_Y_Offset := 0;
//Pause
IF 	GDB.ACS.Host_pause 
	OR	GDB.Auto.PIO.PIO_Move_Pause_Bit
THEN
	GDB.Auto._3_Move.Pause := TRUE;
END_IF;

// X,Y_Offsetㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
	IF TRUE THEN								
		// Docking_Node_in Offset
		IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
				IF GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //[Direction - Left]
					gdb.Auto._3_Move.Step_7_X_Offset := 0;
					gdb.Auto._3_Move.Step_7_Y_Offset := 0;					
				ELSIF GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //[Direction - Right]
					gdb.Auto._3_Move.Step_7_X_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					gdb.Auto._3_Move.Step_7_Y_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
				END_IF;
		END_IF;
				//EPC_Data_Set
				IF TRUE THEN

					IF GDB.Mode.Auto THEN					

						IF 
								((GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction <> 0)	
								AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 2000.0))
								OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction <> 0) THEN
								GDB.ACS.EPC_Data := GDB.ACS.EPC_Data;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;
						ELSE
								GDB.ACS.EPC_Data := 0.00;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;

						END_IF;
					END_IF

					IF gdb.Mode.Semi_Auto THEN
						IF 
								((GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction <> 0)	
								AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 2000.0))
								OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction <> 0) THEN
								GDB.ACS.EPC_Data := GDB.ACS.EPC_Data;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;
						ELSE
								GDB.ACS.EPC_Data := 0.00;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;

						END_IF;
					END_IF

					IF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 1 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset;						
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 2 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 3 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 4 THEN				
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;									
					END_IF;
				END_IF;

	END_IF;

//ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._3_move.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._3_move.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._3_move.Active = FALSE THEN
        GDB.auto._3_move.Step := 0;
    END_IF;	    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._3_move.Step = 1 THEN
        //Ready_Check_Complete
        IF  GDB.Auto._3_move.Pause = FALSE
            AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node = GDB_Retain.Current_Node
			AND NOT(GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2  AND GDB.Auto.Main.Distance_Curr_Dest < 1000 ) //Docking_Node 진입시, 최소거리 1200mm 확보필요.
	        THEN			
	        IF GDB.Command.Direction_Angle_State = 1 THEN //Direction_Angle이 OK인 경우 Step_5
		            GDB.auto._3_move.Step := 5;
			ELSIF GDB.Command.Direction_Angle_State = 2 THEN //Direction_Angle이 NG인 경우 Step_3
					GDB.auto._3_move.Step := 3;
			END_IF;	
        END_IF;
		IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN //현재노드가 목적노드일 경우, Step_99(완료).
					GDB.auto._3_move.Step := 99;
		END_IF;	
	END_IF;	
	//Step_3_Spinturn
	IF GDB.auto._3_move.Step = 3 THEN    
		GDB.auto._5_Spinturn.Active := TRUE;
		GDB.Auto._5_Spinturn.Target_AGV_Angle := GDB.Command.Direction_Angle;
		IF GDB.Auto._5_Spinturn.Step = 99 THEN
			GDB.auto._3_move.Step := 5;
		END_IF				
	END_IF;	
    //Step_5_Wheel_Ready_Run
	IF GDB.auto._3_move.Step = 5 THEN
		//Y_Shift_Home
		IF GDB.Auto.Main.Docking_Node_in_3000mm = FALSE AND GDB.Unit.IO.di_Product_Detect THEN
		GDB.Auto._3_Move.Step_5_Y_Shift_Home := TRUE;
		GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
		END_IF;
		//Auto_Wheel_Ready_Run
        Auto_Wheel_Ready_Run_Instance(in_Enable:=TRUE,
                                       in_Work_Type:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type,
                                       in_Turn:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Turn,
									   in_Start_X:=GDB.monitor.Current_X,
                                       in_Start_Y:=GDB.monitor.Current_Y,
                                       in_End_X:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X - gdb.Auto._3_Move.Step_7_X_Offset,
                                       in_End_Y:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y - gdb.Auto._3_Move.Step_7_Y_Offset,
                                       in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                       in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                       in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                       out_Target_FW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                       out_Target_BW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
									    out_Turn_Error_Bit => GDB.Auto._3_Move.Step_3_Wheel_Turn_Data_Error);
		IF 		gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle <= 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90;
		ELSIF	gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle > 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270;	
		END_IF;					   
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0
			AND ( (GDB.Auto._3_Move.Step_5_Y_Shift_Home AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0)
					OR (GDB.Auto._3_Move.Step_5_Y_Shift_Home = FALSE) ) THEN
            GDB.auto._3_move.Step := 7;
        END_IF;
    END_IF;

    //Step_7_Move	
	PN_Pulse[2](in_Type:= 1, in_Signal:= GDB.auto._3_move.Step = 7);	
	IF GDB.auto._3_move.Step = 7 THEN
        IF TRUE THEN		
			// Upper_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
			IF TRUE THEN				
				//Upper_Ready_Move(Docking)
				IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;

						IF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Loading[Direction - Left]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Unloading[Direction - Left]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Unloading[Direction - Right]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos - 5;	
						END_IF;

				//Upper_Home		
				ELSE 			
						IF GDB.Auto.Main.Distance_Curr_StartPoint > 500 THEN
							GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := TRUE;
							GDB.Auto._3_move.Step_7_Home_Bit := TRUE;
						END_IF;							
						GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;							
				END_IF;
			END_IF;
			// Travel_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
            		Auto_Wheel_move(  in_Enable:=TRUE,                                      
									  in_StartSet_Renew := PN_Pulse[2].out_Pulse,
                                      in_Extend_Permission_Bit:=GDB.Auto._3_move.Pause=FALSE,
									  in_Current_Wheel_Angle_Hold_Bit := gdb.Auto.Main.Docking_Node_out_500mm,
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Current_Node:= GDB_Retain.Current_Node, 									  
									  in_Command_Current_Number := GDB.Command.Current_Number,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
									  in_Start_X_Offset:= gdb.Auto._3_Move.Step_7_X_Offset, 
									  in_Start_Y_Offset:= gdb.Auto._3_Move.Step_7_Y_Offset, 
									  in_End_X_Offset:= gdb.Auto._3_Move.Step_7_X_Offset, 
									  in_End_Y_Offset:= gdb.Auto._3_Move.Step_7_Y_Offset,
									  out_Current_Node=> GDB_Retain.Current_Node,  
                                      out_Command_Current_Number=>GDB.Command.Current_Number,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4,
									  out_Error_Code=>GDB.Auto._3_Move.Step_7_Move_Error_Code);
        END_IF;        
        //Move_Complete
		IF TRUE THEN
	        IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 1
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 5.0),
	                    PT := T#500MS);
	        ELSIF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#200MS);
	        ELSE
	            TON[1](IN := FALSE,
	                    PT := T#200MS);
	        END_IF;
	        IF 		TON[1].Q 
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift - GDB.Monitor.Current_X_Shift_Pos) < 1.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 THEN			
					GDB.auto._3_move.Step := 9;	
				END_IF            
        END_IF;
	END_IF;	
	//Step_9_Step_Return or Command_Complete
	IF GDB.auto._3_move.Step = 9 THEN
		IF TRUE THEN
			GDB_Retain.Current_Node := GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node;
			GDB.Command.Current_Number := GDB.Command.Current_Number + 1;
			IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN
				GDB.auto._3_move.Step := 99;
			ELSE
				GDB.auto._3_move.Step := 1;	
			END_IF
        END_IF;
	END_IF;	
    // 99: Command_Complete        
    IF GDB.auto._3_move.Step = 99 THEN
		IF FALSE THEN
			GDB.auto._3_move.Step := 1;	
		END_IF;                
	END_IF;

PROGRAM Auto_4_Charge
VAR
PN_Pulse	:ARRAY[0..1] OF PN_Pulse;
TON	:ARRAY[0..2] OF TON;
TOF	:ARRAY[0..0] OF TOF;
END_VAR


//Step_Set
IF TRUE THEN
	//ACS 연결 안됐을때 자동 충전 Test
	TON[2] (IN:= (GDB.Mode.Auto AND GDB.Mode.Active AND ACS.ACS_Comm_OK = FALSE AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 3),PT:= T#10S);
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._4_Charge.Active OR TON[2].Q);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._4_Charge.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._4_Charge.Active = FALSE THEN
        GDB.auto._4_Charge.Step := 0;
		TON[1](IN:=FALSE);
    END_IF;

END_IF;

//Initialize
GDB.Unit.IO.do_Auto_Charge_On := FALSE;

CASE GDB.auto._4_Charge.Step OF
    1:  //Ready_Check
        IF GDB.mode.Reset THEN
			GDB.auto._4_Charge.Step := 0;
		END_IF
		IF TRUE THEN
            //Ready_Check_Complete
            IF 		GDB_Retain.Current_Node = GDB.Command.Dest_Node
				AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 3 THEN
                GDB.auto._4_Charge.Step := 3;
            END_IF;
        END_IF;

    3:  //Charge
        IF TRUE THEN
			GDB.Unit.IO.do_Auto_Charge_On := TRUE;
        END_IF;

        //Charge_Complete
        IF 		((GDB.Unit.Tabos_Battery.Battery_1_SOC_Percentage + GDB.Unit.Tabos_Battery.Battery_2_SOC_Percentage)/2 > 65.0) 
			OR 	GDB.ACS.Command_Charge_Stop_Bit THEN
            GDB.auto._4_Charge.Step := 99;
        END_IF;

        // 99: Command_Complete        
    99:
        IF FALSE THEN
            GDB.auto._4_Charge.Step := 1;
        END_IF;
    ELSE
        GDB.auto._4_Charge.Step := 0;
END_CASE;

PROGRAM Auto_5_SpinTurn
VAR
PN_Pulse	:ARRAY[0..1] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..1] OF Angle_Calcuration;

END_VAR



//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._5_SpinTurn.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._5_SpinTurn.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._5_SpinTurn.Active = FALSE THEN
        GDB.auto._5_SpinTurn.Step := 0;
    END_IF;

END_IF;

//Data_Set
IF TRUE THEN
    Angle_Calcuration[1](in_3_Angle_SUB_bit := TRUE,
                          in_SUB_1_1 := GDB.auto._5_SpinTurn.Target_AGV_Angle,
                          in_SUB_1_2 := GDB.monitor.Current_AGV_Angle,
                          out_3_SUB1_s180 => GDB.auto._5_SpinTurn.SUB_Target_Currnet_s180,
                          out_3_SUB1_us180 => GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180);
    GDB.auto._5_SpinTurn.Distance_Per_Degree := ((GDB_Parameter.Distance_FwWheel_BwWheel_mm * 3.141593) / 360.0);
END_IF;

CASE GDB.auto._5_SpinTurn.Step OF
    1:  //Ready_Check
        IF TRUE THEN
            //Ready_Check_Complete
            IF GDB.auto._5_SpinTurn.Target_AGV_Angle >= 0 AND GDB.auto._5_SpinTurn.Target_AGV_Angle < 360 AND
				GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE <> 2 AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE <> 3 AND
			   (GDB_Retain.Node[GDB_Retain.Current_Node].SpinTurn = TRUE OR GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 10 OR GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 > 350) THEN
                GDB.auto._5_SpinTurn.Step := 2;
            END_IF;
            //Ready_Check_StepJump
            IF GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 1.0 THEN
                GDB.auto._5_SpinTurn.Step := 99;
            END_IF;
        END_IF;


    2:  //Wheel_Ready_Run
		IF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) <= 360 THEN
        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90.0;
        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90.0;
		ELSIF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) > 360 THEN
        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270.0;
        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270.0;		
		END_IF;
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0 THEN
            GDB.auto._5_SpinTurn.Step := 3;
        END_IF;

    3:  //Move
		IF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) <= 360 THEN
    	    GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90.0;
    	    GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90.0;
		ELSIF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) > 360 THEN
	        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270.0;
	        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270.0;		
		END_IF;        
        //Move_Complete
        IF GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 1.0 THEN
            GDB.auto._5_SpinTurn.Step := 99;
        END_IF;

        // 99: Command_Complete        
    99:
        IF FALSE THEN
            GDB.auto._5_SpinTurn.Step := 1;
        END_IF;
    ELSE
        GDB.auto._5_SpinTurn.Step := 0;
END_CASE;

PROGRAM Auto_Main
VAR
test : INT;	


PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..2] OF Angle_Calcuration;
Loop_Index	:INT;
Data_Conversion_Instance	: Data_Conversion;

END_VAR


//[Data_Conversion(Link_ID_List)]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
IF TRUE THEN    
    //Initialize
    GDB.Data_Conversion.in_Start_Bit := FALSE;
    GDB.Data_Conversion.in_Add_Bit := FALSE;
	GDB.Data_Conversion.in_Data[0] := GDB_Retain.Current_Node;	
	//Auto_Mode_Start
    IF GDB.ACS.Command_Start_Bit THEN
        GDB.Data_Conversion.in_Start_Bit := TRUE;
	ELSIF GDB.ACS.Command_Add_Bit THEN
        GDB.Data_Conversion.in_Add_Bit := TRUE;	
    END_IF;	
	//SemiAuto_Mode_Start    
    IF GDB.semi_auto.Command_Start_Bit THEN
        GDB.Data_Conversion.in_Start_Bit := TRUE;
    END_IF;

    Data_Conversion_Instance(in_Enable := TRUE,
                              in_Start_Bit := GDB.Data_Conversion.in_Start_Bit,
                              in_Add_Bit := GDB.Data_Conversion.in_Add_Bit,
                              in_Command_Type := GDB.Data_Conversion.in_Command_Type,
                              in_Dest_Node := GDB.Data_Conversion.in_Dest_Node,
                              in_Data := GDB.Data_Conversion.in_Data,
							  in_Current_Node := GDB_Retain.Current_Node,
							  in_SpinTurn_Target_Angle := gdb.Data_Conversion.in_SpinTurn_Target_Angle,
                              out_Complete => GDB.Data_Conversion.out_Complete_Bit,
                              out_Command_Type => GDB.Data_Conversion.out_Command_Type,
                              out_Dest_Node => GDB.Data_Conversion.out_Dest_Node,
							  out_SpinTurn_Target_Angle => gdb.Data_Conversion.out_SpinTurn_Target_Angle,
                              out_Data => GDB.Data_Conversion.out_Data,							  
                              out_Error_In_Data_Fault => GDB.Data_Conversion.out_Error_In_Data_Fault,
                              out_Error_Dest_Node_Data_Fault => GDB.Data_Conversion.out_Error_Dest_Node_Data_Fault,
                              out_Error_Node_Data_Fault => GDB.Data_Conversion.out_Error_Node_Data_Fault,
                              out_Error_No_adjoin_Node => GDB.Data_Conversion.out_Error_No_adjoin_Node);
    IF GDB.Data_Conversion.out_Complete_Bit THEN		
        GDB.Command.Command_Type := GDB.Data_Conversion.out_Command_Type;
        GDB.Command.Dest_Node := GDB.Data_Conversion.out_Dest_Node;
		GDB.Command.SpinTurn_Target_Angle := gdb.Data_Conversion.out_SpinTurn_Target_Angle;
        FOR Loop_Index := 1 TO 1000 BY 1 DO
            GDB.Command.Data_List[Loop_Index] := GDB.Data_Conversion.out_Data[Loop_Index];
            IF GDB.Command.Data_List[Loop_Index] = 0 THEN
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
END_IF;


//[_Main_Step]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
IF TRUE THEN
    //Initialize
	GDB.Auto.Ready.Active := FALSE;
    GDB.Auto._1_Loading.Active := FALSE;
	GDB.Auto._2_Unloading.Active := FALSE;
	GDB.Auto._3_Move.Active := FALSE;
	GDB.Auto._4_Charge.Active := FALSE;
	GDB.Auto._5_Spinturn.Active := FALSE;
	GDB.Auto.PIO.Active := FALSE;	    
	GDB.Auto.Main.Crab_Direction_1L_2R := 0;
	GDB.Auto.Main.Distance_Curr_Dest := 0;
	GDB.Auto.Main.Distance_Curr_StartPoint := 0;
	gdb.Auto.Main.Docking_Node_in_500mm := FALSE;
	gdb.Auto.Main.Docking_Node_in_1500mm := FALSE;
	gdb.Auto.Main.Docking_Node_in_3000mm := FALSE;	
	gdb.Auto.Main.Docking_Node_out_500mm := FALSE;
	gdb.Auto.Main.Docking_Node_out_1500mm := FALSE;
	gdb.Auto.Main.Docking_Node_out_3000mm := FALSE;

	IF GDB.Command.Current_Number = 0 THEN
		GDB.Command.Current_Number := 1;
	END_IF
    //Step_Set
    IF TRUE THEN
        //Step_Active
        IF GDB.mode.Active THEN
            GDB.auto.Main.Active := TRUE;
        ELSE
            GDB.auto.Main.Active := FALSE;
        END_IF;
        //Step_Start
        PN_Pulse[1](in_Type := 1,
                     in_Signal := GDB.auto.Main.Active);
        IF PN_Pulse[1].out_Pulse THEN
			IF GDB.Mode.Auto THEN
	            GDB.auto.Main.Step := 1;
			ELSIF GDB.Mode.Semi_Auto THEN 
			//Command_Clear(Semi_Auto)
				GDB.auto.Main.Step := 100;
			END_IF;	
        END_IF;
        //Step_Clear
        IF GDB.auto.Main.Active = FALSE THEN
            GDB.auto.Main.Step := 0;
			GDB.Command.Command_Perform_Count := 0;
        END_IF;
        //Command_Clear
		PN_Pulse[2](in_Type:=2, in_Signal:=GDB.Mode.Auto);//Auto_Mode가 아닌경우,
		PN_Pulse[3](in_Type:=2, in_Signal:=GDB.Mode.Semi_Auto);//SemiAuto_Mode가 아닌경우,
		IF PN_Pulse[2].out_Pulse OR PN_Pulse[3].out_Pulse THEN
			GDB.Command.Command_Clear_Bit := TRUE;	
		END_IF;			
		IF GDB.Command.Command_Clear_Bit THEN
			GDB.auto.Main.Step := 100;
		END_IF;		
    END_IF;

    //Step
    CASE GDB.auto.Main.Step OF            

        1:  //Ready_Check            
            //Ready_Check_Complete
            GDB.Auto.Ready.Active := TRUE;
            IF GDB.Auto.Ready.Step = 99 THEN
                GDB.auto.Main.Step := 2;
            END_IF;


        2:  //Spare
            IF ((GDB.Command.Command_Type = 1) AND (GDB.Command.Dest_Node <> 0))
                OR ((GDB.Command.Command_Type = 2) AND (GDB.Command.Dest_Node <> 0))
                OR ((GDB.Command.Command_Type = 3) AND (GDB.Command.Dest_Node <> 0))
                OR ((GDB.Command.Command_Type = 4) AND (GDB.Command.Dest_Node <> 0))
                OR (GDB.Command.Command_Type = 5) THEN
                GDB.auto.Main.Step := 3;
            END_IF;

        3:  //Command_Run
			IF GDB.Command.Command_Type = 1 THEN
				GDB.Auto._3_Move.Active := TRUE;
				IF GDB.auto._3_move.Step = 99 THEN
					GDB.Auto._1_Loading.Active := TRUE;
				END_IF
			ELSIF GDB.Command.Command_Type = 2 THEN
				GDB.Auto._3_Move.Active := TRUE;
				IF GDB.auto._3_move.Step = 99 THEN
					GDB.Auto._2_Unloading.Active := TRUE;
				END_IF
			ELSIF GDB.Command.Command_Type = 3 THEN
				GDB.Auto._3_Move.Active := TRUE;
			ELSIF GDB.Command.Command_Type = 4 THEN
				GDB.Auto._4_Charge.Active := TRUE;
			ELSIF GDB.Command.Command_Type = 5 THEN
				GDB.Auto._5_Spinturn.Active := TRUE;	
				GDB.auto._5_SpinTurn.Target_AGV_Angle := gdb.Command.SpinTurn_Target_Angle;
			END_IF;		


            //Command_Run_Complete
            IF (GDB.Command.Command_Type = 1 AND GDB.auto._1_Loading.Step = 99)
                OR (GDB.Command.Command_Type = 2 AND GDB.auto._2_Unloading.Step = 99)
                OR (GDB.Command.Command_Type = 3 AND GDB.auto._3_move.Step = 99 )
                OR (GDB.Command.Command_Type = 4 AND GDB.auto._4_Charge.Step = 99)
                OR (GDB.Command.Command_Type = 5 AND GDB.auto._5_SpinTurn.Step = 99)
            THEN
                GDB.auto.Main.Step := 99;
            END_IF;
            // 99: Command_Complete        
        99:
            IF TRUE THEN
				GDB.Command.Command_Perform_Count := GDB.Command.Command_Perform_Count + 1;
                GDB.auto.Main.Step := 100;
            END_IF;

            // 100 : Data Clear        
        100:
			test := test+1;
			GDB.Command.Command_Clear_Bit := FALSE;
            GDB.Command.Current_Number := 1;
            GDB.Command.Command_Type := 0;
            GDB.Command.Dest_Node := 0;
			GDB.Command.SpinTurn_Target_Angle := 0;
            FOR Loop_Index := 0 TO 1000 BY 1 DO
                GDB.Command.Data_List[Loop_Index] := 0;
            END_FOR;
			FOR Loop_Index := 0 TO 9 BY 1 DO
                GDB.ACS.Command_Carrier_ID[Loop_Index] := 0;
            END_FOR;
			GDB.ACS.EPC_Data := 999.0;			
            IF GDB.Auto.Main.Active AND GDB.Command.Command_Perform_Count = 0 THEN
                GDB.auto.Main.Step := 1;
			ELSIF GDB.Auto.Main.Active AND GDB.Command.Command_Perform_Count <> 0 THEN
				GDB.auto.Main.Step := 2;
            END_IF;
        ELSE
            GDB.auto.Main.Step := 0;
    END_CASE;



//Direction_Angle
// 0: Not_OK
// 1: OK
// 2: Turn
IF TRUE THEN
   	GDB.Command.Direction_Angle := 999;
   	GDB.Command.Direction_Angle_State := 0; //Not_OK
	// 1.Direction이 단방향인 경우,				
   	IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction > 0
   	    AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction < 5 THEN
   	    GDB.Command.Direction_Angle := ((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction - 1) * 90);
   	    Angle_Calcuration[1](in_3_Angle_SUB_bit := TRUE,
   	                          in_SUB_1_1 := GDB.Command.Direction_Angle,
   	                          in_SUB_1_2 := GDB.monitor.Current_AGV_Angle);
   	    IF Angle_Calcuration[1].SUB1_Buffer_us180 < 10.0 THEN
   	        GDB.Command.Direction_Angle_State := 1; //OK
		ELSE
   	        GDB.Command.Direction_Angle_State := 2; //Turn	
   	    END_IF;
	// 2.Direction이 양방향인 경우, 더 가까운 쪽으로 Turn!
	ELSIF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction = 13
		OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction = 24 THEN
		Angle_Calcuration[1](in_3_Angle_SUB_bit := TRUE,
   	                          in_SUB_1_1 := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction/10) - 1) * 90),
   	                          in_SUB_1_2 := GDB.monitor.Current_AGV_Angle); 
		Angle_Calcuration[2](in_3_Angle_SUB_bit := TRUE,
   	                          in_SUB_1_1 := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction MOD 10) - 1) * 90),
   	                          in_SUB_1_2 := GDB.monitor.Current_AGV_Angle); 								  
		IF Angle_Calcuration[1].SUB1_Buffer_us180 < 10 THEN
			GDB.Command.Direction_Angle_State := 1; //OK
			GDB.Command.Direction_Angle := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction/10) - 1) * 90);
		ELSIF Angle_Calcuration[2].SUB1_Buffer_us180 < 10 THEN
			GDB.Command.Direction_Angle_State := 1; //OK
			GDB.Command.Direction_Angle := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction MOD 10) - 1) * 90);
		ELSIF Angle_Calcuration[1].SUB1_Buffer_us180 < 90 THEN
			GDB.Command.Direction_Angle_State := 2; //Turn
			GDB.Command.Direction_Angle := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction/10) - 1) * 90);
		ELSIF Angle_Calcuration[2].SUB1_Buffer_us180 < 90 THEN
			GDB.Command.Direction_Angle_State := 2; //Turn
			GDB.Command.Direction_Angle := (((GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Direction MOD 10) - 1) * 90);
		END_IF;
   	END_IF;
END_IF;

//Crab_Direction_1L_2R	
IF		GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2 
	AND GDB.Command.Data_List[GDB.Command.Current_Number] <> 0 THEN
	Angle_Calcuration[1](in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
						in_X1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node].X, 
						in_Y1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node].Y, 
						in_X2_End:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X, 
						in_Y2_End:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y);
	Angle_Calcuration[2](in_3_Angle_SUB_bit:= TRUE, 
						in_SUB_1_1:= Angle_Calcuration[1].out_1_Theta_us360, 
						in_SUB_1_2:= GDB.Monitor.Current_AGV_Angle);		
	IF Angle_Calcuration[2].out_3_SUB1_s180 > 45 AND Angle_Calcuration[2].out_3_SUB1_s180 < 135 THEN					
		GDB.Auto.Main.Crab_Direction_1L_2R := 1;
	ELSIF Angle_Calcuration[2].out_3_SUB1_s180 > -135 AND Angle_Calcuration[2].out_3_SUB1_s180 < -45 THEN				
		GDB.Auto.Main.Crab_Direction_1L_2R := 2;
	END_IF;
END_IF;
//Distance_Curr_StartPoint
Angle_Calcuration[1](in_2_TwoPoint_Distance_Calculation_Bit:= GDB.Command.Data_List[GDB.Command.Current_Number] <> 0, 
					in_X1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[1]].Start_Node].X,
					in_Y1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[1]].Start_Node].Y,
					in_X2_End:= GDB.Monitor.Current_X, 
					in_Y2_End:= GDB.Monitor.Current_Y,
					out_2_TwoPoint_Distance_mm => GDB.Auto.Main.Distance_Curr_StartPoint);
//Distance_Curr_Dest			
Angle_Calcuration[1](in_2_TwoPoint_Distance_Calculation_Bit:= GDB.Command.Data_List[GDB.Command.Current_Number] <> 0, 
					in_X1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].X,
					in_Y1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].Y,
					in_X2_End:= GDB.Monitor.Current_X, 
					in_Y2_End:= GDB.Monitor.Current_Y,
					out_2_TwoPoint_Distance_mm => GDB.Auto.Main.Distance_Curr_Dest);
//Dest_Node_in
IF 		(GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2
	AND GDB.Auto.Main.Crab_Direction_1L_2R <> 0)   THEN
	IF GDB.Auto.Main.Distance_Curr_Dest < 500 THEN
		gdb.Auto.Main.Docking_Node_in_500mm := TRUE;
	END_IF;	
	IF GDB.Auto.Main.Distance_Curr_Dest < 1500 THEN
		gdb.Auto.Main.Docking_Node_in_1500mm := TRUE;
	END_IF;
	IF GDB.Auto.Main.Distance_Curr_Dest < 3000 THEN
		gdb.Auto.Main.Docking_Node_in_3000mm := TRUE;
	END_IF;
END_IF;	
//Dest_Node_out
IF 		(		GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[1]].Start_Node]._TYPE = 2 )
	AND GDB.Auto.Main.Crab_Direction_1L_2R <> 0 THEN	
	IF	GDB.Auto.Main.Distance_Curr_StartPoint < 500 THEN
		gdb.Auto.Main.Docking_Node_out_500mm := TRUE;
	END_IF;	
	IF	GDB.Auto.Main.Distance_Curr_StartPoint < 1500 THEN
		gdb.Auto.Main.Docking_Node_out_1500mm := TRUE;
	END_IF;
	IF	GDB.Auto.Main.Distance_Curr_StartPoint < 3000 THEN
		gdb.Auto.Main.Docking_Node_out_3000mm := TRUE;		
	END_IF;
END_IF;	

Auto_Ready();
Auto_PIO_1_1();	
Auto_1_Loading();
Auto_2_Unloading();
Auto_3_Move_1();
Auto_4_Charge();
Auto_5_SpinTurn();

END_IF;

