//initialize
GDB.Auto.PIO.PIO_Ignore_Bit := FALSE;
GDB.Auto.PIO.PIO_Move_Pause_Bit := FALSE;
GDB.Auto.PIO.PIO_CIS_TURRET := FALSE;
GDB.Unit.IO.do_DMS_Left_Select := TRUE;
GDB.Unit.IO.do_DMS_Right_Select := TRUE;
GDB.Unit.IO.do_DMS_out_1 := FALSE; // Out1. Valid
GDB.Unit.IO.do_DMS_out_2 := FALSE; // Out2. CS0 	
GDB.Unit.IO.do_DMS_out_3 := FALSE; // Out3. CS1 		
GDB.Unit.IO.do_DMS_out_4 := FALSE; // Out4. Transfer Request	
GDB.Unit.IO.do_DMS_out_5 := FALSE; // Out5. Busy 
GDB.Unit.IO.do_DMS_out_6 := FALSE; // Out6. Complete			
GDB.Unit.IO.do_DMS_out_7 := FALSE; // Out7. LC_Mutting 
IF (GDB.Auto.PIO.PIO_Node[GDB_Retain.Current_Node] AND GDB.Error.Error_Code = 0) OR GDB.Auto.PIO.PIO_Direction_1L_2R = 0 THEN
	GDB.Unit.IO.do_DMS_out_8 := FALSE; // Out8. Interlock
END_IF

//Distance_Curr_PIOnode
Angle_Calcuration[1](in_2_TwoPoint_Distance_Calculation_Bit:= GDB.Auto.PIO.PIO_Dest_Node <> 0, 
					in_X1_Start:= GDB.Monitor.Current_X, 
					in_Y1_Start:= GDB.Monitor.Current_Y, 		
					in_X2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Dest_Node].X, 
					in_Y2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Dest_Node].Y);
//PIO_Complete_Distance
Angle_Calcuration[2](in_2_TwoPoint_Distance_Calculation_Bit:= GDB.Auto.PIO.PIO_Dest_Node <> 0, 
					in_X1_Start:= GDB.Monitor.Current_X, 
					in_Y1_Start:= GDB.Monitor.Current_Y, 		
					in_X2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Start_Node].X, 
					in_Y2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Start_Node].Y);

//PIO_Node_Set
IF TRUE THEN
	//PIO Node Setting 시점
	TON[3](IN:= GDB.Touch.S901_Target_Node_SET_SW, PT:= T#2S);
	TON[4](IN:= GDB.Touch.S901_Target_LINK_SET_SW, PT:= T#2S);
	PN_Pulse[2](in_Type:= 1, in_Signal:= TRUE); //Power On 시
	PN_Pulse[3](in_Type:= 1, in_Signal:= TON[3].Q); //Node Data 변경 시
	PN_Pulse[4](in_Type:= 1, in_Signal:= TON[4].Q); //Link Data 변경 시
	PN_Pulse[5](in_Type:= 1, in_Signal:= GDB.Touch.S901_MAP_Data_Insert); //Insert 버튼 누를 시
