		Node_Search := TRUE;
	ELSE
		Node_Search := FALSE;
	END_IF

	IF Node_Search THEN
		//Initialize
		FOR Index_0 := 1 TO 1000 BY 1 DO
			PIO_Node[Index_0] := 0;
			PIO_Pause_Node[Index_0] := 0;
			PIO_Entry_Node[Index_0] := 0;
			Pass_Node[Index_0] := 0;
		END_FOR

		//PIO_Node_Search
		FOR Index_0 := 1 TO 999 BY 1 DO
			IF GDB_Retain.Node[Index_0]._TYPE = 2 THEN
				FOR Index_1 := 1 TO 10 BY 1 DO
					Pass_Node[1] := Index_0;
					PIO_Pause_Node[Pass_Node[Index_1]] := TRUE;
					IF PIO_Entry_Node[Index_0] <> 0 THEN
						EXIT;
					END_IF

					FOR Index_2 := 1 TO 9 BY 1 DO
						IF (GDB_Retain.Node[Pass_Node[Index_1]]._Port OR GDB_Retain.Node[GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node]._TYPE <> 1)
						  AND PIO_Pause_Node[GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node] = FALSE
						  AND GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node <> 0 THEN
							Pass_Node[Index_1 + 1] := GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node;

						ELSIF GDB_Retain.Node[GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node]._TYPE = 1 THEN
							PIO_Node[GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node] := TRUE;
							PIO_Pause_Node[GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node] := TRUE;
							PIO_Entry_Node[Index_0] := GDB_Retain.Link_ID[Pass_Node[Index_1]*10 + Index_2].End_Node;
							EXIT;
						END_IF
					END_FOR

				END_FOR
			END_IF
		END_FOR

		GDB.Auto.PIO.PIO_Node := PIO_Node;
		GDB.Auto.PIO.PIO_Pause_Node := PIO_Pause_Node;
		GDB.Auto.PIO.PIO_Entry_Node := PIO_Entry_Node;
	END_IF
