PROGRAM Scenario_Main
VAR

	_bStartSW 		: BOOL;  	// Touch
	_bStopSW 		: BOOL; 	// Touch
	_nScenarioNum 	: INT; 		// Touch
	_bHaveCommand 	: BOOL; 	// Touch 
	_bCommandClearSW : BOOL; 	//Touch

	_nRepeatCnt : INT;
	_nCurrentRepeatCnt : INT;

	_fbStartTriger : R_TRIG;
	_nScenarioStep : INT;
	_stCommandList : ARRAY[1..30] OF ST_ScenarioCommand; 
	_nCommandNum : INT;
	_nCommandEA : INT;
	_nIndex : INT;

	_stBeforeCommandList :  ARRAY[1..30] OF ST_ScenarioCommand; 
	_nBeforeCommandNum : INT;
	_nBeforeCommandEA : INT;

	TON	: ARRAY[0..1] OF TON;
	TOF	: ARRAY[0..1] OF TOF;


END_VAR


//=======================================================================================================	
//	Call And Initial

	Scenario_DATA();


//=======================================================================================================	
//	Control

	_fbStartTriger(CLK := _bStartSW);
	IF _fbStartTriger.Q THEN
		_nScenarioStep := 10;
	END_IF

	IF _bCommandClearSW  THEN
		_bHaveCommand := FALSE;
	END_IF

	IF GDB.Error.Error_Code <> 0 OR GDB.Mode.Active = FALSE OR _bStopSW THEN
		_nScenarioStep := 0;
	END_IF

//=======================================================================================================	
// Sequence

	CASE _nScenarioStep OF
		10 :
			IF _bHaveCommand THEN
				_stCommandList := _stBeforeCommandList;
				_nCommandEA := _nBeforeCommandEA;
				_nCommandNum := _nBeforeCommandNum;
				_nScenarioStep := 30;
			ELSE
				_nCurrentRepeatCnt := 0;
				_nCommandEA := 0;
				_nScenarioStep := 20;
			END_IF

		20 :
			FOR _nIndex := 1 TO 30 BY 1 DO
				IF _stCommandList[_nIndex].nCommandType <> 0 THEN
					_nCommandEA := _nCommandEA + 1;
				ELSE
					EXIT;
				END_IF
			END_FOR

			IF _nCommandEA = 0 THEN
				_nScenarioStep := 0;
			ELSE
				_stBeforeCommandList := _stCommandList;
				_nBeforeCommandEA :=_nCommandEA;
				_bHaveCommand := TRUE;
				_nCommandNum := 1;
				_nScenarioStep := 30;
			END_IF

		30 : 
			_nBeforeCommandNum := _nCommandNum;

			IF GDB.Auto.Main.Step = 2 THEN
				GDB.Touch.S25_Command_Type := _stCommandList[_nCommandNum].nCommandType;
				GDB.Touch.S25_Dest_Node := _stCommandList[_nCommandNum].nTargetNode;
				GDB.Touch.S25_SpinTurn_Target_Angle := _stCommandList[_nCommandNum].fSpinTurnAngle;
				_nScenarioStep	:= 35;
			END_IF

		35:

			GDB.Touch.S25_SemiAuto_Start_SW := FALSE;

			IF GDB.Auto.Main.Step = 100 THEN
				_nScenarioStep := 40;	
			END_IF

		40 :
			_nCommandNum := _nCommandNum + 1;
			IF _nCommandNum <= _nCommandEA THEN
				_nScenarioStep := 30;
			ELSE	
				IF _nRepeatCnt > 0 THEN	
					_nCurrentRepeatCnt := _nCurrentRepeatCnt + 1;
					IF _nCurrentRepeatCnt < _nRepeatCnt THEN
						_nCommandNum := 1;
						_nScenarioStep := 30;
					ELSE
						_bHaveCommand := FALSE;
						_nScenarioStep := 0;
					END_IF
				ELSE
					_bHaveCommand := FALSE;
					_nScenarioStep := 0;
				END_IF			
			END_IF		
	END_CASE

	TON[1](IN := GDB.Touch.S25_SemiAuto_Start_SW, PT := T#50MS);
	IF TON[1].Q THEN
		GDB.Touch.S25_SemiAuto_Start_SW := FALSE;
	END_IF

PROGRAM Semi_Auto_Part
VAR
Offline_Path_Search_Instance	:Offline_Path_Search;
PN_Pulse	:ARRAY[0..0] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Loop_Index	:INT;
END_VAR


//Initialize
GDB.semi_auto.Command_Start_Bit := FALSE;
GDB.semi_auto.Renew_Bit := FALSE;
GDB.semi_auto.out_Complete := FALSE;
GDB.semi_auto.out_Error_Not_Exist_Node := FALSE;
IF GDB.mode.Semi_Auto AND GDB.auto.Main.Step = 2 THEN    
    IF GDB.Touch.S25_SemiAuto_Start_SW AND GDB.Touch.S25_Command_Type <> 0 THEN
		FOR Loop_Index := 0 TO 1000 BY 1 DO //Conversion_In_Data_Clear
            GDB.Data_Conversion.in_Data[Loop_Index] := 0;
        END_FOR;	
		// 1:Loading , 2:Unloading , 3:Move
        IF GDB.Touch.S25_Command_Type >= 1 AND GDB.Touch.S25_Command_Type <= 3  AND GDB.Touch.S25_Dest_Node <> 0 THEN 
            GDB.semi_auto.Renew_Bit := TRUE;
		// 4:Charge	
        ELSIF GDB.Touch.S25_Command_Type = 4 AND GDB.Touch.S25_Dest_Node <> 0 THEN
            GDB.semi_auto.Command_Start_Bit := TRUE;
            GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
            GDB.Data_Conversion.in_Dest_Node := GDB.Touch.S25_Dest_Node;
			GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0;
		// 5:SpinTurn	
        ELSIF GDB.Touch.S25_Command_Type = 5 THEN
            GDB.semi_auto.Command_Start_Bit := TRUE;
            GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
            GDB.Data_Conversion.in_Dest_Node := 0;
            GDB.Data_Conversion.in_SpinTurn_Target_Angle := GDB.Touch.S25_SpinTurn_Target_Angle;
        END_IF;
    END_IF;
    Offline_Path_Search_Instance(Renew_Bit := GDB.semi_auto.Renew_Bit,
                                  in_Start_Node := GDB_Retain.Current_Node,
                                  in_End_Node := GDB.Touch.S25_Dest_Node,
                                  out_Complete => GDB.semi_auto.out_Complete,
                                  out_Path_Count => GDB.semi_auto.out_Path_Count,
                                  out_Path_Length_mm => GDB.semi_auto.out_Path_Length_mm,
                                  out_Path => GDB.semi_auto.out_Path,
                                  out_Error_Not_Exist_Node => GDB.semi_auto.out_Error_Not_Exist_Node);
    IF GDB.semi_auto.out_Complete  //경로계산 완료한 경우,
		OR (GDB.semi_auto.out_Error_Not_Exist_Node AND GDB_Retain.Current_Node = GDB.Touch.S25_Dest_Node) THEN //경로계산은 실패했지만 현재노드가 목적노드인 경우,
        GDB.semi_auto.Command_Start_Bit := TRUE;		
        GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
        GDB.Data_Conversion.in_Dest_Node := GDB.Touch.S25_Dest_Node;
		GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0;
        FOR Loop_Index := 1 TO 999 BY 1 DO
            GDB.Data_Conversion.in_Data[Loop_Index] := GDB.semi_auto.out_Path[Loop_Index+1];
        END_FOR;
    END_IF;
END_IF;

