PROGRAM Sequence
VAR

											(* 파일 저장경로 *)
	stFileDir							: STRING(80):='C:\';

											(* 파일 저장주기 *)
	setTime							: TIME:=T#1S;

											(* 파일 저장시작 *)
	fileRWswitch						: BOOL;

											(* NetID주소 비워둘시 Local값*)
	sNetID								: STRING(80):='';


	fbFileOpen							: FB_FileOpen;
	stFileName							: STRING(80);
	bFileOpenExecute				: BOOL;
	fbFileClose							: FB_FileClose;
	bFileCloseExecute			: BOOL;
	fbFilePuts							: FB_FilePuts;
	stRecData							: STRING(255);
	stTempHeaderData			: ARRAY[0..3] OF STRING(255);
	stTempRecData				: ARRAY[0..3] OF STRING(255);
	bFilePutsExecute				: BOOL;
	fbOSGetTime						: NT_GetTime;
	bOSGetTimeExecute		: BOOL;
	strOSTime							: TIMESTRUCT;
	bFileCtrlExecute				: BOOL;
	stPresentTime					: STRING(80);
	Timer									: TON;
	Step									: INT;
	fbFileRead							: FB_FileRead;
	stReadData						: STRING(4);
	bFileReadExecute			: BOOL;
	bFileCtrlDone						: BOOL;
	i											: INT;

	rwSTEP: INT;
	TIMER1: TON;
END_VAR


actFileAccess();
actGetTime();
actFileCfg();
actFileHandle();

IF Test.Test_Trigger OR Test.Charge_State <> 0 THEN
	test.fileRWswitch := TRUE;
END_IF

TIMER1(IN:= , PT:= setTime, Q=> , ET=> );
IF test.fileRWswitch AND rwSTEP=0 THEN
	rwSTEP:=10;
END_IF
CASE rwSTEP OF
	10:
		IF bFileCtrlExecute=FALSE THEN
			TIMER1.IN:=TRUE;
			IF TIMER1.Q THEN
				TIMER1.IN :=FALSE;
				bFileCtrlExecute:=TRUE;
				rwSTEP:=20;
			END_IF
		END_IF

	20:
		IF bFileCtrlDone=TRUE THEN
			bFileCtrlExecute:=FALSE;
			test.fileRWswitch:=FALSE;


			rwSTEP:=0;
		END_IF


END_CASE

