		GDB_Parameter.NAV350_Center_Distance := 635.63; //중심에서 NAV350 까지의 거리.	
	END_IF;*)
	GDB_Parameter.Distance_FwWheel_BwWheel_mm := 900.0; //앞바퀴와 뒷바퀴 중심점 사이의 거리

