PROGRAM Setting_Node_Teaching
VAR
	Pre_Target_Node : INT;
	TON : TON;
	NAV_Average_Point : NAV_Average_Point;
	X_Shift_Offset : REAL;
END_VAR



	//Display_Data
	GDB.Touch.S901_Display_Node_Data := GDB_Retain.Node[GDB.Touch.S901_Target_Node];
IF GDB.Touch.S901_Target_Node <> Pre_Target_Node THEN
	//Set_Data
	 GDB.Touch.S901_SET_Node_Data := GDB_Retain.Node[GDB.Touch.S901_Target_Node];
	//Pre_Target_Node_Set
	 Pre_Target_Node := GDB.Touch.S901_Target_Node ;
END_IF;

//Data_Set
TON(IN:= GDB.Touch.S901_Target_Node_SET_SW, PT:= T#2S);
IF TON.Q THEN	
	GDB_Retain.Node[GDB.Touch.S901_Target_Node] := GDB.Touch.S901_SET_Node_Data;
END_IF;	

//X_Shift_Center
	IF GDB.Mode.Manual AND GDB.Touch.S901_NodeTeaching_X_Shift_Center THEN
		GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
	END_IF;			

//Teaching_Data_Export
	NAV_Average_Point(
	in_Enable:= TRUE, 
	in_Start:= GDB.Touch.S901_Average_Point_SW, 
	in_NAV_Recieve_Complete:= GDB.Unit.SICK_NAV350.Recieve_Complete, 
	in_NAV_X:= GDB.Monitor.Current_X, 
	in_NAV_Y:= GDB.Monitor.Current_Y, 
	in_NAV_T:= GDB.Monitor.Current_AGV_Angle, 
	in_Count_Number:= 50);	
	IF NAV_Average_Point.out_Complete THEN
		GDB.Touch.S901_Average_Point_Complete := TRUE;
		GDB.Touch.S901_Average_Point_T := NAV_Average_Point.out_NAV_T;		
		IF (GDB.Monitor.Current_AGV_Angle >= 0 AND GDB.Monitor.Current_AGV_Angle < 45) OR ((GDB.Monitor.Current_AGV_Angle >= 315 AND GDB.Monitor.Current_AGV_Angle < 360)) THEN
			GDB.Touch.S901_Average_Point_X := NAV_Average_Point.out_NAV_X + GDB.Monitor.Current_X_Shift_Pos;
			GDB.Touch.S901_Average_Point_Y := NAV_Average_Point.out_NAV_Y;
		ELSIF (GDB.Monitor.Current_AGV_Angle >= 45 AND GDB.Monitor.Current_AGV_Angle < 135) THEN
			GDB.Touch.S901_Average_Point_X := NAV_Average_Point.out_NAV_X;
			GDB.Touch.S901_Average_Point_Y := NAV_Average_Point.out_NAV_Y + GDB.Monitor.Current_X_Shift_Pos;	
		ELSIF (GDB.Monitor.Current_AGV_Angle >= 135 AND GDB.Monitor.Current_AGV_Angle < 225) THEN
			GDB.Touch.S901_Average_Point_X := NAV_Average_Point.out_NAV_X - GDB.Monitor.Current_X_Shift_Pos;
			GDB.Touch.S901_Average_Point_Y := NAV_Average_Point.out_NAV_Y;
		ELSIF (GDB.Monitor.Current_AGV_Angle >= 225 AND GDB.Monitor.Current_AGV_Angle < 315) THEN	
			GDB.Touch.S901_Average_Point_X := NAV_Average_Point.out_NAV_X;
			GDB.Touch.S901_Average_Point_Y := NAV_Average_Point.out_NAV_Y - GDB.Monitor.Current_X_Shift_Pos;		
		END_IF;
	ELSIF GDB.Touch.S901_Average_Point_SW THEN
		GDB.Touch.S901_Average_Point_Complete := FALSE;
	END_IF;

