PROGRAM Setting_WheelOffset_AutoSet
VAR
	WheelOffset_AutoSet : WheelOffset_AutoSet;
	Pre_FW_Offset : REAL;
	Pre_BW_Offset : REAL;
	PN_Pulse : PN_Pulse;
END_VAR


//Ready_SW
IF GDB.Touch.S901_Wheel_Angle_Ready_SW THEN
	GDB.manual.Steering_FW_Target_Angle := 180.0;
	GDB.manual.Steering_BW_Target_Angle := 180.0;
END_IF;

//Ready_Lamp
IF 		ABS(GDB.Monitor.Current_FW_Wheel_Angle - 180) < 1.0 
	AND ABS(GDB.Monitor.Current_BW_Wheel_Angle - 180) < 1.0 
	AND GDB.manual.Steering_FW_Target_Angle = 180
	AND GDB.manual.Steering_BW_Target_Angle = 180
THEN
	GDB.Touch.S901_Wheel_Angle_Ready_Lamp := TRUE;
ELSE
	GDB.Touch.S901_Wheel_Angle_Ready_Lamp := FALSE;
END_IF;

//Start
IF 		GDB.mode.Manual 
	AND GDB.Touch.S901_Wheel_Angle_Ready_Lamp
	AND GDB.Touch.S901_Wheel_Offset_AutoSet_Start_SW 
	AND GDB.Error.Error_Code = 0 THEN
	GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp := TRUE;
END_IF;

//Stop
IF 		GDB.mode.Manual = FALSE 
	OR GDB.Touch.S901_Wheel_Offset_AutoSet_Stop_SW
	OR WheelOffset_AutoSet.out_Complete
	OR GDB.Error.Error_Code <> 0 THEN
	GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp := FALSE;	
END_IF;

//Pre_Offset_Data_Set
PN_Pulse(in_Type:= 1, in_Signal:=GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp );
IF PN_Pulse.out_Pulse THEN
	Pre_FW_Offset := GDB_Parameter.Steering_FW_Wheel_Angle_Offset;
	Pre_BW_Offset := GDB_Parameter.Steering_BW_Wheel_Angle_Offset;
END_IF;
//WheelOffset_AutoSet
WheelOffset_AutoSet(	in_Start:= GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp, 
						in_Start_Time_Sec:= T#5S, 
						in_Move_Time_Sec:= T#20S, 
						in_Manual_Mode:= GDB.mode.Manual, 
						in_Distance_FwWheel_BwWheel_mm:= GDB_Parameter.Distance_FwWheel_BwWheel_mm, 
						in_FW_Wheel_Angle:= GDB.monitor.Current_FW_Wheel_Angle, 
						in_BW_Wheel_Angle:= GDB.monitor.Current_BW_Wheel_Angle, 
						in_X_Pos:= GDB.monitor.Current_X, 
						in_Y_Pos:= GDB.monitor.Current_Y, 
						in_AGV_Angle:= GDB.monitor.Current_AGV_Angle, 
						in_Travel_Speed_mpm:= GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm);
						(*out_Step=> , 
						out_Not_Manual_Mode=> , 
						out_WheelAngle_NotReady=> , 
						out_FW_Run=> manual.Travel_Setup_FW_Run, 
						out_BW_Run=> manual.Travel_Setup_BW_Run, 
						out_FW_Offset=> , 
						out_BW_Offset=> );*)
IF GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp THEN
	GDB_Parameter.Steering_FW_Wheel_Angle_Offset := Pre_FW_Offset + WheelOffset_AutoSet.out_FW_Offset;
	GDB_Parameter.Steering_BW_Wheel_Angle_Offset := Pre_BW_Offset + WheelOffset_AutoSet.out_BW_Offset;
END_IF;

PROGRAM Setting_WheelOffset_AutoSet_Test
VAR
	PN_Pulse : ARRAY[0..6] OF PN_Pulse;
	//PreData_set
	Pre_FW_Offset : REAL;
	Pre_BW_Offset : REAL;
	Pre_Offset_90 : REAL;
	Pre_Offset_270 : REAL;
	//FB_CALL
	WheelOffset_AutoSet_180 : WheelOffset_AutoSet_180;
	WheelOffset_AutoSet_90 : WheelOffset_AutoSet_90;
	WheelOffset_AutoSet_270 : WheelOffset_AutoSet_270;
END_VAR


//Initialize
GDB.Touch.S901_Wheel_Angle_Ready_Lamp := FALSE;
GDB.Touch.S901_Wheel_90_Angle_Ready_Lamp := FALSE;
GDB.Touch.S901_Wheel_270_Angle_Ready_Lamp := FALSE;
manual.Travel_Setup_FW_Run := FALSE;
manual.Travel_Setup_BW_Run := FALSE;

//Ready_SW
IF GDB.Touch.S901_Wheel_Angle_Ready_SW THEN
	GDB.Touch.S21_Travel_LowSpeed_SW := TRUE;
	GDB.manual.Steering_FW_Target_Angle := 180.0;
	GDB.manual.Steering_BW_Target_Angle := 180.0;
ELSIF GDB.Touch.S901_Wheel_90_Angle_Ready_SW THEN
	GDB.Touch.S21_Travel_LowSpeed_SW := TRUE;
	GDB.manual.Steering_FW_Target_Angle := 90.0;
	GDB.manual.Steering_BW_Target_Angle := 90.0;
ELSIF GDB.Touch.S901_Wheel_270_Angle_Ready_SW THEN
	GDB.Touch.S21_Travel_LowSpeed_SW := TRUE;
	GDB.manual.Steering_FW_Target_Angle := 270.0;
	GDB.manual.Steering_BW_Target_Angle := 270.0;
END_IF;

//Ready_Lamp
IF 		ABS(GDB.Monitor.Current_FW_Wheel_Angle - 180) < 1.0 AND ABS(GDB.Monitor.Current_BW_Wheel_Angle - 180) < 1.0 
	AND GDB.manual.Steering_FW_Target_Angle = 180 AND GDB.manual.Steering_BW_Target_Angle = 180 AND GDB.Touch.S21_Travel_LowSpeed_Lamp THEN
	GDB.Touch.S901_Wheel_Angle_Ready_Lamp := TRUE;
ELSIF 	ABS(GDB.Monitor.Current_FW_Wheel_Angle - 90) < 1.0 AND ABS(GDB.Monitor.Current_BW_Wheel_Angle - 90) < 1.0 
	AND GDB.manual.Steering_FW_Target_Angle = 90 AND GDB.manual.Steering_BW_Target_Angle = 90 AND GDB.Touch.S21_Travel_LowSpeed_Lamp THEN
	GDB.Touch.S901_Wheel_90_Angle_Ready_Lamp := TRUE;
ELSIF 	ABS(GDB.Monitor.Current_FW_Wheel_Angle - 270) < 1.0 AND ABS(GDB.Monitor.Current_BW_Wheel_Angle - 270) < 1.0 
	AND GDB.manual.Steering_FW_Target_Angle = 270 AND GDB.manual.Steering_BW_Target_Angle = 270 AND GDB.Touch.S21_Travel_LowSpeed_Lamp THEN
	GDB.Touch.S901_Wheel_270_Angle_Ready_Lamp := TRUE;	
END_IF;
PN_Pulse[4](in_Type:= 1, in_Signal:= GDB.Touch.S901_Wheel_Offset_AutoSet_Start_SW);
PN_Pulse[5](in_Type:= 1, in_Signal:= GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_SW);
PN_Pulse[6](in_Type:= 1, in_Signal:= GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_SW);

//Start
IF GDB.mode.Manual AND GDB.Error.Error_Code = 0 AND GDB.Unit.SICK_NAV350.NAV350_OK_Bit THEN
	IF 		GDB.Touch.S901_Wheel_180_Angle_Ready_Lamp AND PN_Pulse[4].out_Pulse THEN
				GDB.Touch.S901_Wheel_180_Offset_AutoSet_Start_Lamp := TRUE;
	ELSIF 	GDB.Touch.S901_Wheel_90_Angle_Ready_Lamp AND PN_Pulse[5].out_Pulse THEN
				GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp := TRUE;
	ELSIF 	GDB.Touch.S901_Wheel_270_Angle_Ready_Lamp AND PN_Pulse[6].out_Pulse THEN
				GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp := TRUE;
	END_IF;			
END_IF;

//Stop
IF 		GDB.mode.Manual = FALSE OR GDB.Unit.SICK_NAV350.NAV350_OK_Bit = FALSE OR GDB.Error.Error_Code <> 0 OR GDB.Touch.S901_Wheel_Offset_AutoSet_Stop_SW THEN
	GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp := FALSE;
	GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp := FALSE;
	GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp := FALSE;
ELSIF GDB.Unit.IO.di_Auto_Key_SW OR GDB.Unit.IO.di_Reset_SW OR WheelOffset_AutoSet_180.out_Complete THEN	
	GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp := FALSE;
ELSIF GDB.Unit.IO.di_Auto_Key_SW OR GDB.Unit.IO.di_Reset_SW OR WheelOffset_AutoSet_90.out_Complete THEN
	GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp := FALSE;
ELSIF GDB.Unit.IO.di_Auto_Key_SW OR GDB.Unit.IO.di_Reset_SW OR WheelOffset_AutoSet_270.out_Complete THEN	
	GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp := FALSE;
END_IF;

//Pre_Offset_Data_Set
PN_Pulse[1](in_Type:= 1, in_Signal:=GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp );
IF PN_Pulse[1].out_Pulse THEN
	Pre_FW_Offset := GDB_Parameter.Steering_FW_Wheel_Angle_Offset;
	Pre_BW_Offset := GDB_Parameter.Steering_BW_Wheel_Angle_Offset;
END_IF;
PN_Pulse[2](in_Type:= 1, in_Signal:=GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp );
IF PN_Pulse[2].out_Pulse THEN
	Pre_Offset_90 := GDB_Parameter.Steering_Wheel_Angle_Offset_90;
END_IF;
PN_Pulse[3](in_Type:= 1, in_Signal:=GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp );
IF PN_Pulse[3].out_Pulse THEN
	Pre_Offset_270 := GDB_Parameter.Steering_Wheel_Angle_Offset_270;
END_IF;

//WheelOffset_AutoSet_180
WheelOffset_AutoSet_180(	in_Start:= GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp, 
						in_Start_Time_Sec:= T#5S, 
						in_Move_Time_Sec:= T#20S, 
						in_Manual_Mode:= GDB.mode.Manual, 
						in_Distance_FwWheel_BwWheel_mm:= GDB_Parameter.Distance_FwWheel_BwWheel_mm, 
						in_FW_Wheel_Angle:= GDB.monitor.Current_FW_Wheel_Angle, 
						in_BW_Wheel_Angle:= GDB.monitor.Current_BW_Wheel_Angle, 
						in_X_Pos:= GDB.monitor.Current_X, 
						in_Y_Pos:= GDB.monitor.Current_Y, 
						in_AGV_Angle:= GDB.monitor.Current_AGV_Angle, 
						in_Travel_Speed_mpm:= GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm);						
IF GDB.Touch.S901_Wheel_Offset_AutoSet_Start_Lamp THEN
	GDB_Parameter.Steering_FW_Wheel_Angle_Offset := Pre_FW_Offset + WheelOffset_AutoSet_180.out_FW_Offset;
	GDB_Parameter.Steering_BW_Wheel_Angle_Offset := Pre_BW_Offset + WheelOffset_AutoSet_180.out_BW_Offset;
END_IF;						


//WheelOffset_AutoSet_90
WheelOffset_AutoSet_90(	in_Start:= GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp, 
						in_Start_Time_Sec:= T#5S, 
						in_Move_Time_Sec:= T#20S, 
						in_Manual_Mode:= GDB.mode.Manual, 
						in_FW_Wheel_Angle:= GDB.monitor.Current_FW_Wheel_Angle, 
						in_BW_Wheel_Angle:= GDB.monitor.Current_BW_Wheel_Angle, 
						in_X_Pos:= GDB.monitor.Current_X, 
						in_Y_Pos:= GDB.monitor.Current_Y, 
						in_AGV_Angle:= GDB.monitor.Current_AGV_Angle, 
						in_Travel_Speed_mpm:= GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm);
IF GDB.Touch.S901_Wheel_90_Offset_AutoSet_Start_Lamp THEN
	GDB_Parameter.Steering_Wheel_Angle_Offset_90 := Pre_Offset_90 + WheelOffset_AutoSet_90.out_Offset;
END_IF;						

//WheelOffset_AutoSet_270	
WheelOffset_AutoSet_270(	in_Start:= GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp, 
							in_Start_Time_Sec:= T#5S, 
							in_Move_Time_Sec:= T#20S, 
							in_Manual_Mode:= GDB.mode.Manual, 
							in_Distance_FwWheel_BwWheel_mm:= , 
							in_FW_Wheel_Angle:= GDB.monitor.Current_FW_Wheel_Angle, 
							in_BW_Wheel_Angle:= GDB.monitor.Current_BW_Wheel_Angle, 
							in_X_Pos:= GDB.monitor.Current_X, 
							in_Y_Pos:= GDB.monitor.Current_Y, 
							in_AGV_Angle:= GDB.monitor.Current_AGV_Angle, 
							in_Travel_Speed_mpm:= GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm);
IF GDB.Touch.S901_Wheel_270_Offset_AutoSet_Start_Lamp THEN
	GDB_Parameter.Steering_Wheel_Angle_Offset_270 := Pre_Offset_270 + WheelOffset_AutoSet_270.out_Offset;
END_IF;						

//Run
IF WheelOffset_AutoSet_180.out_FW_Run OR WheelOffset_AutoSet_90.out_FW_Run OR WheelOffset_AutoSet_270.out_FW_Run THEN
	manual.Travel_Setup_FW_Run := TRUE;
END_IF
IF WheelOffset_AutoSet_180.out_BW_Run OR WheelOffset_AutoSet_90.out_BW_Run OR WheelOffset_AutoSet_270.out_BW_Run THEN
	manual.Travel_Setup_BW_Run := TRUE;
END_IF

