PROGRAM Unit_AnalogModule
VAR
	FW_Wheel_Angle : LREAL;
	BW_Wheel_Angle : LREAL;
	HP_Loadcell : LREAL;
	OP_Loadcell : LREAL;
	HP_OD1000_Distance : LREAL;
	OP_OD1000_Distance : LREAL;

END_VAR


//Analog Data Set
	//1. PotentialMeter
	//2. Loadcell(Fork)
	//3. OD1000

//Exception_PreventionF
IF GDB_Parameter.Steering_BigGear_Teeth = 0 THEN
	GDB_Parameter.Steering_BigGear_Teeth := 1;
END_IF;	

//FW_Wheel_Angle
FW_Wheel_Angle := F_Scale(nValue:= GDB.Unit.IO.AV_Input[1], 
						nInMin:= 0, 
						nInMax:= 32767, 
						fOutMin:= 180.0 - ( (GDB_Parameter.Potentiometer_Rotation_Number/2) * 360*(GDB_Parameter.Sttering_Potentiometer_Gear_Teeth/GDB_Parameter.Steering_BigGear_Teeth)), 
						fOutMax:= 180.0 + ( (GDB_Parameter.Potentiometer_Rotation_Number/2) * 360*(GDB_Parameter.Sttering_Potentiometer_Gear_Teeth/GDB_Parameter.Steering_BigGear_Teeth)));	
//BW_Wheel_Angle
BW_Wheel_Angle := F_Scale(nValue:= GDB.Unit.IO.AV_Input[2], 
						nInMin:= 0, 
						nInMax:= 32767, 
						fOutMin:= 180.0 - ( (GDB_Parameter.Potentiometer_Rotation_Number/2) * 360*(GDB_Parameter.Sttering_Potentiometer_Gear_Teeth/GDB_Parameter.Steering_BigGear_Teeth)), 
						fOutMax:= 180.0 + ( (GDB_Parameter.Potentiometer_Rotation_Number/2) * 360*(GDB_Parameter.Sttering_Potentiometer_Gear_Teeth/GDB_Parameter.Steering_BigGear_Teeth)));	
//HP_Loadcell
HP_Loadcell := F_Scale(nValue:= GDB.Unit.IO.AI_Input[3], 
						nInMin:= 0, 
						nInMax:= 32767, 
						fOutMin:= 0.0, 
						fOutMax:= 2000.0);	
//OP_Loadcell
OP_Loadcell := F_Scale(nValue:= GDB.Unit.IO.AI_Input[4], 
						nInMin:= 0, 
						nInMax:= 32767, 
						fOutMin:= 0.0, 
						fOutMax:= 2000.0);	
//HP_OD1000_Distance
HP_OD1000_Distance := F_Scale(nValue:= GDB.Unit.IO.AI_Input[2], 
							nInMin:= 0, 
							nInMax:= 32767, 
							fOutMin:= 200.0, 
							fOutMax:= 1000.0);	
//OP_OD1000_Distance
OP_OD1000_Distance := F_Scale(nValue:= GDB.Unit.IO.AI_Input[1], 
							nInMin:= 0, 
							nInMax:= 32767, 
							fOutMin:= 200.0, 
							fOutMax:= 1000.0);	

//Move
//GDB.monitor.Current_FW_Wheel_Angle := LREAL_TO_REAL(FW_Wheel_Angle) - GDB_Parameter.Steering_FW_Wheel_Angle_Offset; //기존 : Offset -8.6 + 고정값 +1.02;							
//GDB.monitor.Current_BW_Wheel_Angle := LREAL_TO_REAL(BW_Wheel_Angle) - GDB_Parameter.Steering_BW_Wheel_Angle_Offset; //기존 : offset -0.285 + 고정값 +8.0 +5.98;							
//Move
IF (GDB.monitor.Current_FW_Wheel_Angle > 80 AND GDB.monitor.Current_FW_Wheel_Angle < 100) THEN
	GDB.monitor.Current_FW_Wheel_Angle := LREAL_TO_REAL(FW_Wheel_Angle) - GDB_Parameter.Steering_FW_Wheel_Angle_Offset - GDB_Parameter.Steering_Wheel_Angle_Offset_90 ;
ELSIF (GDB.monitor.Current_FW_Wheel_Angle > 260 AND GDB.monitor.Current_FW_Wheel_Angle < 280) THEN	
	GDB.monitor.Current_FW_Wheel_Angle := LREAL_TO_REAL(FW_Wheel_Angle) - GDB_Parameter.Steering_FW_Wheel_Angle_Offset - GDB_Parameter.Steering_Wheel_Angle_Offset_270 ;
ELSE
	GDB.monitor.Current_FW_Wheel_Angle := LREAL_TO_REAL(FW_Wheel_Angle) - GDB_Parameter.Steering_FW_Wheel_Angle_Offset ;
END_IF;	
IF (GDB.monitor.Current_BW_Wheel_Angle > 80 AND GDB.monitor.Current_BW_Wheel_Angle < 100) THEN
	GDB.monitor.Current_BW_Wheel_Angle := LREAL_TO_REAL(BW_Wheel_Angle) - GDB_Parameter.Steering_BW_Wheel_Angle_Offset - GDB_Parameter.Steering_Wheel_Angle_Offset_90;
ELSIF (GDB.monitor.Current_BW_Wheel_Angle > 260 AND GDB.monitor.Current_BW_Wheel_Angle < 280) THEN
	GDB.monitor.Current_BW_Wheel_Angle := LREAL_TO_REAL(BW_Wheel_Angle) - GDB_Parameter.Steering_BW_Wheel_Angle_Offset - GDB_Parameter.Steering_Wheel_Angle_Offset_270;
ELSE	
	GDB.monitor.Current_BW_Wheel_Angle := LREAL_TO_REAL(BW_Wheel_Angle) - GDB_Parameter.Steering_BW_Wheel_Angle_Offset ;
END_IF;



GDB.monitor.Fork_HP_Loadcell_kg := LREAL_TO_REAL(HP_Loadcell) - 13 ;							
GDB.monitor.Fork_OP_Loadcell_kg := LREAL_TO_REAL(OP_Loadcell) -10 ;							
GDB.monitor.X_Axis_HP_Distance_mm := LREAL_TO_REAL(HP_OD1000_Distance);							
GDB.monitor.X_Axis_OP_Distance_mm := LREAL_TO_REAL(OP_OD1000_Distance);
IF GDB.Auto._1_Loading.Active = FALSE THEN
	GDB.Auto._1_Loading.Step_7_Loadcell_Offset := 0;
END_IF
GDB.monitor.Fork_Both_Loadcell_kg := GDB.monitor.Fork_HP_Loadcell_kg + GDB.monitor.Fork_OP_Loadcell_kg - GDB.Auto._1_Loading.Step_7_Loadcell_Offset;

//OD1000_OK
IF GDB.monitor.X_Axis_HP_Distance_mm < 900.0 AND GDB.monitor.X_Axis_OP_Distance_mm < 900.0 THEN // 850.0 AND GDB.monitor.X_Axis_OP_Distance_mm < 850.0 THEN 포트 거리로 인해 증가
	GDB.monitor.X_Axis_Distance_OK := TRUE;
ELSE
	GDB.monitor.X_Axis_Distance_OK := FALSE;	
END_IF;

