            ELSIF (GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2) THEN
                //GDB.Unit.Drive.SteeringControl.Error_Value_Buffer := GDB.Unit.Drive.SteeringControl._2_Error_Value * 0.3;
				GDB.Unit.Drive.SteeringControl.Error_Value_Buffer := GDB.Unit.Drive.SteeringControl._2_Error_Value * 0.1;
            ELSIF (GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3) THEN
                GDB.Unit.Drive.SteeringControl.Error_Value_Buffer := GDB.Unit.Drive.SteeringControl._2_Error_Value * 0.1;				
            ELSIF (GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5) THEN
                GDB.Unit.Drive.SteeringControl.Error_Value_Buffer := GDB.Unit.Drive.SteeringControl._2_Error_Value * 0.1;
            ELSIF (GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6) THEN
                GDB.Unit.Drive.SteeringControl.Error_Value_Buffer := GDB.Unit.Drive.SteeringControl._2_Error_Value * 0.1;
            END_IF;
            IF GDB.Unit.Drive.SteeringControl._2_Error_Value_Revision_Direction_0cw_1ccw = 0 THEN
                GDB.Unit.Drive.SteeringControl._2_Steering_FW_Wheel_Target_Angle := GDB.Unit.Drive.SteeringControl._2_Steering_FW_Wheel_Target_Angle + GDB.Unit.Drive.SteeringControl.Error_Value_Buffer;
