        GDB.Unit.Drive.SteeringControl.SUB_BWTarget_BWActual_Abs := ABS(GDB.Unit.Drive.SteeringControl._2_Steering_BW_Wheel_Target_Angle - GDB.monitor.Current_BW_Wheel_Angle);
    END_IF;

    //[PID_Control]
    IF TRUE THEN
        FwSteering_PID_Control(in_Enable := (GDB.Unit.Drive.SteeringControl.FW_High_Speed <> 0),
							in_Target_Pos := LREAL_TO_REAL((GDB.Unit.Drive.SteeringControl._2_Steering_FW_Wheel_Target_Angle - 180) * ((3.141593 * GDB_Parameter.Steering_BigGear_Diameter_mm) / 360)),
							in_Current_Pos := LREAL_TO_REAL((GDB.monitor.Current_FW_Wheel_Angle - 180) * ((3.141593 * GDB_Parameter.Steering_BigGear_Diameter_mm) / 360)),
							in_Max_Value := GDB.Unit.Drive.SteeringControl.FW_High_Speed,
