        GDB.Unit.Drive.LiftControl.Target_Lift_Pos := 0;
        GDB.Unit.Drive.LiftControl.High_Speed := 0;
        GDB.Unit.Drive.LiftControl.Low_Speed := 0;
        GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0;
        GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := 0;
        GDB.Unit.Drive.LiftControl.In_Position := 0;
    END_IF;

    //[Auto, Semi_Auto, Manual_PosMove]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
