            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
			IF GDB.Auto._1_Loading.Step_7_Lift_Decel_Bit THEN
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1]*1.5;
			END_IF;			
        END_IF;

		(*
		//2. Unloading [_2_Unloading.Step = 7]
        IF GDB.auto._2_Unloading.Step = 7 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
