		GDB.Unit.IO.D_output5[7] := GDB.Unit.IO.do_OP_DT2_LaserOff;		*)
		// SMD LED
		GDB.Unit.IO.D_output5[9] := GDB.Unit.IO.do_SMD_LED_HP_Left;
		GDB.Unit.IO.D_output5[10] := GDB.Unit.IO.do_SMD_LED_HP_Right;
		GDB.Unit.IO.D_output5[11] := GDB.Unit.IO.do_SMD_LED_OP_Left;
		GDB.Unit.IO.D_output5[12] := GDB.Unit.IO.do_SMD_LED_OP_Right;

PROGRAM Unit_IPS208i
VAR

	//Related FB_TCPIP_Open/Close
	FB_TCPIP_OpenClose_HP	: FB_TCPIP_OpenClose;
	FB_TCPIP_OpenClose_OP	: FB_TCPIP_OpenClose;
	bTCPIP_Start			: BOOL;

	//Related FB_Send/Receive Instance
	FB_Send_IPS_HP			: FB_SocketSend;
	FB_Send_IPS_OP			: FB_SocketSend;
	FB_Recv_IPS_HP			: FB_SocketReceive;
	FB_Recv_IPS_OP			: FB_SocketReceive;

	Hearbit_IPS_HP		: PN_Pulse;
	Hearbit_IPS_OP		: PN_Pulse;

	tHeartbit_IPS_HP	: TOF;
	tHeartbit_IPS_OP	: TOF;

	bMsgSend_HP				: BOOL;
	bMsgSend_OP				: BOOL;

	bMsgRecv_HP				: BOOL;
	bMsgRecv_OP				: BOOL;

	tStep_Timer_HP	: ARRAY[1..5] OF TON;
	tStep_Timer_OP	: ARRAY[1..5] OF TON;

	Rtrig_Com_Strat	: R_TRIG;

	tStep2_Internal_HP		: TON;
	tStep2_Internal_OP		: TON;

	bReceive_Complete_HP	: BOOL;
	bReceive_Complete_OP	: BOOL;

	nIPS_HP_Step		: INT;
	bReceive_HP_Error	: BOOL;

	nIPS_OP_Step		: INT;
	bReceive_OP_Error	: BOOL;

	Buffer_Send_Data	: BYTE;

	//Related IPS208i Parsing
	IPS208i_Recieve_HP : IPS208i_Recieve;
	IPS208i_Recieve_OP : IPS208i_Recieve;

	Loop_Index	: INT;

	//Related Using Receive Data for Calibration
	fXPos_RealData_HP	: REAL;
	fYPos_RealData_HP	: REAL;
	fXPos_RealData_OP	: REAL;
	fYPos_RealData_OP	: REAL;

	bChange	: BOOL;
	bSend	: BOOL;

	tReceive	: TON;
	tReceive_1	: TON;

	tStep2_HP	: TON;
	tStep2_OP	: TON;

	tReceive_Q	: BOOL;
	tReceive_Q_1	: BOOL;

	nMaxRetries	: INT := 5;
	nRetryCount_HP	: INT;
	nRetryCount_OP	: INT;
	bReceive_Error_HP	: BOOL;
	bReceive_Error_OP	: BOOL;

	nLoop	: ARRAY[1..2] OF INT;

END_VAR



	//Acticon CALL
	ACT_FB_Socket();
	ACT_IPS_Parsing();


	//1. 이적재 노드 OR 대기 노드 =============================================================================================
	IF GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2 OR GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4 THEN

		//1-1. 통신 Enable Yes. ===========================================================================================
		bTCPIP_Start	:= TRUE;

		//1-2. Heart-Bit Check Yes.=======================================================================================
		Hearbit_IPS_HP( in_Type	:= 1, in_Signal := GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_HP);
		Hearbit_IPS_OP( in_Type	:= 1, in_Signal := GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_OP);

		tHeartbit_IPS_HP( IN := (Hearbit_IPS_HP.out_Pulse = TRUE), PT := T#1S, Q => GDB.Unit.IPS208i.IPS208i_Comm_OK_HP);
		tHeartbit_IPS_OP( IN := (Hearbit_IPS_OP.out_Pulse = TRUE), PT := T#1S, Q => GDB.Unit.IPS208i.IPS208i_Comm_OK_OP);

		//1-3. IPS Send/Receive Check Yes. ===============================================================================
		//1-3-1. IPS Repeat Send/Receive Start R_TRIG ====================================================================
		Rtrig_Com_Strat( CLK := (GDB.Unit.IPS208i.SocketConnect_State_HP = 1 AND GDB.Unit.IPS208i.SocketConnect_State_HP = 1 AND (GDB.Auto._1_Loading.Step <> 0 OR GDB.Auto._2_Unloading.Step <> 0 OR GDB.Unit.IPS208i.SendData_HP[0] <> Buffer_Send_Data)));

		IF Rtrig_Com_Strat.Q THEN

			nIPS_HP_Step	:= 1;
			nIPS_OP_Step	:= 1;

		END_IF

		ACT_FB_Send_Recv();

		//1-3-2. PLC <> IPS HP Repeat Send/Receive =======================================================================
		CASE nIPS_HP_Step OF

			//1-3-2-1. Send Start ========================================================================================
			1	:	
					tStep_Timer_HP[5]( IN := FALSE);

					nRetryCount_HP	:= 0;

					bMsgRecv_HP	:= FALSE;
					bMsgSend_HP	:= TRUE;

					tStep_Timer_HP[1]( IN := TRUE, PT := T#30MS);

					IF tStep_Timer_HP[1].Q THEN

						nIPS_HP_Step	:= 2;

					END_IF

			//1-3-2-2. Send/Receive Repeat Check ==========================================================================
			2	:
					IF GDB.Unit.IPS208i.SendData_HP[0] = Buffer_Send_Data THEN

						tStep_Timer_HP[1]( IN := FALSE);
						tStep_Timer_HP[3]( IN := FALSE);

						bMsgSend_HP	:= FALSE;
						bMsgRecv_HP	:= TRUE;

						tStep2_Internal_HP( IN := TRUE, PT := T#30MS);

						IF tStep2_Internal_HP.Q THEN

							//1-3-2-2-1. Receive nBytes Check, Normal = 50, Program Change = 5 =================================
							IF GDB.Unit.IPS208i.SendData_HP[0] = 16#47 THEN

								IF GDB.Unit.IPS208i.SocketRecieve_nRecBytes_HP <> 0 THEN

									bReceive_Complete_HP	:= TRUE;

								ELSE

									bReceive_Complete_HP	:= FALSE;

								END_IF

							ELSIF GDB.Unit.IPS208i.SendData_HP[0] = 16#2B THEN

								IF GDB.Unit.IPS208i.SocketRecieve_nRecBytes_HP > 4 THEN

									bReceive_Complete_HP	:= TRUE;

								ELSE

									bReceive_Complete_HP	:= FALSE;	

								END_IF

							END_IF

							//1-3-2-2-2. Send/Receive Complete ==================================================================
							tStep_Timer_HP[2]( IN := bReceive_Complete_HP = TRUE, PT := T#30MS);

							IF tStep_Timer_HP[2].Q THEN

								nIPS_HP_Step	:= 3;

							END_IF

						END_IF

				ELSE

					nIPS_HP_Step	:= 5;

				END_IF


//						


			3	:
					nRetryCount_HP	:= 0;

					bReceive_Complete_HP	:= FALSE;

					IF GDB.Unit.IPS208i.SendData_HP[0] = Buffer_Send_Data THEN

						tStep2_HP(IN := FALSE);
						tStep2_Internal_HP( IN := FALSE);
						tStep_Timer_HP[2]( IN := FALSE);
						bMsgRecv_HP	:= FALSE;
						bMsgSend_HP	:= TRUE;

						tStep_Timer_HP[3]( IN := TRUE, PT := T#30MS);
						IF tStep_Timer_HP[3].Q THEN 

							nIPS_HP_Step	:= 2;

						END_IF

					ELSE

						nIPS_HP_Step	:= 5;

					END_IF

			//1-3-2-5 Data Change Delay ======================================================================================		
			5	:

					bMsgRecv_HP	:= FALSE;
					bMsgSend_HP	:= FALSE;

					tStep2_HP(IN := FALSE);
					tStep2_Internal_HP(IN := FALSE);

					tStep_Timer_HP[1]( IN := FALSE);
					tStep_Timer_HP[2]( IN := FALSE);
					tStep_Timer_HP[3]( IN := FALSE);

					tStep_Timer_HP[5]( IN := TRUE, PT := T#50MS);
					IF tStep_Timer_HP[5].Q THEN

						nIPS_HP_Step	:= 1;

					END_IF

		ELSE

			//Initialization
			nIPS_HP_Step		:= 0;
			nRetryCount_HP		:= 0;
			bReceive_Error_HP	:= FALSE;

			bMsgSend_HP	:= FALSE;
			bMsgRecv_HP	:= FALSE;

			tStep2_HP(IN := FALSE);
			tStep2_Internal_HP(IN := FALSE);

			tStep_Timer_HP[1]( IN := FALSE);
			tStep_Timer_HP[2]( IN := FALSE);
			tStep_Timer_HP[3]( IN := FALSE);
			tStep_Timer_HP[5]( IN := FALSE);

		END_CASE


		//1-3-3. PLC <> IPS OP Repeat Send/Receive =======================================================================
		CASE nIPS_OP_Step OF

			//1-3-3-1. Send Start ========================================================================================
			1	:
					tStep_Timer_OP[5]( IN := FALSE);	

					nRetryCount_OP	:= 0;		

					bMsgRecv_OP	:= FALSE;
					bMsgSend_OP	:= TRUE;

					tStep_Timer_OP[1]( IN := TRUE, PT := T#30MS);

					IF tStep_Timer_OP[1].Q THEN

						nIPS_OP_Step	:= 2;

					END_IF

			//1-3-3-2. Send/Receive Repeat Check =========================================================================
			2	:

					IF GDB.Unit.IPS208i.SendData_HP[0] = Buffer_Send_Data THEN

						tStep_Timer_OP[1]( IN := FALSE);
						tStep_Timer_OP[3]( IN := FALSE);

						bMsgSend_OP	:= FALSE;

						IF NOT bMsgRecv_OP THEN

							bMsgRecv_OP	:= TRUE;

						END_IF

						IF nRetryCount_OP = nMaxRetries THEN

							bReceive_Error_OP	:= TRUE;

						END_IF

						IF nRetryCount_OP < nMaxRetries AND NOT bReceive_Error_OP THEN

							FOR nLoop[2] := 1 TO 5 DO

								IF GDB.Unit.IPS208i.SendData_OP[0] = 16#47 THEN

									IF GDB.Unit.IPS208i.SocketRecieve_nRecBytes_OP = 5 THEN

										bReceive_Complete_OP	:= TRUE;
										nIPS_OP_Step	:= 3;

										EXIT;

									ELSE

										bMsgRecv_OP	:= FALSE;
										nRetryCount_OP	:= nRetryCount_OP + 1;
										bReceive_Complete_OP	:= FALSE;

									END_IF

								ELSIF GDB.Unit.IPS208i.SendData_OP[0] = 16#2B THEN

									IF GDB.Unit.IPS208i.SocketRecieve_nRecBytes_OP = 50 THEN

										bReceive_Complete_OP	:= TRUE;
										nIPS_OP_Step	:= 3;

										EXIT;

									ELSE

										bMsgRecv_OP	:= FALSE;
										nRetryCount_OP	:= nRetryCount_OP + 1;
										bReceive_Complete_OP	:= FALSE;

									END_IF

								END_IF

							END_FOR

						END_IF	

				ELSE

					nIPS_OP_Step	:= 5;

				END_IF

//						tStep2_Internal_OP( IN := TRUE, PT := T#20MS);

//						IF tStep2_Internal_OP.Q THEN

//							bMsgRecv_OP	:= TRUE;

//							//1-3-3-2-1. Receive nBytes Check, Normal = 50, Program Change = 5 ===============================
//							IF GDB.Unit.IPS208i.SendData_OP[0] = 16#47 THEN

//								IF GDB.Unit.IPS208i.SocketRecieve_nRecBytes_OP = 5 THEN

//									bReceive_Complete_OP	:= TRUE;

//								ELSE

//									bReceive_Complete_OP	:= FALSE;

//								END_IF

//							ELSIF GDB.Unit.IPS208i.SendData_OP[0] = 16#2B THEN

//								IF  GDB.Unit.IPS208i.SocketRecieve_nRecBytes_OP = 50 THEN

//									bReceive_Complete_OP	:= TRUE;

//								ELSE

//									bReceive_Complete_OP	:= FALSE;	

//								END_IF

//							END_IF

//							//1-3-3-2-2. Send/Receive Complete ===============================================================
//							tStep_Timer_OP[2]( IN := bReceive_Complete_OP = TRUE, PT := T#10MS);

//							IF tStep_Timer_OP[2].Q  THEN

//								nIPS_OP_Step	:= 3;

//							END_IF

//						END_IF

//					ELSE

//						nIPS_OP_Step := 5;

//					END_IF


			//1-3-3-3. Preparing to Send(Timer : T#50MS) =============================================================
			3	:

					bReceive_Complete_OP	:= FALSE;

					IF GDB.Unit.IPS208i.SendData_HP[0] = Buffer_Send_Data THEN

//						tStep2_OP( IN := FALSE);
//						tStep2_Internal_OP( IN := FALSE);
//						tStep_Timer_OP[2]( IN := FALSE);
						bMsgRecv_OP	:= FALSE;
						bMsgSend_OP	:= TRUE;

						tStep_Timer_OP[3]( IN := TRUE, PT := T#30MS);
						IF tStep_Timer_OP[3].Q THEN

							nIPS_OP_Step	:= 2;

						END_IF

					ELSE

						nIPS_OP_Step	:= 5;

					END_IF

			//1-3-3-5. Data Change Delay =============================================================================
			5	:

					bMsgRecv_OP		:= FALSE;
					bMsgSend_HP		:= FALSE;

//					tStep2_OP( IN := FALSE);
//					tStep2_Internal_OP( IN := FALSE);

					tStep_Timer_OP[1]( IN := FALSE);
//					tStep_Timer_OP[2]( IN := FALSE);
					tStep_Timer_OP[3]( IN := FALSE);

					tStep_Timer_OP[5]( IN := TRUE, PT := T#50MS);
					IF tStep_Timer_OP[5].Q THEN

						nIPS_OP_Step	:= 1;

					END_IF

		ELSE

			//Initialization
			nIPS_OP_Step	:= 0;
			nRetryCount_OP	:= 0;
			bReceive_Error_OP	:= FALSE;

			bMsgSend_OP	:= FALSE;
			bMsgRecv_OP	:= FALSE;

//			tStep2_OP( IN := FALSE);
//			tStep2_Internal_OP( IN := FALSE);

			tStep_Timer_OP[1]( IN := FALSE);
//			tStep_Timer_OP[2]( IN := FALSE);
			tStep_Timer_OP[3]( IN := FALSE);



		END_CASE

		Buffer_Send_Data := GDB.Unit.IPS208i.SendData_HP[0];

//		IF NOT (GDB.Auto._1_Loading.Step <> 0 OR GDB.Auto._2_Unloading.Step <> 0) THEN

//			nIPS_HP_Step	:= 0;
//			nIPS_OP_Step	:= 0;

//		END_IF

	//1-4. IPS Program Change Send Yes ===========================================================================
		(*
			※ IPS Program Information ※

			- Program 0	: Turret
			- Program 1 : Port Loading
			- Program 2 : Port Unloading
		*)

		//1-4-1. Program Change 1. Turret ============================================================================
		IF (((GDB.Auto._1_Loading.Step = 1 OR GDB.Auto._2_Unloading.Step = 1) AND (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1))
			OR ((Setting_IPS_Auto_Teaching.Step = 9 OR Setting_IPS_Auto_Teaching.Step = 13) AND (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1))
			OR GDB.Touch.S901_IPS_Program_Select[1] ) THEN

			GDB.Unit.IPS208i.SendData_HP[0] := 16#47;   GDB.Unit.IPS208i.SendData_OP[0] := 16#47;
         	GDB.Unit.IPS208i.SendData_HP[1] := 16#41;   GDB.Unit.IPS208i.SendData_OP[1] := 16#41;
         	GDB.Unit.IPS208i.SendData_HP[2] := 16#49;   GDB.Unit.IPS208i.SendData_OP[2] := 16#49;
         	GDB.Unit.IPS208i.SendData_HP[3] := 16#3D;   GDB.Unit.IPS208i.SendData_OP[3] := 16#3D;
         	GDB.Unit.IPS208i.SendData_HP[4] := 16#30;   GDB.Unit.IPS208i.SendData_OP[4] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[5] := 16#30;   GDB.Unit.IPS208i.SendData_OP[5] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[6] := 16#30;   GDB.Unit.IPS208i.SendData_OP[6] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[7] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[7] := 16#0;   
         	GDB.Unit.IPS208i.SendData_HP[8] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[8] := 16#0;
         	GDB.Unit.IPS208i.SendData_HP[9] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[9] := 16#0;

		//1-4-2. Program Change 2. Port Loading =====================================================================
		ELSIF ((GDB.Auto._1_Loading.Step = 1 AND GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2))
			OR ((Setting_IPS_Auto_Teaching.Step = 13 AND GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2))
         	OR GDB.Touch.S901_IPS_Program_Select[2] THEN

			GDB.Unit.IPS208i.SendData_HP[0] := 16#47;   GDB.Unit.IPS208i.SendData_OP[0] := 16#47;
         	GDB.Unit.IPS208i.SendData_HP[1] := 16#41;   GDB.Unit.IPS208i.SendData_OP[1] := 16#41;
         	GDB.Unit.IPS208i.SendData_HP[2] := 16#49;   GDB.Unit.IPS208i.SendData_OP[2] := 16#49;
         	GDB.Unit.IPS208i.SendData_HP[3] := 16#3D;   GDB.Unit.IPS208i.SendData_OP[3] := 16#3D;
         	GDB.Unit.IPS208i.SendData_HP[4] := 16#30;   GDB.Unit.IPS208i.SendData_OP[4] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[5] := 16#30;   GDB.Unit.IPS208i.SendData_OP[5] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[6] := 16#31;   GDB.Unit.IPS208i.SendData_OP[6] := 16#31;
         	GDB.Unit.IPS208i.SendData_HP[7] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[7] := 16#0;   
         	GDB.Unit.IPS208i.SendData_HP[8] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[8] := 16#0;
         	GDB.Unit.IPS208i.SendData_HP[9] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[9] := 16#0;

		//1-4-3. Program Change 3. Port Unloading ==================================================================
		ELSIF ((GDB.Auto._2_Unloading.Step = 1 AND GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 ))
         	OR ((Setting_IPS_Auto_Teaching.Step = 9 AND GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2))
         	OR GDB.Touch.S901_IPS_Program_Select[3] THEN

			GDB.Unit.IPS208i.SendData_HP[0] := 16#47;   GDB.Unit.IPS208i.SendData_OP[0] := 16#47;
         	GDB.Unit.IPS208i.SendData_HP[1] := 16#41;   GDB.Unit.IPS208i.SendData_OP[1] := 16#41;
         	GDB.Unit.IPS208i.SendData_HP[2] := 16#49;   GDB.Unit.IPS208i.SendData_OP[2] := 16#49;
         	GDB.Unit.IPS208i.SendData_HP[3] := 16#3D;   GDB.Unit.IPS208i.SendData_OP[3] := 16#3D;
         	GDB.Unit.IPS208i.SendData_HP[4] := 16#30;   GDB.Unit.IPS208i.SendData_OP[4] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[5] := 16#30;   GDB.Unit.IPS208i.SendData_OP[5] := 16#30;
         	GDB.Unit.IPS208i.SendData_HP[6] := 16#32;   GDB.Unit.IPS208i.SendData_OP[6] := 16#32;
         	GDB.Unit.IPS208i.SendData_HP[7] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[7] := 16#0;   
         	GDB.Unit.IPS208i.SendData_HP[8] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[8] := 16#0;
         	GDB.Unit.IPS208i.SendData_HP[9] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[9] := 16#0;

		//1-4-4. Require marker measurement(Normal)
		ELSE

			GDB.Unit.IPS208i.SendData_HP[0] := 16#2B;   GDB.Unit.IPS208i.SendData_OP[0] := 16#2B;
      		GDB.Unit.IPS208i.SendData_HP[1] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[1] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[2] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[2] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[3] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[3] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[4] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[4] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[5] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[5] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[6] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[6] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[7] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[7] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[8] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[8] := 16#0;
      		GDB.Unit.IPS208i.SendData_HP[9] := 16#0;   	GDB.Unit.IPS208i.SendData_OP[9] := 16#0;

		END_IF


		//1-5. IPS Program Change Receive Yes =========================================================================

		//1-5-1. IPS HP Program Change Receive, GS = 00, 5 bytes ======================================================
		IF GDB.Unit.IPS208i.SocketConnect_State_HP = 1
			AND	GDB.Unit.IPS208i.RecieveData_HP[0] = 16#47
         	AND GDB.Unit.IPS208i.RecieveData_HP[1] = 16#53 AND GDB.Unit.IPS208i.RecieveData_HP[2] = 16#3D
         	AND GDB.Unit.IPS208i.RecieveData_HP[3] = 16#30 AND GDB.Unit.IPS208i.RecieveData_HP[4] = 16#30 THEN

			GDB.Unit.IPS208i.Program_Change_OK_HP	:= TRUE;

		ELSE

			GDB.Unit.IPS208i.Program_Change_OK_HP	:= FALSE;

		END_IF

		//1-5-2. IPS OP Program Change Receive, GS = 00, 5 bytes ======================================================
		IF GDB.Unit.IPS208i.SocketConnect_State_OP = 1
			AND	GDB.Unit.IPS208i.RecieveData_OP[0] = 16#47
         	AND GDB.Unit.IPS208i.RecieveData_OP[1] = 16#53 AND GDB.Unit.IPS208i.RecieveData_OP[2] = 16#3D
         	AND GDB.Unit.IPS208i.RecieveData_OP[3] = 16#30 AND GDB.Unit.IPS208i.RecieveData_OP[4] = 16#30 THEN

			GDB.Unit.IPS208i.Program_Change_OK_OP	:= TRUE;

		ELSE

			GDB.Unit.IPS208i.Program_Change_OK_OP	:= FALSE;

		END_IF		

		//1-6. Using Receive Data for Calibration ===================================================================
		//1-6-1. IPS HP =============================================================================================
		//1-6-1-1. IPS HP Turret Loading ============================================================================
		IF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND GDB.auto._1_Loading.Step > 2 ) 
			OR (ABS(GDB.Monitor.Current_Lift_Pos < 100) AND GDB.Touch.S901_IPS_Program_Select[1] = TRUE) THEN

			GDB.Unit.IPS208i.rXpos_RealData_HP := fXPos_RealData_HP;
			GDB.Unit.IPS208i.rYpos_RealData_HP := fYPos_RealData_HP;

		//1-6-1-2. IPS HP Turret Unloading ===========================================================================
		ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND GDB.Auto._2_Unloading.Step > 2 ) 
		OR (ABS(GDB.Monitor.Current_Lift_Pos > 100) AND GDB.Touch.S901_IPS_Program_Select[1] = TRUE) THEN

			GDB.Unit.IPS208i.rXpos_RealData_HP := fXPos_RealData_HP;
			GDB.Unit.IPS208i.rYpos_RealData_HP := fYPos_RealData_HP;

		//1-6-1-3. IPS HP Port =======================================================================================
		ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2) AND (GDB.auto._1_Loading.Step > 2 OR GDB.Auto._2_Unloading.Step > 2) 
			OR GDB.Touch.S901_IPS_Program_Select[2] = TRUE OR GDB.Touch.S901_IPS_Program_Select[3] = TRUE THEN

			GDB.Unit.IPS208i.rXpos_RealData_HP := fXPos_RealData_HP;
			GDB.Unit.IPS208i.rYpos_RealData_HP := fYPos_RealData_HP;

		END_IF;

		//1-6-1-4. IPS HP Final Calculation Data and Initialization ===================================================
		GDB.Monitor.IPS_HP_X := GDB.Unit.IPS208i.rXpos_RealData_HP;// + GDB_Parameter.IPS_HP_X_OFFSET;
		GDB.Monitor.IPS_HP_Y := GDB.Unit.IPS208i.rYpos_RealData_HP;// + GDB_Parameter.IPS_HP_Y_OFFSET;

		FOR Loop_Index := 0 TO 100 DO

			GDB.Unit.IPS208i.RecieveData_HP[Loop_Index] := 0;	

		END_FOR

		//1-6-2. IPS OP =============================================================================================
		//1-6-2-1. IPS OP Turret Loading ============================================================================
		IF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND GDB.auto._1_Loading.Step > 2 ) 
			OR (ABS(GDB.Monitor.Current_Lift_Pos < 100) AND GDB.Touch.S901_IPS_Program_Select[1] = TRUE) THEN

			GDB.Unit.IPS208i.rXpos_RealData_OP := fXPos_RealData_OP ;   
			GDB.Unit.IPS208i.rYpos_RealData_OP := fYPos_RealData_OP ;

		//1-6-2-2. IPS OP Turret Unloading ==========================================================================
		ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND GDB.Auto._2_Unloading.Step > 2 ) 
			OR (ABS(GDB.Monitor.Current_Lift_Pos > 100) AND GDB.Touch.S901_IPS_Program_Select[1] = TRUE) THEN

			GDB.Unit.IPS208i.rXpos_RealData_OP := fXPos_RealData_OP;
			GDB.Unit.IPS208i.rYpos_RealData_OP := fYPos_RealData_OP;

		//1-6-2-3. IPS OP Port ======================================================================================
		ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2) AND (GDB.auto._1_Loading.Step > 2 OR GDB.Auto._2_Unloading.Step > 2) 
			OR GDB.Touch.S901_IPS_Program_Select[2] = TRUE OR GDB.Touch.S901_IPS_Program_Select[3] = TRUE THEN

			GDB.Unit.IPS208i.rXpos_RealData_OP := fXPos_RealData_OP ;
			GDB.Unit.IPS208i.rYpos_RealData_OP := fYPos_RealData_OP ;

		END_IF; 

		//1-6-2-4. IPS OP Final Calculation Data and Initialization ===================================================
		GDB.Monitor.IPS_OP_X := GDB.Unit.IPS208i.rXpos_RealData_OP ;
		GDB.Monitor.IPS_OP_Y := GDB.Unit.IPS208i.rYpos_RealData_OP ;

		FOR Loop_Index := 0 TO 100 DO

			GDB.Unit.IPS208i.RecieveData_OP[Loop_Index] := 0;

		END_FOR;  

	//1. 이적재 노드 OR 대기 노드 No. =================================================================================
	ELSE

		//1-1. 통신 Enable No. =====================================================================================
		bTCPIP_Start	:= FALSE;

		//1-2. Heart-Bit Check No. ==================================================================================
		GDB.Unit.IPS208i.IPS208i_Comm_OK_HP	:= FALSE;
		GDB.Unit.IPS208i.IPS208i_Comm_OK_OP	:= FALSE;

		//1-3.IPS Send/Receive Check ================================================================================
		nIPS_HP_Step	:= 0;
		nIPS_OP_Step	:= 0;
		bReceive_HP_Error	:= FALSE;
		bReceive_OP_Error	:= FALSE;

		//1-5. IPS Program Change Receive No. =======================================================================
		GDB.Unit.IPS208i.Program_Change_OK_HP	:= FALSE;
		GDB.Unit.IPS208i.Program_Change_OK_OP	:= FALSE;

	END_IF

