         GDB.Unit.IPS208i.SendData_HP[5] := 16#30;   GDB.Unit.IPS208i.SendData_OP[5] := 16#30;
         GDB.Unit.IPS208i.SendData_HP[6] := 16#31;   GDB.Unit.IPS208i.SendData_OP[6] := 16#31;
