	 ELSIF Test_Rtrig_HP.Q OR (GDB.Unit.IPS208i.Program_Change_OK_HP AND GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_HP = FALSE AND GDB.Unit.IPS208i.Program_Change_OK_OP AND GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_OP =FALSE) 
