            IF GDB_PARAMETER.RP_Anode OR GDB_PARAMETER.Coater_Anode THEN
            GDB.Unit.IPS208i.rXpos_RealData_HP := Xpos_RealData_HP + GDB_Parameter.IPS_HP_X_OFFSET;
            GDB.Unit.IPS208i.rYpos_RealData_HP := Ypos_RealData_HP + GDB_Parameter.IPS_HP_Y_OFFSET;
            ELSE
            GDB.Unit.IPS208i.rXpos_RealData_HP := Xpos_RealData_HP + GDB_Parameter.IPS_HP_X_OFFSET;
