      ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 AND GDB.Auto._2_Unloading.Step > 2 ) 
         OR (ABS(GDB.Monitor.Current_Lift_Pos > 100) AND GDB.Touch.S901_IPS_Program_Select[1] = TRUE) THEN // 터렛 일때 언로딩
         IF GDB_PARAMETER.RP_Anode OR GDB_PARAMETER.Coater_Anode THEN
