            GDB.Unit.IPS208i.rYpos_RealData_HP := Ypos_RealData_HP + GDB_Parameter.IPS_HP_Y_OFFSET;                     
         END_IF

      ELSIF (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2) AND (GDB.auto._1_Loading.Step > 2 OR GDB.Auto._2_Unloading.Step > 2) 
         OR GDB.Touch.S901_IPS_Program_Select[2] = TRUE OR GDB.Touch.S901_IPS_Program_Select[3] = TRUE THEN //포트 일때

            GDB.Unit.IPS208i.rXpos_RealData_HP := Xpos_RealData_HP + GDB_Parameter.IPS_HP_X_OFFSET;
            GDB.Unit.IPS208i.rYpos_RealData_HP := Ypos_RealData_HP + GDB_Parameter.IPS_HP_Y_OFFSET;
      END_IF;


      GDB.Monitor.IPS_HP_X := GDB.Unit.IPS208i.rXpos_RealData_HP;
      GDB.Monitor.IPS_HP_Y := GDB.Unit.IPS208i.rYpos_RealData_HP;

      IF GDB.Unit.IPS208i.RecieveData_HP[0] = 16#47
         AND GDB.Unit.IPS208i.RecieveData_HP[1] = 16#53
         AND GDB.Unit.IPS208i.RecieveData_HP[2] = 16#3D
         AND GDB.Unit.IPS208i.RecieveData_HP[3] = 16#30
         AND GDB.Unit.IPS208i.RecieveData_HP[4] = 16#30 THEN
         GDB.Unit.IPS208i.Program_Change_OK_HP := TRUE;   
      END_IF;      
         FOR LoopIndex[1] := 0 TO 100 DO
            GDB.Unit.IPS208i.RecieveData_HP[LoopIndex[1]] := 0;
         END_FOR;
   END_IF;   

   IF GDB.Unit.IPS208i.SocketConnect_State_OP = 1 THEN   
      //Send
         //OP
      FB_SocketSend_IPS208i_OP(sSrvNetId:='', 
                           hSocket:= GDB.Unit.IPS208i.SocketConnect_hSocket_OP, 
                           cbLen:= 10#10, 
