                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4);
        END_IF;
        //////////////////in: 현재 상태&맵 정보&보정값 입력 부,   out:FB 내부 주행/ 조향/ 보정 연산 결과         
        ////////////////// 위에는 나머지 보정이나 이동값들 어디서 적용되는지, 주행 위치 목표 위치 



        //Complete
		IF TRUE THEN
	            TON[5](IN := ((GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#300MS);
	        IF TON[5].Q 
				//AND TEST_[15]
				AND GDB.Unit.Drive.LiftControl.Target_reached_Bit
				AND GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Complete
				AND	GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Theta_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Tilting_Drive.Control_PosMove_Complete
				AND GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Complete THEN
	            GDB.auto._2_Unloading.Step := 99;
	        END_IF;
		END_IF;
	END_IF;	    
	//////////////// 목표위치와 실제위치가 조건에 만족하면 타이머 작동 타이머 종료 후 위조건 만족하면 step 99로



    //Step_99_Command_Complete           
	IF GDB.auto._2_Unloading.Step = 99 THEN
        IF FALSE THEN
            GDB.auto._2_Unloading.Step := 100;
        END_IF;
	END_IF;    

/////////////////  99 false시 step 100


    //Step_100_Data Clear
	IF GDB.auto._2_Unloading.Step = 100 THEN
        IF TRUE THEN
            GDB.auto._2_Unloading.Step := 1;
        END_IF;
//// step 1로 돌아감 (초기화)		


	END_IF;

==================================================
Auto_3_Move

PROGRAM Auto_3_move
VAR
PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
TON	:ARRAY[0..1] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Auto_Wheel_Ready_Run_Instance	:Auto_Wheel_Ready_Run;
Auto_Wheel_move	:Auto_Wheel_move;

X_Offset	:REAL;
Y_Offset	:REAL;

END_VAR


//Initialize
GDB.Auto._3_Move.Pause := FALSE;
GDB.Auto._3_Move.Step_5_Y_Shift_Home := FALSE;
GDB.Auto._3_move.Step_7_EPC_Data := 0;
GDB.Auto._3_move.Step_7_Loading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := FALSE;
X_Offset := 0;
Y_Offset := 0;
//Pause
IF 	GDB.ACS.Host_pause 
	OR	GDB.Auto.PIO.PIO_Move_Pause_Bit
THEN
	GDB.Auto._3_Move.Pause := TRUE;
END_IF;

// X,Y_Offsetㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
	IF TRUE THEN								
		// Docking_Node_in Offset
		IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
				IF GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //[Direction - Left]
					X_Offset := 0;
					Y_Offset := 0;						
				ELSIF GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //[Direction - Right]
					X_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					Y_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
				END_IF;
				//EPC_Data_Set
				IF TRUE THEN
					IF GDB.Mode.Auto THEN
						GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;
					ELSIF GDB.Mode.Semi_Auto THEN
						GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;
					END_IF;	
					IF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 1 THEN
						X_Offset := X_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;
						Y_Offset := Y_Offset;					
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 2 THEN
						X_Offset := X_Offset;
						Y_Offset := Y_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 3 THEN
						X_Offset := X_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;
						Y_Offset := Y_Offset;									
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 4 THEN				
						X_Offset := X_Offset;
						Y_Offset := Y_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;									
					END_IF;
				END_IF;
		END_IF;
	END_IF;

//ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._3_move.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._3_move.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._3_move.Active = FALSE THEN
        GDB.auto._3_move.Step := 0;
    END_IF;	    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._3_move.Step = 1 THEN
        //Ready_Check_Complete
        IF  GDB.Auto._3_move.Pause = FALSE
            AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node = GDB_Retain.Current_Node
			AND NOT(GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2 AND GDB.Auto.Main.Distance_Curr_Dest < 1200 ) //Docking_Node 진입시, 최소거리 1200mm 확보필요.
        THEN			
	        IF GDB.Command.Direction_Angle_State = 1 THEN //Direction_Angle이 OK인 경우 Step_5
		            GDB.auto._3_move.Step := 5;
			ELSIF GDB.Command.Direction_Angle_State = 2 THEN //Direction_Angle이 NG인 경우 Step_3
					GDB.auto._3_move.Step := 3;
			END_IF;	
        END_IF;
		IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN //현재노드가 목적노드일 경우, Step_99(완료).
					GDB.auto._3_move.Step := 99;
		END_IF;	
	END_IF;	
	//Step_3_Spinturn
	IF GDB.auto._3_move.Step = 3 THEN    
		GDB.auto._5_Spinturn.Active := TRUE;
		GDB.Auto._5_Spinturn.Target_AGV_Angle := GDB.Command.Direction_Angle;
		IF GDB.Auto._5_Spinturn.Step = 99 THEN
			GDB.auto._3_move.Step := 5;
		END_IF				
	END_IF;	
    //Step_5_Wheel_Ready_Run
	IF GDB.auto._3_move.Step = 5 THEN
		//Y_Shift_Home
		IF GDB.Auto.Main.Docking_Node_in_3000mm = FALSE AND GDB.Unit.IO.di_Product_Detect THEN
		GDB.Auto._3_Move.Step_5_Y_Shift_Home := TRUE;
		GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
		END_IF;
		//Auto_Wheel_Ready_Run
        Auto_Wheel_Ready_Run_Instance(in_Enable:=TRUE,
                                       in_Work_Type:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type,
                                       in_Start_X:=GDB.monitor.Current_X,
                                       in_Start_Y:=GDB.monitor.Current_Y,
                                       in_End_X:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X - X_Offset,
                                       in_End_Y:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y - Y_Offset,
                                       in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                       in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                       in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                       out_Target_FW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                       out_Target_BW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle);
		IF 		gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle <= 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90;
		ELSIF	gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle > 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270;	
		END_IF;					   
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0
			AND ( (GDB.Auto._3_Move.Step_5_Y_Shift_Home AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0)
					OR (GDB.Auto._3_Move.Step_5_Y_Shift_Home = FALSE) ) THEN
            GDB.auto._3_move.Step := 7;
        END_IF;
    END_IF;

    //Step_7_Move	
	PN_Pulse[2](in_Type:= 1, in_Signal:= GDB.auto._3_move.Step = 7);	
	IF GDB.auto._3_move.Step = 7 THEN
        IF TRUE THEN		
			// Upper_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
			IF TRUE THEN				
				//Upper_Ready_Move(Docking)
				IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;

						IF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Loading[Direction - Left]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Unloading[Direction - Left]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Unloading[Direction - Right]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos - 5;	
						END_IF;

				//Upper_Home		
				ELSE 			
						IF GDB.Auto.Main.Distance_Curr_StartPoint > 500 THEN
							GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := TRUE;
							GDB.Auto._3_move.Step_7_Home_Bit := TRUE;
						END_IF;							
						GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;							
				END_IF;
			END_IF;
			// Travel_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
            		Auto_Wheel_move(  in_Enable:=TRUE,                                      
									  in_StartSet_Renew := PN_Pulse[2].out_Pulse,
                                      in_Extend_Permission_Bit:=GDB.Auto._3_move.Pause=FALSE,
									  in_Current_Wheel_Angle_Hold_Bit := gdb.Auto.Main.Docking_Node_out_500mm,
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Current_Node:= GDB_Retain.Current_Node, 									  
									  in_Command_Current_Number := GDB.Command.Current_Number,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
									  in_Start_X_Offset:= X_Offset, 
									  in_Start_Y_Offset:= Y_Offset, 
									  in_End_X_Offset:= X_Offset, 
									  in_End_Y_Offset:= Y_Offset,
									  out_Current_Node=> GDB_Retain.Current_Node,  
                                      out_Command_Current_Number=>GDB.Command.Current_Number,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4,
									  out_Error_Code=>GDB.Auto._3_Move.Step_7_Move_Error_Code);
        END_IF;        
        //Move_Complete
		IF TRUE THEN
	        IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 1
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 5.0),
	                    PT := T#500MS);
	        ELSIF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#200MS);
	        ELSE
	            TON[1](IN := FALSE,
	                    PT := T#200MS);
	        END_IF;
	        IF 		TON[1].Q 
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift - GDB.Monitor.Current_X_Shift_Pos) < 1.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 THEN			
					GDB.auto._3_move.Step := 9;	
				END_IF            
        END_IF;
	END_IF;	
	//Step_9_Step_Return or Command_Complete
	IF GDB.auto._3_move.Step = 9 THEN
		IF TRUE THEN
			GDB_Retain.Current_Node := GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node;
			GDB.Command.Current_Number := GDB.Command.Current_Number + 1;
			IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN
				GDB.auto._3_move.Step := 99;
			ELSE
				GDB.auto._3_move.Step := 1;	
			END_IF
        END_IF;
	END_IF;	
    // 99: Command_Complete        
    IF GDB.auto._3_move.Step = 99 THEN
		IF FALSE THEN
			GDB.auto._3_move.Step := 1;	
		END_IF;                
	END_IF;	


==================================================
Auto_3_Move_1

PROGRAM Auto_3_Move_1
VAR
PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
TON	:ARRAY[0..1] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Auto_Wheel_Ready_Run_Instance	:Auto_Wheel_Ready_Run;
Auto_Wheel_move	:Auto_Wheel_move;

X_Offset	:REAL;
Y_Offset	:REAL;

END_VAR


//Initialize
GDB.Auto._3_Move.Pause := FALSE;
GDB.Auto._3_Move.Step_5_Y_Shift_Home := FALSE;
GDB.Auto._3_move.Step_7_EPC_Data := 0;
GDB.Auto._3_move.Step_7_Loading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit := FALSE;
GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := FALSE;
gdb.Auto._3_Move.Step_7_X_Offset := 0;
gdb.Auto._3_Move.Step_7_Y_Offset := 0;
//Pause
IF 	GDB.ACS.Host_pause 
	OR	GDB.Auto.PIO.PIO_Move_Pause_Bit
THEN
	GDB.Auto._3_Move.Pause := TRUE;
END_IF;

// X,Y_Offsetㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
	IF TRUE THEN								
		// Docking_Node_in Offset
		IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
				IF GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //[Direction - Left]
					gdb.Auto._3_Move.Step_7_X_Offset := 0;
					gdb.Auto._3_Move.Step_7_Y_Offset := 0;					
				ELSIF GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //[Direction - Right]
					gdb.Auto._3_Move.Step_7_X_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_X_Offset;
					gdb.Auto._3_Move.Step_7_Y_Offset := GDB_Retain.Node[GDB.Command.Dest_Node].Docking_Right_Y_Offset;
				END_IF;
		END_IF;
				//EPC_Data_Set
				IF TRUE THEN

					IF GDB.Mode.Auto THEN					

						IF 
								((GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction <> 0)	
								AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 2000.0))
								OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction <> 0) THEN
								GDB.ACS.EPC_Data := GDB.ACS.EPC_Data;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;
						ELSE
								GDB.ACS.EPC_Data := 0.00;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.ACS.EPC_Data;

						END_IF;
					END_IF

					IF gdb.Mode.Semi_Auto THEN
						IF 
								((GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction <> 0)	
								AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 2000.0))
								OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction <> 0) THEN
								GDB.ACS.EPC_Data := GDB.ACS.EPC_Data;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;
						ELSE
								GDB.ACS.EPC_Data := 0.00;
								GDB.Auto._3_Move.Step_7_EPC_Data := GDB.Touch.S25_EPC_Data;

						END_IF;
					END_IF

					IF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 1 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset;						
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 2 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 3 THEN
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset;										
					ELSIF GDB_Retain.Node[GDB.Command.Dest_Node].Turret_EPC_Direction = 4 THEN				
						gdb.Auto._3_Move.Step_7_X_Offset := gdb.Auto._3_Move.Step_7_X_Offset;
						gdb.Auto._3_Move.Step_7_Y_Offset := gdb.Auto._3_Move.Step_7_Y_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;									
					END_IF;
				END_IF;

	END_IF;

//ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._3_move.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._3_move.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._3_move.Active = FALSE THEN
        GDB.auto._3_move.Step := 0;
    END_IF;	    
END_IF;


    //Step_1_Ready_Check
	IF GDB.auto._3_move.Step = 1 THEN
        //Ready_Check_Complete
        IF  GDB.Auto._3_move.Pause = FALSE
            AND GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node = GDB_Retain.Current_Node
			AND NOT(GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2  AND GDB.Auto.Main.Distance_Curr_Dest < 1000 ) //Docking_Node 진입시, 최소거리 1200mm 확보필요.
	        THEN			
	        IF GDB.Command.Direction_Angle_State = 1 THEN //Direction_Angle이 OK인 경우 Step_5
		            GDB.auto._3_move.Step := 5;
			ELSIF GDB.Command.Direction_Angle_State = 2 THEN //Direction_Angle이 NG인 경우 Step_3
					GDB.auto._3_move.Step := 3;
			END_IF;	
        END_IF;
		IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN //현재노드가 목적노드일 경우, Step_99(완료).
					GDB.auto._3_move.Step := 99;
		END_IF;	
	END_IF;	
	//Step_3_Spinturn
	IF GDB.auto._3_move.Step = 3 THEN    
		GDB.auto._5_Spinturn.Active := TRUE;
		GDB.Auto._5_Spinturn.Target_AGV_Angle := GDB.Command.Direction_Angle;
		IF GDB.Auto._5_Spinturn.Step = 99 THEN
			GDB.auto._3_move.Step := 5;
		END_IF				
	END_IF;	
    //Step_5_Wheel_Ready_Run
	IF GDB.auto._3_move.Step = 5 THEN
		//Y_Shift_Home
		IF GDB.Auto.Main.Docking_Node_in_3000mm = FALSE AND GDB.Unit.IO.di_Product_Detect THEN
		GDB.Auto._3_Move.Step_5_Y_Shift_Home := TRUE;
		GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
		END_IF;
		//Auto_Wheel_Ready_Run
        Auto_Wheel_Ready_Run_Instance(in_Enable:=TRUE,
                                       in_Work_Type:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type,
                                       in_Turn:=GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Turn,
									   in_Start_X:=GDB.monitor.Current_X,
                                       in_Start_Y:=GDB.monitor.Current_Y,
                                       in_End_X:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X - gdb.Auto._3_Move.Step_7_X_Offset,
                                       in_End_Y:=GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y - gdb.Auto._3_Move.Step_7_Y_Offset,
                                       in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                       in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                       in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                       out_Target_FW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                       out_Target_BW_Wheel_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
									    out_Turn_Error_Bit => GDB.Auto._3_Move.Step_3_Wheel_Turn_Data_Error);
		IF 		gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle <= 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90;
		ELSIF	gdb.Auto.Main.Docking_Node_out_500mm 
			AND GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle > 360 THEN
			GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270;
			GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270;	
		END_IF;					   
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0
			AND ( (GDB.Auto._3_Move.Step_5_Y_Shift_Home AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0)
					OR (GDB.Auto._3_Move.Step_5_Y_Shift_Home = FALSE) ) THEN
            GDB.auto._3_move.Step := 7;
        END_IF;
    END_IF;

    //Step_7_Move	
	PN_Pulse[2](in_Type:= 1, in_Signal:= GDB.auto._3_move.Step = 7);	
	IF GDB.auto._3_move.Step = 7 THEN
        IF TRUE THEN		
			// Upper_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ							
			IF TRUE THEN				
				//Upper_Ready_Move(Docking)
				IF GDB.Auto.Main.Docking_Node_in_3000mm THEN								
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;

						IF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Loading[Direction - Left]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Loading[Direction - Right]
							GDB.Auto._3_move.Step_7_Loading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].Loading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 1 THEN //Unloading[Direction - Left]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos; 		
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos;
						ELSIF GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Auto.Main.Crab_Direction_1L_2R = 2 THEN //Unloading[Direction - Right]
							GDB.Auto._3_move.Step_7_UnLoading_Ready_Bit := TRUE;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := +1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Navi_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Lift := GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Lift_Pos;
							GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := -1 * GDB_Retain.Node[GDB.Command.Dest_Node].UnLoading_Data.Ready_Y_Shift_Pos - 5;	
						END_IF;

				//Upper_Home		
				ELSE 			
						IF GDB.Auto.Main.Distance_Curr_StartPoint > 500 THEN
							GDB.Auto._3_move.Step_7_Home_Bit_Over_500mm := TRUE;
							GDB.Auto._3_move.Step_7_Home_Bit := TRUE;
						END_IF;							
						GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
						GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;							
				END_IF;
			END_IF;
			// Travel_Partㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
            		Auto_Wheel_move(  in_Enable:=TRUE,                                      
									  in_StartSet_Renew := PN_Pulse[2].out_Pulse,
                                      in_Extend_Permission_Bit:=GDB.Auto._3_move.Pause=FALSE,
									  in_Current_Wheel_Angle_Hold_Bit := gdb.Auto.Main.Docking_Node_out_500mm,
                                      in_Current_X_mm:=GDB.monitor.Current_X,
                                      in_Current_Y_mm:=GDB.monitor.Current_Y,
                                      in_Current_AGV_Angle:=GDB.monitor.Current_AGV_Angle,
                                      in_Direction_Angle:=GDB.Command.Direction_Angle,
                                      in_FW_Wheel_Angle:=GDB.monitor.Current_FW_Wheel_Angle,
                                      in_BW_Wheel_Angle:=GDB.monitor.Current_BW_Wheel_Angle,
                                      in_Distance_FwWheel_BwWheel_mm:=GDB_Parameter.Distance_FwWheel_BwWheel_mm,
									  in_Current_Node:= GDB_Retain.Current_Node, 									  
									  in_Command_Current_Number := GDB.Command.Current_Number,
									  in_Data_List := GDB.Command.Data_List,
									  in_Node := GDB_Retain.Node,
									  in_Link_ID := GDB_Retain.Link_ID,
									  in_Start_X_Offset:= gdb.Auto._3_Move.Step_7_X_Offset, 
									  in_Start_Y_Offset:= gdb.Auto._3_Move.Step_7_Y_Offset, 
									  in_End_X_Offset:= gdb.Auto._3_Move.Step_7_X_Offset, 
									  in_End_Y_Offset:= gdb.Auto._3_Move.Step_7_Y_Offset,
									  out_Current_Node=> GDB_Retain.Current_Node,  
                                      out_Command_Current_Number=>GDB.Command.Current_Number,
                                      out_1_Travel_Actual_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos,
                                      out_1_Travel_Target_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos,
                                      out_1_Travel_Target_Extend_Pos_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos,
									  out_1_Travel_Target_Pos_Total_mm=>GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total,
                                      out_1_Travel_Direction_Invert_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit,
                                      out_1_Travel_Decel_Bit=>GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit,
                                      out_1_Travel_Max_Speed_mpm=>GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm,
                                      out_2_Steering_FW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle,
                                      out_2_Steering_BW_Wheel_Target_Angle=>GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle,
                                      out_2_Error_Value_mm=>GDB.Unit.Drive.Move_Data._2_Error_Value,
                                      out_2_Error_Value_Direction_0cw_1ccw=>GDB.Unit.Drive.Move_Data._2_Error_Value_Revision_Direction_0cw_1ccw,
                                      out_3_AGV_Revision_Angle_s180=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180,
                                      out_3_AGV_Revision_Direction_S1E4=>GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4,
									  out_Error_Code=>GDB.Auto._3_Move.Step_7_Move_Error_Code);
        END_IF;        
        //Move_Complete
		IF TRUE THEN
	        IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 1
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 5.0),
	                    PT := T#500MS);
	        ELSIF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5
	            OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN
	            TON[1](IN := (ABS(GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos - GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos) < 10.0),
	                    PT := T#200MS);
	        ELSE
	            TON[1](IN := FALSE,
	                    PT := T#200MS);
	        END_IF;
	        IF 		TON[1].Q 
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift - GDB.Monitor.Current_X_Shift_Pos) < 1.0
				AND	ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift - GDB.Monitor.Current_Y_Shift_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Theta - GDB.Monitor.Current_Theta_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Tilting - GDB.Monitor.Current_Tilting_Pos) < 1.0
				AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi - GDB.Monitor.Current_Y_Navi_Pos) < 1.0 THEN			
					GDB.auto._3_move.Step := 9;	
				END_IF            
        END_IF;
	END_IF;	
	//Step_9_Step_Return or Command_Complete
	IF GDB.auto._3_move.Step = 9 THEN
		IF TRUE THEN
			GDB_Retain.Current_Node := GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node;
			GDB.Command.Current_Number := GDB.Command.Current_Number + 1;
			IF GDB.Command.Dest_Node = GDB_Retain.Current_Node THEN
				GDB.auto._3_move.Step := 99;
			ELSE
				GDB.auto._3_move.Step := 1;	
			END_IF
        END_IF;
	END_IF;	
    // 99: Command_Complete        
    IF GDB.auto._3_move.Step = 99 THEN
		IF FALSE THEN
			GDB.auto._3_move.Step := 1;	
		END_IF;                
	END_IF;	

