Auto_5_SpinTurn

PROGRAM Auto_5_SpinTurn
VAR
PN_Pulse	:ARRAY[0..1] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..1] OF Angle_Calcuration;

END_VAR



//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto._5_SpinTurn.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto._5_SpinTurn.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto._5_SpinTurn.Active = FALSE THEN
        GDB.auto._5_SpinTurn.Step := 0;
    END_IF;

END_IF;

//Data_Set
IF TRUE THEN
    Angle_Calcuration[1](in_3_Angle_SUB_bit := TRUE,
                          in_SUB_1_1 := GDB.auto._5_SpinTurn.Target_AGV_Angle,
                          in_SUB_1_2 := GDB.monitor.Current_AGV_Angle,
                          out_3_SUB1_s180 => GDB.auto._5_SpinTurn.SUB_Target_Currnet_s180,
                          out_3_SUB1_us180 => GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180);
    GDB.auto._5_SpinTurn.Distance_Per_Degree := ((GDB_Parameter.Distance_FwWheel_BwWheel_mm * 3.141593) / 360.0);
END_IF;

CASE GDB.auto._5_SpinTurn.Step OF
    1:  //Ready_Check
        IF TRUE THEN
            //Ready_Check_Complete
            IF GDB.auto._5_SpinTurn.Target_AGV_Angle >= 0 AND GDB.auto._5_SpinTurn.Target_AGV_Angle < 360 AND
				GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE <> 2 AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE <> 3 AND
			   (GDB_Retain.Node[GDB_Retain.Current_Node].SpinTurn = TRUE OR GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 10 OR GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 > 350) THEN
                GDB.auto._5_SpinTurn.Step := 2;
            END_IF;
            //Ready_Check_StepJump
            IF GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 1.0 THEN
                GDB.auto._5_SpinTurn.Step := 99;
            END_IF;
        END_IF;


    2:  //Wheel_Ready_Run
		IF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) <= 360 THEN
        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90.0;
        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90.0;
		ELSIF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) > 360 THEN
        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270.0;
        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270.0;		
		END_IF;
        IF ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
            AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0 THEN
            GDB.auto._5_SpinTurn.Step := 3;
        END_IF;

    3:  //Move
		IF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) <= 360 THEN
    	    GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 90.0;
    	    GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 90.0;
		ELSIF (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) > 360 THEN
	        GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle := 270.0;
	        GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle := 270.0;		
		END_IF;        
        //Move_Complete
        IF GDB.auto._5_SpinTurn.SUB_Target_Currnet_us180 < 1.0 THEN
            GDB.auto._5_SpinTurn.Step := 99;
        END_IF;

        // 99: Command_Complete        
    99:
        IF FALSE THEN
            GDB.auto._5_SpinTurn.Step := 1;
        END_IF;
    ELSE
        GDB.auto._5_SpinTurn.Step := 0;
END_CASE;


