			//AND GDB.Auto.Exits.Active = FALSE //EXIT 실행 시 Port PIO 시도 금지
			AND	GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2 //목적지가 이적재노드일 때
			AND GDB.Auto.PIO.PIO_Pause_Node[GDB_Retain.Current_Node] //PIO 위치, Mixer 프로그램처럼 PIO_Entry_Node를 조건으로 걸고 싶으나 1동 RP(+) DR룸 대기위치 조건에 부합되지 않음
			AND GDB.Unit.IO.di_DMS_in_6 = FALSE THEN // in6_Complete 가 아닐 때,	(OUT 아닐 때)
			GDB.Auto.PIO.PIO_Direction_1L_2R := GDB.Auto.Main.Crab_Direction_1L_2R;
			GDB.Auto.PIO.PIO_Dest_Node := GDB.Command.Dest_Node;
			GDB.Auto.PIO.PIO_Start_Node := GDB_Retain.Current_Node;
END_IF
	//Clear		
PN_Pulse[6](in_Type:= 1, in_Signal:= GDB.Auto.PIO.PIO_Direction_1L_2R <> 0 AND GDB_Retain.Current_Node = GDB.Auto.PIO.PIO_Start_Node);
TOF[1](IN:= PN_Pulse[6].out_Pulse, PT:= T#1S, Q=> GDB.Auto.PIO.PIO_Move_Pause_Bit); //PIO 정상 종료를 위한 딜레이타임, Complete_Signal
PN_Pulse[1](in_Type:= 2, in_Signal:=GDB.Unit.IO.di_DMS_in_6); //DMS_in6_Complete Down_Pulse
IF PN_Pulse[1].out_Pulse THEN
	IN_Complete := TRUE;
END_IF

IF 	   (GDB.Auto.PIO.PIO_Node[GDB_Retain.Current_Node] AND GDB.Command.Dest_Node <> GDB.Auto.PIO.PIO_Dest_Node AND GDB.Command.Dest_Node <> GDB.Auto.PIO.PIO_Start_Node AND TOF[1].Q = FALSE) //정상 완료하지 않고 다른 노드로 가는 경우,
	OR (GDB.Auto.PIO.PIO_Node[GDB_Retain.Current_Node] AND IN_Complete AND GDB.Unit.IO.di_DMS_in_5) //정상 종료
	OR (GDB.Auto.PIO.PIO_Node[GDB_Retain.Current_Node] AND GDB.Mode.Active = FALSE AND GDB.Error.Error_Code = 0) //대기위치 Manual 상태일 때
	OR (Port_PIO AND GDB.Mode.Active = FALSE AND GDB.Error.Error_Code = 0) //에러 발생 후 리셋 시 포트 PIO 종료
	//OR GDB.Auto.Exits.Step = Exits_Step.Complete //Exit 종료 시
	OR GDB.Auto.PIO.PIO_Ignore_Bit
	THEN
		GDB.Auto.PIO.PIO_Direction_1L_2R := 0;
		GDB.Auto.PIO.PIO_Dest_Node := 0;
		GDB.Auto.PIO.PIO_Start_Node := 0;
		IN_Complete := FALSE;
END_IF


//Map_Setting---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//IF TRUE THEN //RP_2의 경우 PIO Start 조건 위에 있으면 적용이 안됨
//	IF GDB_Parameter.ESNB_2 THEN
//		//RP(-)
//		IF GDB_Parameter.RP_2 THEN //PIO Bypass ON
//			IF (GDB_Retain.Current_Node = 57 OR GDB_Retain.Current_Node = 58 OR
//				GDB_Retain.Current_Node = 53 OR GDB_Retain.Current_Node = 54 OR
//				GDB_Retain.Current_Node = 45 OR GDB_Retain.Current_Node = 46 OR
//				GDB_Retain.Current_Node = 39 OR GDB_Retain.Current_Node = 40 ) AND
//				GDB.Auto.PIO.PIO_Direction_1L_2R = 1
//			THEN
//				GDB.Auto.PIO.PIO_Direction_1L_2R := 0;
//			END_IF
//		END_IF
//	END_IF
//END_IF
//--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


//DMS Direction_Select
IF GDB.Auto.PIO.PIO_Direction_1L_2R = 1 THEN
	GDB.Unit.IO.do_DMS_Left_Select := FALSE;
ELSIF GDB.Auto.PIO.PIO_Direction_1L_2R = 2 THEN
	GDB.Unit.IO.do_DMS_Right_Select := FALSE;
END_IF

//DMS Signal Set
IF GDB.Auto.PIO.PIO_Direction_1L_2R <> 0 THEN
	IF GDB.Unit.IO.do_DMS_out_8 = FALSE THEN
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.LC_Mutting

		// Out5.Busy
		IF GDB.Auto.PIO.PIO_CIS_TURRET = FALSE THEN
			IF (GDB.Unit.IO.di_DMS_in_1 = TRUE OR GDB.Unit.IO.di_DMS_in_2 = TRUE) AND Angle_Calcuration[1].out_2_TwoPoint_Distance_mm < 1200 THEN
				GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy
			END_IF
		ELSIF GDB.Auto.PIO.PIO_CIS_TURRET THEN
			IF (GDB.Auto._1_Loading.Step > 0 AND GDB.Auto._1_Loading.Step <> 11) OR (GDB.Auto._2_Unloading.Step > 0 AND GDB.Auto._2_Unloading.Step <> 11) THEN
			   GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy
			END_IF
		END_IF

		// Out4.Transfer Request
		TON[5](IN:=  ((Port_PIO = FALSE AND (GDB.Auto._1_Loading.Step = 11 OR GDB.Auto._2_Unloading.Step = 11))
				   OR (Port_PIO AND (GDB.Auto._1_Loading.Step = 113 OR GDB.Auto._2_Unloading.Step = 113))),
			   PT:= T#1000MS, Q=> GDB.Unit.IO.do_DMS_out_4); // Out4.Transfer Request

		// Out6.Complete
		//IF GDB.Unit.IO.di_DMS_in_6 AND GDB.Auto.PIO.PIO_Node[GDB_Retain.Current_Node] THEN
		IF GDB.Unit.IO.di_DMS_in_6 AND Angle_Calcuration[2].out_2_TwoPoint_Distance_mm < 200 THEN
			GDB.Unit.IO.do_DMS_out_6 := TRUE; // Out6.Complete
		END_IF
	END_IF

	// Out8.Error
	IF Port_PIO = FALSE AND (GDB.Error.Error_Code <> 0 OR GDB.Mode.Active = FALSE) (*OR GDB.Auto.Exits.Active)*) THEN
		GDB.Unit.IO.do_DMS_out_8 := TRUE;
	ELSIF Port_PIO THEN
		TON[8](IN:= GDB.Error.Error_Code <> 0, PT:= T#0.5S, Q=> GDB.Unit.IO.do_DMS_out_8); //Port Interlock Send Delay //차장님 요청사항	
	END_IF

END_IF


//Move_Pause, 2동 RP STK_Port PIO 통신끊김 무시(3초)하고 진입
//IF TRUE THEN
//	//
//	IF GDB_Parameter.UW_DDA AND Port_PIO THEN
//		PIO_Ignore_3S := TRUE;
//	ELSE
//		PIO_Ignore_3S := FALSE;
//	END_IF

//	//Delay_3S
//	TOF[2](IN:=  ((GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Unit.IO.di_DMS_in_1) 
//			   OR (GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Unit.IO.di_DMS_in_2)), 
//		   PT:= T#3S, Q=> ); //3초 끊기면(출력 살면) 스탑
//	//PIO_Entry_Signal_IN
//	IF TOF[2].Q THEN
//		IN_Entry_Signal := TRUE;
//	ELSIF GDB.Auto.PIO.PIO_Direction_1L_2R = 0 THEN
//		IN_Entry_Signal := FALSE;
//	END_IF
//END_IF

//Move_Pause
	//IN
IF GDB.Auto._5_Spinturn.Step <> 3 THEN
	IF 		GDB.Error.Error_Code = 0
		AND GDB.Unit.IO.di_DMS_in_6 = FALSE
		AND GDB.Command.Dest_Node <> 0
		AND	GDB.Command.Dest_Node = GDB.Auto.PIO.PIO_Dest_Node
		AND ((GDB.Unit.IO.di_Product_Detect = TRUE  AND GDB.Unit.IO.di_DMS_in_1 = FALSE) OR
			 (GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.Unit.IO.di_DMS_in_2 = FALSE))
		AND GDB.Auto.PIO.PIO_Pause_Node[GDB_Retain.Current_Node] //현재 PIO 위치에서
		AND GDB.Auto.PIO.PIO_Pause_Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node] //다음 진행방향도 도킹노드 진입경로일 때
		AND GDB.Auto.PIO.PIO_Entry_Node[GDB.Auto.PIO.PIO_Dest_Node] <> GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node //반자동, 옆포트 들어가는 경우 Pause x
		AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE <> 2 //이적재작업 Chucking Unchucking 도중 PIO Timeout Error 발생하여 작업명령 스킵, AGVC에서 이동명령 생성
		AND (PIO_Ignore_3S = FALSE OR //2동 STK Port 아니거나
			(PIO_Ignore_3S AND IN_Entry_Signal = FALSE) OR //2동 STK Port인데 진입 신호가 안들어왔거나(PIO 시작 안했거나)
			(PIO_Ignore_3S AND IN_Entry_Signal AND TOF[2].Q = FALSE)) //2동 STK Port 진입신호 수신 후 노이즈로 통신 두절 시 정지 딜레이 3초
			//2동 STK Port에서 PIO 시작 후 지속적인 노이즈로 인해 DDA가 진입을 못함, 완전히 무시할 수는 없고 조금씩 끊기더라도 들어가라고 만들어놓은 딜레이
	THEN
		GDB.Auto.PIO.PIO_Move_Pause_Bit := TRUE;
	END_IF
END_IF


//PIO_TimeOut
TON[2](IN:= GDB.Auto.PIO.PIO_Move_Pause_Bit, PT:=T#180S , Q=> GDB.Auto.PIO.PIO_Timeout_Bit);   //60s -> 180s 바꿈    


// PIO LOG

//	GDB.Auto.PIO.PIO_LOG_INPUT.0 := GDB.Unit.IO.di_DMS_in_1;
//	GDB.Auto.PIO.PIO_LOG_INPUT.1 := GDB.Unit.IO.di_DMS_in_2;
//	GDB.Auto.PIO.PIO_LOG_INPUT.2 := GDB.Unit.IO.di_DMS_in_3;
//	GDB.Auto.PIO.PIO_LOG_INPUT.3 := GDB.Unit.IO.di_DMS_in_4;
//	GDB.Auto.PIO.PIO_LOG_INPUT.4 := GDB.Unit.IO.di_DMS_in_5;
//	GDB.Auto.PIO.PIO_LOG_INPUT.5 := GDB.Unit.IO.di_DMS_in_6;
//	GDB.Auto.PIO.PIO_LOG_INPUT.6 := GDB.Unit.IO.di_DMS_in_7;
//	GDB.Auto.PIO.PIO_LOG_INPUT.7 := GDB.Unit.IO.di_DMS_in_8;

//	GDB.Auto.PIO.PIO_LOG_OUTPUT.0 := GDB.Unit.IO.do_DMS_out_1;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.1 := GDB.Unit.IO.do_DMS_out_2;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.2 := GDB.Unit.IO.do_DMS_out_3;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.3 := GDB.Unit.IO.do_DMS_out_4;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.4 := GDB.Unit.IO.do_DMS_out_5;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.5 := GDB.Unit.IO.do_DMS_out_6;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.6 := GDB.Unit.IO.do_DMS_out_7;
//	GDB.Auto.PIO.PIO_LOG_OUTPUT.7 := GDB.Unit.IO.do_DMS_out_8;


==================================================
Auto_PIO_1

PROGRAM Auto_PIO_1
VAR
	PN_Pulse	:ARRAY[0..1] OF PN_Pulse;
	TON	:ARRAY[0..0] OF TON;
	TOF	:ARRAY[0..0] OF TOF;
	Angle_Calcuration	:ARRAY[0..2] OF Angle_Calcuration;
	Loop_Index : INT;
	Direction_Buffer : INT;
END_VAR
(* OUT *)
// Out1.Interface ON
// Out2.Turret Or Port In
// Out3.Turret Or Port In
// Out4.Turret : Request(Chuck/Unchuck) , Port : Lift_Move(Up/Down)
// Out5.Busy (Revision Or Home_Move)
// Out6.Complete : AGV_Wait_Node_Arrive
// Out7.Light_Curtain_Mutting
// Out8.Error (Turret Or Port In)
(* IN *)
// in1.Loading_Request
// in2.Unloading_Request
// in3.Ready
// in4.Busy
// in5.Light_Curtain_Mutting_Ack
// in6.Complete
// in7.-
// in8.Error

//(현재노드가 대기노드 or 도킹노드 ) 또는 End노드가 대기노드
//가 아니면 클리어!

//initialize
GDB.Unit.IO.do_DMS_Left_Select := FALSE;
GDB.Unit.IO.do_DMS_Right_Select := FALSE;
GDB.Unit.IO.do_DMS_out_1 := FALSE; // Out1.Interface ON
GDB.Unit.IO.do_DMS_out_2 := FALSE; // Out2.Turret Or Port In
GDB.Unit.IO.do_DMS_out_3 := FALSE; // Out3.Turret Or Port In
GDB.Unit.IO.do_DMS_out_4 := FALSE; // Out4.Turret : Request(Chuck/Unchuck) , Port : Lift_Move(Up/Down)
GDB.Unit.IO.do_DMS_out_5 := FALSE; // Out5.Busy (Revision Or Home_Move)
GDB.Unit.IO.do_DMS_out_6 := FALSE; // Out6.Complete : AGV_Wait_Node_Arrive
GDB.Unit.IO.do_DMS_out_7 := FALSE; // Out7.Light_Curtain_Mutting
GDB.Unit.IO.do_DMS_out_8 := FALSE; // Out8.Error (Turret Or Port In)

//PIO_Direction_Set

//GDB.Auto.PIO.PIO_Direction_1L_2R




//Step_Set
IF TRUE THEN
    //Step_Active
    IF 		GDB.Mode.Auto //Error시에 표시를 위해,,
		(*AND	GDB.auto.Main.Step <> 0*) THEN
        GDB.auto.PIO.Active := TRUE;
    ELSE
        GDB.auto.PIO.Active := FALSE;
    END_IF;
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto.PIO.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto.PIO.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto.PIO.Active = FALSE THEN
        GDB.auto.PIO.Step := 0;
    END_IF;    
(*	//Step_Initialize
	IF GDB.auto.PIO.Step >= 2 AND GDB.auto.PIO.Step <= 10 AND (GDB.Command.Command_Type <> 1 OR GDB.Command.Command_Type <> 2) THEN //Loading,Unloading 		
		GDB.auto.PIO.Step := 1;
	END_IF;
*)	
END_IF;

Angle_Calcuration[1](in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
					in_X1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].X,
					in_Y1_Start:= GDB_Retain.Node[GDB.Command.Dest_Node].Y,
					in_X2_End:= GDB.Monitor.Current_X, 
					in_Y2_End:= GDB.Monitor.Current_Y);
Angle_Calcuration[2](in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
					in_X1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].X,
					in_Y1_Start:= GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node].Y,
					in_X2_End:= GDB.Monitor.Current_X, 
					in_Y2_End:= GDB.Monitor.Current_Y);

    //Step_1_PIO_Wait
	IF GDB.auto.PIO.Step = 1 THEN
		//Complete		>>> 크랩 이동 중에, (현재노드 또는 진행노드)가 대기노드일 경우 다음 스텝으로 이동
       	IF 		GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2
			AND	GDB.Auto._3_Move.Crab_Direction_1L_2R <> 0
			AND ( 	GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4 
					OR GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 4)					
			AND Angle_Calcuration[1].out_2_TwoPoint_Distance_mm < 3000 THEN					
	        GDB.auto.PIO.Step := 2;						
			Direction_Buffer := GDB.Auto._3_Move.Crab_Direction_1L_2R;
       	END_IF;
	END_IF;	
    //Step_2_STOP AND (Loading or Unloading) Request Wait
	IF GDB.auto.PIO.Step = 2 THEN
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting						
		//Complete
       	IF 	GDB.Unit.IO.di_DMS_Left_GO
			AND ((GDB.Command.Command_Type = 1 AND GDB.Unit.IO.di_DMS_in_2) // in2.Unloading_Request
				OR 	(GDB.Command.Command_Type = 2 AND GDB.Unit.IO.di_DMS_in_1)) // in1.Loading_Request
			AND GDB.Unit.IO.di_DMS_in_5 = FALSE //in5.Light_Curtain_Mutting_Ack
			THEN       	   
	        GDB.auto.PIO.Step := 3;						
       	END_IF;
	END_IF;	
	//Step_3_Move_Inside_Port_or_Turret
	IF GDB.auto.PIO.Step = 3 THEN
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete			
		IF GDB.Auto._3_Move.Step = 99 THEN			
			GDB.auto.PIO.Step := 4;
		END_IF
	END_IF;
	//Step_4_Loading_or_Unloading_Ready_Wait
	IF GDB.auto.PIO.Step = 4 THEN
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete			
		IF GDB.Unit.IO.di_DMS_in_3 = TRUE THEN	// in3.Ready	
			IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
			GDB.auto.PIO.Step := 10;
			ELSIF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 THEN
			GDB.auto.PIO.Step := 20;			
			END_IF;
		END_IF;
	END_IF;
	//Step_10_Loading or Unloading (Turret)
	IF GDB.auto.PIO.Step = 10 THEN		
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy (Revision Or Home_Move)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete
		IF GDB.Auto._1_Loading.Step = 11 OR GDB.Auto._2_Unloading.Step = 11 THEN
			GDB.auto.PIO.Step := 11;
		END_IF;	
	END_IF;
	//Step_11_Loading or Unloading Complete Wait(Turret)
	IF GDB.auto.PIO.Step = 11 THEN		
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_4 := TRUE; // Out4.Turret : Request(Chuck/Unchuck) , Port : Lift_Move(Up/Down)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete
		IF GDB.Unit.IO.di_DMS_in_6 = TRUE THEN // in6.Complete
			GDB.auto.PIO.Step := 30;
		END_IF;	
	END_IF;
	//Step_20_Loading or Unloading (Port)
	IF GDB.auto.PIO.Step = 20 THEN
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy (Revision Or Home_Move)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete
		IF GDB.Auto._1_Loading.Step = 99 OR GDB.Auto._2_Unloading.Step = 99 THEN
			GDB.auto.PIO.Step := 21;
		END_IF;	
	END_IF;
	//Step_21_Loading or Unloading Complete Wait(Port)
	IF GDB.auto.PIO.Step = 21 THEN
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_4 := TRUE; // Out4.Turret : Request(Chuck/Unchuck) , Port : Lift_Move(Up/Down)
		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy (Revision Or Home_Move)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete
		IF GDB.Unit.IO.di_DMS_in_6 = TRUE THEN
			GDB.auto.PIO.Step := 30;
		END_IF;	
	END_IF;
	//Step_30_Move_Wait_Node
	IF GDB.auto.PIO.Step = 30 THEN		
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy (Revision Or Home_Move)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		//Complete
		IF GDB_Retain.Node[GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 4 THEN					
			GDB.auto.PIO.Step := 31;
		END_IF;	
	END_IF;	
		//Step_31_STOP AND (Loading or Unloading) Request Wait
	IF GDB.auto.PIO.Step = 31 THEN		
		//Direction_Select
		IF Direction_Buffer = 1 THEN			
			GDB.Unit.IO.do_DMS_Left_Select := TRUE;
		ELSIF Direction_Buffer = 2 THEN
			GDB.Unit.IO.do_DMS_Right_Select := TRUE;
		END_IF;
		//Signal_Out
		GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5.Busy (Revision Or Home_Move)
		GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7.Light_Curtain_Mutting
		IF GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4 OR Angle_Calcuration[2].out_2_TwoPoint_Distance_mm < 500 THEN
			GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1.Interface ON
			GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2.Turret Or Port In
			GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3.Turret Or Port In
			GDB.Unit.IO.do_DMS_out_6 := TRUE; // Out6.Complete : AGV_Wait_Node_Arrive			
		END_IF;
		//Complete
		IF GDB.Unit.IO.di_DMS_in_5 = TRUE THEN // in5.Light_Curtain_Mutting_Ack							
			GDB.auto.PIO.Step := 1;
		END_IF;	
	END_IF;	

==================================================
Auto_PIO_1_1

PROGRAM Auto_PIO_1_1
VAR
	PN_Pulse	:ARRAY[0..3] OF PN_Pulse;
	TON	:ARRAY[0..3] OF TON;
	TOF	:ARRAY[0..1] OF TOF;
	Angle_Calcuration	:ARRAY[0..1] OF Angle_Calcuration;
	Loop_Index : INT;

	// PIO 통신 중 비정상 종료 감시 모드
	PIO_Abnormal_Monitor_Mode : BOOL;
	PIO_Abnormal_Signal : BOOL;

	PIO_Err_STEP : INT;
	STEP_TON : ARRAY[0..50] OF TON;
	PIO_Loading : BOOL;
	Pio_Unloading : BOOL;




	test22 : BOOL;
	test23 : BOOL;
	test24 : BOOL;
	test25 : BOOL;
	test26 : BOOL; //적재물온
	test27 : BOOL;//적재물오프
END_VAR
(* OUT *)
// Out1. Valid									>>>대기노드 또는 이적재노드인 경우,
// Out2. CS0 									>>>Out1과 동일
// Out3. CS1 									>>> Not_Use
// Out4. Transfer Request						>>>완료노드에서 
// Out5. Busy 									>>>대기노드 또는 이적재노드인 경우,
// Out6. Complete						 		>>>완료노드일 때 Complete신호 들어오는 경우,
// Out7. LC_Mutting 							>>>Out_1과 동일
// Out8. Interlock 								>>>대기노드 또는 이적재노드에서 에러난 경우,
(* IN *)
// in1.Loading_Request
// in2.Unloading_Request
// in3.Ready
// in4.Busy
// in5.Light_Curtain_Mutting_Ack
// in6.Complete
// in7.-
// in8.Error


//initialize
GDB.Auto.PIO.PIO_Ignore_Bit := FALSE;
GDB.Auto.PIO.PIO_Move_Pause_Bit := FALSE;
GDB.Unit.IO.do_DMS_Left_Select := TRUE;
GDB.Unit.IO.do_DMS_Right_Select := TRUE;
IF GDB.Error.Error_Code = 0 THEN
	PIO_Err_STEP := 0;
END_IF
//Distance_Curr_PIOnode
Angle_Calcuration[1](in_2_TwoPoint_Distance_Calculation_Bit:= GDB.Auto.PIO.PIO_Dest_Node <> 0, 
					in_X1_Start:= GDB.Monitor.Current_X, 
					in_Y1_Start:= GDB.Monitor.Current_Y, 
					in_X2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Dest_Node].X, 
					in_Y2_End:= GDB_Retain.Node[GDB.Auto.PIO.PIO_Dest_Node].Y);
//PIO_Ignore
IF		(GDB.Mode.Auto = TRUE AND GDB.Touch.S25_PIO_Ignore)
	OR 	(GDB.Mode.Semi_Auto AND GDB.Touch.S25_PIO_Ignore) 
	OR 	GDB.Auto.PIO.PIO_Timeout_Bit THEN
   //  OR GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 2 THEN
	GDB.Auto.PIO.PIO_Ignore_Bit := TRUE;
END_IF;

//PIO_Direction_Set
	//Move 중일 때,
IF 				GDB.Auto.PIO.PIO_Direction_1L_2R = 0 //현재 PIO하고 있지 않은 경우,
			AND	GDB.Auto.Main.Docking_Node_in_3000mm AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4 //
			AND GDB.Unit.IO.di_DMS_in_6 = FALSE THEN // in6_Complete 가 아닐 때,	(OUT 아닐 때)					      				
			GDB.Auto.PIO.PIO_Direction_1L_2R := GDB.Auto.Main.Crab_Direction_1L_2R;
			GDB.Auto.PIO.PIO_Dest_Node := GDB.Command.Dest_Node;
END_IF;

	//Clear			
PN_Pulse[1](in_Type:=2, in_Signal:=GDB.Unit.IO.di_DMS_in_6); //DMS_in6_Complete Down_Pulse
IF  		(GDB.Command.Dest_Node <> GDB.Auto.PIO.PIO_Dest_Node AND GDB.Unit.IO.di_DMS_in_6 = FALSE
			AND Angle_Calcuration[1].out_2_TwoPoint_Distance_mm > 1200) //정상 완료하지 않고 다른노드로 가는경우,
			OR (PN_Pulse[1].out_Pulse AND GDB.Unit.IO.di_DMS_in_5 = TRUE) //in_Complete신호가 Down Pulse일 때,
			OR TON[1].Q //Out_Complete 신호가 타이머 지났을 때, 
			//OR GDB.Unit.IO.di_DMS_in_5 = TRUE //-라이트커튼 on되었을떄추가
			OR (GDB.Mode.Active = FALSE AND GDB.Error.Error_Code = 0)
			OR GDB.Auto.PIO.PIO_Ignore_Bit //Ignore Bit가 On일 때,
			OR 	GDB.Auto.PIO.PIO_Timeout_Bit THEN //TimeOut 일 때,
			GDB.Auto.PIO.PIO_Direction_1L_2R := 0;		
			GDB.Auto.PIO.PIO_Dest_Node := 0;	
			 GDB.Auto.PIO.Step := 0; 
END_IF;


//DMS Direction_Select
IF GDB.Auto.PIO.PIO_Direction_1L_2R = 1 THEN
	GDB.Unit.IO.do_DMS_Left_Select := FALSE;
ELSIF GDB.Auto.PIO.PIO_Direction_1L_2R = 2 THEN
	GDB.Unit.IO.do_DMS_Right_Select := FALSE;
END_IF;



IF GDB.Auto.PIO.Step = 0 THEN
	GDB.Unit.IO.do_DMS_out_1 := FALSE; // Out1. Valid
	GDB.Unit.IO.do_DMS_out_2 := FALSE; // Out2. CS0 	
	GDB.Unit.IO.do_DMS_out_3 := FALSE; // Out3. CS1 		
	GDB.Unit.IO.do_DMS_out_4 := FALSE; // Out4. Transfer Request	
	GDB.Unit.IO.do_DMS_out_5 := FALSE; // Out5. Busy 
	GDB.Unit.IO.do_DMS_out_6 := FALSE; // Out6. Complete			
	GDB.Unit.IO.do_DMS_out_7 := FALSE; // Out7. LC_Mutting 
	GDB.Unit.IO.do_DMS_out_8 := FALSE; // Out8. Interlock 	
	PIO_Loading := FALSE;
	Pio_Unloading := FALSE;
	FOR Loop_Index := 1 TO 25 BY 1 DO
	STEP_TON[Loop_Index](IN := FALSE);
	END_FOR; 
END_IF

IF GDB.Auto.PIO.PIO_Direction_1L_2R <> 0 AND GDB.Error.Error_Code = 0 AND GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4 AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE = 2 THEN
	IF GDB.Unit.IO.di_Product_Detect = TRUE THEN
		PIO_Unloading := TRUE;
	ELSIF GDB.Unit.IO.di_Product_Detect = FALSE THEN
		PIO_Loading := TRUE;
	END_IF
	GDB.Auto.PIO.Step := 1;
END_IF

IF GDB.Auto.PIO.Step = 1 THEN  // 진입 요청 LC_Mutting요청
	GDB.Unit.IO.do_DMS_out_1 := TRUE; // Out1. Valid 
	GDB.Unit.IO.do_DMS_out_7 := TRUE; // Out7. LC_Mutting
	IF GDB.Unit.IO.do_DMS_out_1 = TRUE AND GDB.Unit.IO.do_DMS_out_7 = TRUE THEN 
		GDB.Auto.PIO.Step := 2;
	END_IF
END_IF

IF GDB.Auto.PIO.Step = 2 THEN //뮤팅 대기
	IF  GDB.Unit.IO.di_DMS_in_5 = FALSE  THEN 
		GDB.Auto.PIO.Step := 3;
	END_IF
END_IF

IF GDB.Auto.PIO.Step = 3 THEN  // 터렛 진입 허가
	IF GDB.Unit.IO.di_DMS_in_1 = TRUE  AND GDB.Unit.IO.di_Product_Detect = TRUE THEN
		GDB.Auto.PIO.Step := 4;
		STEP_TON[1](IN:= //GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);		  
	ELSIF STEP_TON[1].Q AND PIO_UnLoading = TRUE THEN
		PIO_Err_STEP := 3;
		GDB.Auto.PIO.Step := 0;
	END_IF
	IF  GDB.Unit.IO.di_DMS_in_2 = TRUE AND GDB.Unit.IO.di_Product_Detect = FALSE THEN
		GDB.Auto.PIO.Step := 4;
		STEP_TON[2](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 //GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);		  
	ELSIF STEP_TON[2].Q AND PIO_loading = TRUE THEN
		PIO_Err_STEP := 3;
		GDB.Auto.PIO.Step := 0;
	END_IF
END_IF

IF GDB.Auto.PIO.Step = 4 THEN //이동중
	IF GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2 AND GDB.Unit.Drive.TravelControl.Status_Running_Bit = FALSE THEN
		GDB.Auto.PIO.Step := 5;
	END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[3](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[3].Q THEN
				PIO_Err_STEP := 4;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[4](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[4].Q THEN
				PIO_Err_STEP := 4;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF	
END_IF

IF GDB.Auto.PIO.Step = 5 THEN //도착
		GDB.Unit.IO.do_DMS_out_2 := TRUE; // Out2. CS0 	
		GDB.Unit.IO.do_DMS_out_3 := TRUE; // Out3. CS1
		IF GDB.Unit.IO.do_DMS_out_2 = TRUE AND GDB.Unit.IO.do_DMS_out_3 = TRUE THEN
		GDB.Auto.PIO.Step := 6;
		END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[5](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[5].Q THEN
				PIO_Err_STEP := 5;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[6](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[6].Q THEN
				PIO_Err_STEP := 5;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
END_IF

IF GDB.Auto.PIO.Step = 6 THEN  //터렛,포트 이적재 준비 완료 대기----------------------------------------------------------------터렛,포트 스텝 나눠지는부분
	IF GDB.Unit.IO.di_DMS_in_3 = TRUE THEN  //in.3 READY
		IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
		GDB.Auto.PIO.Step := 7;
		ELSIF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 THEN
		GDB.Auto.PIO.Step := 50;
		END_IF
	END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[7](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 //GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[7].Q THEN
				PIO_Err_STEP := 6;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[8](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						// GDB.Unit.IO.di_DMS_in_3 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[8].Q THEN
				PIO_Err_STEP := 6;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
END_IF

IF GDB.Auto.PIO.Step = 7 THEN  // 터렛보정 작업 시작
	IF (GDB.Auto._1_Loading.Step >= 3 AND GDB.Auto._1_Loading.Step <= 9) OR 
	(GDB.Auto._1_Loading.Step >= 105 AND GDB.Auto._1_Loading.Step <= 109) OR
		GDB.Auto._2_Unloading.Step = 3 OR GDB.Auto._2_Unloading.Step = 5 THEN
 		GDB.Unit.IO.do_DMS_out_5 := TRUE; // Out5. Busy 
		IF GDB.Auto._1_Loading.Step = 109 OR GDB.Auto._2_Unloading.Step = 5 THEN
 		GDB.Auto.PIO.Step := 8;
		END_IF
	END_IF
	IF  PIO_Loading = TRUE THEN
		STEP_TON[9](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[9].Q THEN
				PIO_Err_STEP := 7;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[10](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[10].Q THEN
				PIO_Err_STEP := 7;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
END_IF

IF GDB.Auto.PIO.Step = 8 THEN //처킹 신호 요청
	IF (GDB.Auto._1_Loading.Step = 11 OR GDB.Auto._2_Unloading.Step = 11) THEN
		GDB.Unit.IO.do_DMS_out_4 := TRUE; // Out4. Transfer Request
		GDB.Unit.IO.do_DMS_out_5 := FALSE; // Out5. Busy 
			IF GDB.Unit.IO.di_DMS_in_4 = TRUE THEN  // In.4 Busy
			GDB.Auto.PIO.Step := 9; 
			END_IF
	END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[11](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						// GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[11].Q THEN
				PIO_Err_STEP := 8;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[12](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						// GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[12].Q THEN
				PIO_Err_STEP := 8;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
END_IF

IF GDB.Auto.PIO.Step = 9 THEN //처킹 동작 완료 Busy off,complete 수신대기
	IF GDB.Unit.IO.di_DMS_in_4 = FALSE AND GDB.Unit.IO.di_DMS_in_6 = TRUE THEN // in4.Busy
		GDB.Auto.PIO.Step := 10;
	END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[13](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						// GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						 //GDB.Unit.IO.di_DMS_in_6 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_7 = TRUE , PT := T#500MS);	
			IF STEP_TON[13].Q THEN
				PIO_Err_STEP := 8;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
		IF  PIO_UnLoading = TRUE THEN
		STEP_TON[14](IN:= GDB.Unit.IO.di_DMS_in_1 = FALSE OR 
						 GDB.Unit.IO.di_DMS_in_2 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						// GDB.Unit.IO.di_DMS_in_4 = TRUE OR
						 GDB.Unit.IO.di_DMS_in_5 = TRUE OR
						// GDB.Unit.IO.di_DMS_in_6 = TRUE OR
