			IF STEP_TON[23].Q THEN
				PIO_Err_STEP := 52;
				GDB.Auto.PIO.Step := 0;
			END_IF
		END_IF
END_IF

IF GDB.Auto.PIO.Step = 53 THEN		// 포트 컴플릿 대기-> 12번 으로
	IF  GDB.Unit.IO.di_DMS_in_6 = TRUE THEN// in6.Complete
		GDB.Auto.PIO.Step := 11;
	END_IF
		IF  PIO_Loading = TRUE THEN
		STEP_TON[24](IN:= GDB.Unit.IO.di_DMS_in_1 = TRUE OR 
						 GDB.Unit.IO.di_DMS_in_2 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_3 = FALSE OR
						 GDB.Unit.IO.di_DMS_in_4 = TRUE OR
