END_IF




IF GDB.Error.Error_Code <> 0 OR (GDB.Auto.PIO.Step <> 0 AND GDB.Mode.Manual = TRUE) THEN
	GDB.Unit.IO.do_DMS_out_8 := TRUE; // Out8.Interlock		
END_IF

//Move_Pause
	//IN		
IF  (GDB.Unit.IO.di_DMS_in_5 = TRUE OR GDB.Auto.PIO.Step = 2 OR GDB.Auto.PIO.Step = 3) 
	AND GDB.Command.Dest_Node <> 0
	AND	GDB.Command.Dest_Node = GDB.Auto.PIO.PIO_Dest_Node
	AND		((GDB.Unit.IO.di_Product_Detect = TRUE AND GDB.Unit.IO.di_DMS_in_1 = FALSE AND GDB.Auto.PIO.Step <> 1 )  OR
		  (GDB.Unit.IO.di_Product_Detect = FALSE  AND GDB.Unit.IO.di_DMS_in_2 = FALSE AND GDB.Auto.PIO.Step <> 1))

	AND	  GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4
THEN
	GDB.Auto.PIO.PIO_Move_Pause_Bit := TRUE;	
END_IF;




	//OUT
TOF[1](IN:= GDB.Unit.IO.do_DMS_out_6, PT:=T#100MS);	
IF TOF[1].Q THEN
	GDB.Auto.PIO.PIO_Move_Pause_Bit := TRUE;
