Auto_Ready

PROGRAM Auto_Ready
VAR

nTargetNode : INT;

PN_Pulse	:ARRAY[0..2] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Loop_Index	:INT;
Auto_Wheel_Ready_Run : Auto_Wheel_Ready_Run_2;
Auto_Wheel_Move : Auto_Wheel_Move_Line;
//Step_7
Step_7_Direction_Angle : REAL;

END_VAR


//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := GDB.auto.Ready.Active);
    IF PN_Pulse[1].out_Pulse THEN
        GDB.auto.Ready.Step := 1;
    END_IF;
    //Step_Clear
    IF GDB.auto.Ready.Active = FALSE THEN
        GDB.auto.Ready.Step := 0;
    END_IF;

END_IF;

GDB.Auto.Ready.Step_7_EPC_Data_X_Offset := 0; 
GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset := 0;
IF TRUE THEN
	IF 	
		(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction <> 0)	
		AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)
		AND (GDB.auto.Ready.Step = 5 OR GDB.auto.Ready.Step = 7)  THEN

			IF ((GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction = 1) 
				AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)) THEN	// Arriving 신호 시 EPC Data 수신을 위한 Program 수정  22.07.31

				GDB.Auto.Ready.Step_7_EPC_Data_X_Offset := GDB.Auto.Ready.Step_7_EPC_Data_X_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;//- ACS_Part.EPC_TEST;
				GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset := GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset;	

			ELSIF ((GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction = 2) 
				AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)) THEN	// Arriving 신호 시 EPC Data 수신을 위한 Program 수정  22.07.31

				GDB.Auto.Ready.Step_7_EPC_Data_X_Offset := GDB.Auto.Ready.Step_7_EPC_Data_X_Offset;
				GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset := GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset - GDB.Auto._3_Move.Step_7_EPC_Data;// - ACS_Part.EPC_TEST;	

			ELSIF ((GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction = 3)
				AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)) THEN	// Arriving 신호 시 EPC Data 수신을 위한 Program 수정  22.07.31

				GDB.Auto.Ready.Step_7_EPC_Data_X_Offset := GDB.Auto.Ready.Step_7_EPC_Data_X_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;// + ACS_Part.EPC_TEST;
				GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset := GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset;

			ELSIF ((GDB_Retain.Node[GDB_Retain.Current_Node].Turret_EPC_Direction = 4) 
				AND (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 1000.0)) THEN	// Arriving 신호 시 EPC Data 수신을 위한 Program 수정  22.07.31

				GDB.Auto.Ready.Step_7_EPC_Data_X_Offset := GDB.Auto.Ready.Step_7_EPC_Data_X_Offset;
				GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset := GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset + GDB.Auto._3_Move.Step_7_EPC_Data;// + ACS_Part.EPC_TEST;

			END_IF;
	END_IF;
END_IF;

//Initialize


//Step_Start
//Step_1 : Current_State Check
IF GDB.auto.Ready.Step = 1 AND (GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 1 OR GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 3 OR GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 4)  THEN
	nTargetNode := GDB_Retain.Current_Node;
	IF 			ABS(GDB.Monitor.Current_Y_Shift_Pos) < 1.0
			AND ABS(GDB.Monitor.Current_Theta_Pos) < 1.0
			AND ABS(GDB.Monitor.Current_Tilting_Pos) < 1.0 THEN
			GDB.Auto.Ready.Step := 3;
	ELSE	
			GDB.Auto.Ready.Step := 2;	
	END_IF;
ELSIF  GDB.auto.Ready.Step = 1 THEN
	GDB.Auto.Ready.Step := 99;
END_IF;	

//Step_2 : LIFT_Move
IF GDB.auto.Ready.Step = 2 THEN
	GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 50;
	IF 	ABS(GDB.Monitor.Current_Lift_Pos - GDB.Unit.Drive.Move_Data.Target_Pos_Lift) < 1.0	 THEN
				GDB.Auto.Ready.Step := 3;
	END_IF;		
END_IF;	



//Step_3 : Upper_Home
IF GDB.auto.Ready.Step = 3 THEN
	GDB.Unit.Drive.Move_Data.Target_Pos_Lift := 0;
	GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift := 0;			
	GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift := 0;
	GDB.Unit.Drive.Move_Data.Target_Pos_Theta := 0;
	GDB.Unit.Drive.Move_Data.Target_Pos_Tilting := 0;
	GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi := 0;	
	IF		ABS(GDB.Monitor.Current_Lift_Pos) < 1.0
		AND ABS(GDB.Monitor.Current_X_Shift_Pos) < 1.0
		AND	ABS(GDB.Monitor.Current_Y_Shift_Pos) < 1.0
		AND ABS(GDB.Monitor.Current_Theta_Pos) < 1.0
		AND ABS(GDB.Monitor.Current_Tilting_Pos) < 1.0
		AND ABS(GDB.Monitor.Current_Y_Navi_Pos) < 1.0 THEN
		IF 	GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 3 OR ( 	ABS(GDB_Retain.Node[GDB_Retain.Current_Node].X - GDB.Monitor.Current_X) < 50
			AND ABS(GDB_Retain.Node[nTargetNode].Y - GDB.Monitor.Current_Y) < 50 ) THEN
			GDB.Auto.Ready.Step := 99;
		ELSE	
			GDB.Auto.Ready.Step := 5;
		END_IF;	
	END_IF;
END_IF;

//Step_5 : Wheel_Ready_Run
IF GDB.Auto.Ready.Step = 5 THEN
	Auto_Wheel_Ready_Run(	in_Enable:= TRUE, 
							in_Work_Type:= 1, 
							in_Turn:= 0, 
							in_Start_X:= GDB.monitor.Current_X, 
							in_Start_Y:= GDB.monitor.Current_Y, 
							in_End_X:= GDB_Retain.Node[nTargetNode].X - GDB.Auto.Ready.Step_7_EPC_Data_X_Offset,   // 2022.08.17 반자동 모드 및 자기 위치 찾아 갈때도 작업지 전 노드에서는 EPC 먹도록 설정
							in_End_Y:= GDB_Retain.Node[nTargetNode].Y - GDB.Auto.Ready.Step_7_EPC_Data_Y_Offset, 
							in_Current_AGV_Angle:= GDB.monitor.Current_AGV_Angle, 
							in_FW_Wheel_Angle:= GDB.monitor.Current_FW_Wheel_Angle, 
							in_BW_Wheel_Angle:= GDB.monitor.Current_BW_Wheel_Angle, 
							out_Target_FW_Wheel_Angle=> GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle, 
							out_Target_BW_Wheel_Angle=> GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle);
	IF 	    ABS(GDB.Unit.Drive.Move_Data._2_Steering_FW_Wheel_Target_Angle-GDB.monitor.Current_FW_Wheel_Angle) < 1.0
        AND ABS(GDB.Unit.Drive.Move_Data._2_Steering_BW_Wheel_Target_Angle-GDB.monitor.Current_BW_Wheel_Angle) < 1.0 THEN
		GDB.Auto.Ready.Step := 7;								
	END_IF;						
END_IF;

//Step_7 : Current_Node_Move
PN_Pulse[2](in_Type:= 1, in_Signal:= GDB.Auto.Ready.Step = 7);
IF PN_Pulse[2].out_Pulse THEN
	Step_7_Direction_Angle := GDB.monitor.Current_AGV_Angle;
END_IF;
IF GDB.Auto.Ready.Step = 7 THEN
Auto_Wheel_Move(	in_Enable:= TRUE, 
					in_StartSet_Renew:= PN_Pulse[2].out_Pulse, 
					in_Current_X_mm:= GDB.monitor.Current_X, 
					in_Current_Y_mm:= GDB.monitor.Current_Y, 
					in_End_X:= GDB_Retain.Node[nTargetNode].X - GDB.Auto.Ready.Step_7_EPC_Data_X_Offset,    // 2022.08.17 반자동 모드 및 자기 위치 찾아 갈때도 작업지 전 노드에서는 EPC 먹도록 설정
