FUNCTION_BLOCK Angle_Calcuration

VAR_INPUT
in_1_TwoPoint_Angle_Calculation_Bit			:BOOL;
in_2_TwoPoint_Distance_Calculation_Bit		:BOOL;
in_X1_Start									:REAL;
in_Y1_Start									:REAL;
in_X2_End									:REAL;
in_Y2_End									:REAL;
in_3_Angle_SUB_bit							:BOOL;
in_SUB_1_1									:REAL;
in_SUB_1_2									:REAL;
in_SUB_2_1									:REAL;
in_SUB_2_2									:REAL;
in_SUB_3_1									:REAL;
in_SUB_3_2									:REAL;
in_SUB_4_1									:REAL;
in_SUB_4_2									:REAL;
in_4_AngleRangeSet_us360_Bit				:BOOL;
in_Angle									:REAL;
END_VAR


VAR_OUTPUT
out_1_Theta_us360							:REAL;
out_2_TwoPoint_Distance_mm					:REAL;
out_3_SUB1_s180								:REAL;
out_3_SUB1_us180							:REAL;
out_3_SUB2_s180								:REAL;
out_3_SUB2_us180							:REAL;
out_3_SUB3_s180								:REAL;
out_3_SUB3_us180							:REAL;
out_3_SUB4_s180								:REAL;
out_3_SUB4_us180							:REAL;
out_4_Angle_us360							:REAL;
END_VAR

VAR
Theta_Buffer								:REAL;
SUB1_Buffer_s180							:REAL;
SUB1_Buffer_us180							:REAL;
SUB2_Buffer_s180							:REAL;
SUB2_Buffer_us180							:REAL;
SUB3_Buffer_s180							:REAL;
SUB3_Buffer_us180							:REAL;
SUB4_Buffer_s180							:REAL;
SUB4_Buffer_us180							:REAL;
Angle_Range_Set_Buffer						:REAL;
END_VAR


//Initialize
out_1_Theta_us360 := 0;
out_2_TwoPoint_Distance_mm := 0;
out_3_SUB1_s180 := 0;
out_3_SUB1_us180 := 0;
out_3_SUB2_s180 := 0;
out_3_SUB2_us180 := 0;
out_3_SUB3_s180 := 0;
out_3_SUB3_us180 := 0;
out_3_SUB4_s180 := 0;
out_3_SUB4_us180 := 0;
out_4_Angle_us360 := 0;

 Theta_Buffer := 0;
 SUB1_Buffer_s180 := 0;
 SUB1_Buffer_us180 := 0;



(* 1_TwoPoint_Angle_Calculation *)
IF  in_1_TwoPoint_Angle_Calculation_Bit THEN
        //END X좌표 - Start X좌표 <> 0 인 경우(atan 사용가능)
    IF ( in_X2_End -  in_X1_Start) <> 0 THEN
         Theta_Buffer := 57.2958 * ATAN(( in_Y2_End -  in_Y1_Start) / ( in_X2_End -  in_X1_Start));
        IF ( in_X2_End -  in_X1_Start) < 0 THEN //X2-X1<0 인 경우 +180
             Theta_Buffer :=  Theta_Buffer + 180;
        END_IF;
        //End X좌표 - Start X좌표 = 0 인 경우(atan 사용불가)    
    ELSIF ( in_X2_End -  in_X1_Start) = 0 THEN
        IF  in_Y2_End >  in_Y1_Start THEN
             Theta_Buffer := 90;
        ELSIF  in_Y2_End <  in_Y1_Start THEN
             Theta_Buffer := 270;
        ELSE
             Theta_Buffer := 0;
        END_IF;
    END_IF;
        //Theta 0~360범위를 벗어날 시에, 보정
    IF  Theta_Buffer >= 360 THEN
         Theta_Buffer :=  Theta_Buffer - 360;
    ELSIF  Theta_Buffer < 0 THEN
         Theta_Buffer :=  Theta_Buffer + 360;
    END_IF;

     out_1_Theta_us360 :=  Theta_Buffer;
END_IF;

(* in_2_TwoPoint_Distance_Calculation *)
IF  in_2_TwoPoint_Distance_Calculation_Bit THEN
     out_2_TwoPoint_Distance_mm := SQRT((( in_X2_End -  in_X1_Start) * ( in_X2_End -  in_X1_Start))
                                           + (( in_Y2_End -  in_Y1_Start) * ( in_Y2_End -  in_Y1_Start)));
END_IF;

(* 3_Angle_SUB_Calculation *)
IF  in_3_Angle_SUB_bit THEN
    //SUB1
     SUB1_Buffer_s180 :=  in_SUB_1_1 -  in_SUB_1_2;
    IF  SUB1_Buffer_s180 > 180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 - 360;
    ELSIF  SUB1_Buffer_s180 <= -180 THEN
         SUB1_Buffer_s180 :=  SUB1_Buffer_s180 + 360;
    END_IF;
     SUB1_Buffer_us180 := ABS( SUB1_Buffer_s180);

     out_3_SUB1_s180 :=  SUB1_Buffer_s180;
     out_3_SUB1_us180 :=  SUB1_Buffer_us180;

    //SUB2
     SUB2_Buffer_s180 :=  in_SUB_2_1 -  in_SUB_2_2;
    IF  SUB2_Buffer_s180 > 180 THEN
         SUB2_Buffer_s180 :=  SUB2_Buffer_s180 - 360;
    ELSIF  SUB2_Buffer_s180 <= -180 THEN
         SUB2_Buffer_s180 :=  SUB2_Buffer_s180 + 360;
    END_IF;
     SUB2_Buffer_us180 := ABS( SUB2_Buffer_s180);

     out_3_SUB2_s180 :=  SUB2_Buffer_s180;
     out_3_SUB2_us180 :=  SUB2_Buffer_us180;

    //SUB3
     SUB3_Buffer_s180 :=  in_SUB_3_1 -  in_SUB_3_2;
    IF  SUB3_Buffer_s180 > 180 THEN
         SUB3_Buffer_s180 :=  SUB3_Buffer_s180 - 360;
    ELSIF  SUB3_Buffer_s180 <= -180 THEN
         SUB3_Buffer_s180 :=  SUB3_Buffer_s180 + 360;
    END_IF;
     SUB3_Buffer_us180 := ABS( SUB3_Buffer_s180);

     out_3_SUB3_s180 :=  SUB3_Buffer_s180;
     out_3_SUB3_us180 :=  SUB3_Buffer_us180;

    //SUB4
     SUB4_Buffer_s180 :=  in_SUB_4_1 -  in_SUB_4_2;
    IF  SUB4_Buffer_s180 > 180 THEN
         SUB4_Buffer_s180 :=  SUB4_Buffer_s180 - 360;
    ELSIF  SUB4_Buffer_s180 <= -180 THEN
         SUB4_Buffer_s180 :=  SUB4_Buffer_s180 + 360;
    END_IF;
     SUB4_Buffer_us180 := ABS( SUB4_Buffer_s180);

     out_3_SUB4_s180 :=  SUB4_Buffer_s180;
     out_3_SUB4_us180 :=  SUB4_Buffer_us180;

END_IF;

(* 4_Angle Range Set(0~360) *)
IF  in_4_AngleRangeSet_us360_Bit THEN
     Angle_Range_Set_Buffer :=  in_Angle;
    IF  Angle_Range_Set_Buffer >= 360 THEN
         Angle_Range_Set_Buffer :=  Angle_Range_Set_Buffer - 360;
    ELSIF  Angle_Range_Set_Buffer < 0 THEN
         Angle_Range_Set_Buffer :=  Angle_Range_Set_Buffer + 360;
    END_IF;
     out_4_Angle_us360 :=  Angle_Range_Set_Buffer;
END_IF;


