Auto_Lift_Load_Backup

FUNCTION_BLOCK Auto_Lift_Load_Backup
VAR_INPUT
	Enable : BOOL;
	Renew : BOOL;
	in_Loadcell_Value_kg : REAL;
	in_Turret_Weight_kg : REAL;
	in_Current_Speed_mps : REAL;		
	in_Motor_Current : BYTE;
	in_Actual_Lift_Pos : REAL;

END_VAR
VAR_OUTPUT
	out_Load_Complete : BOOL;
	out_Load_kg	:	REAL;
	out_Load_Count : INT;
	out_Lift_Direction : INT;
END_VAR
VAR
	Load_Count : INT;
	Load_Buffer : REAL;
	Lift_Direction_Buffer : INT;
	Pre_Loadcell_Value_kg : REAL;
	Start_Lift_Pos : REAL;
	Down_Bit : BOOL;
	Actual_Lift_Pos_Buffer_1 : REAL;
	Actual_Lift_Pos_Buffer_2 : REAL;
END_VAR


out_Load_Complete := 0;
out_Load_kg	:=	0;
out_Lift_Direction := 0;


IF Enable THEN
	IF Renew THEN
		Load_Count := 0;
		Load_Buffer := 0;
		Pre_Loadcell_Value_kg := 0;
		Down_Bit := 0;
	END_IF



	//Load_Buffer Measurement
	IF 	in_Loadcell_Value_kg > 10.0
	AND	in_Motor_Current > 1.0
	AND in_Current_Speed_mps <> 0
	AND	ABS(in_Loadcell_Value_kg - Pre_Loadcell_Value_kg) < 3.0 
	AND Load_Buffer = 0
	AND in_Loadcell_Value_kg > in_Turret_Weight_kg
	THEN		
		Load_Count := Load_Count + 1;		
		IF Load_Count > 50 THEN // Load 유지 Count
			Load_Buffer := Pre_Loadcell_Value_kg - in_Turret_Weight_kg;
//			Load_Buffer := in_Loadcell_Value_kg;
			Actual_Lift_Pos_Buffer_1 := in_Actual_Lift_Pos;
		END_IF		
	ELSE
		Load_Count := 0;
	END_IF




	//Down Bit Set		
	IF (Load_Buffer <> 0) AND (in_Loadcell_Value_kg - (Load_Buffer+in_Turret_Weight_kg)) > 5.0 THEN
		Down_Bit := 1;
		Actual_Lift_Pos_Buffer_2 := in_Actual_Lift_Pos;
	END_IF	

	//out_Lift_Direction Set
	IF out_Load_Complete = FALSE THEN
	IF Down_Bit = FALSE 
	OR (Down_Bit = TRUE AND (Load_Buffer - in_Loadcell_Value_kg > 5.0 ))
	THEN
		out_Lift_Direction := 1;
	ELSIF (Down_Bit = TRUE AND (in_Loadcell_Value_kg - Load_Buffer > 5.0 )) THEN
		out_Lift_Direction := 2;
	END_IF
	IF Down_Bit = TRUE AND (ABS(in_Loadcell_Value_kg - Load_Buffer)) <= 5.0 THEN
		out_Lift_Direction := 0;		
	END_IF
	END_IF
	//out_Load_Complete
	IF out_Lift_Direction = 0 AND (ABS(in_Loadcell_Value_kg - Load_Buffer)) <= 10.0 THEN
		out_Load_Complete := TRUE;

	END_IF;
	out_Load_Count := Load_Count;
	out_Load_kg := Load_Buffer;
	IF Load_Count = 0 THEN
	Pre_Loadcell_Value_kg := in_Loadcell_Value_kg;
	END_IF	
END_IF

