Auto_Turret_Angle_Revision

FUNCTION_BLOCK Auto_Turret_Angle_Revision
VAR_INPUT
	in_Enable : BOOL;
	//Before은 터렛 각도가 0도 일 때,
	in_Chuck_X_Pos_Before : REAL; // 중심에서 Chuck의 X 좌표
	in_Chuck_Y_Pos_Before : REAL; // 중심에서 Chuck의 Y 좌표		
	in_Reflector_X_Pos_Before : REAL; // 중심에서 Reflector의 X 좌표
	in_Reflector_Y_Pos_Before : REAL; // 중심에서 Reflector의 Y 좌표
	in_Y_Pos_Gap : REAL; //After-Before(좌표계 기준 위쪽으로 이동 시 +) ㅡ 터렛을 보고 섰을 때,사람 발쪽으로 갈수록 +
END_VAR
VAR_OUTPUT
	out_Turret_Angle_Gap : REAL;	//좌표계 기준
	out_Move_X_Pos : REAL;	//좌표계 기준
	out_Move_Y_Pos : REAL;	//좌표계 기준
END_VAR
VAR	
	va_Turret_Angle_Gap : REAL;
	//Reflector
	va_Reflector_Angle_Calcuration : Angle_Calcuration;
	va_Center_Reflector_Distance : REAL;
	va_Reflector_Angle_Before : REAL;
	va_Reflector_Angle_After : REAL;	
	va_Reflector_X_Pos_After : REAL;
	va_Reflector_Y_Pos_After : REAL;
	//Chuck
	va_Chuck_Angle_Calcuration : Angle_Calcuration;
	va_Center_Chuck_Distance  : REAL;
	va_Chuck_Angle_Before : REAL;
	va_Chuck_Angle_After : REAL;
	va_Chuck_X_Pos_After : REAL;
	va_Chuck_Y_Pos_After : REAL;
	//Virtual_Fork_Point
	va_Virtual_Fork_X_Pos : REAL;
	va_Virtual_Fork_Y_Pos : REAL;
END_VAR


	// *모든 값은 180도 뒤집어서 본 것을 기준으로 한다.
	out_Turret_Angle_Gap := 0;
	out_Move_X_Pos := 0;
	out_Move_Y_Pos := 0;
IF 		in_Enable 
	AND ( in_Chuck_X_Pos_Before <> 0 OR in_Chuck_Y_Pos_Before <> 0)
	AND ( in_Reflector_X_Pos_Before <> 0 OR in_Reflector_Y_Pos_Before <> 0) THEN
	// 1. Reflector 
	va_Reflector_Angle_Calcuration(
	in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
	in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
	in_X1_Start:= 0.0, 
	in_Y1_Start:= 0.0, 
	in_X2_End:= in_Reflector_X_Pos_Before, 
	in_Y2_End:= in_Reflector_Y_Pos_Before, 
	out_1_Theta_us360=> va_Reflector_Angle_Before , 																				//va_Reflector_Angle_Before
	out_2_TwoPoint_Distance_mm=> va_Center_Reflector_Distance );																	//va_Center_Reflector_Distance
	va_Reflector_Angle_After := (180/PI) * ASIN( (in_Reflector_Y_Pos_Before + in_Y_Pos_Gap) / va_Center_Reflector_Distance );		//va_Reflector_Angle_After
	va_Reflector_X_Pos_After := va_Center_Reflector_Distance * COS(va_Reflector_Angle_After * (PI/180) );							//va_Reflector_X_Pos_After
	va_Reflector_Y_Pos_After := va_Center_Reflector_Distance * SIN(va_Reflector_Angle_After * (PI/180) );							//va_Reflector_Y_Pos_After

	//Turret_Angle_Gap
	va_Turret_Angle_Gap := va_Reflector_Angle_After - va_Reflector_Angle_Before; // + 방향이 아래방향									//va_Turret_Angle_Gap : 터렛이 기운 각도

	// 2. Chuck		 
	va_Chuck_Angle_Calcuration(
	in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
	in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
	in_X1_Start:= 0.0, 
	in_Y1_Start:= 0.0, 
	in_X2_End:= in_Chuck_X_Pos_Before, 
	in_Y2_End:= in_Chuck_Y_Pos_Before, 
	out_1_Theta_us360=> va_Chuck_Angle_Before , 																					//va_Chuck_Angle_Before 
	out_2_TwoPoint_Distance_mm=> va_Center_Chuck_Distance );																		//va_Center_Chuck_Distance
	va_Chuck_Angle_After := va_Chuck_Angle_Before + va_Turret_Angle_Gap;	 														//va_Chuck_Angle_After
	va_Chuck_X_Pos_After := va_Center_Chuck_Distance * COS(va_Chuck_Angle_After * (PI/180) );										//va_Chuck_X_Pos_After
	va_Chuck_Y_Pos_After := va_Center_Chuck_Distance * SIN(va_Chuck_Angle_After * (PI/180) );										//va_Chuck_Y_Pos_After

	// 3. Virtual Fork Point
	va_Virtual_Fork_X_Pos := va_Reflector_X_Pos_After - (in_Reflector_X_Pos_Before - in_Chuck_X_Pos_Before);						//va_Virtual_Fork_X_Pos : 실제로 도킹 위치에 갔을 때, 포크의 X 좌표
	va_Virtual_Fork_Y_Pos := va_Reflector_Y_Pos_After - (in_Reflector_Y_Pos_Before - in_Chuck_Y_Pos_Before);						//va_Virtual_Fork_Y_Pos : 실제로 도킹 위치에 갔을 때, 포크의 Y 좌표

	// 4. Out_Chuck_Move_Pos
	out_Turret_Angle_Gap := va_Turret_Angle_Gap;																					//out_Turret_Angle_Gap
	out_Move_X_Pos := va_Chuck_X_Pos_After - va_Virtual_Fork_X_Pos;															//out_Chuck_Move_X_Pos
	out_Move_Y_Pos := va_Chuck_Y_Pos_After - va_Virtual_Fork_Y_Pos;															//out_Chuck_Move_Y_Pos

END_IF


