		      		OR ( in_Link_ID[in_Data_List[Loop_Index]].Work_Type = 6 AND  in_Link_ID[in_Data_List[Loop_Index+1]].Work_Type = 5)
		        	OR ( in_Link_ID[in_Data_List[Loop_Index]].Work_Type = 6 AND  in_Link_ID[in_Data_List[Loop_Index+1]].Work_Type = 6))
				AND Distance_Extend_Bit = FALSE								
				AND 	(((Next_Angle_Buffer/90)+1 = in_Link_ID[in_Data_List[Loop_Index+1]].Direction/10) 
					OR	((Next_Angle_Buffer/90)+1 = in_Link_ID[in_Data_List[Loop_Index+1]].Direction MOD 10)) 
    		THEN
    		     out_1_Travel_Target_Extend_Pos_mm :=  out_1_Travel_Target_Extend_Pos_mm +  in_Link_ID[in_Data_List[Loop_Index+1]].Distance;
    		ELSE
    		     Distance_Extend_Bit := TRUE;
    		END_IF;
			IF (( in_Link_ID[in_Data_List[Loop_Index]].Work_Type = 1 AND  in_Link_ID[in_Data_List[Loop_Index+1]].Work_Type = 1) 
				OR ( in_Link_ID[in_Data_List[Loop_Index]].Work_Type = 2 AND  in_Link_ID[in_Data_List[Loop_Index+1]].Work_Type = 2))
				AND Linear_Line_Extend_Bit = FALSE THEN
				out_1_Travel_LinearLine_Extend_mm := out_1_Travel_LinearLine_Extend_mm + in_Link_ID[in_Data_List[Loop_Index+1]].Distance;
			ELSE
				Linear_Line_Extend_Bit := TRUE;
			END_IF;
		out_1_Travel_Target_Pos_Total_mm := out_1_Travel_Target_Pos_Total_mm + 	in_Link_ID[in_Data_List[Loop_Index+1]].Distance;
		Loop_Index := Loop_Index + 1;
	END_WHILE;
	out_1_Travel_Target_Extend_Pos_mm := out_1_Travel_Target_Extend_Pos_mm + out_1_Travel_Target_Pos_mm;
	out_1_Travel_Target_Pos_Total_mm := out_1_Travel_Target_Pos_Total_mm + out_1_Travel_Target_Pos_mm;
	out_1_Travel_LinearLine_Extend_mm := out_1_Travel_LinearLine_Extend_mm + out_1_Travel_Target_Pos_mm;

	IF    ( out_1_Travel_LinearLine_Extend_mm -  out_1_Travel_Actual_Pos_mm < 2000) THEN         
		out_1_Travel_Decel_Bit := TRUE;
    ELSE
         out_1_Travel_Decel_Bit := FALSE;
    END_IF;	



	IF in_Extend_Permission_Bit = FALSE THEN
		out_1_Travel_Target_Extend_Pos_mm := out_1_Travel_Target_Pos_mm;
	END_IF;	
    IF ( out_1_Travel_Target_Extend_Pos_mm >  out_1_Travel_Target_Pos_mm)
        AND ( out_1_Travel_Actual_Pos_mm >  out_1_Travel_Target_Pos_mm)
    THEN
		out_Current_Node := in_Link_ID[in_Data_List[in_Command_Current_Number]].End_Node;
        out_Command_Current_Number := in_Command_Current_Number + 1;		 
    ELSE		
		out_Current_Node := in_Current_Node;
        out_Command_Current_Number := in_Command_Current_Number;		 
    END_IF;


         out_1_Travel_Max_Speed_mpm :=  in_Link_ID[in_Data_List[in_Command_Current_Number]].Speed_mpm;


    IF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 1 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 2 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 3 THEN 

        IF  SUB_TargetProgress_CurrentProgress_us180 <= 90 THEN
             Buffer_Target_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
        ELSIF  SUB_TargetProgress_CurrentProgress_us180 > 90 THEN
             Buffer_Target_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
        END_IF;
         Angle_Calcuration[11](in_4_AngleRangeSet_us360_Bit := TRUE,
                               in_Angle :=  Buffer_Target_Wheel_Angle,
                               out_4_Angle_us360 =>  Buffer_Target_Wheel_Angle);
         out_2_Steering_FW_Wheel_Target_Angle :=  Buffer_Target_Wheel_Angle; 
         out_2_Steering_BW_Wheel_Target_Angle :=  Buffer_Target_Wheel_Angle; 

        IF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 3 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 300 THEN
             out_2_Steering_FW_Wheel_Target_Angle := 180; 
             out_2_Steering_BW_Wheel_Target_Angle := 180; 
             out_2_Error_Value_mm := 0;
        END_IF;

    ELSIF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 5 THEN 
         Buffer_Target_Wheel_Angle := ABS(((180 / 3.141593) * (ASIN(( in_Distance_FwWheel_BwWheel_mm * 3.141593 / 4) / (2.0 * 3.141593 *  CircleEquation_R / 4)))));
        IF  SUB_TargetProgress_StartSetCurrentProgress_s180 > 0 THEN
             Buffer_Target_Wheel_Angle :=  Buffer_Target_Wheel_Angle * -1;
        ELSIF  SUB_TargetProgress_StartSetCurrentProgress_s180 < 0 THEN
             Buffer_Target_Wheel_Angle :=  Buffer_Target_Wheel_Angle * +1;
        END_IF;

        IF  Type_FW_0_BW_1_Bit = 0 THEN
             Buffer_Current_AGV_Angle :=  in_Current_AGV_Angle;

        ELSIF  Type_FW_0_BW_1_Bit = 1 THEN
             Buffer_Current_AGV_Angle :=  in_Current_AGV_Angle + 180;
        END_IF;
         Angle_Calcuration[12](in_4_AngleRangeSet_us360_Bit := TRUE,
                               in_Angle :=  Buffer_Current_AGV_Angle,
                               out_4_Angle_us360 =>  Buffer_Current_AGV_Angle);
         Angle_Calcuration[13](in_3_Angle_SUB_bit := TRUE,
                               in_SUB_1_1 :=  Buffer_Current_AGV_Angle,
                               in_SUB_1_2 :=  CircleEquation_X2_Y2_Slope_us360,
                               out_3_SUB1_s180 =>  SUB_CurrentAGVangle_X2Y2Slope_s180);
        IF  Type_FW_0_BW_1_Bit = 0 THEN
             Buffer_Target_Wheel_Angle :=  Buffer_Target_Wheel_Angle +  SUB_CurrentAGVangle_X2Y2Slope_s180;

        ELSIF  Type_FW_0_BW_1_Bit = 1 THEN
             Buffer_Target_Wheel_Angle :=  Buffer_Target_Wheel_Angle -  SUB_CurrentAGVangle_X2Y2Slope_s180;
        END_IF;


         out_2_Steering_FW_Wheel_Target_Angle := 180 +  Buffer_Target_Wheel_Angle; 
         out_2_Steering_BW_Wheel_Target_Angle := 180 -  Buffer_Target_Wheel_Angle; 


        IF  in_Link_ID[in_Data_List[in_Command_Current_Number+1]].Work_Type <> 0 
			AND NOT(  in_Link_ID[in_Data_List[in_Command_Current_Number]].Turn =  in_Link_ID[in_Data_List[in_Command_Current_Number+1]].Turn
					AND in_Link_ID[in_Data_List[in_Command_Current_Number]].FB = FALSE	
					AND in_Link_ID[in_Data_List[in_Command_Current_Number+1]].FB = FALSE ) THEN
            IF  CircleEquation_R <= 550 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 400 THEN
                 out_2_Steering_FW_Wheel_Target_Angle := 180; 
                 out_2_Steering_BW_Wheel_Target_Angle := 180; 
                 out_2_Error_Value_mm := 0;
            ELSIF  CircleEquation_R <= 650 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 320 THEN
                 out_2_Steering_FW_Wheel_Target_Angle := 180; 
                 out_2_Steering_BW_Wheel_Target_Angle := 180; 
                 out_2_Error_Value_mm := 0;
            ELSIF  CircleEquation_R <= 750 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 250 THEN
                 out_2_Steering_FW_Wheel_Target_Angle := 180; 
                 out_2_Steering_BW_Wheel_Target_Angle := 180; 
                 out_2_Error_Value_mm := 0;
            ELSIF  CircleEquation_R <= 1200 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 160 THEN
                 out_2_Steering_FW_Wheel_Target_Angle := 180; 
                 out_2_Steering_BW_Wheel_Target_Angle := 180; 
                 out_2_Error_Value_mm := 0;
            ELSIF  CircleEquation_R > 1200 AND  out_1_Travel_Target_Pos_mm -  out_1_Travel_Actual_Pos_mm < 160 THEN //160
                 out_2_Steering_FW_Wheel_Target_Angle := 180; 
                 out_2_Steering_BW_Wheel_Target_Angle := 180; 
                 out_2_Error_Value_mm := 0;


            END_IF;

        END_IF;
    ELSIF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 6 THEN 
        IF  SUB_TargetProgress_CurrentProgress_us180 <= 90 THEN
             Buffer_Target_Wheel_Angle := ( in_Current_AGV_Angle -  CircleEquation_X2_Y2_Slope_us360) + 180;

        ELSIF  SUB_TargetProgress_CurrentProgress_us180 > 90 THEN
             Buffer_Target_Wheel_Angle := ( in_Current_AGV_Angle -  CircleEquation_X2_Y2_Slope_us360 - 180) + 180;
        END_IF;
         Angle_Calcuration[14](in_4_AngleRangeSet_us360_Bit := TRUE,
                               in_Angle :=  Buffer_Target_Wheel_Angle,
                               out_4_Angle_us360 =>  Buffer_Target_Wheel_Angle);
         out_2_Steering_FW_Wheel_Target_Angle :=  Buffer_Target_Wheel_Angle; 
         out_2_Steering_BW_Wheel_Target_Angle :=  Buffer_Target_Wheel_Angle; 
    END_IF;


    IF ( in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 5 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 6) AND  Type_Turn_Start_Bit = 0 THEN
        IF  Type_Wheelangle_90_180_270 = 1 THEN
             out_2_Steering_FW_Wheel_Target_Angle := 90;
             out_2_Steering_BW_Wheel_Target_Angle := 90;
        ELSIF  Type_Wheelangle_90_180_270 = 2 THEN
             out_2_Steering_FW_Wheel_Target_Angle := 180;
             out_2_Steering_BW_Wheel_Target_Angle := 180;
        ELSIF  Type_Wheelangle_90_180_270 = 3 THEN
             out_2_Steering_FW_Wheel_Target_Angle := 270;
             out_2_Steering_BW_Wheel_Target_Angle := 270;
        END_IF;
         out_2_Error_Value_mm := 0;
    END_IF;





    IF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 1 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 2 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 3 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 6 THEN
         out_3_AGV_Revision_Angle_s180 :=  SUB_TargetProgress_ErrorValueProgress_us180; 
        IF 45 <  SUB_TargetProgress_AGVangle_s180 AND  SUB_TargetProgress_AGVangle_s180 < 135 THEN
             out_3_AGV_Revision_Direction_S1E4 := 1;
        ELSIF -135 <  SUB_TargetProgress_AGVangle_s180 AND  SUB_TargetProgress_AGVangle_s180 < -45 THEN
             out_3_AGV_Revision_Direction_S1E4 := 2;
        ELSIF -45 <  SUB_TargetProgress_AGVangle_s180 AND  SUB_TargetProgress_AGVangle_s180 < 45 THEN
             out_3_AGV_Revision_Direction_S1E4 := 3;
        ELSIF (135 <  SUB_TargetProgress_AGVangle_s180 OR  SUB_TargetProgress_AGVangle_s180 < -135) THEN
             out_3_AGV_Revision_Direction_S1E4 := 4;
        ELSE
             out_3_AGV_Revision_Direction_S1E4 := 0;
        END_IF;
    ELSE
         out_3_AGV_Revision_Direction_S1E4 := 0;
    END_IF;

	IF in_Current_Wheel_Angle_Hold_Bit THEN
		out_2_Steering_FW_Wheel_Target_Angle := in_FW_Wheel_Angle;
		out_2_Steering_BW_Wheel_Target_Angle := in_BW_Wheel_Angle;
		out_2_Error_Value_mm := 0;
	END_IF

     out_Error_Code := 0;
    IF  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 5 OR  in_Link_ID[in_Data_List[in_Command_Current_Number]].Work_Type = 6 THEN
        IF  Type_AGVangle_0_90_180_270 = 0 THEN
             out_Error_Code := 1;
        ELSIF  Type_Wheelangle_90_180_270 = 0 THEN
             out_Error_Code := 2;
        ELSIF  Type_TargetProgress_45_135_225_315 = 0 THEN
             out_Error_Code := 3;
		ELSIF CircleEquation_A = 0 AND CircleEquation_B = 0 THEN
	 		 out_Error_Code := 4;
        END_IF;

    END_IF;










END_IF;

