Auto Wheel Ready Run

FUNCTION_BLOCK Auto_Wheel_Ready_Run  
VAR_INPUT
in_Enable	:BOOL;
in_Work_Type	:INT;
in_Turn			:INT;
in_Start_X	:REAL;
in_Start_Y	:REAL;
in_End_X	:REAL;
in_End_Y	:REAL;
in_Current_AGV_Angle	:REAL;
in_FW_Wheel_Angle	:REAL;
in_BW_Wheel_Angle	:REAL;

END_VAR
VAR_OUTPUT
	out_Target_FW_Wheel_Angle					:REAL;
	out_Target_BW_Wheel_Angle					:REAL;
	out_Travel_Direction_0F1B					:BOOL;
	out_Turn_Error_Bit							:BOOL;
	out_CrabTurn_Error_Bit						:BOOL;
END_VAR
VAR
	Progress_Target_us360						:REAL;
	Progress_Current_us360						:REAL;
	SUB_TargetProgress_AGVAngle_s180			:REAL;
	SUB_TargetProgress_CurrentProgress_s180		:REAL;
	SUB_TargetProgress_AGVAngle_us180			:REAL;
	SUB_TargetProgress_CurrentProgress_us180	:REAL;
END_VAR


IF  in_Enable = 1 THEN 
    IF  in_Work_Type = 1 OR  in_Work_Type = 2 OR  in_Work_Type = 3 THEN
        IF ( in_End_X -  in_Start_X) <> 0 THEN
             Progress_Target_us360 := 57.2958 * ATAN(( in_End_Y -  in_Start_Y) / ( in_End_X -  in_Start_X));
            IF ( in_End_X -  in_Start_X) < 0 THEN 
                 Progress_Target_us360 :=  Progress_Target_us360 + 180;
            END_IF;
        ELSIF ( in_End_X -  in_Start_X) = 0 THEN
            IF  in_End_Y >  in_Start_Y THEN
                 Progress_Target_us360 := 90;
            END_IF;

            IF  in_End_Y <  in_Start_Y THEN
                 Progress_Target_us360 := 270;
            END_IF;

        END_IF;
        IF  Progress_Target_us360 >= 360 THEN
             Progress_Target_us360 :=  Progress_Target_us360 - 360;
        ELSIF  Progress_Target_us360 < 0 THEN
             Progress_Target_us360 :=  Progress_Target_us360 + 360;
        END_IF;


         Progress_Current_us360 :=  in_Current_AGV_Angle - ((( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2) - 180);

        IF  Progress_Current_us360 >= 360 THEN
             Progress_Current_us360 :=  Progress_Current_us360 - 360;
        ELSIF  Progress_Current_us360 < 0 THEN
             Progress_Current_us360 :=  Progress_Current_us360 + 360;
        END_IF;
         SUB_TargetProgress_AGVAngle_s180 :=  Progress_Target_us360 -  in_Current_AGV_Angle;
        IF  SUB_TargetProgress_AGVAngle_s180 > 180 THEN
             SUB_TargetProgress_AGVAngle_s180 :=  SUB_TargetProgress_AGVAngle_s180 - 360;
        ELSIF  SUB_TargetProgress_AGVAngle_s180 <= -180 THEN
             SUB_TargetProgress_AGVAngle_s180 :=  SUB_TargetProgress_AGVAngle_s180 + 360;
        END_IF;
         SUB_TargetProgress_AGVAngle_us180 := ABS( SUB_TargetProgress_AGVAngle_s180);
         SUB_TargetProgress_CurrentProgress_s180 :=  Progress_Target_us360 -  Progress_Current_us360;
        IF  SUB_TargetProgress_CurrentProgress_s180 > 180 THEN
             SUB_TargetProgress_CurrentProgress_s180 :=  SUB_TargetProgress_CurrentProgress_s180 - 360;
        ELSIF  SUB_TargetProgress_CurrentProgress_s180 <= -180 THEN
             SUB_TargetProgress_CurrentProgress_s180 :=  SUB_TargetProgress_CurrentProgress_s180 + 360;
        END_IF;
         SUB_TargetProgress_CurrentProgress_us180 := ABS( SUB_TargetProgress_CurrentProgress_s180);
        IF  SUB_TargetProgress_AGVAngle_us180 > 95 THEN
             out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
             out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
             out_Travel_Direction_0F1B := 1; 
        ELSIF  SUB_TargetProgress_AGVAngle_us180 < 85 THEN
             out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
             out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
             out_Travel_Direction_0F1B := 0; 

        ELSE
            IF  SUB_TargetProgress_CurrentProgress_us180 <= 90 THEN 
                 out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
                 out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360) + 180;
                 out_Travel_Direction_0F1B := 0;
            END_IF;

            IF  SUB_TargetProgress_CurrentProgress_us180 > 90 THEN 
                 out_Target_FW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
                 out_Target_BW_Wheel_Angle := ( in_Current_AGV_Angle -  Progress_Target_us360 - 180) + 180;
                 out_Travel_Direction_0F1B := 1;
            END_IF;


        END_IF;


        IF  out_Target_FW_Wheel_Angle >= 360 THEN
             out_Target_FW_Wheel_Angle :=  out_Target_FW_Wheel_Angle - 360;
        ELSIF  out_Target_FW_Wheel_Angle < 0 THEN
             out_Target_FW_Wheel_Angle :=  out_Target_FW_Wheel_Angle + 360;
        END_IF;

        IF  out_Target_BW_Wheel_Angle >= 360 THEN
             out_Target_BW_Wheel_Angle :=  out_Target_BW_Wheel_Angle - 360;
        ELSIF  out_Target_BW_Wheel_Angle < 0 THEN
             out_Target_BW_Wheel_Angle :=  out_Target_BW_Wheel_Angle + 360;
        END_IF;

    ELSIF  in_Work_Type = 5 THEN
         out_Target_FW_Wheel_Angle := 180;
         out_Target_BW_Wheel_Angle := 180;



//	ELSIF  in_Work_Type = 6 THEN
//        IF 75 < ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 AND ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 < 100 THEN
//             out_Target_FW_Wheel_Angle := 90;
//             out_Target_BW_Wheel_Angle := 90;
//        ELSIF 170 < ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 AND ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 < 190 THEN
//             out_Target_FW_Wheel_Angle := 180;
//             out_Target_BW_Wheel_Angle := 180;
//        ELSIF 260 < ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 AND ( in_FW_Wheel_Angle +  in_BW_Wheel_Angle) / 2 < 280 THEN
//             out_Target_FW_Wheel_Angle := 270;
//             out_Target_BW_Wheel_Angle := 270;
//        ELSE
//             out_CrabTurn_Error_Bit := 1;
//        END_IF;
//    END_IF;
///////////Auto_Wheel_Ready_Run///////////////////////////////////////////////////////////////////////////////////
      ELSIF  in_Work_Type = 2 OR in_Work_Type = 6 THEN
        IF in_Turn = 5 THEN
             out_Target_FW_Wheel_Angle := 90;
             out_Target_BW_Wheel_Angle := 90;
        ELSIF in_Turn = 6 THEN
             out_Target_FW_Wheel_Angle := 180;
             out_Target_BW_Wheel_Angle := 180;
        ELSIF in_Turn = 7 THEN
             out_Target_FW_Wheel_Angle := 270;
             out_Target_BW_Wheel_Angle := 270;
        ELSE
             out_Turn_Error_Bit := 1;
        END_IF;
    END_IF;
 /////////////////////////////////////////////////////////////////////////////////////////////////////////////////   
END_IF;

==================================================
Data Conversion

FUNCTION_BLOCK Data_Conversion
VAR_INPUT
in_Enable	:BOOL;
in_Start_Bit	:BOOL;
in_Add_Bit	:BOOL;
in_Command_Type	:INT;
in_Dest_Node	:INT;
in_SpinTurn_Target_Angle : REAL;
in_Data	:ARRAY[0..1000] OF INT;
in_Current_Node : INT;
END_VAR
VAR_OUTPUT
out_Complete	:BOOL;
out_Command_Type	:INT;
out_Dest_Node	:INT;
out_SpinTurn_Target_Angle : REAL;
out_Data	:ARRAY[0..1000] OF INT;
out_Error_In_Data_Fault	:INT;
out_Error_Dest_Node_Data_Fault	:INT;
out_Error_Node_Data_Fault	:INT;
out_Error_No_adjoin_Node	:INT;

END_VAR
VAR

Loop_Index_1	:INT;
Loop_Index_2	:INT;
va_Data	:ARRAY[0..1000] OF INT;
va_Pre_Data	:ARRAY[0..1000] OF INT;
va_Pre_Command_Type	:INT;
va_Pre_Dest_Node	:INT;
va_va_Data_End_Number	:INT;
va_in_Data_Add_Start_Number	:INT;

END_VAR


 va_in_Data_Add_Start_Number := 1;

 out_Complete := FALSE;
 out_Error_In_Data_Fault := 0;
 out_Error_Dest_Node_Data_Fault := 0;
 out_Error_No_adjoin_Node := 0;
 out_Error_Node_Data_Fault := 0;
FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
     va_Data[ Loop_Index_1] := 0;
END_FOR;



IF  in_Enable THEN

    IF  in_Start_Bit = 1 THEN 
        IF 	   (in_Command_Type = 1 )
				OR (in_Command_Type = 2  )
				OR  in_Command_Type = 3 THEN
            IF  GDB_Retain.Node[ in_Dest_Node]._Type = 0
                OR GDB_Retain.Node[ in_Dest_Node].X = 0
                OR GDB_Retain.Node[ in_Dest_Node].Y = 0 THEN
                 out_Error_Dest_Node_Data_Fault := 1;
            END_IF;
            IF  in_Data[1] = 0 AND in_Current_Node <> in_Dest_Node THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;
            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                    IF  in_Data[ Loop_Index_1] = 0 THEN
                        EXIT;
                    END_IF;
                    IF GDB_Retain.Node[ in_Data[ Loop_Index_1]].X = 0
                        OR GDB_Retain.Node[ in_Data[ Loop_Index_1]].Y = 0
                        OR GDB_Retain.Node[ in_Data[ Loop_Index_1]]._Type = 0
                    THEN
                         out_Error_Node_Data_Fault :=  Loop_Index_1;
                        EXIT;
                    END_IF;

                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[(( in_Data[ Loop_Index_1-1] * 10) +  Loop_Index_2)].End_Node =  in_Data[ Loop_Index_1] THEN
                             va_Data[ Loop_Index_1] := (( in_Data[ Loop_Index_1-1] * 10) +  Loop_Index_2);
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ Loop_Index_1] = 0 THEN
                             out_Error_No_adjoin_Node :=  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
            END_FOR;
            IF   out_Error_In_Data_Fault = 0
                    AND  out_Error_Dest_Node_Data_Fault = 0
                    AND  out_Error_Node_Data_Fault = 0
                    AND  out_Error_No_adjoin_Node = 0 THEN					
                     out_Command_Type := in_Command_Type;
                     out_Dest_Node :=  in_Dest_Node;
					 out_SpinTurn_Target_Angle := 0;
                    FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
                         out_Data[ Loop_Index_1] :=  va_Data[ Loop_Index_1];
                    END_FOR;
                     out_Complete := TRUE;
            END_IF;

        ELSIF  in_Command_Type = 4 THEN 
            IF  in_Dest_Node = 0
                OR GDB_Retain.Node[ in_Dest_Node]._Type <> 3
                OR GDB_Retain.Node[ in_Dest_Node].X = 0
                OR GDB_Retain.Node[ in_Dest_Node].Y = 0 THEN
                 out_Error_Dest_Node_Data_Fault := 1;
            END_IF;
            IF  out_Error_Dest_Node_Data_Fault = 0 THEN
                out_Command_Type := 4;
                out_Dest_Node :=  in_Dest_Node;         
                 out_Complete := TRUE;
            END_IF;

        ELSIF  in_Command_Type = 5 THEN 
            IF  in_SpinTurn_Target_Angle < 0 OR  in_SpinTurn_Target_Angle >= 360 THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;
            IF  out_Error_In_Data_Fault = 0 THEN
                 out_Command_Type := 5;
                 out_Dest_Node := 0;
				 out_SpinTurn_Target_Angle := in_SpinTurn_Target_Angle;                 				 
                 out_Complete := TRUE;
            END_IF;
        END_IF;


    END_IF;

    IF  in_Add_Bit AND  va_Pre_Command_Type = 3 THEN 

        IF TRUE THEN
            IF  in_Data[1] = 0 THEN
                 out_Error_In_Data_Fault := 1;
            END_IF;

            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                 va_Data[ Loop_Index_1] :=  va_Pre_Data[ Loop_Index_1];
                IF  va_Data[ Loop_Index_1] = 0 THEN
                    EXIT;
                END_IF;
            END_FOR;


            FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
                IF  va_Data[ Loop_Index_1] = 0 THEN
                     va_va_Data_End_Number :=  Loop_Index_1 - 1 ;
                    EXIT;
                END_IF;
            END_FOR;
             Loop_Index_1 := 1;
            WHILE  in_Data[ Loop_Index_1] <> 0 DO
                IF  in_Data[ Loop_Index_1] = GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node THEN
                     va_in_Data_Add_Start_Number :=  Loop_Index_1 + 1;
                    EXIT;
                END_IF;
                IF  va_in_Data_Add_Start_Number <> 1 THEN
                    EXIT;
                END_IF;
                 Loop_Index_1 :=  Loop_Index_1 + 1;
            END_WHILE;
             Loop_Index_1 := 0;
            WHILE  in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1] <> 0 DO

                IF GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]].X = 0
                    OR GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]].Y = 0
                    OR GDB_Retain.Node[ in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1]]._Type = 0
                THEN
                     out_Error_Node_Data_Fault :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                    EXIT;
                END_IF;
                IF  Loop_Index_1 = 0 THEN
                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[((GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node * 10) +  Loop_Index_2)].End_Node =  in_Data[ va_in_Data_Add_Start_Number] THEN
                             va_Data[ va_va_Data_End_Number + 1] := (((GDB_Retain.Link_ID[ va_Data[ va_va_Data_End_Number]].End_Node * 10) +  Loop_Index_2));
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ va_va_Data_End_Number + 1] = 0 THEN
                             out_Error_No_adjoin_Node :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
                ELSE
                    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
                        IF GDB_Retain.Link_ID[(( in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1 - 1] * 10) +  Loop_Index_2)].End_Node =  in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1] THEN
                             va_Data[ va_va_Data_End_Number +  Loop_Index_1 + 1] := (( in_Data[ va_in_Data_Add_Start_Number +  Loop_Index_1 - 1] * 10) +  Loop_Index_2);
                            EXIT;
                        END_IF;
                        IF  Loop_Index_2 = 9 AND  va_Data[ va_va_Data_End_Number +  Loop_Index_1 + 1] = 0 THEN
                             out_Error_No_adjoin_Node :=  va_in_Data_Add_Start_Number +  Loop_Index_1;
                        END_IF;
                    END_FOR;
                    IF  out_Error_No_adjoin_Node <> 0 THEN
                        EXIT;
                    END_IF;
                END_IF;

                 Loop_Index_1 :=  Loop_Index_1 + 1;
            END_WHILE;
            IF  out_Error_In_Data_Fault = 0
                AND  out_Error_Dest_Node_Data_Fault = 0
                AND  out_Error_Node_Data_Fault = 0
                AND  out_Error_No_adjoin_Node = 0
                AND  va_Data[1] <> 0 THEN
                 out_Command_Type :=  in_Command_Type;
                 out_Dest_Node :=  in_Dest_Node;
                FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
                     out_Data[ Loop_Index_1] :=  va_Data[ Loop_Index_1];
                END_FOR;
                 out_Complete := TRUE;
            END_IF;



        END_IF;
    END_IF;

    IF  out_Complete THEN
         va_Pre_Command_Type :=  out_Command_Type;
         va_Pre_Dest_Node :=  out_Dest_Node;
        FOR  Loop_Index_1 := 1 TO 1000 BY 1 DO
             va_Pre_Data[ Loop_Index_1] :=  out_Data[ Loop_Index_1];
            IF  out_Data[ Loop_Index_1] = 0 THEN
                EXIT;
            END_IF;
        END_FOR;
    END_IF;


    END_IF;



==================================================
NAV Average Point

FUNCTION_BLOCK NAV_Average_Point
VAR_INPUT
	in_Enable				: BOOL;
	in_Start 				: BOOL;
	in_NAV_Recieve_Complete : BOOL;
	in_NAV_X 				: REAL;
	in_NAV_Y 				: REAL;
	in_NAV_T 			: REAL;
	in_Count_Number 		: INT; // 1 보다 큰 값.
END_VAR;
VAR_OUTPUT
	out_Complete			: BOOL;
	out_NAV_X				: REAL;
	out_NAV_Y				: REAL;
	out_NAV_T				: REAL;	
END_VAR;
VAR
	START : BOOL;
	COUNT : INT;

	SUM_X : LREAL;
	SUM_Y : LREAL;
	SUM_T : LREAL;


PN_Pulse	:ARRAY[0..1] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
Loop_Index : INT;

END_VAR;


out_Complete		:= FALSE;
IF in_Enable THEN
	PN_Pulse[1](in_Type:=1 , in_Signal:=in_Start);
	IF PN_Pulse[1].out_Pulse THEN
		COUNT 		:= 1;
		SUM_X		:= 0;
		SUM_Y 		:= 0;
		SUM_T 		:= 0;
	END_IF;

	IF in_NAV_Recieve_Complete AND COUNT <= in_Count_Number THEN
		SUM_X 			:= SUM_X + in_NAV_X;
		SUM_Y 			:= SUM_Y + in_NAV_Y;
		SUM_T 			:= SUM_T + in_NAV_T;
		IF COUNT = in_Count_Number THEN
			out_Complete		:= TRUE;
			out_NAV_X 			:= SUM_X / in_Count_Number;
			out_NAV_Y 			:= SUM_Y / in_Count_Number;
			out_NAV_T 			:= SUM_T / in_Count_Number;			
		END_IF;
		COUNT := COUNT + 1; 
	END_IF;
END_IF;	

==================================================
NAV Offset Adjust

FUNCTION_BLOCK NAV_Offset_Adjust
VAR_INPUT
	in_Enable : BOOL;
	in_Start : BOOL;
	in_NAV_Recieve_Complete : BOOL;
	in_Reference_X_Data : REAL;
	in_Reference_Y_Data : REAL;
	in_Reference_T_Data : REAL;
	in_NAV_X_Real_Data : REAL;
	in_NAV_Y_Real_Data : REAL;
	in_NAV_T_Real_Data : REAL;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;	
	out_Data_Error : BOOL;
	out_NAV_X_Offset : REAL;
	out_NAV_Y_Offset : REAL;
	out_NAV_T_Offset : REAL;
END_VAR
VAR	
	PN_Pulse	:ARRAY[0..0] OF PN_Pulse;
	TON	:ARRAY[0..1] OF TON;
	TOF	:ARRAY[0..0] OF TOF;
	Angle_Calcuration : Angle_Calcuration;
	Loop_Index : INT;


	NAV_Average_Point : NAV_Average_Point;	
	DT_Reference_InData : REAL;
	Angle_Reference_Indata : REAL;


END_VAR


//initialize
out_Complete := FALSE;
IF in_Start THEN
	out_Data_Error := FALSE;
END_IF

IF in_Enable THEN
	NAV_Average_Point(	in_Enable:= TRUE, 
						in_Start:= in_Start, 
						in_NAV_Recieve_Complete:= in_NAV_Recieve_Complete, 
						in_NAV_X:= in_NAV_X_Real_Data, 
						in_NAV_Y:= in_NAV_Y_Real_Data, 
						in_NAV_T:= in_NAV_T_Real_Data, 
						in_Count_Number:= 50, 
						out_Complete=> , 
						out_NAV_X=> , 
						out_NAV_Y=> , 
						out_NAV_T=> );	
	IF NAV_Average_Point.out_Complete THEN		 
		Angle_Calcuration(	in_3_Angle_SUB_bit:= TRUE, 
							in_SUB_1_1:= in_Reference_T_Data, 
							in_SUB_1_2:= NAV_Average_Point.out_NAV_T);
		IF 		ABS(in_Reference_X_Data - NAV_Average_Point.out_NAV_X) < 100.0 
			AND ABS(in_Reference_Y_Data - NAV_Average_Point.out_NAV_Y) < 100.0 
			AND Angle_Calcuration.out_3_SUB1_us180 < 10.0 THEN
			//1번째, Reference값에서 In_Data 까지의 거리와 각도를 구한다.
			Angle_Calcuration(	in_1_TwoPoint_Angle_Calculation_Bit:= TRUE,
								in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
								in_X1_Start:= in_Reference_X_Data, 
								in_Y1_Start:= in_Reference_Y_Data, 
								in_X2_End:= NAV_Average_Point.out_NAV_X, 
								in_Y2_End:= NAV_Average_Point.out_NAV_Y, 
								out_1_Theta_us360=> Angle_Reference_Indata, 
								out_2_TwoPoint_Distance_mm=> DT_Reference_InData);
			//2번째, (In_Data의 각도)에서 (Reference값에서 In_Data 까지의 각도)를 뺀다.
					//그럼 Reference의 각도가 0도 기준으로 된다. 여기서는 X값이 Y_Offset 값, Y축이 X_Offset 값이 된다.					
			Angle_Calcuration(	in_3_Angle_SUB_bit:= TRUE, 
								in_SUB_1_1:= Angle_Reference_Indata, 
								in_SUB_1_2:= in_Reference_T_Data);
			//3번째, Reference 값에서 InData까지의 거리와 각도를 통해서 오프셋 값을 구한다.								
			out_NAV_X_Offset := -1 * (DT_Reference_InData * SIN(Angle_Calcuration.out_3_SUB1_s180*(PI/180)));
			out_NAV_Y_Offset := -1 * (DT_Reference_InData * COS(Angle_Calcuration.out_3_SUB1_s180*(PI/180)));					
			Angle_Calcuration(	in_3_Angle_SUB_bit:= TRUE, 
								in_SUB_1_1:= in_NAV_T_Real_Data, 
								in_SUB_1_2:= in_Reference_T_Data);
			out_NAV_T_Offset := Angle_Calcuration.out_3_SUB1_s180;			
			out_Complete := TRUE;																		
		ELSE
			out_Data_Error := TRUE;
		END_IF				
	END_IF;						


END_IF

==================================================
NAV Offset symmetry

FUNCTION_BLOCK NAV_Offset_symmetry
VAR_INPUT
	in_Enable : BOOL;
	in_Start : BOOL;
	in_Reset : BOOL;
	in_NAV_Recieve_Complete : BOOL;
	in_Center_NAV_Distance : REAL;
	in_NAV_X_Real_Data : REAL;
	in_NAV_Y_Real_Data : REAL;
	in_NAV_Angle_Real_Data : REAL;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;	
	out_Step : INT;	
	out_Target_Angle : REAL;
	out_NAV_X_Offset : REAL;
	out_NAV_Y_Offset : REAL;
END_VAR
VAR
	Step : INT;
	NAV_Average_Point : NAV_Average_Point;	
	NAV_X_1 : REAL;
	NAV_Y_1 : REAL;
	NAV_T_1 : REAL;
	NAV_X_2 : REAL;
	NAV_Y_2 : REAL;
	NAV_T_2 : REAL;
	Center_X : REAL;
	Center_Y : REAL;



	PN_Pulse	:ARRAY[0..0] OF PN_Pulse;
	TON	:ARRAY[0..1] OF TON;
	TOF	:ARRAY[0..0] OF TOF;
	Angle_Calcuration : Angle_Calcuration;
	Loop_Index : INT;

END_VAR


// NAV의 X,Y 오프셋을 구하는 프로그램
(* 
1. AGV를 티칭존으로 들어가서 정확하게 맞춘 뒤에, Start 입력.
2. AGV를 180도 돌린 뒤에, 티칭존으로 정확하게 맞춘 뒤에 다시 Start 입력.
	* 처음 각도에서 180도를 틀 때, 0.1도 이내로 들어와야 함.(0.1도 틀어질 때 마다, ([센터에서 나브까지의 거리] * 0.0017453) 만큼 틀어진다. 최대한 정확히 할 것. )
*)
//Initialize
out_Complete := FALSE;
out_NAV_X_Offset := 0;
out_NAV_Y_Offset := 0;
//Enable
IF in_Enable THEN
	IF in_Reset OR Step = 0 THEN //Reset
		Step := 1;
		NAV_X_1 := 0;
		NAV_Y_1 := 0;
		NAV_T_1 := 0;
		NAV_X_2 := 0;
		NAV_Y_2 := 0;
		NAV_T_2 := 0;
		Center_X := 0;
		Center_Y := 0;
		out_Target_Angle := 0;
	END_IF;

	IF Step=1 THEN //Step_1_First_Point_Set
		NAV_Average_Point(in_Enable:= TRUE, 
							in_Start:= in_Start, 
							in_NAV_Recieve_Complete:= in_NAV_Recieve_Complete, 
							in_NAV_X:= in_NAV_X_Real_Data, 
							in_NAV_Y:= in_NAV_Y_Real_Data, 
							in_NAV_T:= in_NAV_Angle_Real_Data, 
							in_Count_Number:= 50, 								
							out_NAV_X=> NAV_X_1, 
							out_NAV_Y=> NAV_Y_1, 
							out_NAV_T=>NAV_T_1);
		IF NAV_Average_Point.out_Complete THEN
			Step := 2;
		END_IF	
	END_IF
	IF Step = 2 THEN //Step_2_Second_Point_Set
		Angle_Calcuration(in_4_AngleRangeSet_us360_Bit:= TRUE, in_Angle:= NAV_T_1 + 180);
		out_Target_Angle := Angle_Calcuration.out_4_Angle_us360;
		NAV_Average_Point(in_Enable:= TRUE, 
							in_Start:= in_Start, 
							in_NAV_Recieve_Complete:= in_NAV_Recieve_Complete, 
							in_NAV_X:= in_NAV_X_Real_Data, 
							in_NAV_Y:= in_NAV_Y_Real_Data, 
							in_NAV_T:= in_NAV_Angle_Real_Data, 
							in_Count_Number:= 50, 								
							out_NAV_X=> NAV_X_2, 
							out_NAV_Y=> NAV_Y_2, 
							out_NAV_T=>NAV_T_2);
		Angle_Calcuration(	in_3_Angle_SUB_bit:= TRUE, 
							in_SUB_1_1:= NAV_T_1, 
							in_SUB_1_2:= NAV_T_2 + 180);					
		IF NAV_Average_Point.out_Complete AND (Angle_Calcuration.out_3_SUB1_us180 <= 0.1) THEN
			Step := 4; //OK
		ELSIF NAV_Average_Point.out_Complete AND (Angle_Calcuration.out_3_SUB1_us180 > 0.1) THEN
			Step := 3; //Fail						
		END_IF	
	END_IF

	TON[1](IN:= Step = 3, PT:= T#3S); //Step_3_Second_Point_Set_Fail
	IF TON[1].Q  THEN 		
		Step := 2;
	END_IF			

	IF Step = 4 THEN	//Step_4_Offset_Set
		//중심점
		Center_X :=	(NAV_X_1 + NAV_X_2)/2;				
		Center_Y := (NAV_Y_1 + NAV_Y_2)/2;					
		//중심점에서 NAV_1 까지의 거리와 각도.
		Angle_Calcuration(	in_1_TwoPoint_Angle_Calculation_Bit:= TRUE, 
								in_2_TwoPoint_Distance_Calculation_Bit:= TRUE, 
								in_X1_Start:= Center_X, 
								in_Y1_Start:= Center_Y, 
								in_X2_End:= NAV_X_1, 
								in_Y2_End:= NAV_Y_1);					
		//OFFSET						
		out_NAV_X_Offset := +1 * (Angle_Calcuration.out_2_TwoPoint_Distance_mm*SIN((NAV_T_1 - Angle_Calcuration.out_1_Theta_us360)*(PI/180)));
		out_NAV_Y_Offset := -1 * (Angle_Calcuration.out_2_TwoPoint_Distance_mm*COS((NAV_T_1 - Angle_Calcuration.out_1_Theta_us360)*(PI/180)) - in_Center_NAV_Distance);
		out_Complete := TRUE;
		Step := 99;		
	END_IF;		
	out_Step := Step;
END_IF;

==================================================
Offline Path Search

FUNCTION_BLOCK Offline_Path_Search
VAR_INPUT
	Renew_Bit	:BOOL;
	in_Start_Node	:INT;
	in_End_Node	:INT;
END_VAR
VAR_OUTPUT
	out_Complete	:BOOL;
out_Path_Count	:INT;
out_Path_Length_mm	:REAL;
out_Path	:ARRAY[0..1000] OF INT;
out_Error_Not_Exist_Node	:BOOL;

END_VAR
VAR	

//Check
Renew_Check_Bit	:BOOL;
//경로 계산 변수
Pass_Node	:ARRAY[0..1000] OF INT; //처리가 완료된 노드의 집합 [배열번호:Pass순서, 배열값:Pass된 노드번호]
Pass_Node_Check	:ARRAY[0..1000] OF BOOL; //처리가 완료된 노드 검색용	[배열번호:노드번호, 배열값:Pass여부]
Cost	:ARRAY[0..1000] OF REAL; //시작점에서 해당 노드까지 가는데 걸리는 비용[배열번호:노드번호, 배열값:비용] _____ [0:Max 고정값]
Before_Node	:ARRAY[0..1000] OF INT; //[배열번호:노드번호, 배열값:이전의 노드]
FB_Loop_Index	:INT;
Loop_Index_0	:INT;
Loop_Index_1	:INT;
Loop_Index_2	:INT;
Loop_Index_3	:INT;
Angle_Calcuration	:Angle_Calcuration;
Cost_Buffer	:REAL;
Lowest_Cost_Node_Buffer	:INT;
Calcuration_Complete	:BOOL;
//배열 정렬 변수
Path_Reverse_Buffer	:ARRAY[0..1000] OF INT;
Path_Buffer	:ARRAY[0..1000] OF INT;
Path_Count	:INT;
Loop_Index_4	:INT;
Loop_Index_5	:INT;
Loop_Index_6	:INT;



END_VAR


 out_Complete := FALSE;
 out_Path_Count := 0;
 out_Path_Length_mm := 0;
 out_Error_Not_Exist_Node := FALSE;
FOR  Loop_Index_0 := 0 TO 1000 BY 1 DO
     out_Path[ Loop_Index_0] := 0;
END_FOR;

IF  Renew_Bit THEN
    FOR  Loop_Index_1 := 0 TO 1000 BY 1 DO
         Pass_Node[ Loop_Index_1] := 0;
         Pass_Node_Check[ Loop_Index_1] := 0;
         Before_Node[ Loop_Index_1] := 0;
         Path_Buffer[ Loop_Index_1] := 0;
         Cost[ Loop_Index_1] := 99999999.0;
    END_FOR;
     Cost[0] :=  Cost[1] + 10000000;
     Calcuration_Complete := FALSE;

     Pass_Node[1] :=  in_Start_Node;
     Cost[ in_Start_Node] := 0;
     Loop_Index_1 := 1;
     Renew_Check_Bit := TRUE;
END_IF;


IF ( Calcuration_Complete = FALSE) AND ( Renew_Bit = FALSE) AND ( Renew_Check_Bit = TRUE) THEN
    FOR FB_Loop_Index := 1 TO 5 BY 1 DO 

     Pass_Node_Check[ Pass_Node[ Loop_Index_1]] := TRUE; 


    FOR  Loop_Index_2 := 1 TO 9 BY 1 DO
        IF GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node <> 0 THEN 
            IF  Pass_Node_Check[GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node] = FALSE THEN

                IF (GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].Distance +  Cost[ Pass_Node[ Loop_Index_1]]) <  Cost[GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node] THEN 
                     Cost[GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node] := (GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].Distance +  Cost[ Pass_Node[ Loop_Index_1]]); 
                     Before_Node[GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node] :=  Pass_Node[ Loop_Index_1]; 
                END_IF;
            END_IF;
        ELSIF GDB_Retain.Link_ID[ Pass_Node[ Loop_Index_1]*10 +  Loop_Index_2].End_Node = 0 THEN 
            EXIT;
        END_IF;
    END_FOR;


     Lowest_Cost_Node_Buffer := 0;  
    FOR  Loop_Index_3 := 1 TO 999 BY 1 DO
        IF  Cost[ Lowest_Cost_Node_Buffer] >  Cost[ Loop_Index_3]
            AND  Pass_Node_Check[ Loop_Index_3] = FALSE
        THEN
             Lowest_Cost_Node_Buffer :=  Loop_Index_3;
        END_IF;
    END_FOR;
    IF  Lowest_Cost_Node_Buffer <> 0 THEN
         Pass_Node[ Loop_Index_1 + 1] :=  Lowest_Cost_Node_Buffer;
         Loop_Index_1 :=  Loop_Index_1 + 1;
    ELSIF  Lowest_Cost_Node_Buffer = 0 THEN
         Calcuration_Complete := 1;
    END_IF;

	END_FOR;
END_IF;

IF  Calcuration_Complete THEN
     Path_Reverse_Buffer[1] :=  in_End_Node;
    FOR  Loop_Index_4 := 1 TO 999 BY 1 DO
         Path_Reverse_Buffer[ Loop_Index_4 + 1] :=  Before_Node[ Path_Reverse_Buffer[ Loop_Index_4]];
        IF  Before_Node[ Path_Reverse_Buffer[ Loop_Index_4]] =  in_Start_Node THEN
             Path_Count :=  Loop_Index_4 + 1;
            EXIT;
        END_IF;
    END_FOR;
    FOR  Loop_Index_5 := 1 TO  Path_Count BY 1 DO
         Path_Buffer[ Loop_Index_5] :=  Path_Reverse_Buffer[ Path_Count -  Loop_Index_5 + 1];
    END_FOR;

    IF  Path_Buffer[1] =  in_Start_Node AND  Path_Buffer[ Path_Count] =  in_End_Node THEN
         out_Complete := TRUE;
         out_Path_Count :=  Path_Count;
         out_Path_Length_mm :=  Cost[ in_End_Node];
        FOR  Loop_Index_6 := 1 TO 1000 BY 1 DO
             out_Path[ Loop_Index_6] :=  Path_Buffer[ Loop_Index_6];
        END_FOR;
    ELSE
         out_Error_Not_Exist_Node := TRUE;
    END_IF;
     Renew_Check_Bit := FALSE;
     Calcuration_Complete := FALSE;
END_IF;

==================================================
PID Control

FUNCTION_BLOCK PID_Control
VAR_INPUT
	in_Enable : BOOL;

	in_Target_Pos : REAL;
	in_Current_Pos : REAL;
	in_Max_Value : REAL;
	in_Min_Value : REAL;
	in_Gain_P : REAL;
	in_Distance_Offset : REAL;
	in_inPosition : REAL;
	(*
	in2_Travel_Bit	: BOOL := FALSE;
	in2_Current_Speed_mpm : REAL;
	in2_Speed_Control_Point : REAL;
	*)
END_VAR
VAR_OUTPUT
	out_Target_Reached : BOOL;
	out_iDirection : INT;
