==================================================
Calculation 1 TwoPoint Angle

FUNCTION Calculation_1_TwoPoint_Angle : REAL
VAR_INPUT
	in_X1_Start									:REAL;
	in_Y1_Start									:REAL;
	in_X2_End									:REAL;
	in_Y2_End									:REAL;
END_VAR

VAR
	Theta_Buffer								:REAL;
END_VAR



(* 1_TwoPoint_Angle_Calculation *)
IF  in_X1_Start = 0 AND in_Y1_Start = 0 AND in_X2_End = 0 AND in_Y2_End = 0 THEN
	Calculation_1_TwoPoint_Angle := 0;
	RETURN;
END_IF;
        //END X좌표 - Start X좌표 <> 0 인 경우(atan 사용가능)
    IF ( in_X2_End -  in_X1_Start) <> 0 THEN
         Theta_Buffer := 57.2958 * ATAN(( in_Y2_End -  in_Y1_Start) / ( in_X2_End -  in_X1_Start));
        IF ( in_X2_End -  in_X1_Start) < 0 THEN //X2-X1<0 인 경우 +180
             Theta_Buffer :=  Theta_Buffer + 180;
        END_IF;
        //End X좌표 - Start X좌표 = 0 인 경우(atan 사용불가)    
    ELSIF ( in_X2_End -  in_X1_Start) = 0 THEN
        IF  in_Y2_End >  in_Y1_Start THEN
             Theta_Buffer := 90;
        ELSIF  in_Y2_End <  in_Y1_Start THEN
             Theta_Buffer := 270;
        ELSE
             Theta_Buffer := 0;
        END_IF;
    END_IF;
        //Theta 0~360범위를 벗어날 시에, 보정
    IF  Theta_Buffer >= 360 THEN
         Theta_Buffer :=  Theta_Buffer - 360;
    ELSIF  Theta_Buffer < 0 THEN
         Theta_Buffer :=  Theta_Buffer + 360;
    END_IF;

     Calculation_1_TwoPoint_Angle :=  Theta_Buffer;

