     Calculation_2_TwoPoint_Distance := SQRT((( in_X2_End -  in_X1_Start) * ( in_X2_End -  in_X1_Start))
                                           + (( in_Y2_End -  in_Y1_Start) * ( in_Y2_End -  in_Y1_Start)));

