		//Complete
		IF Load_Buffer <> 0 THEN
			Step := 2;
			out_Load_kg := Load_Buffer;
			Actual_Lift_Pos_Buffer_1 := in_Actual_Lift_Pos;
		END_IF;	
	END_IF;

	IF Step = 2 THEN // Step_2 : Load Up Point Detect
		out_Lift_Direction := 1;	
		out_Lift_Speed_mpm := 0.15;	
		//Complete
		IF (in_Loadcell_Value_kg - ( Load_Buffer (* + in_Turret_Weight_kg *))) > 5.0 THEN
			Step := 3;			
			Actual_Lift_Pos_Buffer_2 := in_Actual_Lift_Pos;
		END_IF;	
	END_IF;


	IF Step = 3 THEN // Step_3 : Load_Buffer_Move
		IF 	(Load_Buffer - in_Loadcell_Value_kg > 0.0 ) THEN
			out_Lift_Direction := 1;
		ELSIF (Load_Buffer - in_Loadcell_Value_kg < 0.0 ) THEN
			out_Lift_Direction := 2;
		END_IF;
		IF ABS(Load_Buffer - in_Loadcell_Value_kg) > 50.0 THEN
			out_Lift_Speed_mpm := 0.07;
		ELSE
			out_Lift_Speed_mpm := 0.07;
		END_IF


		TON[1](in:= ABS(Load_Buffer - in_Loadcell_Value_kg) < 5.0 , PT := T#300MS );
		IF (TON[1].Q) THEN
			Step := 4;
		END_IF;
	END_IF;

	IF Step = 4 THEN // Step_4 : Complete
		out_Load_Complete := TRUE;
	END_IF;

	out_Load_kg	:=	Load_Buffer;
END_IF;

