Auto Lift Load DemoTilt

FUNCTION_BLOCK Auto_Lift_Load_DemoTilt
VAR_INPUT
	Enable : BOOL;
	Renew : BOOL;
	in_Loadcell_Value_kg : REAL;	
	in_Measured_Weight_kg : REAL;
	in_Actual_Lift_Pos : REAL;
	//tilt 추가 
	in_HP_Loadcell_Value_kg : REAL;
	in_OP_Loadcell_Value_kg : REAL;

END_VAR
VAR_OUTPUT
	out_Load_Complete : BOOL;
	out_Load_kg	:	REAL;
	out_Lift_Direction : INT;
	out_Lift_Speed_mpm : REAL;
	out_Start_Pos : REAL;	
	//tilt 추가
	out_Tilting_Direction : INT;
	out_Tilting_Speed_mpm : REAL;
END_VAR
VAR
	TON : ARRAY[0..2] OF TON;
	Step : INT;
	Load_Buffer : REAL;	
	Load_Buffer_1 : real;
	Load_Difference : REAL;
	Repeat_Count : INT;
END_VAR


out_Load_Complete := 0;
out_Lift_Direction := 0;
out_Lift_Speed_mpm := 0;
out_Tilting_Direction := 0;
out_Tilting_Speed_mpm := 0;
//Repeat_Count := 0;
Load_Difference := (in_HP_Loadcell_Value_kg - in_OP_Loadcell_Value_kg);


IF Enable THEN
	IF Renew THEN
		Step := 1;
		Load_Buffer := 0;
		Repeat_Count := 0;
		out_Start_Pos := in_Actual_Lift_Pos;		
	END_IF;

	IF Step = 1 THEN // Step_1 : Lift Up (Product_Detect_Point)
		out_Lift_Direction := 1;
		out_Lift_Speed_mpm := 0.10;
		//Complete
		IF in_Loadcell_Value_kg > 100 THEN
			Step := 3; //7;
//	END_IF;	
//	END_IF;			

//=================================================================================================
	//Demo호기 울트라 소닉 미장착으로 인한 [로드셀 = 권경 ] 보정 스텝 스킵 

		    Load_Buffer := 100; //1500; 공보빈 사이클로 인한 무게 변경 //in_Measured_Weight_kg;
			TON[1](in:=FALSE);
		END_IF;	
	END_IF;

	IF Step = 3 THEN // Step_3 : Load_Buffer_Check
		//Complete
		IF Load_Buffer > 10 THEN
			Step := 5;
		END_IF;	
	END_IF;

	IF Step = 5 THEN // Step_5 : Load_Buffer_Move
		IF 	(Load_Buffer - in_Loadcell_Value_kg > 1.0 ) THEN
			out_Lift_Direction := 1;
		ELSIF (Load_Buffer - in_Loadcell_Value_kg < -1.0 ) THEN
			out_Lift_Direction := 2;
		END_IF;
		IF ABS(Load_Buffer - in_Loadcell_Value_kg) > 50.0 THEN
			out_Lift_Speed_mpm := 0.10; //0.07;
		ELSE
			out_Lift_Speed_mpm := 0.10; //0.07;
		END_IF


		TON[1](in:= ABS(Load_Buffer - in_Loadcell_Value_kg) < 30.0 , PT := T#1S ); //200ms
		IF (TON[1].Q) THEN
			Step := 7;
		END_IF;

	END_IF;

//=============================================================================================	
	// Step_7 : Load_Balancing	
	IF Step = 7 THEN 
		IF Load_Difference > 0.5 THEN
			out_Tilting_Direction := 1;
		ELSIF Load_Difference < -0.5 THEN
			out_Tilting_Direction := 2;
		END_IF
		IF ABS(Load_Difference) > 20 THEN
			out_Tilting_Speed_mpm := 0.5;
		ELSIF ABS(Load_Difference) < 20 THEN
			out_Tilting_Speed_mpm := 0.5;
		END_IF

		TON[2](IN:= ABS(Load_Difference) < 10 , PT := T#200MS); // Balance_Check		
		IF TON[2].Q THEN
//==================================================================================================
	// 로드셀 = 권경 보정 스텝 스킵 			
			  (*IF ABS(Load_Buffer - in_Loadcell_Value_kg) < 60.0 AND Repeat_Count = 2 THEN
		   	  (ABS(Load_Buffer - in_Loadcell_Value_kg) < 50.0 AND Repeat_Count = 5) THEN*)


				Step := 9;			

				(*Repeat_Count := 0;
			ELSE
				Step := 5;
		//END_IF
			//Repeat_Count := Repeat_Count + 1;		*)	
//===================================================================================================
		END_IF
	END_IF;		

	IF Step = 9 THEN // Step_4 : Complete
		out_Load_Complete := TRUE;
		//Repeat_Count := 0;
	END_IF;

	out_Load_kg	:=	Load_Buffer;
END_IF;

//===================================================================================================
(*	
	IF Step = 9 THEN // Step_9 : 30kg weight up
		Load_Buffer_1 := Load_Buffer + 30.0;
		Step := 11;
	END_IF;


	IF Step = 11 THEN // Step_11 : Lift up 30kg
		out_Lift_Direction := 1;
		out_Lift_Speed_mpm := 0.10;
		//Complete
		IF ABS(Load_Buffer_1 - in_Loadcell_Value_kg) < 10.0
  			OR Load_Buffer_1 > 115.0  THEN
			Step := 13;
		END_IF;	
	END_IF;

	IF Step = 13 THEN // Step_13 : Complete
		out_Load_Complete := TRUE;
	END_IF;

	out_Load_kg	:=	Load_Buffer;

END_IF;
