    nInMax    : INT;
    fOutMin    : LREAL;
    fOutMax    : LREAL;
END_VAR
VAR_OUTPUT
	out_Value : LREAL;
END_VAR
VAR
    _nValue        : INT;
    _nInValue    : INT;
    _fOutValue    : LREAL;
    _fScale        : LREAL;
END_VAR


IF nInMin >= nInMax    OR fOutMin >= fOutMax THEN
    out_Value    := 0;
    RETURN;
END_IF



_nValue        := LIMIT(nInMin, nValue, nInMax);
_nInValue    := nInMax - nInMin;
_nValue        := _nValue - nInMin;
_fOutValue    := fOutMax - fOutMin;



_fScale        := _nValue / DINT_TO_LREAL(_nInValue);
out_Value        := _fOutValue * _fScale + fOutMin;
