FB LogManager

FUNCTION_BLOCK FB_LogManager
VAR CONSTANT
	VAR_HEADER_BUFFER_SIZE : DINT := 3000;
	VAR_VALUE_BUFFER_SIZE : DINT := 100000;
END_VAR
VAR_IN_OUT
	IO_aHeader			: ARRAY[*] OF STRING;
	IO_aValue			: ARRAY[*] OF STRING;
END_VAR
VAR_INPUT
	IN_bExecute				: BOOL;
	IN_sLogType	 			: STRING := 'Period'; (* Period OR Manual *)
	IN_tLogingPeriod		: TIME := T#1S; (* Only Period Type *)
	IN_bManualLog			: BOOL; (* Only Manual Type *)
	IN_bForceSave			: BOOL;
	IN_sNetID				: STRING(80):='';
	IN_sFileDir				: STRING(80):='C:\'; (* 파일 저장경로 *)
	IN_sFileName	  	 	: STRING(80):='Test.csv'; (* 파일 이름 *)
	IN_bRenewHeader		 	: BOOL; (* 새로운 Cell Name 입력 시 *)
	IN_nBufferSize			: DINT := VAR_VALUE_BUFFER_SIZE; (* If bUseBuffer is true and Cant Bigger then VAR_VALUE_BUFFER_SIZE *)
	IN_bUseBuffer	 	 	: BOOL:=TRUE; (* Not used persistent data, 버퍼 쌓일시 바로 작성 *)
END_VAR
VAR_OUTPUT
	OUT_bError : BOOL;
	OUT_nErrorID :  UDINT;
	OUT_bLossStorage : BOOL;
END_VAR
VAR PERSISTENT
	aBufferWriteHeader			: ARRAY [1..VAR_HEADER_BUFFER_SIZE] OF BYTE;
	aBufferWriteValue			: ARRAY [1..VAR_VALUE_BUFFER_SIZE] OF BYTE;
	nBufferWriteHeaderSize : UDINT;	
	nBufferWriteValueSize : UDINT;
END_VAR
VAR	

	nErrorCnt : INT;	
	bLostStorage : BOOL;
	bError : BOOL; 
	nErrId : UDINT;  
	hFile : UINT; 	
	bSave : BOOL;
	nBeforeDay : WORD;
	bSaveComplete : BOOL;
	bHeaderChanged	: BOOL;
	bDayChanged : BOOL;
	bReWrite : BOOL;
	sHeaderCheck : STRING(4); 
	nHeaderMin : DINT;
	nHeaderMax : DINT;
	nValueMin : DINT;
	nValueMax : DINT;
	nBufferSize : DINT;

	fbLogingPeriod		: TON;
	fbManualLogTrig : R_TRIG;
	fbForceSaveTrig : R_TRIG;
	fbRenewHeaderTrig	: R_TRIG;

	nStep	: INT;
	nLastStep : INT;
	nIndex 	: DINT;

	fbFileOpen							: FB_FileOpen;
	fbFileClose							: FB_FileClose;
	fbFileWrite							: FB_FileWrite;
	fbFileWriteName						: FB_FileWrite;
	fbFileRead							: FB_FileRead;
	fbFileSeek							: FB_FileSeek;
	sFileName : STRING;

	fbNT_GetTime: NT_GetTime;
	sSystemTime							: STRING;
	stTempSTR							: TIMESTRUCT;
END_VAR
VAR CONSTANT
	sDate								: STRING(4):='Date';
	sComma								: STRING(1):=',';
	sSummary							: STRING(1):='$L';
END_VAR


//===================================================================================
// Initial
	SetCommon();

//===================================================================================
// Control	

	IF NOT (IN_bExecute AND IO_aHeader[nHeaderMin] <> '') THEN
		nStep := 0;
		nBufferWriteValueSize := 0;
		MEMSET(ADR(aBufferWriteValue),0,SIZEOF(aBufferWriteValue));
	ELSE
		(* Header Set *)
		fbRenewHeaderTrig(CLK:=IN_bRenewHeader);
		IF fbRenewHeaderTrig.Q OR nBufferWriteHeaderSize = 0 THEN
			SetHeader();
		END_IF

		(* Value Set *)
		fbLogingPeriod(IN:=fbLogingPeriod.Q = FALSE AND IN_sLogType = 'Period', PT:= IN_tLogingPeriod);
		fbManualLogTrig(CLK := IN_bManualLog AND IN_sLogType = 'Manual');
		IF fbLogingPeriod.Q OR fbManualLogTrig.Q THEN
			SetValue(); 						
		END_IF

		(* Save *)
		fbForceSaveTrig(CLK := IN_bForceSave);
		IF (fbForceSaveTrig.Q AND 0 < nBufferWriteValueSize)
		OR bDayChanged
		OR (ABS(nBufferSize - (nBufferSize/10)) < UDINT_TO_DINT(nBufferWriteValueSize) AND IN_bUseBuffer) THEN
			bSave := TRUE;
		END_IF

	END_IF

//===================================================================================
// Logging And Save

	CASE nStep OF 
		0 : (* Logging *)
			nErrId:=0; 
			bError:= FALSE; 
			bLostStorage := FALSE;
			bReWrite := FALSE;

			IF bSave THEN
				nStep := 1;
			END_IF 

		1 : (* Header Check*)	
			MEMSET(ADR(sHeaderCheck), 0, SIZEOF(sHeaderCheck));
			fbFileOpen( bExecute := FALSE );
			fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEREAD ); 
			nStep := 2;	

		2 : 
			fbFileOpen( bExecute := FALSE ); 
			IF NOT fbFileOpen.bBusy THEN 
				IF fbFileOpen.bError THEN
					bReWrite := TRUE;
					nStep := 10;
				ELSE		
					nStep := 3;
				END_IF
			END_IF 	

		3 : 
			fbFileRead(bExecute := FALSE);
			fbFileRead(bExecute := TRUE, pReadBuff := ADR(sHeaderCheck), cbReadLen := 4);	
			nStep := 4;

		4 :
			fbFileRead(bExecute := FALSE);
			IF NOT fbFileRead.bBusy THEN 
			    IF sHeaderCheck <> 'Date' THEN
					bReWrite := TRUE;
				END_IF
				nStep := 5;
			END_IF 

		5: (* File Close *)
			fbFileClose( bExecute := FALSE ); 
			fbFileClose( bExecute := TRUE); 
			nStep := 6;

		6: 
			fbFileClose( bExecute := FALSE ); 
			IF NOT fbFileClose.bBusy THEN 
			    IF fbFileClose.bError THEN 
				 	nErrId := fbFileClose.nErrId; 
				 	bError := TRUE; 
					nStep := 999;
				ELSE
					nStep := 10; 
			    END_IF   
			END_IF 


		10 : (* File Open *)
			fbFileOpen( bExecute := FALSE ); 
			IF bHeaderChanged OR bReWrite THEN
				fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEWRITE );  
			ELSE
				fbFileOpen( bExecute := TRUE, nMode := FOPEN_MODEAPPEND ); 
			END_IF
			nStep := 20;		

		20: 
			fbFileOpen( bExecute := FALSE ); 
			IF NOT fbFileOpen.bBusy THEN 
			    IF fbFileOpen.bError THEN 
					nErrId := fbFileOpen.nErrId; 
					bError := TRUE; 
					nStep := 999; 
					bLostStorage := SEL(bHeaderChanged OR bReWrite, FALSE, nErrId = 1804);
					// 여기서 Write모드로 썻는데 에러라면 D드라이브 없어서 그런거라고 볼수밖에 없나.
			    ELSE 
					nStep := SEL(bHeaderChanged OR bReWrite, 50, 30);
				END_IF 
			END_IF 

		30 : (* Header Write *)
			fbFileWrite( bExecute := FALSE ); 
			fbFileWrite( bExecute := TRUE, pWriteBuff := ADR(aBufferWriteHeader), cbWriteLen := nBufferWriteHeaderSize); 
			nStep := 40;

		40 : 
			fbFileWrite( bExecute := FALSE ); 
			IF NOT fbFileWrite.bBusy THEN 
			   IF fbFileWrite.bError THEN 
					nErrId := fbFileWrite.nErrId; 
					bError := TRUE; 
					nStep := 999; 
			   ELSE 
					nStep := 50; 
			   END_IF 
			END_IF 

		50 : (* Value Write *)
 			fbFileWrite( bExecute := FALSE ); 
			fbFileWrite( bExecute := TRUE, pWriteBuff := ADR(aBufferWriteValue), cbWriteLen := nBufferWriteValueSize); 
			nStep := 60;	

		60 : 
			fbFileWrite( bExecute := FALSE ); 
			IF NOT fbFileWrite.bBusy THEN 
			   IF fbFileWrite.bError THEN 
					nErrId := fbFileWrite.nErrId; 
					bError := TRUE; 
					nStep := 999; 
			   ELSE 
					nStep := 70; 
			   END_IF 
			END_IF 	

		70: (* File Close *)
			fbFileClose( bExecute := FALSE ); 
			fbFileClose( bExecute:=TRUE); 
			nStep := 80;

		80: 
			fbFileClose( bExecute := FALSE ); 
			IF NOT fbFileClose.bBusy THEN 
			    IF fbFileClose.bError THEN 
				 	nErrId := fbFileClose.nErrId; 
				 	bError := TRUE; 
					nStep := 999;
				ELSE
					nStep := 90; 
			    END_IF   
			END_IF 

		90: (* Complete *)
			bSave := FALSE;
			bHeaderChanged := FALSE;
			nBufferWriteValueSize := 0;
			MEMSET(ADR(aBufferWriteValue), 0, SIZEOF(aBufferWriteValue));
			nStep := 0;

		999: (* Error *)
			bSave := FALSE; 
			nErrorCnt := nErrorCnt + 1;
			nStep := 0;	//24.02.23 수정 (주석되어 있어서 에러 발생시 스텝 초기 안됨)

	END_CASE

	IF nStep <> 0 AND nStep <> 999 THEN
		nLastStep := nStep;
	END_IF

	OUT_bLossStorage := bLostStorage;
	OUT_bError := bError;
	OUT_nErrorID := nErrId;

	IF nStep = 999 OR OUT_bError THEN
		GDB.Error.USB_Error_Bit := TRUE;
	ELSE 
		GDB.Error.USB_Error_Bit := FALSE;
	END_IF

==================================================
SetCommon

METHOD PRIVATE SetCommon
VAR
	nHeaderBufferOverFlowPrevent : DINT;
	nValueBufferOverFlowPrevent : DINT;
END_VAR



	nHeaderBufferOverFlowPrevent := REAL_TO_DINT(DINT_TO_REAL(VAR_HEADER_BUFFER_SIZE)  * 0.9);	
	nValueBufferOverFlowPrevent := REAL_TO_DINT(DINT_TO_REAL(VAR_VALUE_BUFFER_SIZE)  * 0.9);	

	IF UDINT_TO_DINT(nBufferWriteHeaderSize) >= nHeaderBufferOverFlowPrevent THEN
		nBufferWriteHeaderSize:=0;  
		MEMSET(ADR(aBufferWriteHeader),0,SIZEOF(aBufferWriteHeader));	
	END_IF

	IF UDINT_TO_DINT(nBufferWriteValueSize) >= nValueBufferOverFlowPrevent THEN
		nBufferWriteValueSize := 0;
		MEMSET(ADR(aBufferWriteValue), 0, SIZEOF(aBufferWriteValue));
	END_IF

	MEMSET(ADR(sSystemTime),0,SIZEOF(sSystemTime));
	sSystemTime:= CONCAT(WORD_TO_STRING(stTempSTR.wYear),'.');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wMonth));
	sSystemTime:= CONCAT(sSystemTime,'.');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wDay));
	sSystemTime:= CONCAT(sSystemTime,'_');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wHour));
	sSystemTime:= CONCAT(sSystemTime,'.');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wMinute));
	sSystemTime:= CONCAT(sSystemTime,'.');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wSecond));
	sSystemTime:= CONCAT(sSystemTime,'.');
	sSystemTime:= CONCAT(sSystemTime,WORD_TO_STRING(stTempSTR.wMilliseconds));

	IF nBeforeDay = 0 THEN
		nBeforeDay := stTempSTR.wDay;
	END_IF

	bDayChanged := FALSE;
	IF nBeforeDay <> stTempSTR.wDay THEN
		nBeforeDay := stTempSTR.wDay;
		bDayChanged := TRUE;
	END_IF

	// 파일 작업 중 또는 날짜 변경으로 인한 저장시 경로 변경 금지.
	IF nStep = 0 AND bDayChanged = FALSE THEN 
		sFileName := CONCAT(IN_sFileName, '_');
		sFileName := CONCAT(sFileName, WORD_TO_STRING(stTempSTR.wYear));
		//F_FillZero 함수가 없어 테스트를 위해 없이 사용.
		//sFileName := CONCAT(sFileName, WORD_TO_STRING(stTempSTR.wMonth));
		//sFileName := CONCAT(sFileName, WORD_TO_STRING(stTempSTR.wDay));
		//sFileName := CONCAT(sFileName, F_FillZero(WORD_TO_STRING(stTempSTR.wMonth), 2));
		//sFileName := CONCAT(sFileName, F_FillZero(WORD_TO_STRING(stTempSTR.wDay), 2));
