FUNCTION_BLOCK Home_And_Limit_Search
VAR_INPUT
	in_No_Limit_Sensor	: BOOL;
	in_Start_Bit : BOOL;
	in_Stop_Bit : BOOL;
	in_Current_Pos : REAL;
	in_Home_Offset : REAL;
	in_HomeSensor_Bit_NO : BOOL;
	in_FW_Limit_Bit_NC : BOOL;
	in_BW_Limit_Bit_NC : BOOL;		
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Step : INT;
	out_Fail : BOOL;	
	out_Home_Pos : REAL;
	out_FW_Limit_Pos : REAL;
	out_BW_Limit_Pos : REAL;
	out_FW_Run_High : BOOL;
	out_FW_Run_Low : BOOL;
	out_BW_Run_High : BOOL;
	out_BW_Run_Low : BOOL;	
END_VAR
VAR
	Step : INT;
	TON : ARRAY[0..4] OF TON;
	PN_Pulse : ARRAY[0..1] OF PN_Pulse;
END_VAR


//초기화
out_Complete := FALSE;
out_Fail := FALSE;
out_FW_Run_High := FALSE;
out_FW_Run_Low := FALSE;
out_BW_Run_High := FALSE;
out_BW_Run_Low := FALSE;

//Start
PN_Pulse[1](in_Type:= 1, 
			in_Signal:= 	Step = 0 
						AND in_Start_Bit
						AND in_FW_Limit_Bit_NC = TRUE
						AND in_BW_Limit_Bit_NC = TRUE);
IF PN_Pulse[1].out_Pulse THEN
	Step := 1;	
	out_Home_Pos := 0;
	out_FW_Limit_Pos := 0;
	out_BW_Limit_Pos := 0;
END_IF;

//Stop
IF in_Stop_Bit THEN
	Step := 0;
END_IF

out_Step := Step;



//Step_1 : BW_Limit_Search
IF Step = 1 THEN
		out_BW_Run_High := TRUE;
	IF in_No_Limit_Sensor = FALSE AND in_BW_Limit_Bit_NC = FALSE THEN //BW_Limit 감지 시,
		out_BW_Limit_Pos := in_Current_Pos;
		Step := 3;				
	ELSIF in_No_Limit_Sensor AND in_HomeSensor_Bit_NO THEN //Home 감지 시,
		Step := 2;				
	END_IF;		
END_IF;
//Step_2 : Home_Detect
IF Step = 2 THEN
	out_BW_Run_Low := TRUE;
	TON[1](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
	IF TON[1].Q THEN
		Step := 3;
	END_IF;		
END_IF
//Step_3 : 	Home_Search
IF Step = 3 THEN
	out_FW_Run_High := TRUE;
	IF in_HomeSensor_Bit_NO THEN
		Step := 4;
	END_IF;
END_IF
//Step_4 : Home_Detect(FW_Run_Low)
IF Step = 4 THEN	
	out_FW_Run_Low := TRUE;
	TON[2](IN := in_HomeSensor_Bit_NO = FALSE,PT := T#1S);
	IF TON[2].Q THEN
		Step := 5;
	END_IF;
END_IF;	
//Step_5 : Home_Detect(BW_Run_Low)
IF Step = 5 THEN
	out_BW_Run_Low := TRUE;
	IF in_HomeSensor_Bit_NO THEN
		Step := 6;
	END_IF;
END_IF;	
//Step_6 : 	Home_Set
IF Step = 6 THEN
	IF in_No_Limit_Sensor = FALSE AND in_HomeSensor_Bit_NO THEN				
		out_Home_Pos := in_Current_Pos - in_Home_Offset;
		Step := 7;
	ELSIF in_No_Limit_Sensor = TRUE AND in_HomeSensor_Bit_NO THEN				
		out_Home_Pos := in_Current_Pos - in_Home_Offset;
		out_Complete := TRUE;
		Step := 0;				
	END_IF;
END_IF; 	
//Step_7 : FW_Limit_Search
IF Step = 7 THEN
	out_FW_Run_High := TRUE;
	IF in_FW_Limit_Bit_NC = FALSE THEN
		out_FW_Limit_Pos := in_Current_Pos;				
		Step := 8;				
	END_IF	
END_IF
//Step_8 : BW_Move
IF Step = 8 THEN
	out_BW_Run_Low := TRUE;
	TON[3](IN:= in_FW_Limit_Bit_NC , PT:= T#1S);
	IF TON[3].Q THEN
		out_Complete := TRUE;
		Step := 0;			
	END_IF	
END_IF

//Timeout
TON[4](IN:= Step <> 0, PT:= T#300S);
IF TON[4].Q THEN
	out_Fail := TRUE;
	Step := 0;
END_IF

(*
