FUNCTION_BLOCK PILZ_Recieve
VAR_INPUT
	in_bStart					:BOOL;
	in_array_ByRcvData			:ARRAY[0..42] OF BYTE;
END_VAR

VAR_OUTPUT
	out_bComplete				:BOOL;
	out_bFormatError			:BOOL;
	out_array_ByIOData			:ARRAY[0..15] OF BYTE;
	out_ByTableNum				:BYTE;
	out_BySegmentNum			:BYTE;
	out_array_ByPayload			:ARRAY[0..12] OF BYTE;	
END_VAR

VAR
	static_ByBCC_Sum			:BYTE;
	static_iForIndex			:INT;
END_VAR


IF  in_bStart = TRUE THEN

    //변수 초기화
     out_bFormatError := false;
     out_bComplete := false;
     static_ByBCC_Sum := 0;

    //BCC 계산
    FOR  static_iForIndex := 10#4 TO 10#39 BY 10#1 DO
         static_ByBCC_Sum :=  static_ByBCC_Sum +  in_array_ByRcvData[ static_iForIndex];
    END_FOR;
     static_ByBCC_Sum := UINT_TO_BYTE(16#100 -  static_ByBCC_Sum);

    //BCC OK
    IF  static_ByBCC_Sum =  in_array_ByRcvData[41] THEN

        MEMMOVE(destAddr:=ADR(out_array_ByIOData[0]) , srcAddr:=ADR(in_array_ByRcvData[8]) , n:=10#16 );

        out_ByTableNum :=  in_array_ByRcvData[25]; // Table Number.
        out_BySegmentNum :=  in_array_ByRcvData[26]; // Segment Number.

		MEMMOVE(destAddr:=ADR(out_array_ByPayload[0]) , srcAddr:=ADR(in_array_ByRcvData[27]) , n:=10#16 ); 

		out_bComplete := TRUE;
    END_IF;

    //BCC NG
    IF  static_ByBCC_Sum <>  in_array_ByRcvData[41] THEN
         out_bFormatError := TRUE;
    END_IF;

END_IF;

IF  in_bStart = FALSE THEN
     out_bComplete := FALSE;
     out_bFormatError := FALSE;
END_IF;


==================================================
PILZ Send

FUNCTION_BLOCK PILZ_Send
VAR_INPUT
	in_bStart				:BOOL;
	in_array_ByIOdata		:ARRAY[0..15] OF BYTE;
	in_ByTableNo			:BYTE;
	in_BySegmentNo			:BYTE;
END_VAR
VAR_OUTPUT
	out_bComplete			:BOOL;
	out_array_BySendData	:ARRAY[0..42] OF BYTE;
END_VAR
VAR
	static_iForIndex		:INT;
END_VAR


IF  in_bStart = TRUE THEN

     out_bComplete := false;

     out_array_BySendData[0] := 16#05; //Byte0
     out_array_BySendData[1] := 16#15; //Byte1
     out_array_BySendData[2] := 16#00; //Byte2
     out_array_BySendData[3] := 16#26; //Byte3
     out_array_BySendData[4] := 16#5C; //Byte4
     out_array_BySendData[5] := 16#63; //Byte5_Controlbyte
     out_array_BySendData[6] := 16#00; //Byte6
     out_array_BySendData[7] := 16#00; //Byte7

     MEMCPY(destAddr:=ADR(out_array_BySendData[8]) , srcAddr:=ADR(in_array_ByIOdata[0]) , n:=SIZEOF(in_array_ByIOdata) );

     out_array_BySendData[25] :=  in_ByTableNo;//Byte25 : Table Number
     out_array_BySendData[26] :=  in_BySegmentNo;//Byte26 : Segment Sumber
     out_array_BySendData[27] := 16#00;//Byte27
     out_array_BySendData[28] := 16#00;//Byte28
     out_array_BySendData[29] := 16#00;//Byte29
     out_array_BySendData[30] := 16#00;//Byte30
     out_array_BySendData[31] := 16#00;//Byte31
     out_array_BySendData[32] := 16#00;//Byte32
     out_array_BySendData[33] := 16#00;//Byte33
     out_array_BySendData[34] := 16#00;//Byte34
     out_array_BySendData[35] := 16#00;//Byte35
     out_array_BySendData[36] := 16#00;//Byte36
     out_array_BySendData[37] := 16#00;//Byte37
     out_array_BySendData[38] := 16#00;//Byte38
     out_array_BySendData[39] := 16#00;//Byte39
     out_array_BySendData[40] := 16#00;//Byte40

     out_array_BySendData[41] := 16#00;//Byte41 : BCC(Byte4~39 Cehcksum);
    FOR  static_iForIndex := 10#4 TO 10#39 BY 10#1 DO
         out_array_BySendData[41] :=  out_array_BySendData[41] +  out_array_BySendData[ static_iForIndex];
    END_FOR;
     out_array_BySendData[41] := UINT_TO_BYTE(16#100 -  out_array_BySendData[41]);

     out_array_BySendData[42] := 16#10;//Byte42

     out_bComplete := TRUE;

END_IF;

IF  in_bStart = FALSE THEN
     out_bComplete := FALSE;
END_IF;
==================================================
Position Control

FUNCTION_BLOCK Position_Control

VAR_INPUT
in_bStart							:BOOL;
in_iTarget_position_mm				:REAL;
in_iActual_position_mm				:REAL;
in_iTarget_High_Speed_mpm			:REAL;
in_iTarget_Low_Speed_mpm			:REAL;
in_iActual_Speed_mps				:REAL;
in_iAccel_Speed_mps2				:REAL;
in_iDecel_Speed_mps2				:REAL;
in_Decel_Distance_Offset_mm			:REAL;
in_InPosition_mm					:REAL;
in_Speed_0_Direction_0_Bit			:BOOL;
END_VAR

VAR_OUTPUT
out_bTarget_reached					:BOOL;
out_iDirection						:INT;
out_Output_Value_mpm				:REAL;
END_VAR

VAR
static_Decel_Distance_mm			:REAL;
static_Decel_Distance_Offset_mm 	:REAL;
END_VAR


 out_bTarget_reached := 0;
 out_iDirection := 0;
 out_Output_Value_mpm := 0;
// Decel_Distance (감속 거리 계산)
// 감속 거리 = (-1/2) * ( 현재속도^2 / 감속도 )
// [단위 m/s]
IF in_bStart AND in_iDecel_Speed_mps2 <> 0 THEN
 static_Decel_Distance_mm := ((0.5) * ( in_iActual_Speed_mps *  in_iActual_Speed_mps) /  in_iDecel_Speed_mps2) * 1000 ;
 //static_Decel_Distance_Offset_mm := in_Decel_Distance_Offset_mm + in_iActual_Speed_mps*0.1; //Offset 값 + 100ms동안 움직인 거리(반응속도)
 static_Decel_Distance_Offset_mm := in_Decel_Distance_Offset_mm ; //Offset 값 + 100ms동안 움직인 거리(반응속도)
//목표위치가 현재위치보다 큰 경우
IF  in_iTarget_position_mm >  in_iActual_position_mm THEN
    IF ( in_iTarget_position_mm -  in_iActual_position_mm) > ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //고속으로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_High_Speed_mpm;
    END_IF;

    IF ( in_iTarget_position_mm -  in_iActual_position_mm) < ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //저속으로 2로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_Low_Speed_mpm;
    END_IF;

    IF ABS( in_iTarget_position_mm -  in_iActual_position_mm) <  in_InPosition_mm THEN //In Position 값 설정
         out_Output_Value_mpm := 0;
        IF  in_iActual_Speed_mps = 0 THEN
             out_bTarget_reached := 1;
        END_IF;
    END_IF;
     out_iDirection := 1;
END_IF;

//목표위치가 현재위치보다 작은 경우
IF  in_iTarget_position_mm <  in_iActual_position_mm THEN
    IF ( in_iActual_position_mm -  in_iTarget_position_mm) > ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //목표속도 1로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_High_Speed_mpm;
    END_IF;

    IF ( in_iActual_position_mm -  in_iTarget_position_mm) < ( static_Decel_Distance_mm +  static_Decel_Distance_Offset_mm) THEN //목표속도 2로 가는 경우
         out_Output_Value_mpm :=  in_iTarget_Low_Speed_mpm;
    END_IF;

    IF ABS( in_iActual_position_mm -  in_iTarget_position_mm) <  in_InPosition_mm THEN //In Position 값 설정
         out_Output_Value_mpm := 0;
        IF  in_iActual_Speed_mps = 0 THEN
             out_bTarget_reached := 1;
        END_IF;
    END_IF;
     out_iDirection := 2;
END_IF;

IF  in_iTarget_position_mm =  in_iActual_position_mm AND  in_iActual_Speed_mps = 0 THEN
     out_bTarget_reached := 1;
END_IF;


// in_Speed_0_Direction_0_Bit : 속도가 0일 때에, 방향 비트를 0으로 할 것인지 아니면 그대로 출력할 것인지 선택_
IF  in_Speed_0_Direction_0_Bit = 1 AND  out_Output_Value_mpm = 0 THEN    
         out_iDirection := 0;    
END_IF;


END_IF;
