Tabos Battery Receive

FUNCTION_BLOCK Tabos_Battery_Receive
VAR_INPUT
	in_Enable : BOOL;
	in_Address : INT;
	in_Data : ARRAY[1..19] OF BYTE;
END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Receive_Fail : BOOL;
	out_Voltage_V : REAL;
	out_Current_A : REAL;
	out_SOC_Percentage : INT;
	out_Error : UINT;
	out_Temperature : REAL;
END_VAR
VAR
	bu_Checksum : BYTE;
	Test0 : UINT;
END_VAR


out_Complete := FALSE;
out_Receive_Fail := FALSE;
(*
out_Voltage_V := 0;
out_Current_A := 0;
out_SOC_Percentage := 0;
out_Error := 0;
out_Temperature := 0;
*)





IF in_Enable THEN
	//CheckSum := Adrress(3) + Length(4) + Command(5) + Order(6) + Data1 + Data 2 ... Data 10
	bu_Checksum := UINT_TO_BYTE((in_Data[3]+in_Data[4]+in_Data[5]+in_Data[6]+in_Data[7]+in_Data[8]+in_Data[9]+in_Data[10]+in_Data[11]+in_Data[12]+in_Data[13]+
					in_Data[14]+in_Data[15]+in_Data[16]) MOD (16#100));


	IF in_Data[1] = 16#AF AND in_Data[2] = 16#FA AND in_Data[17] = bu_Checksum AND in_Data[18] = 16#AF AND in_Data[19] = 16#A0 THEN
		//out_Voltage_V 
		out_Voltage_V := UINT_TO_REAL(BYTE_TO_UINT(in_Data[8]) + SHL(BYTE_TO_UINT(in_Data[7]),8))/100;
		//out_Current_A 
		out_Current_A := INT_TO_REAL(BYTE_TO_INT(in_Data[10]) + SHL(BYTE_TO_INT(in_Data[9]),8))/100;
		//out_SOC_Percentage 
		out_SOC_Percentage := BYTE_TO_INT(in_Data[12]);
		//out_Error (Bit Data)
				//0 배터리 과전압 		8 배터리 과전압
				//1 배터리 저전압 		9 배터리 저전압
				//2 충전 전류 과다 		10 충전 전류 과다
				//3 방전 전류 과다 		11 방전 전류 과다
				//4 고온도 				12 고온도
				//5 저온도 				13 저온도
				//6 BMU 에러 			14 -
				//7 - 					15 -
		out_Error := BYTE_TO_UINT(in_Data[14]) + SHL(BYTE_TO_UINT(in_Data[13]),8);
		//out_Temperature 
		out_Temperature := UINT_TO_REAL(BYTE_TO_UINT(in_Data[16]) + SHL(BYTE_TO_UINT(in_Data[15]),8))/10;

		out_Complete := TRUE;

	ELSE
		out_Receive_Fail := TRUE;
	END_IF

END_IF

