FUNCTION_BLOCK Zapi_Drive_Send
VAR_INPUT
	in_enable : BOOL;
	in_Sync_Bit : BOOL;
	//Speed
	in_TargetSpeed_mpm						:REAL;
	in_Wheel_Diameter_mm 					:REAL;
	in_Gear_Ratio 							:REAL;	
	//Data
	in1_20_enable_power 					:BOOL;
	in1_21_power_Contact_on					:BOOL; 
//	in1_22_NEB_								:BOOL;
	in1_23_forward_req						:BOOL;
	in1_24_reverse_req						:BOOL;
//	in1_25_SAUX1							:BOOL;
//	in1_26_SAUX2							:BOOL;
//	in1_27_SAUX3							:BOOL;
//	in1_30_SAUX4							:BOOL;
//	in1_31_SAUX5							:BOOL;
//	in1_32_HORN								:BOOL;	
	in1_33_MC_generic_purpose				:BOOL;
	in1_34_agv_request						:BOOL;
	in1_35_reset_STO_SS1_alarm				:BOOL;	
//	in1_36_Spare							:BOOL;	
	in1_37_Stuffing							:BOOL;
	in1_40_Pedal_Brake_Req 					:BYTE;
//	in1_50_dc_pump_Target	 				:BYTE;
//	in1_60_target_evp		 				:BYTE;
//	in1_70_target_evp 						:BYTE;

//	in2_00_Max_torque_motoringing			:BYTE;
//	in2_10_Max_torque_braking				:BYTE;
//	in2_20_ControlWord2						:UINT;
//	in2_40_Free								:DINT;

END_VAR
VAR_OUTPUT
	out_Complete : BOOL;
	out_Data : ARRAY[0..30] OF BYTE;
	out_Direction : INT;
	out_rpm : UINT;
END_VAR

VAR
	va_Buffer_Data : ARRAY[0..30] OF BYTE;
	va1_00_TargetSpeed_Hz_x10	:UINT;
	va_Stuff_Buffer : BOOL;
END_VAR


out_Complete := FALSE;
MEMSET(destAddr:=ADR(va_Buffer_Data[0]) , fillByte:=10#0 , n:=SIZEOF(va_Buffer_Data));
IF in_enable AND in_Wheel_Diameter_mm <> 0 AND in_Gear_Ratio <> 0 THEN	
	IF in_Sync_Bit THEN
	va_Stuff_Buffer := NOT(va_Stuff_Buffer);
	END_IF;	



	va1_00_TargetSpeed_Hz_x10	:= LREAL_TO_UINT(((((in_TargetSpeed_mpm*1000)/(PI*in_Wheel_Diameter_mm))*in_Gear_Ratio)/30)*10);
	va_Buffer_Data[0] 			:= UINT_TO_BYTE((va1_00_TargetSpeed_Hz_x10)AND(16#00FF));
	va_Buffer_Data[1] 			:= UINT_TO_BYTE(SHR(va1_00_TargetSpeed_Hz_x10,8));
	va_Buffer_Data[2].0 		:= in1_20_enable_power;
	va_Buffer_Data[2].1 		:= in1_21_power_Contact_on;
//	va_Buffer_Data[2].2 		:= in1_22_NEB_;
	va_Buffer_Data[2].3 		:= in1_23_forward_req;
	va_Buffer_Data[2].4 		:= in1_24_reverse_req;	
//	va_Buffer_Data[2].5 		:= in1_25_SAUX1;
//	va_Buffer_Data[2].6 		:= in1_26_SAUX2;
//	va_Buffer_Data[2].7 		:= in1_27_SAUX3;
//	va_Buffer_Data[3].0 		:= in1_30_SAUX4;
// 	va_Buffer_Data[3].1 		:= in1_31_SAUX5;
//	va_Buffer_Data[3].2 		:= in1_32_HORN;
	va_Buffer_Data[3].3 		:= in1_33_MC_generic_purpose;
	va_Buffer_Data[3].4 		:= in1_34_agv_request;
	va_Buffer_Data[3].5 		:= in1_35_reset_STO_SS1_alarm;
//	va_Buffer_Data[3].6 		:= in1_36_Spare;
	va_Buffer_Data[3].7 		:= va_Stuff_Buffer;
//	va_Buffer_Data[3].7 		:= in1_37_Stuffing;	
	va_Buffer_Data[4] 			:= in1_40_Pedal_Brake_Req;		
//	va_Buffer_Data[5] 			:= in1_50_dc_pump_Target;
//	va_Buffer_Data[6] 			:= in1_60_target_evp;
//	va_Buffer_Data[7] 			:= in1_70_target_evp;

//	va_Buffer_Data[10] 			:= in2_00_Max_torque_motoringing;
//	va_Buffer_Data[11] 			:= in2_10_Max_torque_braking;
//	va_Buffer_Data[12] 			:= 0;
//	va_Buffer_Data[13] 			:= 0;
	va_Buffer_Data[13].7 		:= va_Stuff_Buffer;
//	va_Buffer_Data[14] 			:= 0;
//	va_Buffer_Data[15] 			:= 0;
//	va_Buffer_Data[16] 			:= 0;

//	IF in_TargetSpeed_mpm = 0 AND (va_Buffer_Data[2].3 = TRUE OR va_Buffer_Data[2].4 = TRUE) THEN
//		va_Buffer_Data[4] := 10#100;
//	END_IF
	IF in_TargetSpeed_mpm = 0 THEN
		va_Buffer_Data[2].3 := FALSE;
		va_Buffer_Data[2].4 := FALSE;
	END_IF
(*	IF va_Buffer_Data[2].3 = FALSE AND va_Buffer_Data[2].4 = FALSE THEN
		va_Buffer_Data[0] := 0;
		va_Buffer_Data[1] := 0;
	END_IF
*)	

	IF va_Buffer_Data[2].3 THEN
		out_Direction := 1;
	ELSIF va_Buffer_Data[2].4 THEN
		out_Direction := 2;
	ELSE
		out_Direction := 0;
	END_IF
	out_rpm := va1_00_TargetSpeed_Hz_x10;

	MEMCPY(destAddr:=ADR(out_Data[0]) , srcAddr:=ADR(va_Buffer_Data[0]) , n:=SIZEOF(va_Buffer_Data));
	out_Complete := TRUE;
END_IF
