k:=LIMIT(1,k,5);
CASE step OF
	0:
		EL72DCLinkRead(bExecute:=FALSE);
		EL72DCLinkRead(
			sNetId:= EL72NetID, 
			nSlaveAddr:= SlaveAddr[k], 
			nSubIndex:= 16#12, 
			nIndex:= 16#9010, 
			pDstBuf:= ADR(DCLinkVoltage[k]), 
