			bExecute:= TRUE, 
			tTimeout:= , 
			bBusy=> , 
			bError=> , 
			nErrId=> );
		EL72AmpareRead(bExecute:=FALSE);
		EL72AmpareRead(
			sNetId:= EL72NetID, 
			nSlaveAddr:= SlaveAddr[k], 
			nSubIndex:= 16#08, 
			nIndex:= 16#9009, 
			pDstBuf:= ADR(RatedCurrent[k]), 
			cbBufLen:= SIZEOF(RatedCurrent[k]), 
			bExecute:= TRUE, 
			tTimeout:= , 
			bBusy=> , 
			bError=> , 
			nErrId=> );	
		step:=10;
	10:
		EL72DCLinkRead();
		IF EL72DCLinkRead.bBusy=FALSE THEN
			EL72DCLinkRead(bExecute:=FALSE);
			k:=k+1;
			IF k=6 THEN
				k:=1;
			END_IF
			step:=0;
		END_IF
END_CASE

