==================================================
Manual Part

 PROGRAM Manual_Part
VAR
END_VAR


(* Travel *)
IF TRUE THEN
    //Initialize
    GDB.manual.Travel_TargetSpeed_mpm := 0;
    GDB.manual.Travel_FW_Direction := 0;
    GDB.manual.Travel_BW_Direction := 0;

    IF GDB.mode.Manual THEN
        //Travel_Speed_Set
        IF (GDB.Touch.S21_Travel_HighSpeed_Lamp = FALSE AND GDB.Touch.S21_Travel_LowSpeed_Lamp = FALSE)
            OR GDB.Touch.S21_Travel_LowSpeed_SW THEN
            GDB.Touch.S21_Travel_HighSpeed_Lamp := FALSE;
            GDB.Touch.S21_Travel_LowSpeed_Lamp := TRUE;
        ELSIF GDB.Touch.S21_Travel_HighSpeed_SW THEN
            GDB.Touch.S21_Travel_HighSpeed_Lamp := TRUE;
            GDB.Touch.S21_Travel_LowSpeed_Lamp := FALSE;
        END_IF;
        IF GDB.Touch.S21_Travel_HighSpeed_Lamp THEN

            GDB.manual.Travel_TargetSpeed_mpm := GDB_Parameter.Travel_High_Speed[3];
        ELSIF GDB.Touch.S21_Travel_LowSpeed_Lamp THEN
            GDB.manual.Travel_TargetSpeed_mpm := GDB_Parameter.Travel_High_Speed[1];

        END_IF;

        //Travel_Move
        IF GDB.Touch.S21_Travel_Both_FW_Run_SW OR GDB.manual.Travel_Setup_FW_Run THEN
            GDB.manual.Travel_FW_Direction := 1;
            GDB.manual.Travel_BW_Direction := 1;
        ELSIF GDB.Touch.S21_Travel_Both_BW_Run_SW OR GDB.manual.Travel_Setup_BW_Run THEN
            GDB.manual.Travel_FW_Direction := 2;
            GDB.manual.Travel_BW_Direction := 2;
        ELSIF GDB.Touch.S21_Travel_FW_Wheel_FW_Run_SW THEN
            GDB.manual.Travel_FW_Direction := 1;
            GDB.manual.Travel_BW_Direction := 0;
        ELSIF GDB.Touch.S21_Travel_FW_Wheel_BW_Run_SW THEN
            GDB.manual.Travel_FW_Direction := 2;
            GDB.manual.Travel_BW_Direction := 0;
        ELSIF GDB.Touch.S21_Travel_BW_Wheel_FW_Run_SW THEN
            GDB.manual.Travel_FW_Direction := 0;
            GDB.manual.Travel_BW_Direction := 1;
        ELSIF GDB.Touch.S21_Travel_BW_Wheel_BW_Run_SW THEN
            GDB.manual.Travel_FW_Direction := 0;
            GDB.manual.Travel_BW_Direction := 2;
        ELSIF GDB.Touch.S21_SpinTurn_Ready_OK_Lamp AND GDB.Touch.S21_SpinTurn_CW_SW THEN
            GDB.manual.Travel_FW_Direction := 2;
            GDB.manual.Travel_BW_Direction := 1;
        ELSIF GDB.Touch.S21_SpinTurn_Ready_OK_Lamp AND GDB.Touch.S21_SpinTurn_CCW_SW THEN
            GDB.manual.Travel_FW_Direction := 1;
            GDB.manual.Travel_BW_Direction := 2;
        END_IF;

    END_IF;
END_IF;
(* Steering *)
//Initialize
GDB.Touch.S21_SpinTurn_Ready_OK_Lamp := FALSE;
IF  GDB.mode.Manual = FALSE
    OR GDB.manual.Steering_FW_Target_Angle <= 80
	OR GDB.manual.Steering_FW_Target_Angle >= 280
    OR GDB.manual.Steering_BW_Target_Angle <= 80
	OR GDB.manual.Steering_BW_Target_Angle >= 280 THEN
    GDB.manual.Steering_FW_Target_Angle := GDB.monitor.Current_FW_Wheel_Angle;
    GDB.manual.Steering_BW_Target_Angle := GDB.monitor.Current_BW_Wheel_Angle;
END_IF;

IF GDB.mode.Manual THEN
    //Steering_Move
    IF  GDB.Touch.S21_Steering_Target_Start_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.Touch.S21_Steering_Target_Angle;
        GDB.manual.Steering_BW_Target_Angle := GDB.Touch.S21_Steering_Target_Angle;
    ELSIF  GDB.Touch.S21_Steering_Both_CW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle + 0.005;
        GDB.manual.Steering_BW_Target_Angle := GDB.manual.Steering_BW_Target_Angle + 0.005;
    ELSIF GDB.Touch.S21_Steering_Both_CCW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle - 0.005;
        GDB.manual.Steering_BW_Target_Angle := GDB.manual.Steering_BW_Target_Angle - 0.005;
    ELSIF GDB.Touch.S21_Steering_FW_Wheel_CW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle + 0.005;
        GDB.manual.Steering_BW_Target_Angle := GDB.manual.Steering_BW_Target_Angle ;
    ELSIF GDB.Touch.S21_Steering_FW_Wheel_CCW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle - 0.005;
        GDB.manual.Steering_BW_Target_Angle := GDB.manual.Steering_BW_Target_Angle ;
    ELSIF GDB.Touch.S21_Steering_BW_Wheel_CW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle ;
        GDB.manual.Steering_BW_Target_Angle := GDB.manual.Steering_BW_Target_Angle + 0.005;
    ELSIF GDB.Touch.S21_Steering_BW_Wheel_CCW_SW THEN
        GDB.manual.Steering_FW_Target_Angle := GDB.manual.Steering_FW_Target_Angle ;
