Scenario Main

PROGRAM Scenario_Main
VAR

	_bStartSW 		: BOOL;  	// Touch
	_bStopSW 		: BOOL; 	// Touch
	_nScenarioNum 	: INT; 		// Touch
	_bHaveCommand 	: BOOL; 	// Touch 
	_bCommandClearSW : BOOL; 	//Touch

	_nRepeatCnt : INT;
	_nCurrentRepeatCnt : INT;

	_fbStartTriger : R_TRIG;
	_nScenarioStep : INT;
	_stCommandList : ARRAY[1..30] OF ST_ScenarioCommand; 
	_nCommandNum : INT;
	_nCommandEA : INT;
	_nIndex : INT;

	_stBeforeCommandList :  ARRAY[1..30] OF ST_ScenarioCommand; 
	_nBeforeCommandNum : INT;
	_nBeforeCommandEA : INT;

	TON	: ARRAY[0..1] OF TON;
	TOF	: ARRAY[0..1] OF TOF;


END_VAR


//=======================================================================================================	
//	Call And Initial

	Scenario_DATA();


//=======================================================================================================	
//	Control

	_fbStartTriger(CLK := _bStartSW);
	IF _fbStartTriger.Q THEN
		_nScenarioStep := 10;
	END_IF

	IF _bCommandClearSW  THEN
		_bHaveCommand := FALSE;
	END_IF

	IF GDB.Error.Error_Code <> 0 OR GDB.Mode.Active = FALSE OR _bStopSW THEN
		_nScenarioStep := 0;
	END_IF

//=======================================================================================================	
// Sequence

	CASE _nScenarioStep OF
		10 :
			IF _bHaveCommand THEN
				_stCommandList := _stBeforeCommandList;
				_nCommandEA := _nBeforeCommandEA;
				_nCommandNum := _nBeforeCommandNum;
				_nScenarioStep := 30;
			ELSE
				_nCurrentRepeatCnt := 0;
				_nCommandEA := 0;
				_nScenarioStep := 20;
			END_IF

		20 :
			FOR _nIndex := 1 TO 30 BY 1 DO
				IF _stCommandList[_nIndex].nCommandType <> 0 THEN
					_nCommandEA := _nCommandEA + 1;
				ELSE
					EXIT;
				END_IF
			END_FOR

			IF _nCommandEA = 0 THEN
				_nScenarioStep := 0;
			ELSE
				_stBeforeCommandList := _stCommandList;
				_nBeforeCommandEA :=_nCommandEA;
				_bHaveCommand := TRUE;
				_nCommandNum := 1;
				_nScenarioStep := 30;
			END_IF

		30 : 
			_nBeforeCommandNum := _nCommandNum;

			IF GDB.Auto.Main.Step = 2 THEN
				GDB.Touch.S25_Command_Type := _stCommandList[_nCommandNum].nCommandType;
				GDB.Touch.S25_Dest_Node := _stCommandList[_nCommandNum].nTargetNode;
				GDB.Touch.S25_SpinTurn_Target_Angle := _stCommandList[_nCommandNum].fSpinTurnAngle;
				_nScenarioStep	:= 35;
			END_IF

		35:

			GDB.Touch.S25_SemiAuto_Start_SW := FALSE;

			IF GDB.Auto.Main.Step = 100 THEN
				_nScenarioStep := 40;	
			END_IF

		40 :
			_nCommandNum := _nCommandNum + 1;
			IF _nCommandNum <= _nCommandEA THEN
				_nScenarioStep := 30;
			ELSE	
				IF _nRepeatCnt > 0 THEN	
					_nCurrentRepeatCnt := _nCurrentRepeatCnt + 1;
					IF _nCurrentRepeatCnt < _nRepeatCnt THEN
						_nCommandNum := 1;
						_nScenarioStep := 30;
					ELSE
						_bHaveCommand := FALSE;
						_nScenarioStep := 0;
					END_IF
				ELSE
					_bHaveCommand := FALSE;
					_nScenarioStep := 0;
				END_IF			
			END_IF		
	END_CASE

	TON[1](IN := GDB.Touch.S25_SemiAuto_Start_SW, PT := T#50MS);
	IF TON[1].Q THEN
		GDB.Touch.S25_SemiAuto_Start_SW := FALSE;
	END_IF

