PROGRAM Semi_Auto_Part
VAR
Offline_Path_Search_Instance	:Offline_Path_Search;
PN_Pulse	:ARRAY[0..0] OF PN_Pulse;
TON	:ARRAY[0..0] OF TON;
TOF	:ARRAY[0..0] OF TOF;
Loop_Index	:INT;
END_VAR


//Initialize
GDB.semi_auto.Command_Start_Bit := FALSE;
GDB.semi_auto.Renew_Bit := FALSE;
GDB.semi_auto.out_Complete := FALSE;
GDB.semi_auto.out_Error_Not_Exist_Node := FALSE;
IF GDB.mode.Semi_Auto AND GDB.auto.Main.Step = 2 THEN    
    IF GDB.Touch.S25_SemiAuto_Start_SW AND GDB.Touch.S25_Command_Type <> 0 THEN
		FOR Loop_Index := 0 TO 1000 BY 1 DO //Conversion_In_Data_Clear
            GDB.Data_Conversion.in_Data[Loop_Index] := 0;
        END_FOR;	
		// 1:Loading , 2:Unloading , 3:Move
        IF GDB.Touch.S25_Command_Type >= 1 AND GDB.Touch.S25_Command_Type <= 3  AND GDB.Touch.S25_Dest_Node <> 0 THEN 
            GDB.semi_auto.Renew_Bit := TRUE;
		// 4:Charge	
        ELSIF GDB.Touch.S25_Command_Type = 4 AND GDB.Touch.S25_Dest_Node <> 0 THEN
            GDB.semi_auto.Command_Start_Bit := TRUE;
            GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
            GDB.Data_Conversion.in_Dest_Node := GDB.Touch.S25_Dest_Node;
			GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0;
		// 5:SpinTurn	
        ELSIF GDB.Touch.S25_Command_Type = 5 THEN
            GDB.semi_auto.Command_Start_Bit := TRUE;
            GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
            GDB.Data_Conversion.in_Dest_Node := 0;
            GDB.Data_Conversion.in_SpinTurn_Target_Angle := GDB.Touch.S25_SpinTurn_Target_Angle;
        END_IF;
    END_IF;
    Offline_Path_Search_Instance(Renew_Bit := GDB.semi_auto.Renew_Bit,
                                  in_Start_Node := GDB_Retain.Current_Node,
                                  in_End_Node := GDB.Touch.S25_Dest_Node,
                                  out_Complete => GDB.semi_auto.out_Complete,
                                  out_Path_Count => GDB.semi_auto.out_Path_Count,
                                  out_Path_Length_mm => GDB.semi_auto.out_Path_Length_mm,
                                  out_Path => GDB.semi_auto.out_Path,
                                  out_Error_Not_Exist_Node => GDB.semi_auto.out_Error_Not_Exist_Node);
    IF GDB.semi_auto.out_Complete  //경로계산 완료한 경우,
		OR (GDB.semi_auto.out_Error_Not_Exist_Node AND GDB_Retain.Current_Node = GDB.Touch.S25_Dest_Node) THEN //경로계산은 실패했지만 현재노드가 목적노드인 경우,
        GDB.semi_auto.Command_Start_Bit := TRUE;		
        GDB.Data_Conversion.in_Command_Type := GDB.Touch.S25_Command_Type;
        GDB.Data_Conversion.in_Dest_Node := GDB.Touch.S25_Dest_Node;
		GDB.Data_Conversion.in_SpinTurn_Target_Angle := 0;
        FOR Loop_Index := 1 TO 999 BY 1 DO
            GDB.Data_Conversion.in_Data[Loop_Index] := GDB.semi_auto.out_Path[Loop_Index+1];
        END_FOR;
    END_IF;
END_IF;

