Setting IPS Auto Teaching

PROGRAM Setting_IPS_Auto_Teaching
VAR

	Step : INT;
	//Lift_Control
	Lift_Pos_Move : BOOL;
	Lift_Target_Pos : REAL;
	Lift_Direction : INT;
	Lift_Speed_mpm : REAL;
	//Tilting_Control	
	Tilting_Direction : INT;
	Tilting_Speed : REAL;
	Tilting_AccelSpeed : REAL;
	Tilting_DecelSpeed : REAL;

	//Data
	Data_Raise_Point_Lift_Pos : REAL;
	Data_Loading_Point_Lift_Pos : REAL;
	Data_Unloading_Point_Lift_Pos : REAL;
	Data_Loading_IPS_HP_X : REAL;
	Data_Loading_IPS_HP_Y : REAL;
	Data_Loading_IPS_OP_X : REAL;
	Data_Loading_IPS_OP_Y : REAL;
	Data_Unloading_IPS_HP_X : REAL;
	Data_Unloading_IPS_HP_Y : REAL;
	Data_Unloading_IPS_OP_X : REAL;
	Data_Unloading_IPS_OP_Y : REAL;




	//Sum
	Sum_Count_HP	: INT;
	Sum_IPS_HP_X : REAL;
	Sum_IPS_HP_Y : REAL;
	Sum_Count_OP	: INT;
	Sum_IPS_OP_X : REAL;
	Sum_IPS_OP_Y : REAL;

	//Step_3
	Auto_Lift_Load : Auto_Lift_Load;

	PN_Pulse	:ARRAY[0..2] OF PN_Pulse;
	TON	:ARRAY[0..8] OF TON;
	TOF	:ARRAY[0..0] OF TOF;
	Angle_Calcuration	:ARRAY[0..0] OF Angle_Calcuration;
	Loop_Index : INT;
END_VAR



//Initialize
GDB.Touch.S901_IPS_AutoTeaching_Node_Type_Ready_Lamp := FALSE;
GDB.Touch.S901_IPS_AutoTeaching_Node_Turret_Port_Ready_Lamp := FALSE;
GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction := 0;
GDB.Touch.S901_IPS_AutoTeaching_Node_NAV_Pos_Ready_Lamp := FALSE;
GDB.Touch.S901_IPS_AutoTeaching_Node_UpDown_Distance_Ready_Lamp := FALSE;
gdb.touch.S901_IPS_AutoTeaching_Timeout := FALSE;
Lift_Pos_Move := FALSE;
Lift_Target_Pos := 0;
Lift_Direction := 0;
Lift_Speed_mpm := 0;
Tilting_Direction := 0;
Tilting_Speed := 0;
Tilting_AccelSpeed := 0;
Tilting_DecelSpeed := 0;

//Ready
	//Node_Type
IF GDB_Retain.Node[GDB_Retain.Current_Node]._TYPE = 2 THEN
	GDB.Touch.S901_IPS_AutoTeaching_Node_Type_Ready_Lamp := TRUE;
END_IF;
	//Turret_Port_Select
IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 <> 0 THEN
	GDB.Touch.S901_IPS_AutoTeaching_Node_Turret_Port_Ready_Lamp := TRUE;
END_IF;
	//Y_Shift_Direction
IF GDB.Monitor.Current_Y_Shift_Pos > 270.0 THEN
	GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction := 1;
ELSIF GDB.Monitor.Current_Y_Shift_Pos < -270.0 THEN
	GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction := 2;
END_IF;
	//NAV_Pos
IF 		GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 1 
	AND ABS(GDB_Retain.Node[GDB_Retain.Current_Node].X - GDB.Monitor.Current_X) < 50.0
	AND ABS(GDB_Retain.Node[GDB_Retain.Current_Node].Y - GDB.Monitor.Current_Y) < 50.0 THEN
		GDB.Touch.S901_IPS_AutoTeaching_Node_NAV_Pos_Ready_Lamp := TRUE;
ELSIF 	GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 2 
	AND ABS((GDB_Retain.Node[GDB_Retain.Current_Node].X - GDB_Retain.Node[GDB_Retain.Current_Node].Docking_Right_X_Offset)- GDB.Monitor.Current_X) < 50.0
	AND ABS((GDB_Retain.Node[GDB_Retain.Current_Node].Y - GDB_Retain.Node[GDB_Retain.Current_Node].Docking_Right_Y_Offset)- GDB.Monitor.Current_Y) < 50.0 THEN
		GDB.Touch.S901_IPS_AutoTeaching_Node_NAV_Pos_Ready_Lamp := TRUE;
END_IF;	
	//S901_IPS_AutoTeaching_Node_UpDown_Distance_Ready_Lamp
IF 	(GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1
	AND (GDB.Touch.S901_IPS_AutoTeaching_DOWN_Distance) > 80)
	OR (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2
	AND (GDB.Touch.S901_IPS_AutoTeaching_UP_Distance + GDB.Touch.S901_IPS_AutoTeaching_DOWN_Distance) > 120) THEN
	GDB.Touch.S901_IPS_AutoTeaching_Node_UpDown_Distance_Ready_Lamp := TRUE;
END_IF;

//Step_Set
IF TRUE THEN
    //Step_Start
    PN_Pulse[1](in_Type := 1,
                 in_Signal := 		Step = 0
								AND	GDB.Touch.S901_IPS_AutoTeaching_Node_Type_Ready_Lamp = TRUE
								AND GDB.Touch.S901_IPS_AutoTeaching_Node_Turret_Port_Ready_Lamp = TRUE
								AND GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction <> 0
								AND GDB.Touch.S901_IPS_AutoTeaching_Node_NAV_Pos_Ready_Lamp = TRUE
								AND GDB.Touch.S901_IPS_AutoTeaching_Node_UpDown_Distance_Ready_Lamp = TRUE
								AND GDB.Touch.S901_IPS_AutoTeaching_Start = TRUE);				 				 								
    IF PN_Pulse[1].out_Pulse THEN
        Step := 1;
    END_IF;

    //Step_Clear
		//TIMEOUT_Timer
//	TON[7](IN:= Step <> 0, PT:= T#300S);
	IF TON[7].Q THEN
		Step := 0;
		gdb.touch.S901_IPS_AutoTeaching_Timeout := TRUE;
	END_IF;
    IF 		GDB.Mode.Manual = FALSE
		OR  GDB.Error.Error_Code <> 0
		OR 	GDB.Touch.S901_IPS_AutoTeaching_Stop
		OR	GDB.Touch.S901_IPS_AutoTeaching_Node_Type_Ready_Lamp = FALSE
		OR GDB.Touch.S901_IPS_AutoTeaching_Node_Turret_Port_Ready_Lamp = FALSE
		OR GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 0
		OR GDB.Touch.S901_IPS_AutoTeaching_Node_NAV_Pos_Ready_Lamp = FALSE
		OR GDB.Touch.S901_IPS_AutoTeaching_Node_UpDown_Distance_Ready_Lamp = FALSE
	THEN
        Step := 0;
    END_IF;    
END_IF;






//Step_1 : X_Shift_Revision
IF Step = 1 THEN	
	gdb.touch.S901_IPS_AutoTeaching_Complete := FALSE;
	gdb.touch.S901_IPS_AutoTeaching_Timeout := FALSE;
	GDB.Unit.Drive.Move_Data.Difference_mm_X := (GDB.monitor.X_Axis_HP_Distance_mm - GDB.monitor.X_Axis_OP_Distance_mm);
	//Complete
	TON[1](IN:= ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0 , PT:= T#300MS);
	IF TON[1].Q THEN
		Step := 3; 
	END_IF;
END_IF;

//Step_3 : (Y_Shift,Theta,Tilting)Servo_OFF & LIFT_UP
PN_Pulse[2](in_Type:= 1, in_Signal:= Step = 3);
IF Step = 3 THEN
	Auto_Lift_Load(	Enable:= TRUE, 
					Renew:= PN_Pulse[2].out_Pulse, 
					in_Loadcell_Value_kg:= GDB.Monitor.Fork_Both_Loadcell_kg, 
					in_Min_Weight_Kg:= 50.0, 
					in_Max_Weight_Kg:= 500.0,
					in_Turret_Weight_kg:= 0, 
					in_Current_Speed_mps:= GDB.Unit.Drive.Lift_Drive.CurrentSpeed_mps, 
					in_Motor_Current:= GDB.Unit.Drive.Lift_Drive.in1_70_Actual_Current, 
					in_Actual_Lift_Pos:= GDB.monitor.Current_Lift_Pos,
					out_Lift_Direction => Lift_Direction,
					out_Lift_Speed_mpm => Lift_Speed_mpm);

	(*
	IF GDB.Monitor.Fork_Both_Loadcell_kg > 205 THEN
		Lift_Direction := 2;	
	ELSIF GDB.Monitor.Fork_Both_Loadcell_kg < 195 THEN
		Lift_Direction := 1;	
	END_IF;	
	IF GDB.Monitor.Fork_Both_Loadcell_kg > 50.0 THEN
		Lift_Speed_mpm := 0.05;
	ELSE
		Lift_Speed_mpm := 0.2;
	END_IF	
	*)
	//Complete
	//TON[8](IN:= ABS(GDB.Monitor.Fork_Both_Loadcell_kg-200) < 10, PT:= T#200MS);
	IF (*TON[8].Q*) Auto_Lift_Load.out_Load_Complete THEN
		Step := 5; 
	END_IF;
END_IF


//Step_5 : Raise_Point_Pos_Search
TON[2](IN:= Step = 5, PT:= T#300MS); //Servo_On Delay
IF Step = 5  AND TON[2].Q THEN
	IF GDB.Monitor.Fork_Both_Loadcell_kg > 105 THEN
		Lift_Direction := 2;
		Lift_Speed_mpm := 0.03;	
	ELSIF GDB.Monitor.Fork_Both_Loadcell_kg < 95 THEN
		Lift_Direction := 1;
		Lift_Speed_mpm := 0.03;	
	END_IF;	
	//Complete
	TON[4](IN:= ABS(GDB.Monitor.Fork_Both_Loadcell_kg-100) < 10, PT:= T#500MS);
	IF TON[4].Q THEN
		Data_Raise_Point_Lift_Pos := GDB.Monitor.Current_Lift_Pos;
		Step := 7;
	END_IF;
END_IF;


//Step_7 : Tilting_Revision
IF Step = 7 THEN
	IF GDB.Monitor.Fork_HP_Loadcell_kg - GDB.Monitor.Fork_OP_Loadcell_kg > 3.0 THEN
		Tilting_Direction := 1;
	ELSIF GDB.Monitor.Fork_HP_Loadcell_kg - GDB.Monitor.Fork_OP_Loadcell_kg < -3.0 THEN
		Tilting_Direction := 2;
	END_IF;	
	Tilting_Speed := 1.0;
	Tilting_AccelSpeed := 100.0;
	Tilting_DecelSpeed := 200.0;	
	//Complete
	TON[3](IN:= ABS(GDB.Monitor.Fork_HP_Loadcell_kg - GDB.Monitor.Fork_OP_Loadcell_kg) < 5.0 , PT:= T#200MS);
	IF TON[3].Q THEN
		Step := 9; 
	END_IF;
END_IF;


//Step_9 : Unload Pos Move
IF Step = 9 THEN
	IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
		//Complete
		IF 		GDB.Unit.IPS208i.Program_Change_OK_HP
			AND GDB.Unit.IPS208i.Program_Change_OK_OP  THEN
			Step := 11;
			Data_Unloading_Point_Lift_Pos := GDB.Monitor.Current_Lift_Pos;
		END_IF;		
	ELSIF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 THEN
		Lift_Pos_Move := TRUE;
		Lift_Target_Pos := Data_Raise_Point_Lift_Pos + GDB.Touch.S901_IPS_AutoTeaching_UP_Distance;
		Lift_Speed_mpm := 0.6;
		//Complete
		TON[5](IN:= ABS(Lift_Target_Pos - GDB.Monitor.Current_Lift_Pos) < 0.5, PT:= T#500MS);
		IF 		TON[5].Q 
			AND GDB.Unit.IPS208i.Program_Change_OK_HP
			AND GDB.Unit.IPS208i.Program_Change_OK_OP  THEN
			Step := 11;
			Data_Unloading_Point_Lift_Pos := GDB.Monitor.Current_Lift_Pos;
		END_IF;
	END_IF;	
	Sum_Count_HP := 1;
	Sum_IPS_HP_X := 0;
	Sum_IPS_HP_Y := 0;
	Sum_Count_OP := 1;
	Sum_IPS_OP_X := 0;
	Sum_IPS_OP_Y := 0;
END_IF;

//Step_11 : Unload Pos IPS Data SET
IF Step = 11 THEN
		//HP
	IF  GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_HP
		AND GDB.Unit.IPS208i.iState_HP = 0
		AND Sum_Count_HP < 11 THEN		
		Sum_IPS_HP_X := Sum_IPS_HP_X + GDB.Unit.IPS208i.rXpos_RealData_HP;
		Sum_IPS_HP_Y := Sum_IPS_HP_Y + GDB.Unit.IPS208i.rYpos_RealData_HP;				
		IF Sum_Count_HP = 10 THEN
			Data_Unloading_IPS_HP_X := Sum_IPS_HP_X / Sum_Count_HP;
			Data_Unloading_IPS_HP_Y := Sum_IPS_HP_Y / Sum_Count_HP;
		END_IF;
		Sum_Count_HP := Sum_Count_HP + 1;
	END_IF;
		//OP
	IF  GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_OP
		AND GDB.Unit.IPS208i.iState_OP = 0
		AND Sum_Count_OP < 11 THEN		
		Sum_IPS_OP_X := Sum_IPS_OP_X + GDB.Unit.IPS208i.rXpos_RealData_OP;
		Sum_IPS_OP_Y := Sum_IPS_OP_Y + GDB.Unit.IPS208i.rYpos_RealData_OP;		
		IF Sum_Count_OP = 10 THEN
			Data_Unloading_IPS_OP_X := Sum_IPS_OP_X / Sum_Count_OP;
			Data_Unloading_IPS_OP_Y := Sum_IPS_OP_Y / Sum_Count_OP;
		END_IF;
		Sum_Count_OP := Sum_Count_OP + 1;
	END_IF;	
	//Complete
	IF Sum_Count_HP = 11 AND Sum_Count_OP = 11 THEN
		Step := 13;
	END_IF;
END_IF;

//Step_13 : Load Pos Move
IF Step = 13 THEN
	Lift_Pos_Move := TRUE;
	Lift_Target_Pos := Data_Raise_Point_Lift_Pos - GDB.Touch.S901_IPS_AutoTeaching_DOWN_Distance;
	Lift_Speed_mpm := 0.6;
	//Complete
	TON[6](IN:= ABS(Lift_Target_Pos - GDB.Monitor.Current_Lift_Pos) < 0.5, PT:= T#500MS);
	IF 		TON[6].Q 
		AND GDB.Unit.IPS208i.Program_Change_OK_HP
		AND GDB.Unit.IPS208i.Program_Change_OK_OP  THEN
		Step := 15;
		Data_Loading_Point_Lift_Pos := GDB.Monitor.Current_Lift_Pos;
	END_IF;	
	Sum_Count_HP := 1;
	Sum_IPS_HP_X := 0;
	Sum_IPS_HP_Y := 0;
	Sum_Count_OP := 1;
	Sum_IPS_OP_X := 0;
	Sum_IPS_OP_Y := 0;
END_IF;

//Step_15 : Unload Pos IPS Data SET
IF Step = 15 THEN
		//HP
	IF  GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_HP
		AND GDB.Unit.IPS208i.iState_HP = 0
		AND Sum_Count_HP < 11 THEN		
		Sum_IPS_HP_X := Sum_IPS_HP_X + GDB.Unit.IPS208i.rXpos_RealData_HP;
		Sum_IPS_HP_Y := Sum_IPS_HP_Y + GDB.Unit.IPS208i.rYpos_RealData_HP;				
		IF Sum_Count_HP = 10 THEN
			Data_Loading_IPS_HP_X := Sum_IPS_HP_X / Sum_Count_HP;
			Data_Loading_IPS_HP_Y := Sum_IPS_HP_Y / Sum_Count_HP;
		END_IF;
		Sum_Count_HP := Sum_Count_HP + 1;
	END_IF;
		//OP
	IF  GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_OP
		AND GDB.Unit.IPS208i.iState_OP = 0
		AND Sum_Count_OP < 11 THEN			
		Sum_IPS_OP_X := Sum_IPS_OP_X + GDB.Unit.IPS208i.rXpos_RealData_OP;
		Sum_IPS_OP_Y := Sum_IPS_OP_Y + GDB.Unit.IPS208i.rYpos_RealData_OP;		
		IF Sum_Count_OP = 10 THEN
			Data_Loading_IPS_OP_X := Sum_IPS_OP_X / Sum_Count_OP;
			Data_Loading_IPS_OP_Y := Sum_IPS_OP_Y / Sum_Count_OP;
		END_IF;
		Sum_Count_OP := Sum_Count_OP + 1;
	END_IF;	
	//Complete
	IF Sum_Count_HP = 11 AND Sum_Count_OP = 11 THEN
		Step := 99;
	END_IF;
END_IF;



//Step_99 : Complete
IF Step = 99 THEN	
	//Loading_Data_Insert
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Lift_Pos 							:=  Data_Loading_Point_Lift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Y_Shift_Pos 						:=	GDB.Touch.S901_IPS_AutoTeaching_Ready_Y_Shift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Ready_Y_Navi_Pos 							:=	GDB.Touch.S901_IPS_AutoTeaching_Ready_Y_Navi_Pos;
	IF GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 1 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_HP_IPS_X 					:=	Data_Loading_IPS_HP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_HP_IPS_Y 					:=	Data_Loading_IPS_HP_Y;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_OP_IPS_X 					:=	Data_Loading_IPS_OP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Left_OP_IPS_Y 					:=	Data_Loading_IPS_OP_Y;
	ELSIF GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 2 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_HP_IPS_X 				:=	Data_Loading_IPS_HP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_HP_IPS_Y 				:=	Data_Loading_IPS_HP_Y;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_OP_IPS_X 				:=	Data_Loading_IPS_OP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Right_OP_IPS_Y 				:=	Data_Loading_IPS_OP_Y;
	END_IF
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Zero_Angle_IPS_Y 			:=	(Data_Loading_IPS_HP_Y + Data_Loading_IPS_OP_Y)/2;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Chuck_X_Pos_Before 			:=	GDB.Touch.S901_IPS_AutoTeaching_Chuck_X_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Chuck_Y_Pos_Before 			:=	GDB.Touch.S901_IPS_AutoTeaching_Chuck_Y_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Reflector_X_Pos_Before 		:=	GDB.Touch.S901_IPS_AutoTeaching_Reflector_X_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_5_Turret_Reflector_Y_Pos_Before 		:=	GDB.Touch.S901_IPS_AutoTeaching_Reflector_Y_Pos_Before;
	IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_DT 							:=	Data_Unloading_Point_Lift_Pos - Data_Loading_Point_Lift_Pos - 5;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_Start_DT 				:=	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_DT - 20;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_End_DT 					:=	GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_DT;
	ELSIF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_DT 							:=	Data_Unloading_Point_Lift_Pos - Data_Loading_Point_Lift_Pos;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_Start_DT 				:=	Data_Raise_Point_Lift_Pos - Data_Loading_Point_Lift_Pos - 20;
		GDB_Retain.Node[GDB_Retain.Current_Node].Loading_Data.Step_7_Lift_Decel_End_DT 					:=	Data_Raise_Point_Lift_Pos - Data_Loading_Point_Lift_Pos + 20;

	END_IF;	
	//Unloading_Data_Insert
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Lift_Pos 							:=  Data_Unloading_Point_Lift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Y_Shift_Pos 						:=	GDB.Touch.S901_IPS_AutoTeaching_Ready_Y_Shift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Ready_Y_Navi_Pos 						:=	GDB.Touch.S901_IPS_AutoTeaching_Ready_Y_Navi_Pos;
	IF GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 1 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Left_HP_IPS_X 				:=	Data_Unloading_IPS_HP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Left_HP_IPS_Y 				:=	Data_Unloading_IPS_HP_Y;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Left_OP_IPS_X 				:=	Data_Unloading_IPS_OP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Left_OP_IPS_Y 				:=	Data_Unloading_IPS_OP_Y;
	ELSIF GDB.Touch.S901_IPS_AutoTeaching_Node_Y_Shift_Direction = 2 THEN
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Right_HP_IPS_X 				:=	Data_Unloading_IPS_HP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Right_HP_IPS_Y 				:=	Data_Unloading_IPS_HP_Y;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Right_OP_IPS_X 				:=	Data_Unloading_IPS_OP_X;
		GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Right_OP_IPS_Y 				:=	Data_Unloading_IPS_OP_Y;
	END_IF	
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Zero_Angle_IPS_Y 			:=	(Data_Unloading_IPS_HP_Y + Data_Unloading_IPS_OP_Y)/2;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Chuck_X_Pos_Before 		:=	GDB.Touch.S901_IPS_AutoTeaching_Chuck_X_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Chuck_Y_Pos_Before 		:=	GDB.Touch.S901_IPS_AutoTeaching_Chuck_Y_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Reflector_X_Pos_Before 	:=	GDB.Touch.S901_IPS_AutoTeaching_Reflector_X_Pos_Before;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_5_Turret_Reflector_Y_Pos_Before 	:=	GDB.Touch.S901_IPS_AutoTeaching_Reflector_Y_Pos_Before;
	IF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1 THEN
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_DT 						:=	Data_Unloading_Point_Lift_Pos - Data_Loading_Point_Lift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_Decel_Start_DT 			:=	0;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_Decel_End_DT 				:=	20;				
	ELSIF GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 2 THEN	
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_DT 						:=	Data_Unloading_Point_Lift_Pos - Data_Loading_Point_Lift_Pos;
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_Decel_Start_DT 			:=	Data_Unloading_Point_Lift_Pos - (Data_Raise_Point_Lift_Pos + 20);
	GDB_Retain.Node[GDB_Retain.Current_Node].UnLoading_Data.Step_13_Lift_Decel_End_DT 				:=	Data_Unloading_Point_Lift_Pos - (Data_Raise_Point_Lift_Pos - 20);		
	END_IF

	gdb.touch.S901_IPS_AutoTeaching_Complete := TRUE;
	Step := 0;
END_IF;


