	GDB_Parameter.Zapi_Drive_Port_BwTravel := 16#1004; //[I/O >> Device(EL6751) >> 각 해당 Box 클릭 >> ADS 탭에서 확인 가능]
	GDB_Parameter.Zapi_Drive_Port_FwSteering := 16#1006; //[I/O >> Device(EL6751) >> 각 해당 Box 클릭 >> ADS 탭에서 확인 가능]
	GDB_Parameter.Zapi_Drive_Port_BwSteering := 16#1008; //[I/O >> Device(EL6751) >> 각 해당 Box 클릭 >> ADS 탭에서 확인 가능]
	GDB_Parameter.Zapi_Drive_Port_Lift := 16#100A; //[I/O >> Device(EL6751) >> 각 해당 Box 클릭 >> ADS 탭에서 확인 가능]

	(* 포일 + 점보롤 ID로 구분 할 시,
	IF GDB_Parameter.Vehicle_ID = ?? THEN
