==================================================
Unit Drive Beckhoff

PROGRAM Unit_Drive_Beckhoff
VAR
	//11.X_Shift_Control
		X_Shift_Control_TON 		: ARRAY[0..0] OF TON;
		X_Shift_Control_PN_Pulse 	: ARRAY[0..2] OF PN_Pulse;
	//12.Y_Shift_Control
		Y_Shift_Control_TON 		: ARRAY[0..0] OF TON;
		Y_Shift_Control_PN_Pulse 	: ARRAY[0..2] OF PN_Pulse;
	//13.Theta_Control
		Theta_Control_TON 			: ARRAY[0..0] OF TON;
		Theta_Control_PN_Pulse 		: ARRAY[0..2] OF PN_Pulse;
	//14.Tilting_Control
		Tilting_Control_TON 		: ARRAY[0..0] OF TON;
		Tilting_Control_PN_Pulse 	: ARRAY[0..2] OF PN_Pulse;
	//15.Y_Navi_Control
		Y_Navi_Control_TON 			: ARRAY[0..2] OF TON;
		Y_Navi_Control_PN_Pulse 	: ARRAY[0..2] OF PN_Pulse;

	//21.X_Shift
	MC_Power_X_Shift : MC_Power;
	MC_Stop_X_Shift : MC_Stop;
	MC_Halt_X_Shift : MC_Halt;
	MC_Reset_X_Shift : MC_Reset;
	MC_Jog_X_Shift : MC_Jog;
	MC_MoveAbsolute_X_Shift : MC_MoveAbsolute;
	//22.Y_Shift
	MC_Power_Y_Shift : MC_Power;
	MC_Stop_Y_Shift : MC_Stop;
	MC_Halt_Y_Shift : MC_Halt;
	MC_Reset_Y_Shift : MC_Reset;
	MC_Jog_Y_Shift : MC_Jog;
	MC_MoveAbsolute_Y_Shift : MC_MoveAbsolute;
	//23.Theta
	MC_Power_Theta : MC_Power;
	MC_Stop_Theta : MC_Stop;
	MC_Halt_Theta : MC_Halt;
	MC_Reset_Theta : MC_Reset;
	MC_Jog_Theta : MC_Jog;
	MC_MoveAbsolute_Theta : MC_MoveAbsolute;
	//24.Tilting
	MC_Power_Tilting : MC_Power;
	MC_Stop_Tilting : MC_Stop;
	MC_Halt_Tilting : MC_Halt;
	MC_Reset_Tilting : MC_Reset;
	MC_Jog_Tilting : MC_Jog;
	MC_MoveAbsolute_Tilting : MC_MoveAbsolute;
	//25.Y_Navi
	MC_Power_Y_Navi : MC_Power;
	MC_Stop_Y_Navi : MC_Stop;
	MC_Halt_Y_Navi : MC_Halt;
	MC_Reset_Y_Navi : MC_Reset;
	MC_Jog_Y_Navi : MC_Jog;
	MC_MoveAbsolute_Y_Navi : MC_MoveAbsolute;

	//Test
	X_Timer : ARRAY[0..2] OF TON;
	R_TRIG : R_TRIG;
	R_TRIGER : ARRAY[0..2] OF R_TRIG;
	TOF : ARRAY[0..2] OF TOF;
	fbMC_SetEncoderScalingFactor: MC_SetEncoderScalingFactor;
	fbADSWRITE_X_Shift : ADSWRITE;
END_VAR






	//11. X_Shift Control
	IF TRUE THEN
		//Initialize
		GDB.Unit.Drive.X_Shift_Drive.Control_MC_Power_On := TRUE;
		GDB.Unit.Drive.X_Shift_Drive.Control_Stop := FALSE;
		GDB.Unit.Drive.X_Shift_Drive.Control_Halt := FALSE;
		GDB.Unit.Drive.X_Shift_Drive.Control_Reset := FALSE;
		GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Fwd := FALSE;
		GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Bwd := FALSE;
		GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start := FALSE;



		R_TRIGER[1](CLK:=GDB.Touch.S901_MAP_Data_Insert = TRUE);
		X_Timer[1](in:= GDB.Touch.S901_MAP_Data_Insert = TRUE, PT:= T#1S);

			IF 		(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 AND ( GDB.Auto._1_Loading.Step.9 OR GDB.Auto._1_Loading.Step.11 OR GDB.Auto._2_Unloading.Step.11)) 
				OR	(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 2 AND ( GDB.Auto._1_Loading.Step.7 OR GDB.Auto._2_Unloading.Step.7 )) 
				OR	gdb.Touch.S901_Servo_Off_X_Shift OR X_Timer[1].Q OR R_TRIGER[1].Q THEN				
				GDB.Unit.Drive.X_Shift_Drive.Control_MC_Power_On := FALSE;
			END_IF;
		//Stop
			X_Shift_Control_PN_Pulse[1](in_Type:= 2,
									 	in_Signal:= (GDB.Mode.Active));
//									 	in_Signal:= (GDB.Mode.Manual AND (GDB.manual.X_Shift_PosMove_Start))
//												OR	(GDB.Mode.Active));
			IF GDB.Error.Error_On_Bit OR X_Shift_Control_PN_Pulse[1].out_Pulse THEN
				GDB.Unit.Drive.X_Shift_Drive.Control_Stop := TRUE;
			END_IF;

		//Halt	
			X_Shift_Control_PN_Pulse[2](in_Type:= 2, in_Signal:= (GDB.Mode.Manual AND GDB.manual.X_Shift_PosMove_Start));
			IF X_Shift_Control_PN_Pulse[2].out_Pulse THEN
				GDB.Unit.Drive.X_Shift_Drive.Control_Halt := TRUE;
			END_IF;	

 		//Reset
			IF GDB.Mode.Reset THEN
				GDB.Unit.Drive.X_Shift_Drive.Control_Reset := TRUE;
			END_IF;
		//Move
		IF GDB.Error.Error_On_Bit = FALSE AND GDB.Unit.Drive.X_Shift_Drive.Status_Ready THEN
			//Jog
				//Manual
				IF GDB.mode.Manual THEN
					IF GDB.manual.X_Shift_Jog_Direction = 1 THEN
						GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Fwd 	:= TRUE;
					ELSIF GDB.manual.X_Shift_Jog_Direction = 2 THEN
						GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Bwd 	:= TRUE;
					END_IF;			
                    //GDB.manual.X_Shift_Speed := LIMIT(0, GDB.manual.X_Shift_Speed,5);				
					GDB.Unit.Drive.X_Shift_Drive.Control_Speed 				:= GDB.manual.X_Shift_Speed;
					GDB.Unit.Drive.X_Shift_Drive.Control_AccelSpeed 		:= GDB.manual.X_Shift_AccelSpeed;
					GDB.Unit.Drive.X_Shift_Drive.Control_DecelSpeed 		:= GDB.manual.X_Shift_DecelSpeed;
				END_IF;
				//Loading_Step_3 /Loading_Step_5 / Loading_Step_13 / Unloading_Step_3 / Unloading_Step_5
				IF 		GDB.monitor.X_Axis_Distance_OK
					AND (	GDB.Auto._1_Loading.Step = 3 
						OR GDB.Auto._1_Loading.Step = 5 
						OR GDB.Auto._1_Loading.Step = 13  
						OR GDB.Auto._2_Unloading.Step = 3 
						OR GDB.Auto._2_Unloading.Step = 5 
						OR GDB.Auto._2_Unloading.Step = 21
						OR Setting_IPS_Auto_Teaching.Step = 1
						OR (GDB.Mode.Manual AND GDB.Touch.S901_NodeTeaching_X_Shift_Center)
							) THEN
							IF GDB.Unit.Drive.Move_Data.Difference_mm_X > 0.4 THEN
								GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Fwd 	:= TRUE;
							ELSIF GDB.Unit.Drive.Move_Data.Difference_mm_X < -0.4	THEN
								GDB.Unit.Drive.X_Shift_Drive.Control_Jog_Bwd 	:= TRUE;
							END_IF;
							GDB.Unit.Drive.X_Shift_Drive.Control_Speed 		:= 1.0;
							GDB.Unit.Drive.X_Shift_Drive.Control_AccelSpeed := 10.0;
							GDB.Unit.Drive.X_Shift_Drive.Control_DecelSpeed := 100.0;				
							IF ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) > 5.0 THEN
								GDB.Unit.Drive.X_Shift_Drive.Control_Speed 	:= ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) * 0.2;
							END_IF;
				END_IF;

			//PosMove_Start
				//Manual
				IF (GDB.mode.Manual AND GDB.manual.X_Shift_PosMove_Start) THEN
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start		:= TRUE;
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Position 	:= GDB.manual.X_Shift_Target_Pos;
					GDB.Unit.Drive.X_Shift_Drive.Control_Speed 				:= GDB.manual.X_Shift_Speed;
					GDB.Unit.Drive.X_Shift_Drive.Control_AccelSpeed 		:= GDB.manual.X_Shift_AccelSpeed;
					GDB.Unit.Drive.X_Shift_Drive.Control_DecelSpeed 		:= GDB.manual.X_Shift_DecelSpeed;			
				END_IF;
				//Move_Step_7
				IF GDB.Auto._3_Move.Step = 7 AND 		(GDB.Auto._3_Move.Step_7_Loading_Ready_Bit
													OR	GDB.Auto._3_Move.Step_7_UnLoading_Ready_Bit
													OR	GDB.Auto._3_Move.Step_7_Home_Bit_Over_500mm ) THEN
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start		:= TRUE;
					IF ABS(GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Position - GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift) > 1.0 THEN //Position 바뀔 시, 새로운 Pos로 반영하기 위함
						GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start		:= FALSE;
					END_IF;
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Position 	:= GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift;
					GDB.Unit.Drive.X_Shift_Drive.Control_Speed 				:= 10.0;
					GDB.Unit.Drive.X_Shift_Drive.Control_AccelSpeed 		:= 10.0;
					GDB.Unit.Drive.X_Shift_Drive.Control_DecelSpeed 		:= 20.0;			
				END_IF;

				//Ready_Step_3
				IF GDB.Auto.Ready.Step = 3 THEN
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start		:= TRUE;
					IF ABS(GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Position - GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift) > 1.0 THEN //Position 바뀔 시, 새로운 Pos로 반영하기 위함
						GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Start		:= FALSE;
					END_IF;
					GDB.Unit.Drive.X_Shift_Drive.Control_PosMove_Position 	:= GDB.Unit.Drive.Move_Data.Target_Pos_X_Shift;
					GDB.Unit.Drive.X_Shift_Drive.Control_Speed 				:= 10.0;
					GDB.Unit.Drive.X_Shift_Drive.Control_AccelSpeed 		:= 10.0;
					GDB.Unit.Drive.X_Shift_Drive.Control_DecelSpeed 		:= 20.0;			
				END_IF;
		END_IF;

	END_IF;

	//12. Y_Shift Control
	IF TRUE THEN
		//Initialize
		GDB.Unit.Drive.Y_Shift_Drive.Control_MC_Power_On := TRUE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_Stop := FALSE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_Halt := FALSE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_Reset := FALSE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Fwd := FALSE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Bwd := FALSE;
		GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Start := FALSE;
		//MC_Power_On
			IF 		(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 AND ( GDB.Auto._1_Loading.Step.9 OR GDB.Auto._1_Loading.Step.11 OR GDB.Auto._2_Unloading.Step.11)) 
				OR	(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 2 AND ( GDB.Auto._1_Loading.Step = 7 OR (GDB.Auto._2_Unloading.Step = 13 AND GDB.Monitor.Current_Lift_Pos > 130 )))  
				OR	Setting_IPS_Auto_Teaching.Step = 3 
				OR	gdb.Touch.S901_Servo_Off_Y_Shift THEN
				GDB.Unit.Drive.Y_Shift_Drive.Control_MC_Power_On := FALSE;
			END_IF;
		//Stop
			Y_Shift_Control_PN_Pulse[1](in_Type:= 2,
									 	in_Signal:= (GDB.Mode.Active));
//									 	in_Signal:= (GDB.Mode.Manual AND (GDB.manual.Y_Shift_PosMove_Start))
//												OR	(GDB.Mode.Active));
			IF GDB.Error.Error_On_Bit OR Y_Shift_Control_PN_Pulse[1].out_Pulse THEN
				GDB.Unit.Drive.Y_Shift_Drive.Control_Stop := TRUE;
			END_IF;
		//Halt	
			Y_Shift_Control_PN_Pulse[2](in_Type:= 2, in_Signal:= (GDB.Mode.Manual AND GDB.manual.Y_Shift_PosMove_Start));
			IF Y_Shift_Control_PN_Pulse[2].out_Pulse THEN
				GDB.Unit.Drive.Y_Shift_Drive.Control_Halt := TRUE;
			END_IF;	
		//Reset		
			IF GDB.Mode.Reset THEN
				GDB.Unit.Drive.Y_Shift_Drive.Control_Reset := TRUE;
			END_IF;
		//Move
		IF GDB.Error.Error_On_Bit = FALSE AND GDB.Unit.Drive.Y_Shift_Drive.Status_Ready THEN
			//Jog_Fwd
				//Manual
				IF GDB.mode.Manual THEN
					IF GDB.manual.Y_Shift_Jog_Direction = 1 THEN
						GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Fwd 	:= TRUE;
					ELSIF GDB.manual.Y_Shift_Jog_Direction = 2 THEN
						GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Bwd 	:= TRUE;
					END_IF;				
					//GDB.manual.Y_Shift_Speed := LIMIT(0, GDB.manual.Y_Shift_Speed,5);
					GDB.Unit.Drive.Y_Shift_Drive.Control_Speed 		:= GDB.manual.Y_Shift_Speed;
					GDB.Unit.Drive.Y_Shift_Drive.Control_AccelSpeed := GDB.manual.Y_Shift_AccelSpeed;
					GDB.Unit.Drive.Y_Shift_Drive.Control_DecelSpeed := GDB.manual.Y_Shift_DecelSpeed;
				END_IF;
				//Loading_Step_5 / Unloading_Step_5 
				IF (GDB.Auto._1_Loading.Step = 5 OR GDB.Auto._2_Unloading.Step = 5) THEN
						IF GDB.Unit.Drive.Move_Data.Difference_mm_Y < -0.4 THEN
							GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Fwd 	:= TRUE;
						ELSIF GDB.Unit.Drive.Move_Data.Difference_mm_Y > 0.4 THEN
							GDB.Unit.Drive.Y_Shift_Drive.Control_Jog_Bwd 	:= TRUE;
						END_IF;
						GDB.Unit.Drive.Y_Shift_Drive.Control_Speed 		:= 1.0;
						GDB.Unit.Drive.Y_Shift_Drive.Control_AccelSpeed := 100.0;
						GDB.Unit.Drive.Y_Shift_Drive.Control_DecelSpeed := 100.0;				
						IF ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Y) > 3.0 THEN
							GDB.Unit.Drive.Y_Shift_Drive.Control_Speed 	:= ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Y) * 0.5;
						END_IF;
				END_IF;
			//PosMove_Start
				//Manual
				IF (GDB.mode.Manual AND GDB.manual.Y_Shift_PosMove_Start) THEN
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Start 		:= TRUE;
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Position 	:= GDB.manual.Y_Shift_Target_Pos;
					GDB.Unit.Drive.Y_Shift_Drive.Control_Speed 		:= GDB.manual.Y_Shift_Speed;
					GDB.Unit.Drive.Y_Shift_Drive.Control_AccelSpeed := GDB.manual.Y_Shift_AccelSpeed;
					GDB.Unit.Drive.Y_Shift_Drive.Control_DecelSpeed := GDB.manual.Y_Shift_DecelSpeed;			
				END_IF;
				//Loading_Step_3
				IF GDB.Auto._1_Loading.Step = 3 
					AND ABS(GDB.Unit.Drive.Move_Data.Target_Pos_Lift - GDB.Monitor.Current_Lift_Pos) < 1.0 THEN
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Start 		:= TRUE;
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Position 	:= GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift;
					GDB.Unit.Drive.Y_Shift_Drive.Control_Speed 				:= 80.0;
					GDB.Unit.Drive.Y_Shift_Drive.Control_AccelSpeed 		:= 80.0;
					GDB.Unit.Drive.Y_Shift_Drive.Control_DecelSpeed 		:= 80.0;			
				END_IF;				
				//Loading_Step_13
				IF GDB.Auto._1_Loading.Step = 13 THEN
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Start 		:= TRUE;
					GDB.Unit.Drive.Y_Shift_Drive.Control_PosMove_Position 	:= GDB.Unit.Drive.Move_Data.Target_Pos_Y_Shift;
