			IF 		(GDB_Retain.Node[GDB.Command.Dest_Node].Turret_1_Port_2 = 1 AND ( GDB.Auto._1_Loading.Step.9 ))
				OR	gdb.Touch.S901_Servo_Off_Y_Navi THEN				
				GDB.Unit.Drive.Y_Navi_Drive.Control_MC_Power_On := FALSE;
			END_IF;
		//Stop
			Y_Navi_Control_PN_Pulse[1](in_Type:= 2,
									 	in_Signal:= (GDB.Mode.Active));
//									 	in_Signal:= (GDB.Mode.Manual AND (GDB.manual.Y_Navi_PosMove_Start))
//												OR	(GDB.Mode.Active));
			IF GDB.Error.Error_On_Bit OR Y_Navi_Control_PN_Pulse[1].out_Pulse THEN
				GDB.Unit.Drive.Y_Navi_Drive.Control_Stop := TRUE;
			END_IF;
		//Halt	
			Y_Navi_Control_PN_Pulse[2](in_Type:= 2, in_Signal:= (GDB.Mode.Manual AND GDB.manual.Y_Navi_PosMove_Start));
			IF Y_Navi_Control_PN_Pulse[2].out_Pulse THEN
				GDB.Unit.Drive.Y_Navi_Drive.Control_Halt := TRUE;
			END_IF;
	 	//Reset		
			IF GDB.Mode.Reset THEN
				GDB.Unit.Drive.Y_Navi_Drive.Control_Reset := TRUE;
			END_IF;
		//Move
		IF GDB.Error.Error_On_Bit = FALSE AND GDB.Unit.Drive.Y_Navi_Drive.Status_Ready THEN
			//Jog_Fwd
				//Manual
				IF GDB.mode.Manual THEN
					IF GDB.manual.Y_Navi_Jog_Direction = 1 THEN
						GDB.Unit.Drive.Y_Navi_Drive.Control_Jog_Fwd 	:= TRUE;
					ELSIF GDB.manual.Y_Navi_Jog_Direction = 2 THEN
						GDB.Unit.Drive.Y_Navi_Drive.Control_Jog_Bwd 	:= TRUE;
					END_IF;					
					//GDB.manual.Y_Navi_Speed := LIMIT(0, GDB.manual.Y_Navi_Speed,5);
					GDB.Unit.Drive.Y_Navi_Drive.Control_Speed 			:= GDB.manual.Y_Navi_Speed;
					GDB.Unit.Drive.Y_Navi_Drive.Control_AccelSpeed 		:= GDB.manual.Y_Navi_AccelSpeed;
					GDB.Unit.Drive.Y_Navi_Drive.Control_DecelSpeed 		:= GDB.manual.Y_Navi_DecelSpeed;
				END_IF;
			//PosMove_Start
				//Manual
				IF (GDB.mode.Manual AND GDB.manual.Y_Navi_PosMove_Start) THEN
					GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Start 		:= TRUE;
					GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position 	:= GDB.manual.Y_Navi_Target_Pos;
					GDB.Unit.Drive.Y_Navi_Drive.Control_Speed 			:= GDB.manual.Y_Navi_Speed;
