					GDB.Unit.Drive.Y_Navi_Drive.Control_DecelSpeed 		:= GDB.manual.Y_Navi_DecelSpeed;
				END_IF;
				//Move_Step_7
				IF GDB.Auto._3_Move.Step = 7 AND 		(GDB.Auto._3_Move.Step_7_Loading_Ready_Bit
													OR	GDB.Auto._3_Move.Step_7_UnLoading_Ready_Bit
													OR	GDB.Auto._3_Move.Step_7_Home_Bit_Over_500mm ) THEN
					GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Start 		:= TRUE;
					IF ABS(GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position - GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi) > 1.0 THEN //Position 바뀔 시, 새로운 Pos로 반영하기 위함
						GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Start		:= FALSE;
					END_IF;
					GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position 	:= GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi;
					GDB.Unit.Drive.Y_Navi_Drive.Control_Speed 				:= 100.0;
					GDB.Unit.Drive.Y_Navi_Drive.Control_AccelSpeed 			:= 100.0;
					GDB.Unit.Drive.Y_Navi_Drive.Control_DecelSpeed 			:= 100.0;			
				END_IF;
				//Ready_Step_3
				IF GDB.Auto.Ready.Step = 3 THEN
					GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Start		:= TRUE;
					IF ABS(GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position - GDB.Unit.Drive.Move_Data.Target_Pos_Y_Navi) > 1.0 THEN //Position 바뀔 시, 새로운 Pos로 반영하기 위함
