						Enable:= GDB.Unit.Drive.Y_Navi_Drive.Control_MC_Power_On, 
						Enable_Positive:= TRUE, 
						Enable_Negative:= TRUE, 
						Override:= 100);
		MC_Stop_Y_Navi(Axis:= GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref, 
						Execute:= GDB.Unit.Drive.Y_Navi_Drive.Control_Stop);
		MC_Halt_Y_Navi(Axis:= GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref,
						Execute:= GDB.Unit.Drive.Y_Navi_Drive.Control_Halt);				
		MC_Reset_Y_Navi(Axis:= GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref, 
						Execute:= GDB.Unit.Drive.Y_Navi_Drive.Control_Reset);		
		MC_Jog_Y_Navi(	Axis:= GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref, 
						JogForward:= GDB.Unit.Drive.Y_Navi_Drive.Control_Jog_Fwd AND GDB.Unit.IO.di_Y_Navi_Left_Limit , 
						JogBackwards:= GDB.Unit.Drive.Y_Navi_Drive.Control_Jog_Bwd AND GDB.Unit.IO.di_Y_Navi_Right_Limit , 
						Mode:= E_JogMode.MC_JOGMODE_CONTINOUS,  
						Velocity:= GDB.Unit.Drive.Y_Navi_Drive.Control_Speed, 
						Acceleration:= GDB.Unit.Drive.Y_Navi_Drive.Control_AccelSpeed, 
						Deceleration:= GDB.Unit.Drive.Y_Navi_Drive.Control_DecelSpeed);		
		//GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position := LIMIT(GDB_Parameter.Y_Navi_Backward_Limit,GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position,GDB_Parameter.Y_Navi_Forward_Limit);		
		MC_MoveAbsolute_Y_Navi(Axis:= GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref, 
								Execute:= GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Start AND GDB.Unit.IO.di_Y_Navi_Left_Limit AND GDB.Unit.IO.di_Y_Navi_Right_Limit , 
								Position:= GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Position + GDB_Parameter.Y_Navi_Pos_Offset, 
								Velocity:= GDB.Unit.Drive.Y_Navi_Drive.Control_Speed, 
								Acceleration:= GDB.Unit.Drive.Y_Navi_Drive.Control_AccelSpeed, 
								Deceleration:= GDB.Unit.Drive.Y_Navi_Drive.Control_DecelSpeed, 
								Done=>GDB.Unit.Drive.Y_Navi_Drive.Control_PosMove_Complete );
		GDB.Unit.Drive.Y_Navi_Drive.Status_Ready := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.0;
		GDB.Unit.Drive.Y_Navi_Drive.Status_Homed := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.1;
		GDB.Unit.Drive.Y_Navi_Drive.Status_NotMoving := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.2;
		GDB.Unit.Drive.Y_Navi_Drive.Status_InPosRange := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.3;
		GDB.Unit.Drive.Y_Navi_Drive.Status_InTargetPos := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.4;
		GDB.Unit.Drive.Y_Navi_Drive.Status_MovingFw := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.9;
		GDB.Unit.Drive.Y_Navi_Drive.Status_MovingBw := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.StateDWord.10;
		GDB.Unit.Drive.Y_Navi_Drive.Status_ErrorCode := GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.ErrorCode;
		GDB.Unit.Drive.Y_Navi_Drive.Status_ActualPos := LREAL_TO_REAL(GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.ActPos) - GDB_Parameter.Y_Navi_Pos_Offset;
		GDB.Unit.Drive.Y_Navi_Drive.Status_ActualSpeed := LREAL_TO_REAL(GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.ActVelo);
		GDB.Unit.Drive.Y_Navi_Drive.Status_OutputPercentage := LREAL_TO_REAL(GDB.Unit.Drive.Y_Navi_Drive.Axis_Ref.NcToPlc.ActTorque);
		GDB.monitor.Current_Y_Navi_Pos := GDB.Unit.Drive.Y_Navi_Drive.Status_ActualPos;		
	END_IF;
