Unit Drive ZAPI

PROGRAM Unit_Drive_ZAPI
VAR

TON	:ARRAY[0..2] OF TON;
TON_Q	:ARRAY[0..2] OF BOOL;
TOF	:ARRAY[0..1] OF TOF;
Travel_PID_Control	:PID_Control;
FwSteering_PID_Control	:PID_Control;
BwSteering_PID_Control	:PID_Control;
Lift_PID_Control	:PID_Control;

(*ZAPI_Drive*)
	//Drive_Check
	ADSREAD_FwTravel : ADSREAD;
	ADSREAD_BwTravel : ADSREAD;
	ADSREAD_FwSteering : ADSREAD;
	ADSREAD_BwSteering : ADSREAD;
	ADSREAD_LIFT : ADSREAD;
	FwTravel_SDO_Read_Error_Bit : BOOL;
	BwTravel_SDO_Read_Error_Bit : BOOL;
	FwSteering_SDO_Read_Error_Bit : BOOL;
	BwSteering_SDO_Read_Error_Bit : BOOL;
	LIFT_SDO_Read_Error_Bit : BOOL;	
	FwTravel_SDO_RdData : ARRAY[1..4] OF BYTE;
	BwTravel_SDO_RdData : ARRAY[1..4] OF BYTE;
	FwSteering_SDO_RdData : ARRAY[1..4] OF BYTE;
	BwSteering_SDO_RdData : ARRAY[1..4] OF BYTE;
	LIFT_SDO_RdData : ARRAY[1..4] OF BYTE;
	FW_Travel_OK_TON : TON;
	BW_Travel_OK_TON : TON;
	FW_Steering_OK_TON : TON;
	BW_Steering_OK_TON : TON;
	LIFT_OK_TON : TON;
	//AcDc_Control
	FW_Travel_AcDc_Control_Instance	:AcDc_Control;
	BW_Travel_AcDc_Control_Instance	:AcDc_Control;
	//Zapi_Drive_Send,Receive
	Zapi_Drive_Send_FwTravel : Zapi_Drive_Send;
	Zapi_Drive_Receive_FwTravel : Zapi_Drive_Receive;	
	Zapi_Drive_Send_BwTravel : Zapi_Drive_Send;
	Zapi_Drive_Receive_BwTravel : Zapi_Drive_Receive;	
	Zapi_Drive_Send_FwSteering : Zapi_Drive_Send;
	Zapi_Drive_Receive_FwSteering : Zapi_Drive_Receive;	
	Zapi_Drive_Send_BwSteering : Zapi_Drive_Send;
	Zapi_Drive_Receive_BwSteering : Zapi_Drive_Receive;	
	Zapi_Drive_Send_Lift : Zapi_Drive_Send;
	Zapi_Drive_Receive_Lift : Zapi_Drive_Receive;
END_VAR

(*Travel_Control*)
IF TRUE THEN
    //Initialize
    IF TRUE THEN
        GDB.Unit.Drive.TravelControl.FW_Direction := 0;
        GDB.Unit.Drive.TravelControl.BW_Direction := 0;
        GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm := 0;
        GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm := 0;
        GDB.Unit.Drive.TravelControl.Target_reached_Bit := FALSE;
        GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos := 0;
        GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos := 0;
        GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos := 0;
		GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total := 0;
        GDB.Unit.Drive.TravelControl._1_Travel_Direction_Invert_Bit := FALSE;
        GDB.Unit.Drive.TravelControl._1_Travel_Decel_Bit := FALSE;
        GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm := 0;
        GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 := 0;
        GDB.Unit.Drive.TravelControl._3_AGV_Revision_Direction_s1_e4 := 0;
        GDB.Unit.Drive.TravelControl.High_Speed := 0;
        GDB.Unit.Drive.TravelControl.Low_Speed := 0;
        GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0;
        GDB.Unit.Drive.TravelControl.In_Position := 0;
        GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := 0;
    END_IF;
    //[Auto, Semi_Auto]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
    IF GDB.mode.Auto OR GDB.mode.Semi_Auto THEN
        //1. Move [GDB.auto._1_move.Step = 3] - WorkType : 1,2,3,5
        IF GDB.auto._3_move.Step = 7 THEN // Work_Type : 1,2,3,5
            GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos;
            GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos;
            GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos;
			GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total := GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total;
            GDB.Unit.Drive.TravelControl._1_Travel_Direction_Invert_Bit := GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit;
            GDB.Unit.Drive.TravelControl._1_Travel_Decel_Bit := GDB.Unit.Drive.Move_Data._1_Travel_Decel_Bit;
            GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm := GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm;
            GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 := GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180;
            GDB.Unit.Drive.TravelControl._3_AGV_Revision_Direction_s1_e4 := GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4;
            IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 1
                OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2
                OR GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 THEN // 1 : Straight_Line , 2 : Crab_Move, 3:diagonal_Line
                GDB.Unit.Drive.TravelControl.High_Speed := 40;//GDB_Parameter.Travel_High_Speed[2];
				IF GDB.Unit.Drive.TravelControl.High_Speed > GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm THEN
					GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
				END_IF
                GDB.Unit.Drive.TravelControl.Low_Speed := 1.0;
                GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0.1;
                GDB.Unit.Drive.TravelControl.In_Position := 5.0;
                GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := (GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2 * 3;
                //High_Speed_Condition_Set : TON[1].Q
                IF GDB.Unit.Drive.TravelControl.Status_Running_Bit
                    AND (ABS(GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180) < 3.0)
                    AND
                    ((GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm > 45.0 AND GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS > 3000.0)
                    OR (GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm <= 45.0 AND GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS > 3000.0))
                THEN
                    TON[1](IN := TRUE,
               PT := T#3S);
                ELSE
                    TON[1](IN := FALSE,
               PT := T#3S);
                END_IF;
                //High_Speed_Set[Accel_Point]
                IF TON[1].Q // 170 < Angle < 190
                    AND ABS(((GDB.monitor.Current_FW_Wheel_Angle + GDB.monitor.Current_BW_Wheel_Angle) / 2) - 180) < 10
					AND GDB.Unit.Drive.TravelControl.High_Speed < GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm
                THEN
                    IF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos > 5000) AND (GDB.Unit.IO.di_Product_Detect = FALSE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos > 5000) AND (GDB.Unit.IO.di_Product_Detect = TRUE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm / 60 * 45;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos <= 5000) AND (GDB.Unit.IO.di_Product_Detect = FALSE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos <= 5000) AND (GDB.Unit.IO.di_Product_Detect = TRUE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm / 60 * 45;                        
                    END_IF;
                ELSIF TON[1].Q // Angle < 170 , 190 < Angle
                    AND ABS(((GDB.monitor.Current_FW_Wheel_Angle + GDB.monitor.Current_BW_Wheel_Angle) / 2) - 180) >= 10
					AND GDB.Unit.Drive.TravelControl.High_Speed < GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm
                THEN
                    IF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos > 5000) AND (GDB.Unit.IO.di_Product_Detect = FALSE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos > 5000) AND (GDB.Unit.IO.di_Product_Detect = TRUE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm / 30 * 20;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos <= 5000) AND (GDB.Unit.IO.di_Product_Detect = FALSE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                    ELSIF (GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos <= 5000) AND (GDB.Unit.IO.di_Product_Detect = TRUE) THEN
                        GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm / 30 * 20;
                    END_IF;
                END_IF;
                //High_Speed_Set[Decel_Point]    
                IF (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 700 (*OR GDB.Unit.Drive.SteeringControl.SUB_FWTarget_FWActual_Abs > 5.0 OR GDB.Unit.Drive.SteeringControl.SUB_BWTarget_BWActual_Abs > 5.0*) )
                    //OR
                    //(GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 AND
                    //((GDB.Unit.Drive.SteeringControl.SUB_FWTarget_FWActual_Abs > 5.0) OR (GDB.Unit.Drive.SteeringControl.SUB_BWTarget_BWActual_Abs > 5.0)))
                THEN
                    GDB.Unit.Drive.TravelControl.High_Speed := GDB_Parameter.Travel_High_Speed[1];
                END_IF;
            END_IF;
            IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5 THEN // 5 : R_Turn
                GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                GDB.Unit.Drive.TravelControl.Low_Speed := 1.0;
                GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0.1;
                GDB.Unit.Drive.TravelControl.In_Position := 5.0;
                GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := (GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2 * 3;

                //High_Speed_Set[Decel_Point]    
                IF (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 500) THEN
                    GDB.Unit.Drive.TravelControl.High_Speed := GDB_Parameter.Travel_High_Speed[1];
                END_IF;
            END_IF;
            IF GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN // 6 : Crab_Turn
                GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.TravelControl._1_Travel_Max_Speed_mpm;
                GDB.Unit.Drive.TravelControl.Low_Speed := 1.0;
                GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0.1;
                GDB.Unit.Drive.TravelControl.In_Position := 5.0;
                GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := (GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2 * 3;
                //High_Speed_Set[Decel_Point]    
                IF (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 500) THEN
                    GDB.Unit.Drive.TravelControl.High_Speed := GDB_Parameter.Travel_High_Speed[1];
                END_IF;
            END_IF;
        END_IF;




        //6. Spinturn [GDB.auto._5_SpinTurn.Step = 3] - Command_Type : 5
        IF GDB.auto._5_SpinTurn.Step = 3 THEN
            GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos := GDB.monitor.Current_AGV_Angle * GDB.auto._5_SpinTurn.Distance_Per_Degree;
            GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos := (GDB.monitor.Current_AGV_Angle + GDB.auto._5_SpinTurn.SUB_Target_Currnet_s180) * GDB.auto._5_SpinTurn.Distance_Per_Degree;
            GDB.Unit.Drive.TravelControl.High_Speed := GDB_Parameter.Travel_High_Speed[1] * 1.5;
            GDB.Unit.Drive.TravelControl.Low_Speed := 1.0;
            GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0.1;
            GDB.Unit.Drive.TravelControl.In_Position := 5.0;
            GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := (GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2 * 3;
            //High_Speed_Set[Decel_Point]    
            IF (GDB.Unit.Drive.TravelControl.SUB_TargetExtend_ActualPos_ABS < 300) THEN
                GDB.Unit.Drive.TravelControl.High_Speed := GDB_Parameter.Travel_High_Speed[1];
            END_IF;
        END_IF;
         //3. Ready [GDB.auto.Ready.Step = 7]
        IF GDB.auto.Ready.Step = 7 THEN
			GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Actual_Pos;
            GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos;
            GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos := GDB.Unit.Drive.Move_Data._1_Travel_Target_Extend_Pos;
			GDB.Unit.Drive.TravelControl._1_Travel_Target_Pos_Total := GDB.Unit.Drive.Move_Data._1_Travel_Target_Pos_Total;
            GDB.Unit.Drive.TravelControl._1_Travel_Direction_Invert_Bit := GDB.Unit.Drive.Move_Data._1_Travel_Direction_Invert_Bit;
            GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 := GDB.Unit.Drive.Move_Data._3_AGV_Revision_Angle_s180;
            GDB.Unit.Drive.TravelControl._3_AGV_Revision_Direction_s1_e4 := GDB.Unit.Drive.Move_Data._3_AGV_Revision_Direction_s1_e4;			
            GDB.Unit.Drive.TravelControl.High_Speed := GDB.Unit.Drive.Move_Data._1_Travel_Max_Speed_mpm;
            GDB.Unit.Drive.TravelControl.Low_Speed := 1.0;
            GDB.Unit.Drive.TravelControl.Travel_P_Gain := 0.1;
            GDB.Unit.Drive.TravelControl.In_Position := 5.0;
            GDB.Unit.Drive.TravelControl.Decel_Distance_Offset := (GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2 * 3;
        END_IF;


        //PID_Control
        IF TRUE THEN
            IF (GDB.mode.Auto OR GDB.mode.Semi_Auto) AND 
				GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 2 OR
				GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 3 OR
				GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 5 OR
				GDB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Work_Type = 6 THEN
				GDB.Unit.Drive.TravelControl.High_Speed := LIMIT(0,GDB.Unit.Drive.TravelControl.High_Speed,20);
			END_IF

		Travel_PID_Control(in_Enable := (GDB.Unit.Drive.TravelControl.High_Speed <> 0),
       in_Target_Pos := GDB.Unit.Drive.TravelControl._1_Travel_Target_Extend_Pos,
       in_Current_Pos := GDB.Unit.Drive.TravelControl._1_Travel_Actual_Pos,
       in_Max_Value := GDB.Unit.Drive.TravelControl.High_Speed,
       in_Min_Value := GDB.Unit.Drive.TravelControl.Low_Speed,
       in_Gain_P := GDB.Unit.Drive.TravelControl.Travel_P_Gain,
       in_Distance_Offset := GDB.Unit.Drive.TravelControl.Decel_Distance_Offset,
       in_inPosition := GDB.Unit.Drive.TravelControl.In_Position,
       out_Target_Reached => GDB.Unit.Drive.TravelControl.Target_reached_Bit,
       out_iDirection => GDB.Unit.Drive.TravelControl.Direction_Buffer,
       out_Output_Value_mpm => GDB.Unit.Drive.TravelControl.Output_Value_Buffer_mpm);
            GDB.Unit.Drive.TravelControl.FW_Direction := GDB.Unit.Drive.TravelControl.Direction_Buffer;
            GDB.Unit.Drive.TravelControl.BW_Direction := GDB.Unit.Drive.TravelControl.Direction_Buffer;
            GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm := GDB.Unit.Drive.TravelControl.Output_Value_Buffer_mpm;
            GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm := GDB.Unit.Drive.TravelControl.Output_Value_Buffer_mpm;
        END_IF;

        //Direction_Set
        IF GDB.Unit.Drive.TravelControl._1_Travel_Direction_Invert_Bit THEN    //Travel_Direction_Invert_Bit = TRUE 인 경우,
            IF GDB.Unit.Drive.TravelControl.Direction_Buffer = 1 THEN
                GDB.Unit.Drive.TravelControl.FW_Direction := 2;
                GDB.Unit.Drive.TravelControl.BW_Direction := 2;
            ELSIF GDB.Unit.Drive.TravelControl.Direction_Buffer = 2 THEN
                GDB.Unit.Drive.TravelControl.FW_Direction := 1;
                GDB.Unit.Drive.TravelControl.BW_Direction := 1;
            END_IF;
        END_IF;
        IF GDB.auto._5_SpinTurn.Step = 3 AND (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) <= 360 THEN // Spinturn인 경우
            IF GDB.Unit.Drive.TravelControl.Direction_Buffer = 1 THEN
                GDB.Unit.Drive.TravelControl.BW_Direction := 2;
            ELSIF GDB.Unit.Drive.TravelControl.Direction_Buffer = 2 THEN
                GDB.Unit.Drive.TravelControl.BW_Direction := 1;
            END_IF;
		ELSIF GDB.auto._5_SpinTurn.Step = 3 AND (GDB.Monitor.Current_FW_Wheel_Angle + GDB.Monitor.Current_BW_Wheel_Angle) > 360 THEN // Spinturn인 경우
            IF GDB.Unit.Drive.TravelControl.Direction_Buffer = 1 THEN
                GDB.Unit.Drive.TravelControl.FW_Direction := 2;
            ELSIF GDB.Unit.Drive.TravelControl.Direction_Buffer = 2 THEN
                GDB.Unit.Drive.TravelControl.FW_Direction := 1;
            END_IF;	
        END_IF;
        //AGV_Revision_Angle_Set
        IF (GDB.Unit.Drive.TravelControl.Direction_Buffer <> 0) THEN
            //속도에 따른 Revision Buffer
            IF ((GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2) > 15.0 THEN
                GDB.Unit.Drive.TravelControl.Revision_Buffer := GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 * 1.5;
            ELSIF (((GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2) <= 15.0) AND
                (((GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2) > 2.5) THEN
                GDB.Unit.Drive.TravelControl.Revision_Buffer := GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 * 1.0;
            ELSIF (((GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2) <= 2.5) AND
                (((GDB.Unit.Drive.FW_Travel_Drive.CurrentSpeed_mpm + GDB.Unit.Drive.BW_Travel_Drive.CurrentSpeed_mpm) / 2) > 0.5) THEN
                GDB.Unit.Drive.TravelControl.Revision_Buffer := GDB.Unit.Drive.TravelControl._3_AGV_Revision_Angle_s180 * 0.5;
