                IF GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm < 0 THEN
                    GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm := 0;
                END_IF;
            END_IF;

            //AGV_Revision_Direction = 2 인 경우,
