                GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm := GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm - GDB.Unit.Drive.TravelControl.Revision_Buffer;
                IF GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm < 0 THEN
