        GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := 0;
        GDB.Unit.Drive.LiftControl.Target_reached_Bit := FALSE;
        GDB.Unit.Drive.LiftControl.Target_Lift_Pos := 0;
        GDB.Unit.Drive.LiftControl.High_Speed := 0;
        GDB.Unit.Drive.LiftControl.Low_Speed := 0;
        GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0;
        GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := 0;
        GDB.Unit.Drive.LiftControl.In_Position := 0;
    END_IF;

    //[Auto, Semi_Auto, Manual_PosMove]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
    IF GDB.mode.Auto OR GDB.mode.Semi_Auto OR (GDB.mode.Manual AND GDB.manual.Lift_PosMove_Start) THEN
        //1. Loading [_1_Loading.Step = 3]
        IF GDB.auto._1_Loading.Step = 3 AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[4];
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
			IF GDB.Auto._1_Loading.Step_7_Lift_Decel_Bit THEN
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1]*1.5;
			END_IF;			
        END_IF;


        //1. Loading [_1_Loading.Step = 7]
        IF GDB.auto._1_Loading.Step = 7 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[4];
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
			IF GDB.Auto._1_Loading.Step_7_Lift_Decel_Bit THEN
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1]*1.5;
			END_IF;			
        END_IF;

		(*
		//2. Unloading [_2_Unloading.Step = 7]
        IF GDB.auto._2_Unloading.Step = 7 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1] * 1.5;
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
        END_IF;*)
		//2. Unloading [_2_Unloading.Step = 3]
        IF GDB.auto._2_Unloading.Step = 3 AND ABS(GDB.Unit.Drive.Move_Data.Difference_mm_X) < 2.0 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[3];
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
			IF GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit THEN
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1]*1.5;
			END_IF;		
        END_IF;

		//2. Unloading [_2_Unloading.Step = 13]
        IF GDB.auto._2_Unloading.Step = 13 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[3];
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
			IF GDB.Auto._2_Unloading.Step_13_Lift_Decel_Bit THEN
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[1]*1.5;
			END_IF;		
        END_IF;
		//3. Move [_3_Move.Step = 7]
        IF GDB.auto._3_Move.Step = 7 THEN
			IF		GDB.auto._3_Move.Step_7_Loading_Ready_Bit //Loading_Ready 인 경우,
				OR  GDB.auto._3_Move.Step_7_UnLoading_Ready_Bit //Unloading_Ready 인 경우,
				OR (ABS(GDB.Monitor.Current_Y_Shift_Pos) < 1.0 AND (GDB.auto._3_Move.Step_7_Home_Bit)) THEN //Home이동, Y_Shift가 원점인 경우,
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[6];				
				GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
			ELSIF 	ABS(GDB.Monitor.Current_Y_Shift_Pos) >= 1.0 THEN //Home이동, Y_Shift가 원점이 아닌경우,
				IF GDB.Unit.IO.di_Product_Detect = FALSE AND GDB.auto._3_Move.Step_7_Home_Bit AND GDB.Monitor.Current_Lift_Pos > 60 THEN //화물이 없는 경우, 	
					GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[6];				
					GDB.Unit.Drive.LiftControl.Target_Lift_Pos := 60;	
				END_IF;	
			END_IF;            					
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
		END_IF;
		//4. Ready [Ready.Step = 2]
        IF GDB.auto.Ready.Step = 2 THEN
			GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[6];				
			GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
		END_IF;		
		//5. Ready [Ready.Step = 3]
        IF GDB.auto.Ready.Step = 3 THEN
			IF			(ABS(GDB.Monitor.Current_Y_Shift_Pos) < 1.0 
					AND ABS(GDB.Monitor.Current_Theta_Pos) < 1.0 
					AND ABS(GDB.Monitor.Current_Tilting_Pos) < 1.0) THEN //Home이동, Y_Shift가 원점인 경우,
				GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[6];				
				GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.Unit.Drive.Move_Data.Target_Pos_Lift;
			ELSIF 	(ABS(GDB.Monitor.Current_Y_Shift_Pos) >= 1.0
					OR ABS(GDB.Monitor.Current_Theta_Pos) >= 1.0
					OR ABS(GDB.Monitor.Current_Tilting_Pos) >= 1.0) AND GDB.Monitor.Current_Lift_Pos > 40 THEN //Home이동, Y_Shift가 원점이 아닌경우, 	
					GDB.Unit.Drive.LiftControl.High_Speed := GDB_Parameter.Lift_High_Speed[6];				
					GDB.Unit.Drive.LiftControl.Target_Lift_Pos := 40;	
			END_IF;            					
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 1.0;
		END_IF;				
        //11. Manual_PosMove
        IF (GDB.mode.Manual AND GDB.manual.Lift_PosMove_Start) AND GDB.Error.Error_Code = 0 THEN
            GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB.manual.Lift_Target_Pos;
            GDB.Unit.Drive.LiftControl.High_Speed := GDB.Manual.Lift_Speed;
            GDB.Unit.Drive.LiftControl.Low_Speed := 0.1;
            GDB.Unit.Drive.LiftControl.Lift_P_Gain := 0.1;
            GDB.Unit.Drive.LiftControl.Decel_Distance_Offset := GDB.Unit.Drive.LIFT_Drive.CurrentSpeed_mpm * 2.0;
            GDB.Unit.Drive.LiftControl.In_Position := 0.5;
        END_IF;


        (*//Pos_Limit
        IF TRUE THEN
            //Pos_Limit
            IF GDB.Unit.Drive.LiftControl.Target_Lift_Pos < GDB_Parameter.Lift_Backward_Limit THEN
                GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB_Parameter.Lift_Backward_Limit;
            ELSIF GDB.Unit.Drive.LiftControl.Target_Lift_Pos > GDB_Parameter.Lift_Forward_Limit THEN
                GDB.Unit.Drive.LiftControl.Target_Lift_Pos := GDB_Parameter.Lift_Forward_Limit;
            END_IF;
        END_IF;*)

        //PID_Control
        IF TRUE THEN
            Lift_PID_Control(in_Enable := (GDB.Unit.Drive.LiftControl.High_Speed <> 0),
                              in_Target_Pos := GDB.Unit.Drive.LiftControl.Target_Lift_Pos,
                              in_Current_Pos := GDB.monitor.Current_Lift_Pos,
                              in_Max_Value := GDB.Unit.Drive.LiftControl.High_Speed,
                              in_Min_Value := GDB.Unit.Drive.LiftControl.Low_Speed,
                              in_Gain_P := GDB.Unit.Drive.LiftControl.Lift_P_Gain,
                              in_Distance_Offset := GDB.Unit.Drive.LiftControl.Decel_Distance_Offset,
                              in_inPosition := GDB.Unit.Drive.LiftControl.In_Position,
                              out_Target_Reached => GDB.Unit.Drive.LiftControl.Target_reached_Bit,
                              out_iDirection => GDB.Unit.Drive.LiftControl.Lift_Direction,
                              out_Output_Value_mpm => GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm);
        END_IF;
    END_IF;
    //ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ        

    //[Manual_Jog]ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ
    IF (GDB.mode.Manual AND GDB.manual.Lift_Jog_Direction <> 0) THEN

        GDB.Unit.Drive.LiftControl.Lift_Direction := GDB.manual.Lift_Jog_Direction;
        GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := GDB.Manual.Lift_Speed;
    END_IF;
    //ㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡㅡ        

	//[Jog ( Loading_Step_5 / Loading_Step_9 / Unloading_Step_5 )]
	IF GDB.auto._1_Loading.Step = 5 OR GDB.auto._2_Unloading.Step = 5 THEN
		IF GDB.Unit.Drive.Move_Data.Difference_mm_Lift > 0.4 THEN
			GDB.Unit.Drive.LiftControl.Lift_Direction := 1;
		ELSIF GDB.Unit.Drive.Move_Data.Difference_mm_Lift < -0.4	THEN
			GDB.Unit.Drive.LiftControl.Lift_Direction := 2;
		END_IF;
		GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := 0.3;			
		IF ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Lift) > 3.0 THEN
			GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := ABS(GDB.Unit.Drive.Move_Data.Difference_mm_Lift) * 0.12;
		END_IF;
	ELSIF GDB.auto._1_Loading.Step = 9 THEN
		GDB.Unit.Drive.LiftControl.Lift_Direction := GDB.Auto._1_Loading.Step_9_Lift_Direction;
		GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := GDB.Auto._1_Loading.Step_9_Lift_Speed_mpm;
	END_IF;

	//[Limit_Sensor]
	(*IF GDB.Unit.IO.di_Lift_Up_Limit = FALSE AND GDB.Unit.Drive.LiftControl.Lift_Direction = 1 THEN
		GDB.Unit.Drive.LiftControl.Lift_Direction := 0;
	ELSIF GDB.Unit.IO.di_Lift_Down_Limit = FALSE AND GDB.Unit.Drive.LiftControl.Lift_Direction = 2 THEN
		GDB.Unit.Drive.LiftControl.Lift_Direction := 0;
	END_IF;*)	

    //[Speed_Limit]
    IF TRUE THEN
        //Speed_Limit
        IF GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm < 0 THEN
            GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := 0;
        ELSIF GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm > 3.0 THEN
            GDB.Unit.Drive.LiftControl.Lift_TargetSpeed_mpm := 3.0;
        END_IF;
    END_IF;
END_IF;
