PROGRAM Unit_IPS208i_ST
VAR
(*		
	Program 0 : Turret ( 353 mm )
	Program 1 : Port Loading ( 225 mm )
	Program 2 : Port Unloading ( 125 mm )
*)
(*
2020.12.28 [회사·현장 식별 표기 비공개] 기준
	Program 0 : Turret ( 421 mm )

2021.01.01 [회사·현장 식별 표기 비공개] 기준
	Program 0 : Turret ( 381 mm )	
	Program 1 : Port Loading ( 257 mm )
	Program 2 : Port Unloading ( 165 mm )
*)



//Send_Time
Send_Time : TIME;
//Default
TON	:ARRAY[0..2] OF TON;
TON_Q	:ARRAY[0..2] OF BOOL;
TOF	:ARRAY[0..2] OF TOF;
PN_Pulse :ARRAY[0..2] OF PN_Pulse;
LoopIndex : ARRAY[0..1] OF INT;

	//Socket Intance
	TCPIP_OpenClose_IPS208i_HP : TCPIP_OpenClose;
	FB_SocketSend_IPS208i_HP : FB_SocketSend;
	FB_SocketReceive_IPS208i_HP : FB_SocketReceive;

	TCPIP_OpenClose_IPS208i_OP : TCPIP_OpenClose;
	FB_SocketSend_IPS208i_OP : FB_SocketSend;
	FB_SocketReceive_IPS208i_OP : FB_SocketReceive;

	//IPS208i FB_Instance
	IPS208i_Recieve_HP : IPS208i_Recieve;

	IPS208i_Recieve_OP : IPS208i_Recieve;

	Xpos_RealData_OP : REAL;
	Ypos_RealData_OP : REAL;
	Xpos_RealData_HP : REAL;
	Ypos_RealData_HP : REAL;

	Test_Send_Req_HP : BOOL;
	Test_Send_Req_OP : BOOL;

	Test_Rtrig_HP : R_TRIG;
	Test_Rtrig_OP : R_TRIG;
	test_ms : BOOL;
END_VAR



//Initialize
IF GDB.Unit.IPS208i.SendData_HP[0] = 16#2B OR GDB.Unit.IPS208i.SendData_OP[0] = 16#2B THEN
   GDB.Unit.IPS208i.Program_Change_OK_HP := FALSE;
   GDB.Unit.IPS208i.Program_Change_OK_OP := FALSE;
END_IF;

Test_Rtrig_HP(CLK:=TRUE);
Test_Rtrig_OP(CLK:=TRUE);
Test_Send_Req_HP := FALSE;
Test_Send_Req_OP := FALSE;

//1.Heart-Bit Check
PN_Pulse[1](in_Type:=1, in_Signal:=GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_HP);
PN_Pulse[2](in_Type:=1, in_Signal:=GDB.Unit.IPS208i.IPS208i_Recieve_FB_Complete_OP);
TOF[1](IN:=(PN_Pulse[1].out_Pulse) , PT:= T#1S , Q=> GDB.Unit.IPS208i.IPS208i_Comm_OK_HP);
TOF[2](IN:=(PN_Pulse[2].out_Pulse) , PT:= T#1S , Q=> GDB.Unit.IPS208i.IPS208i_Comm_OK_OP);


//2. IPS208i Connection Opne/Close
TCPIP_OpenClose_IPS208i_HP(in_bEnable:= TRUE, 
                     in_bReset:= (GDB.Mode.Reset OR GDB.Unit.IPS208i.SocketSend_bError_HP) 
                              AND GDB.Unit.IPS208i.IPS208i_Comm_OK_HP = FALSE , 
                     in_sRemoteHost:= GDB_Parameter.IP_IPS208i_HP, 
                     in_nRemotePort:= GDB_Parameter.Port_IPS208i_HP, 
                     out_ConnectState=> GDB.Unit.IPS208i.SocketConnect_State_HP, 
                     out_ErrorCode=> GDB.Unit.IPS208i.SocketConnect_Error_Code_HP, 
                     out_T_hSocket=> GDB.Unit.IPS208i.SocketConnect_hSocket_HP);
TCPIP_OpenClose_IPS208i_OP(in_bEnable:= TRUE, 
                     in_bReset:= (GDB.Mode.Reset OR GDB.Unit.IPS208i.SocketSend_bError_OP) 
                              AND GDB.Unit.IPS208i.IPS208i_Comm_OK_OP = FALSE , 
                     in_sRemoteHost:= GDB_Parameter.IP_IPS208i_OP, 
                     in_nRemotePort:= GDB_Parameter.Port_IPS208i_OP, 
                     out_ConnectState=> GDB.Unit.IPS208i.SocketConnect_State_OP, 
                     out_ErrorCode=> GDB.Unit.IPS208i.SocketConnect_Error_Code_OP, 
                     out_T_hSocket=> GDB.Unit.IPS208i.SocketConnect_hSocket_OP);                     
//3.IPS208i Data Send/Recieve

//   Send_Time := T#30MS;
//   IF       GDB.Unit.IPS208i.SendData_HP[0] <> 16#2B
//      OR    GDB.Unit.IPS208i.SendData_OP[0] <> 16#2B THEN
//      Send_Time := T#100MS;
//   END_IF;   
//   TON[1](IN:=TON_Q[1]=FALSE, PT:=Send_Time, Q=>TON_Q[1]);
	 TON[2](IN:=TON_Q[2]=FALSE, PT:=T#10MS, Q=>TON_Q[2]);

//Program_Change   1 - 터렛 , 양극포일PNT2호 터렛
      IF    ((GDB.auto._1_Loading.Step = 1 OR GDB.auto._2_Unloading.Step = 1) AND (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1))
         OR ((Setting_IPS_Auto_Teaching.Step = 9 OR Setting_IPS_Auto_Teaching.Step = 13) AND (GDB_Retain.Node[GDB_Retain.Current_Node].Turret_1_Port_2 = 1))  
         OR GDB.Touch.S901_IPS_Program_Select[1] THEN         
         GDB.Unit.IPS208i.SendData_HP[0] := 16#47;   GDB.Unit.IPS208i.SendData_OP[0] := 16#47;
