Unit S30B ST

PROGRAM Unit_S30B_ST
VAR

	S30B_MOVE_TYPE_CHANGE: BOOL;
END_VAR


//Run Type Define
// 1 : 전진
// 2 : 후진
// 3 : 스핀턴
// 4 : 바퀴 한쪽만 Run
IF  GDB.Unit.Drive.TravelControl.FW_Direction = 1 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 1 THEN // 전진
     GDB.Unit.SICK_S30B.Run_Type := 1;
    ELSIF  GDB.Unit.Drive.TravelControl.FW_Direction = 2 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 2 THEN // 후진
         GDB.Unit.SICK_S30B.Run_Type := 2;
    ELSIF ( GDB.Unit.Drive.TravelControl.FW_Direction = 1 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 2) // 스핀턴
        OR ( GDB.Unit.Drive.TravelControl.FW_Direction = 2 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 1) THEN
         GDB.Unit.SICK_S30B.Run_Type := 3;
    ELSIF ( GDB.Unit.Drive.TravelControl.FW_Direction = 1 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 0) // 바퀴 한쪽만 Run
        OR ( GDB.Unit.Drive.TravelControl.FW_Direction = 2 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 0)
        OR ( GDB.Unit.Drive.TravelControl.FW_Direction = 0 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 1) 
        OR ( GDB.Unit.Drive.TravelControl.FW_Direction = 0 AND  GDB.Unit.Drive.TravelControl.BW_Direction = 2) THEN
         GDB.Unit.SICK_S30B.Run_Type := 4;
    ELSE
     GDB.Unit.SICK_S30B.Run_Type := 0;
END_IF;
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


GDB.Unit.SICK_S30B.High_Speed_Field_Value := 10;

//Move Type Define
//AGV 중심에서 진행방향 ( 휠의 각도 + 주행방향(정/역) )
// 0 : Not moving
// 1 : Angle 355 ~ 5   //0도 직선구간
// 2 : Angle   5 ~ 85
// 3 : Angle  85 ~ 95  //90도 직선구간
// 4 : Angle  95 ~ 175
// 5 : Angle 175 ~ 185 //180도 직선구간
// 6 : Angle 185 ~ 265
// 7 : Angle 265 ~ 275 //270도 직선구간
// 8 : Angle 275 ~ 355
// 9 : SpinTurn
// 10 : only One Wheel Run
// 11 :
// 12 :
// 13 :
// 14 :
// 15 : Forward Right Turn
// 16 : Forward Left Turn
// 17 : Backward Right Turn
// 18 : Backward Left Turn
//

IF (GDB.Unit.SICK_S30B.Run_Type = 1 OR GDB.Unit.SICK_S30B.Run_Type = 2) AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE >= 2 AND GDB_Retain.Node[GDB.Command.Dest_Node]._TYPE <= 3 THEN
	 GDB.Unit.SICK_S30B.move_Type := 0;
END_IF

IF (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node]._TYPE = 2
    OR (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node]._TYPE = 4 
    AND GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 2))

	AND (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 2
	OR (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 4
	AND GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node]._TYPE = 2))

	OR GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].Start_Node]._TYPE = 3
	OR GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE = 3 THEN

 //GDB.Unit.SICK_S30B.move_Type := 0;
 S30B_MOVE_TYPE_CHANGE := TRUE;
ELSE 
 S30B_MOVE_TYPE_CHANGE := FALSE;


END_IF;


IF  GDB.Unit.SICK_S30B.Run_Type = 1 AND (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE <> 3 
		OR GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE <> 2 ) THEN // 전진일 경우
    //  GDB.Unit.S30B.AGV_Run_Angle 계산
     GDB.Unit.SICK_S30B.AGV_Run_Angle := -((( GDB.monitor.Current_FW_Wheel_Angle +  GDB.monitor.Current_BW_Wheel_Angle) / 2) - 180);
    IF  GDB.Unit.SICK_S30B.AGV_Run_Angle < 0 THEN
         GDB.Unit.SICK_S30B.AGV_Run_Angle :=  GDB.Unit.SICK_S30B.AGV_Run_Angle + 360;
    ELSIF  GDB.Unit.SICK_S30B.AGV_Run_Angle >= 360 THEN
         GDB.Unit.SICK_S30B.AGV_Run_Angle :=  GDB.Unit.SICK_S30B.AGV_Run_Angle - 360;
    END_IF;
    // Field Type
    IF (0 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 10) OR (350 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 360) THEN
         GDB.Unit.SICK_S30B.move_Type := 1; //Angle 355 ~ 5   //0도 직선구간
    ELSIF (10 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 80) THEN
         GDB.Unit.SICK_S30B.move_Type := 2; //Angle   5 ~ 85
    ELSIF (80 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 100) THEN
         GDB.Unit.SICK_S30B.move_Type := 3; //Angle  85 ~ 95  //90도 직선구간
    ELSIF (260 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 280) THEN
         GDB.Unit.SICK_S30B.move_Type := 7; //Angle 265 ~ 275 //270도 직선구간
    ELSIF (280 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 350) THEN
         GDB.Unit.SICK_S30B.move_Type := 8; //Angle 275 ~ 355
    END_IF;

    IF ( GDB.monitor.Current_FW_Wheel_Angle -  GDB.monitor.Current_BW_Wheel_Angle) > 20 THEN
         GDB.Unit.SICK_S30B.move_Type := 15; //Forward Right Turn
    ELSIF ( GDB.monitor.Current_FW_Wheel_Angle -  GDB.monitor.Current_BW_Wheel_Angle) < -20 THEN
         GDB.Unit.SICK_S30B.move_Type := 16; //Forward Right Turn
    END_IF;

ELSIF  GDB.Unit.SICK_S30B.Run_Type = 2 AND (GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE <> 3 
		OR GDB_Retain.Node[GdB_Retain.Link_ID[GDB.Command.Data_List[GDB.Command.Current_Number]].End_Node]._TYPE <> 2 ) THEN // 후진일 경우
    //  GDB.Unit.S30B.AGV_Run_Angle 계산
     GDB.Unit.SICK_S30B.AGV_Run_Angle := (- ((( GDB.monitor.Current_FW_Wheel_Angle +  GDB.monitor.Current_BW_Wheel_Angle) / 2) - 180)) + 180;
    IF  GDB.Unit.SICK_S30B.AGV_Run_Angle < 0 THEN
         GDB.Unit.SICK_S30B.AGV_Run_Angle :=  GDB.Unit.SICK_S30B.AGV_Run_Angle + 360;
    ELSIF  GDB.Unit.SICK_S30B.AGV_Run_Angle >= 360 THEN
         GDB.Unit.SICK_S30B.AGV_Run_Angle :=  GDB.Unit.SICK_S30B.AGV_Run_Angle - 360;
    END_IF;

    // Field Type
    IF (80 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 100) THEN
         GDB.Unit.SICK_S30B.move_Type := 3; //Angle  85 ~ 95  //90도 직선구간
    ELSIF (100 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 170) THEN
         GDB.Unit.SICK_S30B.move_Type := 4; //Angle  95 ~ 175
    ELSIF (170 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 190) THEN
         GDB.Unit.SICK_S30B.move_Type := 5; //Angle 175 ~ 185 //180도 직선구간
    ELSIF (190 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 260) THEN
         GDB.Unit.SICK_S30B.move_Type := 6; //Angle 185 ~ 265
    ELSIF (260 <=  GDB.Unit.SICK_S30B.AGV_Run_Angle AND  GDB.Unit.SICK_S30B.AGV_Run_Angle <= 280) THEN
         GDB.Unit.SICK_S30B.move_Type := 7; //Angle 265 ~ 275 //270도 직선구간
    END_IF;

    IF ( GDB.monitor.Current_FW_Wheel_Angle -  GDB.monitor.Current_BW_Wheel_Angle) > 20 THEN
         GDB.Unit.SICK_S30B.move_Type := 18; //Forward Left Turn
    ELSIF ( GDB.monitor.Current_FW_Wheel_Angle -  GDB.monitor.Current_BW_Wheel_Angle) < -20 THEN
         GDB.Unit.SICK_S30B.move_Type := 17; //Forward Right Turn
    END_IF;

ELSIF  GDB.Unit.SICK_S30B.Run_Type = 3 THEN // SpinTurn일 경우
     GDB.Unit.SICK_S30B.move_Type := 9;
ELSIF  GDB.Unit.SICK_S30B.Run_Type = 4 THEN // 바퀴 한쪽만 Run일 경우
     GDB.Unit.SICK_S30B.move_Type := 10;
ELSE
     GDB.Unit.SICK_S30B.move_Type := 0;

END_IF;

// Field Type Define
// A  B  C  
// 0  0  0  (10#21) S30B 기준 우측 High Speed
// 0  0  1  (10#37) S30B 기준 우측 Low Speed
// 0  1  0  (10#25) S30B 기준 좌측 High Speed
// 0  1  1  (10#41) S30B 기준 좌측 Low Speed
// 1  0  0  (10#22) S30B 기준 정면 대각선
// 1  0  1  (10#38) S30B 기준 우측 대각선
// 1  1  0  (10#26) S30B 기준 좌측 대각선
// 1  1  1  (10#42) 항상 ON

// Field Select
IF  GDB.Unit.SICK_S30B.move_Type = 1 THEN // 1 : Angle 355 ~ 5   //0도 직선구간
    IF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) >  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //고속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#41;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;
    ELSIF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) <=  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //저속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#25;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;
    END_IF;
ELSIF  GDB.Unit.SICK_S30B.move_Type = 2 THEN // 2 : Angle   5 ~ 85
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#26;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 3 THEN // 3 : Angle  85 ~ 95  //90도 직선구간
    IF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) >  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //고속일 경우
         //GDB.Unit.SICK_S30B.Output_Byte_1 := 10#42;
		 GDB.Unit.SICK_S30B.Output_Byte_1 := 10#38;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;
    ELSIF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) <=  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //저속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#38;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;
    END_IF;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 4 THEN // 4 : Angle  95 ~ 175
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#38;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#22;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 5 THEN // 5 : Angle 175 ~ 185 //180도 직선구간
    IF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) >  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //고속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#41;
    ELSIF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) <=  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //저속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#25;
    END_IF;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 6 THEN // 6 : Angle 185 ~ 265
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#26;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 7 THEN // 7 : Angle 265 ~ 275 //270도 직선구간
    IF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) >  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //고속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
         //GDB.Unit.SICK_S30B.Output_Byte_2 := 10#42;
		 GDB.Unit.SICK_S30B.Output_Byte_2 := 10#38;
    ELSIF (( GDB.Unit.Drive.TravelControl.FW_TargetSpeed_mpm +  GDB.Unit.Drive.TravelControl.BW_TargetSpeed_mpm) / 2) <=  GDB.Unit.SICK_S30B.High_Speed_Field_Value THEN //저속일 경우
         GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
         GDB.Unit.SICK_S30B.Output_Byte_2 := 10#38;
    END_IF;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 8 THEN // 8 : Angle 275 ~ 355
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#22;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#38;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 9 THEN // 9 : SpinTurn
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;

ELSIF  GDB.Unit.SICK_S30B.move_Type = 10 THEN // 10 : only One Wheel Run
     GDB.Unit.SICK_S30B.Output_Byte_1 := 10#37;
     GDB.Unit.SICK_S30B.Output_Byte_2 := 10#37;


    // Field Type Define
