ELSIF 		(GDB.Touch.Common_Semi_Auto_Mode_Lamp = TRUE AND Pulse_PN_SemiAuto.out_P_Pulse) 
		OR 	TON_SemiAuto.Q 
		OR gdb.Error.Error_Code <> 0
