//Reset
(*PN_Pulse[1](in_Type:= 1, in_Signal:= GDB.Unit.IO.di_Reset_SW OR GDB.Touch.Common_Reset_SW OR Auto_Bumper_Reset , out_Pulse=> GDB.mode.Reset );
TOF[1](IN:=(PN_Pulse[1].out_Pulse) , PT:=T#2S , Q=>GDB.mode.Reset_Maintain_2S );

(*CAN_Module*)
PN_Pulse[2](in_Type:=1, 
			in_Signal:= GDB.mode.Reset_Maintain_2S
						AND (		GDB.Unit.Drive.FW_Travel_Drive.Drive_Actual_Status_OK = FALSE
								OR	GDB.Unit.Drive.BW_Travel_Drive.Drive_Actual_Status_OK = FALSE
								OR	GDB.Unit.Drive.FW_Steering_Drive.Drive_Actual_Status_OK = FALSE
								OR	GDB.Unit.Drive.BW_Steering_Drive.Drive_Actual_Status_OK = FALSE
								OR	GDB.Unit.Drive.Lift_Drive.Drive_Actual_Status_OK = FALSE
								OR	GDB.Unit.SICK_BCG05.Status_OK = FALSE));
TOF[2](IN:=PN_Pulse[2].out_Pulse , PT:=T#3S);
PN_Pulse[3](in_Type:=1, in_Signal:= TOF[2].Q);
PN_Pulse[4](in_Type:=2, in_Signal:= TOF[2].Q);

