END_IF;
FB_EcSetSlaveState(
	sNetId:= GDB_Parameter.EtherCAT_NetID, 
	nSlaveAddr:= GDB_Parameter.SlaveAddr_EL6751, 
	bExecute:= (PN_Pulse[3].out_Pulse OR PN_Pulse[4].out_Pulse) );
GDB.monitor.CAN_OP_Mode := FB_EcSetSlaveState.currState.deviceState.3; 

*)
