END_IF;		
Pulse_PN_Reset(in_Signal:= GDB.Mode.Reset, out_P_Pulse=>GDB.mode.Reset_P_Pulse);													//Reset_P_Pulse
TOF_Reset(	PT:=T#10S, ET=>GDB.Mode.Reset_CAN_Time, Q=>GDB.Mode.Reset_CAN,															//Reset_CAN
